def _generate_otp_code() -> str:
    """Generate a cryptographically secure six-digit one-time password."""
    return f"{secrets.randbelow(900000) + 100000:06d}"


def _validate_student_id(db: Session, raw_student_id: Optional[str], *, field_name: str = "student_id") -> str:
    normalized_student_id = str(raw_student_id).strip() if raw_student_id is not None else ""
    if not normalized_student_id:
        raise HTTPException(status_code=400, detail=f"{field_name} is required.")

    admin_user = db.query(Admin).filter(
        or_(Admin.username == normalized_student_id, Admin.email == normalized_student_id)
    ).first()
    if admin_user:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid {field_name}. Please provide a valid student ID, not an admin username."
        )

    student = db.query(Student).filter(Student.student_id == normalized_student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found.")

    return normalized_student_id


def _parse_price_to_etb(raw_value: Optional[object], usd_to_etb: float = 56.0) -> float:
    """Parse product prices from database strings such as '$120', 'ETB 1700', or '1200' into ETB."""
    if raw_value is None:
        return 0.0

    if isinstance(raw_value, Decimal):
        return float(raw_value)
    if isinstance(raw_value, (int, float)):
        return float(raw_value)

    value_text = str(raw_value).strip()
    if not value_text:
        return 0.0

    is_usd = '$' in value_text or value_text.lower().startswith('usd') or 'usd' in value_text.lower()
    cleaned = value_text.replace('ETB', '').replace('Birr', '').replace('USD', '').replace('$', '').replace(',', '').strip()

    try:
        amount = float(cleaned)
    except ValueError:
        match = re.search(r"[-+]?\d*\.?\d+", cleaned)
        if not match:
            return 0.0
        amount = float(match.group(0))

    return amount * usd_to_etb if is_usd else amount


def _tokenize(text: Optional[str]) -> List[str]:
    if not text:
        return []
    return re.findall(r"[a-zA-Z0-9]+", str(text).lower())


class _FallbackTfidfMatrix:
    def __init__(self, rows: List[Dict[str, float]]):
        self.rows = rows
        self.shape = (len(rows), len({term for row in rows for term in row}))

    def __getitem__(self, item):
        if isinstance(item, slice):
            return _FallbackTfidfMatrix(self.rows[item])
        return _FallbackTfidfMatrix([self.rows[item]])


class _FallbackTfidfVectorizer:
    def __init__(self, ngram_range=(1, 1), lowercase=True):
        self.ngram_range = ngram_range
        self.lowercase = lowercase

    def _terms(self, document: str) -> List[str]:
        text = document.lower() if self.lowercase else document
        tokens = re.findall(r"[a-zA-Z0-9]+", text)
        terms = []
        for size in range(self.ngram_range[0], self.ngram_range[1] + 1):
            terms.extend(' '.join(tokens[index:index + size]) for index in range(len(tokens) - size + 1))
        return terms

    def fit_transform(self, documents: List[str]) -> _FallbackTfidfMatrix:
        term_counts = [Counter(self._terms(document)) for document in documents]
        document_frequency = Counter(term for counts in term_counts for term in counts)
        row_count = len(documents)
        rows = []
        for counts in term_counts:
            total = sum(counts.values()) or 1
            row = {
                term: (count / total) * (math.log((1 + row_count) / (1 + document_frequency[term])) + 1)
                for term, count in counts.items()
            }
            magnitude = math.sqrt(sum(value * value for value in row.values())) or 1.0
            rows.append({term: value / magnitude for term, value in row.items()})
        return _FallbackTfidfMatrix(rows)


def _fallback_cosine_similarity(matrix_a: _FallbackTfidfMatrix, matrix_b: _FallbackTfidfMatrix):
    values = []
    for row_a in matrix_a.rows:
        row_values = []
        magnitude_a = math.sqrt(sum(value * value for value in row_a.values())) or 1.0
        for row_b in matrix_b.rows:
            magnitude_b = math.sqrt(sum(value * value for value in row_b.values())) or 1.0
            score = sum(value * row_b.get(term, 0.0) for term, value in row_a.items())
            row_values.append(score / (magnitude_a * magnitude_b))
        values.append(row_values)
    return values


def _get_tfidf_vectorizer():
    if TfidfVectorizer is not None:
        return TfidfVectorizer(ngram_range=(1, 2), lowercase=True)
    return _FallbackTfidfVectorizer(ngram_range=(1, 2), lowercase=True)


def _build_tfidf_vectors(corpus: List[str]):
    """Build recommendation vectors with scikit-learn or a standard-library fallback."""
    documents = [str(document or '') for document in corpus]
    if not any(document.strip() for document in documents):
        return None, None

    try:
        vectorizer = _get_tfidf_vectorizer()
        return vectorizer.fit_transform(documents), vectorizer
    except ValueError:
        return None, None


def _cosine_similarity(vec_a, vec_b) -> float:
    """Return cosine similarity for two TF-IDF rows."""
    if vec_a is None or vec_b is None:
        return 0.0
    if cosine_similarity is not None:
        return float(cosine_similarity(vec_a, vec_b)[0][0])
    return float(_fallback_cosine_similarity(vec_a, vec_b)[0][0])


def _student_interest_text(student: Student, db: Session) -> str:
    department = str(getattr(student, "department", "") or "")
    college = str(getattr(student, "college", "") or "")
    weighted_terms = _tokenize(department) * 4 + _tokenize(college) * 3
    now = datetime.now()

    for model in cast(Tuple[Any, Any, Any], (WishlistItem, CartItem, Order)):
        if model is WishlistItem:
            rows = db.query(WishlistItem).filter(WishlistItem.student_id == student.student_id).all()
        elif model is CartItem:
            rows = db.query(CartItem).filter(CartItem.student_id == student.student_id).all()
        else:
            rows = db.query(Order).filter(Order.student_id == student.student_id).all()

        for row in rows:
            product = db.query(Product).filter(Product.id == row.product_id).first()
            if product:
                interaction_date = getattr(row, "created_at", None)
                age_days = max(0, (now - interaction_date).days) if interaction_date else 365
                recency_weight = max(1, int(round(4 * (0.5 ** (age_days / 30)))))
                if model is Order:
                    signal_weight = 6 if str(getattr(row, "status", "")).lower() == "completed" else 4
                elif model is CartItem:
                    signal_weight = 3
                else:
                    signal_weight = 2
                repeat_count = max(1, signal_weight + recency_weight)
                product_text = " ".join([
                    str(getattr(product, "title", "") or ""),
                    str(getattr(product, "category", "") or ""),
                    str(getattr(product, "subcategory", "") or ""),
                    str(getattr(product, "description", "") or ""),
                ])
                weighted_terms.extend(_tokenize(product_text) * repeat_count)

    return " ".join(weighted_terms)



def _normalize_payment_type(raw_value: Optional[str]) -> str:
    if not raw_value:
        return "Product Purchase"

    value = str(raw_value).strip().lower()
    if not value:
        return "Product Purchase"

    mapping = {
        "product purchase": "Product Purchase",
        "purchase": "Product Purchase",
        "checkout": "Product Purchase",
        "wallet deposit": "Wallet Deposit",
        "deposit": "Wallet Deposit",
        "wallet": "Wallet Deposit",
        "seller payout": "Seller Payout",
        "payout": "Seller Payout",
        "refund": "Refund",
        "reversal": "Refund",
    }
    return mapping.get(value, value.title())


CREDIT_TRANSACTION_TYPES = {"Wallet Deposit", "Refund", "Escrow Release", "Product Sale", "Dispute Release"}
DEBIT_TRANSACTION_TYPES = {"Product Purchase", "Wallet Withdrawal", "Escrow Hold", "Seller Payout", "Dispute Hold"}


def _transaction_direction(raw_value: Optional[str]) -> str:
    return "credit" if _normalize_payment_type(raw_value) in CREDIT_TRANSACTION_TYPES else "debit"


def _normalize_order_status(raw_value: Optional[str]) -> str:
    if raw_value is None:
        return "Pending"
    value = str(raw_value).strip()
    if not value:
        return "Pending"

    normalized = value.lower()
    aliases = {
        "pending": "Pending",
        "processing": "Processing",
        "ready to meet": "Ready to Meet",
        "ready for pickup": "Ready for Pickup",
        "ready_for_pickup": "Ready for Pickup",
        "pickup": "Ready for Pickup",
        "out for delivery": "Ready for Pickup",
        "out_for_delivery": "Ready for Pickup",
        "delivery": "Ready for Pickup",
        "completed": "Completed",
        "expired": "Expired",
        "rejected": "Rejected",
        "refunded": "Refunded",
        "success": "Completed",
        "successful": "Completed",
        "disputed": "Disputed",
        "cancelled": "Cancelled",
        "canceled": "Cancelled",
        "returned": "Returned",
    }
    return aliases.get(normalized, value.title())


def _normalize_payment_status(raw_value: Optional[str]) -> str:
    if raw_value is None:
        return "Pending"
    value = str(raw_value).strip()
    if not value:
        return "Pending"

    normalized = value.lower()
    aliases = {
        "pending": "Pending",
        "processing": "Pending",
        "success": "Successful",
        "successful": "Successful",
        "paid": "Successful",
        "completed": "Successful",
        "failed": "Failed",
        "cancelled": "Failed",
        "canceled": "Failed",
        "refunded": "Refunded",
        "refund": "Refunded",
    }
    return aliases.get(normalized, value.title())


def _compute_chapa_signature(secret: str, payload: dict) -> str:
    raw = (
        f"{payload.get('tx_ref', '')}:{payload.get('status', '')}:"
        f"{payload.get('amount', '')}:{payload.get('currency', '')}"
    )
    return hmac.new(secret.encode('utf-8'), raw.encode('utf-8'), hashlib.sha256).hexdigest()


def _compute_chapa_body_signature(secret: str, body: bytes) -> str:
    try:
        payload = json.loads(body.decode("utf-8"))
        signature_body = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
        signature_body = body
    return hmac.new(secret.encode("utf-8"), signature_body, hashlib.sha256).hexdigest()


def _get_or_create_wallet_for_student(db: Session, student: Student) -> Wallet:
    wallet = (
        db.query(Wallet)
        .filter(Wallet.student_id == student.student_id)
        .with_for_update()
        .first()
    )
    if wallet is None:
        wallet = Wallet(
            student_id=student.student_id,
            balance=Decimal(str(student.wallet_balance or 0)).quantize(Decimal("0.01")),
        )
        db.add(wallet)
        db.flush()

    if getattr(student, "wallet", None) is None:
        student.wallet = wallet

    if student.wallet_balance is None:
        student.wallet_balance = wallet.balance

    return wallet


def _settle_verified_chapa_transaction(
    db: Session,
    tx_ref: str,
    expected_amount: Optional[Decimal] = None,
) -> Dict[str, Any]:
    """Atomically settle a verified Chapa wallet deposit exactly once."""
    # Verification requests may have performed reads before reaching this helper.
    db.rollback()
    try:
        with db.begin():
            transaction = (
                db.query(Transaction)
                .filter(Transaction.tx_id == tx_ref)
                .with_for_update()
                .first()
            )
            if not transaction:
                raise HTTPException(status_code=404, detail="Payment transaction not found.")
            if _normalize_payment_type(transaction.type) != "Wallet Deposit":
                raise HTTPException(
                    status_code=400,
                    detail="Only wallet deposit transactions can be settled through Chapa payment verification.",
                )

            student = (
                db.query(Student)
                .filter(Student.student_id == transaction.student_id)
                .with_for_update()
                .first()
            )
            if not student:
                raise HTTPException(status_code=404, detail="Student not found for payment settlement.")

            payment_key = f"chapa-wallet:{tx_ref}"
            payment_record = db.query(PaymentIdempotency).filter(
                PaymentIdempotency.idempotency_key == payment_key,
            ).with_for_update().first()
            if payment_record and (
                payment_record.buyer_id != student.student_id
                or payment_record.transaction_id != transaction.tx_id
            ):
                raise HTTPException(status_code=409, detail="Payment reference is already assigned to another wallet.")
            if not payment_record:
                db.add(PaymentIdempotency(
                    idempotency_key=payment_key,
                    order_id=None,
                    buyer_id=student.student_id,
                    product_id=None,
                    transaction_id=transaction.tx_id,
                ))
                db.flush()

            wallet = (
                db.query(Wallet)
                .filter(Wallet.student_id == student.student_id)
                .with_for_update()
                .first()
            )
            if wallet is None:
                wallet = Wallet(
                    student_id=student.student_id,
                    balance=Decimal(str(student.wallet_balance or 0)).quantize(Decimal("0.01")),
                )
                db.add(wallet)
                db.flush()

            if _normalize_payment_status(transaction.status) == "Successful":
                return {
                    "transaction_id": transaction.tx_id,
                    "student_id": student.student_id,
                    "amount": Decimal(str(transaction.amount)).quantize(Decimal("0.01")),
                    "wallet_balance": Decimal(str(wallet.balance or 0)).quantize(Decimal("0.01")),
                    "already_settled": True,
                }

            amount = Decimal(str(transaction.amount)).quantize(Decimal("0.01"))
            if amount <= 0:
                raise HTTPException(status_code=400, detail="Payment transaction amount must be greater than 0.")
            if expected_amount is not None and amount != expected_amount.quantize(Decimal("0.01")):
                raise HTTPException(status_code=400, detail="Payment callback amount does not match the transaction.")

            _, wallet, _ = apply_transaction(
                db,
                student_id=student.student_id,
                tx_id=transaction.tx_id,
                transaction_type="Wallet Deposit",
                amount=amount,
                description=transaction.description or f"Wallet deposit for {student.student_id}",
                status="Successful",
                transaction=transaction,
            )

            return {
                "transaction_id": transaction.tx_id,
                "student_id": student.student_id,
                "amount": amount,
                "wallet_balance": wallet.balance,
                "already_settled": False,
            }
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception("Unable to settle Chapa payment safely.")
        raise HTTPException(status_code=500, detail="Unable to settle payment safely.")


def _settle_verified_chapa_product_order(
    db: Session,
    tx_ref: str,
    expected_amount: Optional[Decimal] = None,
) -> Dict[str, Any]:
    """Complete a Chapa split order without crediting the seller's wallet."""
    db.rollback()
    try:
        with db.begin():
            transaction = (
                db.query(Transaction)
                .filter(Transaction.tx_id == tx_ref)
                .with_for_update()
                .first()
            )
            if not transaction or _normalize_payment_type(transaction.type) != "Product Purchase":
                raise HTTPException(status_code=404, detail="Product payment transaction not found.")

            payment_record = (
                db.query(PaymentIdempotency)
                .filter(PaymentIdempotency.transaction_id == tx_ref)
                .with_for_update()
                .first()
            )
            if not payment_record or not payment_record.order_id:
                raise HTTPException(status_code=404, detail="Order not found for product payment.")
            if payment_record.buyer_id != transaction.student_id:
                raise HTTPException(status_code=409, detail="Product payment reference does not match its buyer.")

            order = (
                db.query(Order)
                .filter(Order.id == payment_record.order_id)
                .with_for_update()
                .first()
            )
            if not order or order.student_id != transaction.student_id:
                raise HTTPException(status_code=404, detail="Order not found for product payment.")

            amount = Decimal(str(transaction.amount)).quantize(Decimal("0.01"))
            order_amount = (
                Decimal(str(order.price)) * Decimal(int(order.quantity or 1))
            ).quantize(Decimal("0.01"))
            if amount <= 0 or amount != order_amount:
                raise HTTPException(status_code=400, detail="Product payment amount does not match the order.")
            if expected_amount is not None and amount != expected_amount.quantize(Decimal("0.01")):
                raise HTTPException(status_code=400, detail="Chapa payment amount does not match the order.")

            if (
                _normalize_payment_status(transaction.status) == "Successful"
                and _normalize_payment_status(order.payment_status) == "Successful"
            ):
                return {
                    "transaction_id": transaction.tx_id,
                    "student_id": transaction.student_id,
                    "order_id": order.id,
                    "amount": amount,
                    "commission": Decimal(str(order.seller_commission or 0)).quantize(Decimal("0.01")),
                    "already_settled": True,
                }
            if _normalize_payment_status(transaction.status) != "Pending":
                raise HTTPException(status_code=409, detail="Product payment is no longer pending.")

            commission = Decimal(str(order.seller_commission or 0)).quantize(Decimal("0.01"))
            if commission < 0 or commission > amount:
                raise HTTPException(status_code=409, detail="Order commission is invalid.")

            now = datetime.now(timezone.utc).replace(tzinfo=None)
            transaction.status = "Successful"
            transaction.description = f"Chapa split payment for order #{order.id}"
            order.status = "Completed"
            order.payment_status = "Successful"
            order.paid_at = now
            order.completed_at = now
            order.expired_at = None
            order.is_funds_released = True
            cart_item = (
                db.query(CartItem)
                .filter(
                    CartItem.student_id == order.student_id,
                    CartItem.product_id == order.product_id,
                )
                .with_for_update()
                .first()
            )
            if cart_item:
                cart_quantity = int(cart_item.quantity or 1)
                purchased_quantity = int(order.quantity or 1)
                if cart_quantity <= purchased_quantity:
                    db.delete(cart_item)
                else:
                    cart_item.quantity = cart_quantity - purchased_quantity

            if commission:
                system_wallet = (
                    db.query(SystemSetting)
                    .filter(SystemSetting.key == "system_wallet_balance")
                    .with_for_update()
                    .first()
                )
                if system_wallet:
                    balance = Decimal(str(system_wallet.value or 0)).quantize(Decimal("0.01"))
                    system_wallet.value = str((balance + commission).quantize(Decimal("0.01")))
                else:
                    db.add(SystemSetting(
                        key="system_wallet_balance",
                        value=str(commission),
                    ))

            db.add(AuditLog(
                admin_id=None,
                action="payment_completed",
                entity_type="Order",
                entity_id=order.id,
                description=(
                    f"Chapa split payment {tx_ref} completed for order #{order.id}; "
                    f"platform commission {commission} ETB."
                ),
                status="SUCCESS",
                ip_address="127.0.0.1",
            ))
            buyer = db.query(Student).filter(Student.student_id == order.student_id).first()
            seller = db.query(Student).filter(Student.student_id == order.seller_id).first()
            order_target = json.dumps({"kind": "order", "order_id": order.id})
            if buyer:
                _add_student_notification(
                    db,
                    buyer,
                    "Payment completed",
                    f"Your Chapa payment for '{order.title}' is complete.",
                    "payment",
                    order_target,
                    reference_id=str(order.id),
                    action_label="View Order",
                    action_url=f"/dashboard?tab=buyer&section=orders&order={order.id}",
                )
            if seller:
                _add_student_notification(
                    db,
                    seller,
                    "Payment received",
                    f"Chapa confirmed payment for '{order.title}'. You can arrange handover.",
                    "payment",
                    order_target,
                    reference_id=str(order.id),
                    action_label="View Order",
                    action_url=f"/dashboard?tab=seller&section=orders&order={order.id}",
                )
            return {
                "transaction_id": transaction.tx_id,
                "student_id": transaction.student_id,
                "order_id": order.id,
                "seller_id": order.seller_id,
                "amount": amount,
                "commission": commission,
                "already_settled": False,
            }
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception(
            "Unable to settle Chapa split order for transaction %s safely.",
            tx_ref,
        )
        raise HTTPException(status_code=500, detail="Unable to settle product payment safely.")


def _release_pending_chapa_product_order(db: Session, tx_ref: str, *, expired: bool) -> bool:
    """Release inventory once when a pending Chapa product payment fails or expires."""
    db.rollback()
    try:
        with db.begin():
            transaction = (
                db.query(Transaction)
                .filter(Transaction.tx_id == tx_ref)
                .with_for_update()
                .first()
            )
            if not transaction or _normalize_payment_type(transaction.type) != "Product Purchase":
                return False
            if _normalize_payment_status(transaction.status) != "Pending":
                return False

            payment_record = (
                db.query(PaymentIdempotency)
                .filter(PaymentIdempotency.transaction_id == tx_ref)
                .with_for_update()
                .first()
            )
            order = (
                db.query(Order)
                .filter(Order.id == payment_record.order_id)
                .with_for_update()
                .first()
                if payment_record and payment_record.order_id
                else None
            )
            if not order or _normalize_payment_status(order.payment_status) != "Pending":
                return False

            product = (
                db.query(Product)
                .filter(Product.id == order.product_id)
                .with_for_update()
                .first()
            )
            if product:
                product.stock = int(product.stock or 0) + int(order.quantity or 1)
                _sync_product_status_with_stock(product)

            now = datetime.now(timezone.utc).replace(tzinfo=None)
            order.status = "Expired" if expired else "Cancelled"
            order.payment_status = "Failed"
            order.expired_at = now if expired else order.expired_at
            transaction.status = "Failed"
            transaction.description = (
                f"Chapa checkout expired for order #{order.id}"
                if expired
                else f"Chapa checkout initialization failed for order #{order.id}"
            )
            return True
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception(
            "Unable to release inventory for Chapa product payment %s.",
            tx_ref,
        )
        raise HTTPException(status_code=500, detail="Unable to release product checkout inventory safely.")


async def _reconcile_pending_payments() -> None:
    """Verify pending Chapa deposits and product orders, settling confirmed payments."""
    try:
        secret = get_chapa_secret_key()
    except PayoutProviderError:
        secret = ""
    if not secret:
        logging.getLogger("app.payments").warning(
            "Skipping pending payment reconciliation because Chapa is not configured."
        )
        return

    db = SessionLocal()
    try:
        pending_transactions = (
            db.query(Transaction)
            .filter(
                Transaction.status == "Pending",
                Transaction.type == "Wallet Deposit",
            )
            .all()
        )
        for pending_transaction in pending_transactions:
            try:
                verification = _request_chapa_verification(pending_transaction.tx_id)
            except HTTPException:
                logging.getLogger("app.payments").warning(
                    "Unable to verify pending transaction %s.", pending_transaction.tx_id
                )
                continue
            expected_amount = Decimal(str(pending_transaction.amount)).quantize(Decimal("0.01"))
            if verification["status"] != "Successful" or verification["amount"] != expected_amount:
                continue

            try:
                settlement = _settle_verified_chapa_transaction(
                    db,
                    pending_transaction.tx_id,
                    expected_amount=verification["amount"],
                )
                if settlement["already_settled"]:
                    continue
                locked_transaction = db.query(Transaction).filter(
                    Transaction.tx_id == settlement["transaction_id"]
                ).first()
                student = db.query(Student).filter(
                    Student.student_id == settlement["student_id"]
                ).first()
                if not locked_transaction or not student:
                    logging.getLogger("app.payments").error(
                        "Settlement records disappeared for transaction %s.",
                        pending_transaction.tx_id,
                    )
                    db.rollback()
                    continue
                _dispatch_student_notification(
                    db,
                    student,
                    "Payment Successful",
                    f"Your wallet deposit of {settlement['amount']} ETB was completed successfully.",
                    "payment",
                    badge="Completed",
                    details_table={
                        "Amount": f"{settlement['amount']} ETB",
                        "Reference": settlement["transaction_id"],
                        "Date": datetime.now(timezone.utc).strftime("%b %d, %Y").replace(" 0", " "),
                    },
                )
                db.add(AuditLog(
                    admin_id=None,
                    action="Payment Auto-Verified",
                    entity_type="Payment",
                    entity_id=locked_transaction.id,
                    description=f"Automatically verified Chapa payment {locked_transaction.tx_id}; credited {settlement['amount']} ETB to student {student.student_id}.",
                    status="SUCCESS",
                    ip_address="127.0.0.1",
                ))
                db.commit()
                logging.getLogger("app.payments").info(
                    "Automatically settled Chapa transaction %s.", locked_transaction.tx_id
                )
            except HTTPException:
                db.rollback()
                logging.getLogger("app.payments").warning(
                    "Chapa transaction verification did not satisfy settlement requirements for %s.",
                    pending_transaction.tx_id,
                )

        pending_product_payments = (
            db.query(Transaction)
            .filter(
                Transaction.status == "Pending",
                Transaction.type == "Product Purchase",
            )
            .all()
        )
        for pending_transaction in pending_product_payments:
            try:
                verification = _request_chapa_verification(pending_transaction.tx_id)
                expected_amount = Decimal(str(pending_transaction.amount)).quantize(Decimal("0.01"))
                if verification["amount"] != expected_amount:
                    continue
                if verification["status"] == "Successful":
                    settlement = _settle_verified_chapa_product_order(
                        db,
                        pending_transaction.tx_id,
                        expected_amount=verification["amount"],
                    )
                    continue

                created_at = pending_transaction.created_at
                pending_age = (
                    datetime.now(timezone.utc).replace(tzinfo=None) - created_at
                    if created_at
                    else timedelta(0)
                )
                if verification["status"] in {"Failed", "Expired", "Cancelled"} or pending_age >= timedelta(minutes=60):
                    _release_pending_chapa_product_order(
                        db,
                        pending_transaction.tx_id,
                        expired=verification["status"] not in {"Failed", "Cancelled"},
                    )
            except HTTPException:
                db.rollback()
                logging.getLogger("app.payments").warning(
                    "Unable to reconcile pending Chapa product payment %s.",
                    pending_transaction.tx_id,
                )
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception("Pending payment reconciliation failed.")
    finally:
        db.close()


def _resolve_pending_payout(
    db: Session,
    payout_id: int,
    status: str,
    provider_reference: Optional[str] = None,
    failure_reason: Optional[str] = None,
) -> Optional[str]:
    """Apply one payout state transition and its wallet ledger effects exactly once."""
    db.rollback()
    initial_payout = db.query(PayoutTransaction).filter(PayoutTransaction.id == payout_id).first()
    if not initial_payout:
        return None
    student_id = initial_payout.student_id
    db.rollback()

    notification = None
    normalized_status = "failed" if status in {"cancelled", "canceled", "failed"} else status
    if normalized_status not in {"pending", "processing", "completed", "failed"}:
        raise ValueError(f"Unsupported payout status: {status}")

    with db.begin():
        student = db.query(Student).filter(
            Student.student_id == student_id,
        ).with_for_update().first()
        wallet = db.query(Wallet).filter(
            Wallet.student_id == student_id,
        ).with_for_update().first()
        payout = db.query(PayoutTransaction).filter(
            PayoutTransaction.id == payout_id,
        ).with_for_update().first()
        if not payout:
            return None
        previous_status = str(payout.status or "pending").lower()
        if previous_status in {"completed", "failed", "cancelled", "canceled"}:
            return previous_status
        if not student or not wallet:
            raise ValueError(f"Wallet records are missing for payout {payout.internal_reference}.")

        transaction = db.query(Transaction).filter(
            Transaction.tx_id == payout.internal_reference,
        ).with_for_update().first()
        amount = abs(Decimal(str(payout.amount or 0)).quantize(Decimal("0.01")))
        held_balance = Decimal(str(wallet.held_balance or 0)).quantize(Decimal("0.01"))
        if normalized_status in {"completed", "failed"}:
            if held_balance < amount:
                raise ValueError(f"Held wallet balance is insufficient for payout {payout.internal_reference}.")
            wallet.held_balance = held_balance - amount
            if normalized_status == "completed":
                payout.status = "completed"
                if transaction:
                    transaction.type = "Wallet Withdrawal"
                    transaction.amount = -amount
                    transaction.status = "Successful"
                    transaction.description = "Withdrawal successful; confirmed by Chapa."
                notification = (
                    "Withdraw successful",
                    f"Your withdraw of {amount} ETB was confirmed and completed successfully.",
                )
            else:
                reason = failure_reason or "Chapa reported that the transfer failed."
                payout.status = "failed"
                payout.failure_reason = reason
                reversal_reference = f"REVERSAL-{payout.internal_reference}"
                reversal = db.query(Transaction).filter(
                    Transaction.tx_id == reversal_reference,
                ).with_for_update().first()
                if reversal is None:
                    apply_transaction(
                        db,
                        student_id=student_id,
                        tx_id=reversal_reference,
                        transaction_type="Refund",
                        amount=amount,
                        description=f"Reversal - Withdraw #{payout.id}",
                        status="Successful",
                    )
                if transaction:
                    transaction.type = "Wallet Withdrawal"
                    transaction.amount = -amount
                    transaction.status = "Failed"
                    transaction.description = f"Withdrawal failed; reversal issued. {reason}"[:255]
                notification = (
                    "Withdraw failed - reversed",
                    f"Your withdraw request of {amount} ETB failed. The funds were returned to your available wallet balance.",
                )
                if "timeout" in reason.lower() or "did not confirm" in reason.lower():
                    db.add(AuditLog(
                        admin_id=None,
                        action="Stale Payout Alert",
                        entity_type="PayoutTransaction",
                        entity_id=payout.id,
                        description=f"Payout {payout.internal_reference} failed after provider confirmation timed out; {amount} ETB was reversed.",
                        status="WARNING",
                        severity="high",
                        ip_address="127.0.0.1",
                    ))
        else:
            payout.status = normalized_status
            if transaction:
                transaction.status = "Processing" if normalized_status == "processing" else "Pending"
                transaction.description = "Payout is processing with Chapa." if normalized_status == "processing" else "Payout is pending confirmation from Chapa."

        if provider_reference:
            payout.provider_reference = provider_reference
        student.wallet_balance = Decimal(str(wallet.balance or 0)).quantize(Decimal("0.01"))
        if notification:
            _add_student_notification(db, student, notification[0], notification[1], "payout")
        db.add(AuditLog(
            admin_id=None,
            action="Wallet Payout State Updated",
            entity_type="PayoutTransaction",
            entity_id=payout.id,
            description=f"Payout {payout.internal_reference} transitioned from {previous_status} to {payout.status}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        final_status = payout.status
        notification_email = (
            student,
            notification,
            "Completed" if normalized_status == "completed" else "Failed",
            {
                "Amount": f"{amount} ETB",
                "Reference": payout.internal_reference,
                "Date": datetime.now(timezone.utc).strftime("%b %d, %Y").replace(" 0", " "),
            },
        ) if notification else None

    if notification_email:
        _send_student_notification_email(
            notification_email[0],
            notification_email[1][0],
            notification_email[1][1],
            "payout",
            badge=notification_email[2],
            details_table=notification_email[3],
        )
    return final_status


async def _reconcile_pending_payouts(
    payout_ids: Optional[List[int]] = None,
    force_fail: bool = False,
) -> dict:
    """Resolve provider payouts and refund stale or failed transfers independently."""
    try:
        timeout_hours = max(1, float(os.getenv("PAYOUT_TIMEOUT_HOURS", "24")))
    except (TypeError, ValueError):
        timeout_hours = 24
    try:
        processing_timeout_minutes = max(30, float(os.getenv("PAYOUT_PROCESSING_TIMEOUT_MINUTES", "60")))
    except (TypeError, ValueError):
        processing_timeout_minutes = 60
    cutoff = datetime.now() - timedelta(hours=timeout_hours)
    processing_cutoff = datetime.now() - timedelta(minutes=processing_timeout_minutes)
    logger = logging.getLogger("app.payments")
    logger.info(
        "Starting pending payout reconciliation timeout_hours=%s selected_ids=%s force_fail=%s.",
        timeout_hours,
        payout_ids,
        force_fail,
    )
    scan_db = SessionLocal()
    try:
        ids_to_scan = payout_ids or [payout_id for (payout_id,) in scan_db.query(PayoutTransaction.id).filter(
            PayoutTransaction.status.in_(["pending", "processing"]),
        ).all()]
    finally:
        scan_db.close()

    summary = {"checked": 0, "completed": 0, "failed": 0, "skipped": 0, "errors": 0}
    for payout_id in ids_to_scan:
        db = SessionLocal()
        try:
            payout = db.query(PayoutTransaction).filter(
                PayoutTransaction.id == payout_id,
                PayoutTransaction.status.in_(["pending", "processing"]),
            ).first()
            if not payout:
                summary["skipped"] += 1
                logger.warning("Skipping payout id=%s: it is missing or no longer pending/processing.", payout_id)
                continue

            summary["checked"] += 1
            payout_status = str(payout.status or "pending").strip().lower()
            is_stale = payout.created_at < cutoff
            is_processing_stale = payout_status == "processing" and payout.created_at < processing_cutoff
            provider = db.query(PayoutProvider).filter(PayoutProvider.id == payout.provider_id).first()
            provider_code = provider.code if provider else None
            adapter = get_payout_adapter(provider_code) if provider_code else None
            logger.info(
                "Payout reconciliation lookup payout_id=%s internal_reference=%s provider_id=%s provider_code=%s provider_name=%s provider_reference=%s adapter=%s stale=%s.",
                payout.id,
                payout.internal_reference,
                payout.provider_id,
                provider_code,
                provider.name if provider else None,
                payout.provider_reference,
                type(adapter).__name__ if adapter else None,
                is_stale,
            )
            result = None
            status_checked = False
            if force_fail:
                logger.warning(
                    "Force-failing payout id=%s internal_reference=%s at admin request.",
                    payout.id,
                    payout.internal_reference,
                )
            elif adapter is None:
                summary["skipped"] += 1
                logger.error(
                    "Cannot reconcile payout id=%s internal_reference=%s: no adapter for provider_id=%s provider_code=%s; CHAPA_SECRET_KEY configured=%s.",
                    payout.id,
                    payout.internal_reference,
                    payout.provider_id,
                    provider_code,
                    bool(os.getenv("CHAPA_SECRET_KEY", "").strip()),
                )
            else:
                try:
                    status_reference = payout.provider_reference or payout.internal_reference
                    logger.info(
                        "Calling payout adapter status payout_id=%s internal_reference=%s status_reference=%s adapter=%s.",
                        payout.id,
                        payout.internal_reference,
                        status_reference,
                        type(adapter).__name__,
                    )
                    result = adapter.get_transfer_status(status_reference)
                    status_checked = True
                    logger.info(
                        "Payout adapter status returned payout_id=%s internal_reference=%s status=%s provider_reference=%s message=%s.",
                        payout.id,
                        payout.internal_reference,
                        result.status,
                        result.provider_reference,
                        result.message,
                    )
                except PayoutProviderError as error:
                    summary["errors"] += 1
                    logger.exception(
                        "Unable to reconcile payout id=%s internal_reference=%s provider_id=%s provider_code=%s retryable=%s status_code=%s: %s",
                        payout.id,
                        payout.internal_reference,
                        payout.provider_id,
                        provider_code,
                        error.retryable,
                        error.status_code,
                        error,
                    )

            if force_fail or ((is_stale or is_processing_stale) and result is None and status_checked):
                _resolve_pending_payout(
                    db,
                    payout.id,
                    "failed",
                    failure_reason=(
                        "Manually force-failed by an administrator"
                        if force_fail
                        else "Provider did not confirm within the timeout window"
                    ),
                )
                summary["failed"] += 1
            elif result and result.status == "completed" and result.provider_reference:
                _resolve_pending_payout(
                    db,
                    payout.id,
                    "completed",
                    provider_reference=result.provider_reference,
                )
                summary["completed"] += 1
            elif result and result.status == "completed":
                raise PayoutProviderError(
                    "The payout provider reported completion without a transfer reference."
                )
            elif result and result.status in {"failed", "cancelled"}:
                _resolve_pending_payout(
                    db,
                    payout.id,
                    result.status,
                    provider_reference=result.provider_reference,
                    failure_reason=result.message,
                )
                summary["failed"] += 1
            elif (is_stale or is_processing_stale) and status_checked:
                _resolve_pending_payout(
                    db,
                    payout.id,
                    "failed",
                    failure_reason=(
                        f"Provider did not confirm within the {processing_timeout_minutes:g}-minute processing timeout"
                        if is_processing_stale
                        else "Provider did not confirm within the timeout window"
                    ),
                )
                summary["failed"] += 1
            elif is_stale or is_processing_stale:
                # Do not refund a payout based solely on a local timeout when
                # Chapa could not be queried; retry on the next scheduler run.
                summary["skipped"] += 1
        except Exception:
            summary["errors"] += 1
            db.rollback()
            logger.exception(
                "Pending payout reconciliation failed for payout id %s.", payout_id
            )
        finally:
            db.close()
    logger.info("Finished pending payout reconciliation summary=%s.", summary)
    return summary










# Read Gmail SMTP credentials from Backend/.env or the process environment.
SENDER_EMAIL = os.getenv("SENDER_EMAIL", "").strip()
SENDER_PASSWORD = os.getenv("SENDER_PASSWORD", "").strip()

# Configure a simple file logger for email/SMTP errors
LOG_DIR = os.path.join(os.path.dirname(__file__), "logs")
os.makedirs(LOG_DIR, exist_ok=True)
EMAIL_LOG_PATH = os.path.join(LOG_DIR, "email_errors.log")
email_logger = logging.getLogger("app.email")
if not email_logger.handlers:
    fh = logging.FileHandler(EMAIL_LOG_PATH)
    fh.setLevel(logging.INFO)
    fmt = logging.Formatter('%(asctime)s %(levelname)s %(message)s')
    fh.setFormatter(fmt)
    email_logger.addHandler(fh)
    email_logger.setLevel(logging.INFO)



def _smtp_credentials() -> tuple[str, str]:
    sender_email = (
        os.getenv("SMTP_USER", "").strip()
        or os.getenv("SENDER_EMAIL", SENDER_EMAIL).strip()
    )
    sender_password = (
        os.getenv("SMTP_PASSWORD", "")
        or os.getenv("SENDER_PASSWORD", SENDER_PASSWORD)
    ).strip().strip("\"'").strip().replace(" ", "")
    return sender_email, sender_password


def _smtp_configuration() -> tuple[str, int, str]:
    host = os.getenv("SMTP_HOST", "").strip() or "smtp.gmail.com"
    port_value = os.getenv("SMTP_PORT", "").strip()
    try:
        port = int(port_value) if port_value else 587
    except ValueError as error:
        raise ValueError("SMTP_PORT must be an integer.") from error
    if not 1 <= port <= 65535:
        raise ValueError("SMTP_PORT must be between 1 and 65535.")

    security = os.getenv("SMTP_SECURITY", "").strip().lower()
    if not security:
        security = "ssl" if port == 465 else "starttls"
    if security not in {"starttls", "ssl"}:
        raise ValueError("SMTP_SECURITY must be starttls or ssl.")
    return host, port, security


def _smtp_connection_error(error: Exception) -> bool:
    if isinstance(error, smtplib.SMTPAuthenticationError):
        return False
    return isinstance(
        error,
        (smtplib.SMTPConnectError, smtplib.SMTPServerDisconnected, TimeoutError, OSError),
    )


def _smtp_failure_hint(stage: str, error: Exception) -> Optional[str]:
    if isinstance(error, smtplib.SMTPAuthenticationError):
        return "Gmail requires an App Password (2-Step Verification)."
    if stage in {"connect", "starttls", "login", "send"} and _smtp_connection_error(error):
        return "Check whether the port is blocked by firewall/antivirus/network."
    return None


def _log_smtp_stage_success(stage: str, mode: str, host: str, port: int) -> None:
    email_logger.info(
        "SMTP stage succeeded stage=%s mode=%s host=%s port=%s.",
        stage,
        mode,
        host,
        port,
    )


def _create_ipv4_smtp_socket(
    host: str,
    port: int,
    timeout: Optional[float],
    source_address: Optional[Tuple[str, int]] = None,
) -> socket.socket:
    addresses = socket.getaddrinfo(host, port, socket.AF_INET, socket.SOCK_STREAM)
    last_error = None
    for family, socket_type, protocol, _, address in addresses:
        try:
            return socket.create_connection(address, timeout, source_address)
        except OSError as error:
            last_error = error
    if last_error:
        raise last_error
    raise OSError(f"No IPv4 address found for SMTP host {host}.")


class _IPv4SMTP(smtplib.SMTP):
    def _get_socket(self, host, port, timeout):
        if timeout is not None and not timeout:
            raise ValueError("Non-blocking socket (timeout=0) is not supported")
        return _create_ipv4_smtp_socket(host, port, timeout, self.source_address)


class _IPv4SMTP_SSL(smtplib.SMTP_SSL):
    def _get_socket(self, host, port, timeout):
        if timeout is not None and not timeout:
            raise ValueError("Non-blocking socket (timeout=0) is not supported")
        new_socket = _create_ipv4_smtp_socket(host, port, timeout, self.source_address)
        return self.context.wrap_socket(new_socket, server_hostname=self._host)


def _smtp_attempt(
    host: str,
    port: int,
    mode: str,
    sender_email: str,
    sender_password: str,
    recipient: str,
    subject: str,
    body: str,
    html_body: Optional[str] = None,
) -> None:
    message = MIMEMultipart("alternative")
    plain_body = render_system_email_text(subject, "Hello,", [body]) if html_body is None else body
    rich_body = html_body or render_system_email(subject, "Hello,", [body])
    message.attach(MIMEText(plain_body, "plain", "utf-8"))
    message.attach(MIMEText(rich_body, "html", "utf-8"))
    message["Subject"] = subject
    message["From"] = formataddr(("UniXchange Security", sender_email))
    message["Reply-To"] = formataddr(("UniXchange Support", sender_email))
    message["To"] = recipient
    stage = "connect"
    print(
        f"Connecting to {host}:{port} with {mode} SMTP for sender={sender_email} receiver={recipient}.",
        flush=True,
    )
    email_logger.info(
        "Connecting to SMTP host=%s port=%s mode=%s sender=%s receiver=%s.",
        host,
        port,
        mode,
        sender_email,
        recipient,
    )
    try:
        context = ssl.create_default_context()
        if mode == "ssl":
            with _IPv4SMTP_SSL(
                host, port, context=context, timeout=15
            ) as server:
                server.ehlo()
                _log_smtp_stage_success("connect", mode, host, port)
                stage = "login"
                server.login(sender_email, sender_password)
                _log_smtp_stage_success("login", mode, host, port)
                stage = "send"
                refused = server.sendmail(sender_email, recipient, message.as_string())
        else:
            with _IPv4SMTP(host, port, timeout=15) as server:
                server.ehlo()
                _log_smtp_stage_success("connect", mode, host, port)
                stage = "starttls"
                server.starttls(context=context)
                server.ehlo()
                _log_smtp_stage_success("starttls", mode, host, port)
                stage = "login"
                server.login(sender_email, sender_password)
                _log_smtp_stage_success("login", mode, host, port)
                stage = "send"
                refused = server.sendmail(sender_email, recipient, message.as_string())
        if refused:
            stage = "send"
            raise smtplib.SMTPRecipientsRefused(refused)
        _log_smtp_stage_success("send", mode, host, port)
    except (smtplib.SMTPException, OSError, TimeoutError) as error:
        raise SMTPDeliveryError(stage, error) from error


class SMTPDeliveryError(Exception):
    def __init__(self, stage: str, original_error: Exception):
        super().__init__(stage)
        self.stage = stage
        self.original_error = original_error


def _send_smtp_message(
    recipient: str,
    subject: str,
    body: str,
    html_body: Optional[str] = None,
) -> dict[str, Any]:
    sender_email, sender_password = _smtp_credentials()
    print(
        f"Preparing SMTP email sender={sender_email or '(not configured)'} "
        f"receiver={recipient or '(missing)'}.",
        flush=True,
    )
    email_logger.info(
        "Preparing SMTP email sender=%s receiver=%s.",
        sender_email or "(not configured)",
        recipient or "(missing)",
    )
    if not sender_email or not sender_password:
        print("SMTP delivery failed: sender email or app password is not configured.", flush=True)
        email_logger.error(
            "SMTP delivery failed at stage=configuration mode=unconfigured: "
            "SENDER_EMAIL or SENDER_PASSWORD is missing."
        )
        return {
            "success": False,
            "stage": "configuration",
            "mode": "unconfigured",
            "port": None,
            "hint": "Configure SENDER_EMAIL and SENDER_PASSWORD.",
            "attempts": [],
        }

    try:
        host, port, configured_mode = _smtp_configuration()
    except ValueError:
        email_logger.exception("Failed to send OTP email")
        email_logger.error(
            "SMTP delivery failed at stage=configuration mode=unconfigured: "
            "SMTP_PORT or SMTP_SECURITY is invalid."
        )
        return {
            "success": False,
            "stage": "configuration",
            "mode": "unconfigured",
            "port": None,
            "hint": "Check SMTP_PORT and SMTP_SECURITY configuration.",
            "attempts": [],
        }

    modes = [(port, configured_mode)]
    if configured_mode == "starttls":
        fallback = (465, "ssl")
    else:
        fallback = (587, "starttls")
    if fallback != modes[0]:
        modes.append(fallback)

    attempts: list[dict[str, Any]] = []
    for attempt_index, (attempt_port, mode) in enumerate(modes):
        stage = "connect"
        try:
            _smtp_attempt(
                host,
                attempt_port,
                mode,
                sender_email,
                sender_password,
                recipient,
                subject,
                body,
                html_body,
            )
        except SMTPDeliveryError as delivery_error:
            error = delivery_error.original_error
            stage = delivery_error.stage
            hint = _smtp_failure_hint(stage, error)
            attempt = {
                "success": False,
                "stage": stage,
                "mode": mode,
                "port": attempt_port,
                "error_type": type(error).__name__,
            }
            if hint:
                attempt["hint"] = hint
            attempts.append(attempt)
            email_logger.exception("Failed to send OTP email")
            print(
                f"SMTP delivery failed host={host}:{attempt_port} mode={mode} "
                f"stage={stage} error={type(error).__name__}.",
                flush=True,
            )
            email_logger.error(
                "SMTP delivery failed at stage=%s mode=%s host=%s port=%s error_type=%s%s",
                stage,
                mode,
                host,
                attempt_port,
                type(error).__name__,
                f"; hint: {hint}" if hint else "",
            )
            can_fallback = (
                attempt_index == 0
                and len(modes) > 1
                and _smtp_connection_error(error)
            )
            if can_fallback:
                email_logger.warning(
                    "SMTP retrying once with fallback mode=%s port=%s after stage=%s failed.",
                    fallback[1],
                    fallback[0],
                    stage,
                )
                continue
            return {
                "success": False,
                "stage": stage,
                "mode": mode,
                "port": attempt_port,
                "hint": hint,
                "attempts": attempts,
            }
        else:
            print(
                f"SMTP delivery succeeded sender={sender_email} receiver={recipient} "
                f"host={host}:{attempt_port}.",
                flush=True,
            )
            email_logger.info(
                "SMTP delivery succeeded sender=%s receiver=%s host=%s port=%s.",
                sender_email,
                recipient,
                host,
                attempt_port,
            )
            attempts.append({
                "success": True,
                "stage": "send",
                "mode": mode,
                "port": attempt_port,
            })
            return {
                "success": True,
                "stage": "send",
                "mode": mode,
                "port": attempt_port,
                "hint": None,
                "attempts": attempts,
            }

    return {
        "success": False,
        "stage": "connect",
        "mode": configured_mode,
        "port": port,
        "hint": "Check whether the port is blocked by firewall/antivirus/network.",
        "attempts": attempts,
    }


def _log_development_otp(otp: str) -> None:
    if _is_production_environment():
        return
    if not re.fullmatch(r"\d{6}", str(otp)):
        return
    environment = os.getenv("ENV", "").strip().lower()
    log_otp = os.getenv("EMAIL_DEV_LOG_OTP", "").strip().lower() in {
        "1", "true", "yes", "on",
    }
    if environment == "development" and log_otp:
        print(f"[DEV ONLY] Account recovery OTP: {otp}", flush=True)


def send_otp_email_diagnostic(
    receiver_email: str,
    otp: str,
    purpose: str = "password_reset",
) -> dict[str, Any]:
    _log_development_otp(otp)
    if not receiver_email:
        print("OTP email delivery failed: receiver email is missing.", flush=True)
        email_logger.error("OTP email delivery failed at stage=configuration: recipient is missing.")
        return {
            "success": False,
            "stage": "configuration",
            "mode": "unconfigured",
            "port": None,
            "hint": "The recipient email address is missing.",
            "attempts": [],
        }

    purpose_key = purpose.strip().lower()
    purpose_templates = {
        "password_reset": (
            "Password Reset Code",
            "Use this verification code to securely reset your UniXchange account password.",
        ),
        "wallet_pin_reset": (
            "Wallet PIN Reset Code",
            "Use this authorization code to reset your 4-digit Wallet security PIN.",
        ),
        "student_login": (
            "Login Verification Code",
            "Use this verification code to securely sign in to your UniXchange account.",
        ),
        "login_2fa": (
            "Login Verification Code",
            "Use this verification code to securely complete your UniXchange sign-in.",
        ),
        "admin_login_2fa": (
            "Admin Login Verification Code",
            "Use this verification code to securely complete administrator sign-in to UniXchange.",
        ),
        "support": (
            "Support Verification Code",
            "Use this verification code to securely verify your request with UniXchange Support.",
        ),
        "support_2fa": (
            "Support Verification Code",
            "Use this verification code to securely verify your request with UniXchange Support.",
        ),
    }
    title, description = purpose_templates.get(
        purpose_key,
        (
            f"{purpose.replace('_', ' ').strip().title()} Code",
            "Use this verification code to complete your requested action on UniXchange.",
        ),
    )
    otp_text = str(otp)
    notice = (
        "This code expires in 10 minutes and can be used only once. "
        "Never share this code with anyone."
    )
    footer = "© 2026 UniXchange Campus Marketplace. All rights reserved."
    plain_body = "\n\n".join((title, description, otp_text, notice, footer))
    html_body = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{html.escape(title)}</title>
  <style>
    @media only screen and (max-width: 600px) {{
      .email-card {{ width: 100% !important; }}
      .email-content {{ padding: 28px 20px !important; }}
      .otp-code {{ font-size: 28px !important; letter-spacing: 5px !important; }}
    }}
  </style>
</head>
<body style="margin:0; padding:0; background-color:#f8fafc; color:#1e293b; font-family:Arial, Helvetica, sans-serif;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#f8fafc;">
    <tr>
      <td align="center" style="padding:32px 16px;">
        <table role="presentation" class="email-card" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%; max-width:600px; background-color:#ffffff; border:1px solid #e2e8f0; border-radius:16px; overflow:hidden;">
          <tr>
            <td align="center" style="padding:28px 24px; background-color:#4338ca; background-image:linear-gradient(120deg,#4338ca 0%,#2563eb 100%); color:#ffffff; font-size:24px; font-weight:700; letter-spacing:0.3px;">
              UniXchange
            </td>
          </tr>
          <tr>
            <td class="email-content" style="padding:40px 48px 32px;">
              <h1 style="margin:0 0 14px; color:#0f172a; font-size:24px; line-height:1.3; font-weight:700;">{html.escape(title)}</h1>
              <p style="margin:0 0 28px; color:#475569; font-size:16px; line-height:1.6;">{html.escape(description)}</p>
              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 24px; background-color:#f1f5f9; border:1px solid #e2e8f0; border-radius:12px;">
                <tr>
                  <td align="center" style="padding:22px 12px;">
                    <span class="otp-code" style="color:#312e81; font-family:'Courier New', Courier, monospace; font-size:32px; font-weight:700; letter-spacing:6px; white-space:nowrap;">{html.escape(otp_text)}</span>
                  </td>
                </tr>
              </table>
              <p style="margin:0; color:#64748b; font-size:14px; line-height:1.6;">{html.escape(notice)}</p>
            </td>
          </tr>
          <tr>
            <td align="center" style="padding:20px 24px; border-top:1px solid #e2e8f0; color:#94a3b8; font-size:12px; line-height:1.5;">
              {html.escape(footer)}
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>"""
    return _send_smtp_message(
        receiver_email,
        title,
        plain_body,
        html_body,
    )


def send_otp_email(
    receiver_email: str,
    otp: str,
    purpose: str = "password_reset",
) -> bool:
    """Send an OTP email without logging the OTP or SMTP credentials."""
    return bool(
        send_otp_email_diagnostic(receiver_email, otp, purpose=purpose)["success"]
    )



def send_verification_status_email(receiver_email: str, status: str, reason: Optional[str] = None) -> bool:
    """Send a branded verification status email with a plain-text fallback."""
    normalized_sender_email = os.getenv("SENDER_EMAIL", SENDER_EMAIL).strip()
    normalized_sender_password = os.getenv("SENDER_PASSWORD", SENDER_PASSWORD).strip().replace(" ", "")

    try:
        if not _notifications_enabled(None, "emailNotifs"):
            email_logger.warning("Verification email was not sent because email notifications are disabled.")
            return False
        if not receiver_email:
            return False
        if not normalized_sender_email or not normalized_sender_password:
            email_logger.error(
                "Verification email was not sent: SENDER_EMAIL or SENDER_PASSWORD is missing from Backend/.env."
            )
            return False

        greeting = "Hello,"
        paragraphs = ["Your UniXchange account verification status has been updated."]
        if reason:
            paragraphs.append(f"Reason: {reason}")
        details_table = {
            "Status": status,
            "Date": datetime.now(timezone.utc).strftime("%b %d, %Y").replace(" 0", " "),
        }
        action_button = {
            "label": "View Account",
            "url": urljoin(FRONTEND_BASE_URL.rstrip("/") + "/", ""),
        }

        msg = MIMEMultipart("alternative")
        msg["Subject"] = "Campus Marketplace Verification Update"
        msg["From"] = formataddr(("UniXchange Security", normalized_sender_email))
        msg["Reply-To"] = formataddr(("UniXchange Support", normalized_sender_email))
        msg["To"] = receiver_email
        msg.attach(MIMEText(
            render_system_email_text(
                "Verification Update",
                greeting,
                paragraphs,
                badge=status,
                details_table=details_table,
                action_button=action_button,
            ),
            "plain",
            "utf-8",
        ))
        msg.attach(MIMEText(
            render_system_email(
                "Verification Update",
                greeting,
                paragraphs,
                badge=status,
                details_table=details_table,
                action_button=action_button,
            ),
            "html",
            "utf-8",
        ))

        context = ssl.create_default_context()
        with _IPv4SMTP_SSL(
            "smtp.gmail.com",
            465,
            context=context,
            timeout=15,
        ) as server:
            server.login(normalized_sender_email, normalized_sender_password)
            server.sendmail(normalized_sender_email, receiver_email, msg.as_string())

        return True
    except Exception as e:
        email_logger.exception(f"Failed to send verification email to {receiver_email}: {e}")
        return False


