# 1. የተማሪዎች ምዝገባ ኤፒአይ (POST /api/register)
@app.post("/api/register", status_code=status.HTTP_201_CREATED)
def register_student(student_data: StudentRegister, db: Session = Depends(get_db)):
    security = get_security_settings(db)
    student_verification_defaults = DEFAULT_SETTINGS_BLOCKS["studentVerification"]
    allowed_email_domain = str(_get_setting_value(
        db,
        "studentVerification",
        "allowedEmailDomain",
        student_verification_defaults["allowedEmailDomain"],
    ) or "").strip().lstrip("@").lower()
    require_university_email = _setting_bool(_get_setting_value(
        db,
        "studentVerification",
        "requireUniversityEmail",
        student_verification_defaults["requireUniversityEmail"],
    ), student_verification_defaults["requireUniversityEmail"])
    auto_approve_students = _setting_bool(_get_setting_value(
        db,
        "studentVerification",
        "autoApproveStudents",
        student_verification_defaults["autoApproveStudents"],
    ), student_verification_defaults["autoApproveStudents"])

    if require_university_email:
        email_parts = student_data.email.strip().rsplit("@", 1)
        email_domain = email_parts[1].lower() if len(email_parts) == 2 else ""
        if email_domain != allowed_email_domain:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Registration failed. Please use your official university email "
                    f"ending with @{allowed_email_domain}"
                ),
            )

    minimum_password_length = security.min_password_length
    if len(student_data.password) < minimum_password_length:
        raise HTTPException(status_code=400, detail=f"Password must be at least {minimum_password_length} characters.")

    existing_id = db.query(Student).filter(Student.student_id == student_data.student_id).first()
    if existing_id:
        raise HTTPException(status_code=400, detail="Student ID is already registered.")

    existing_email = db.query(Student).filter(Student.email == student_data.email).first()
    if existing_email:
        raise HTTPException(status_code=400, detail="Email is already registered.")

    hashed_password = hash_password(student_data.password)

    db_student = Student(
        name=student_data.name,
        student_id=student_data.student_id,
        email=student_data.email,
        phone=student_data.phone,
        password=hashed_password,
        college=student_data.college,
        department=student_data.department,
        wallet_balance=Decimal("0.00"),
        is_verified=auto_approve_students,
        status="Pending Verification" if security.require_student_verification else "Active",
    )
    db.add(db_student)
    db.flush()

    wallet = Wallet(
        student_id=db_student.student_id,
        balance=Decimal("0.00"),
    )
    db.add(wallet)
    db_student.wallet = wallet
    db.commit()
    db.refresh(db_student)

    return {
        "message": "Registration submitted for verification." if security.require_student_verification else "Success",
        "user": {"name": db_student.name, "studentId": db_student.student_id},
        "requires_verification": security.require_student_verification,
    }


# 2. የጋራ የሎጊን ኤፒአይ ኤንድፖይንት (POST /api/login)

@app.post("/api/login")
@app.post("/api/auth/login")
def login_user(data: LoginRequest, request: Request, db: Session = Depends(get_db)):
    security = get_security_settings(db)
    identifier = _login_identifier(data.id_or_email)

    # 2.1 Check the administrator table first
    normalized_id = _login_identifier(data.id_or_email)

    admin = db.query(Admin).filter(
        or_(
            func.lower(Admin.username) == normalized_id,
            func.lower(Admin.email) == normalized_id,
        )
    ).first()

    if _is_email_identifier(normalized_id):
        student = db.query(Student).filter(
            func.lower(Student.email) == normalized_id
        ).first()
    else:
        student = db.query(Student).filter(
            func.lower(Student.student_id) == normalized_id
        ).first()

    attempt_identifier = (
        f"admin:{admin.id}" if admin
        else f"student:{student.student_id.lower()}" if student
        else identifier
    )
    try:
        _check_login_lock(db, attempt_identifier, security)
    except HTTPException:
        _record_auth_login(
            db,
            request,
            success=False,
            actor_name=identifier,
            actor_id=admin.id if admin else student.student_id if student else None,
            actor_role="admin" if admin else "student" if student else "unknown",
            identifier=identifier,
            reason="Account temporarily locked after repeated failed login attempts",
            severity="CRITICAL",
            admin_id=admin.id if admin else None,
            entity_id=admin.id if admin else student.id if student else None,
        )
        db.commit()
        raise

    admin_locked_until = (
        _as_utc_datetime(admin.locked_until) if admin else None
    )

    if (
        admin is not None
        and admin_locked_until
        and admin_locked_until > datetime.now(timezone.utc)
    ):
        _record_auth_login(
            db,
            request,
            success=False,
            actor_name=identifier,
            actor_id=admin.id,
            actor_role="admin",
            identifier=identifier,
            reason="Administrator account is temporarily locked",
            severity="CRITICAL",
            admin_id=admin.id,
            entity_id=admin.id,
        )
        _record_admin_login_event(db, admin.id, "login_locked", request)
        db.commit()
        retry_at = admin_locked_until.strftime("%Y-%m-%d %H:%M:%S UTC")
        raise HTTPException(
            status_code=429,
            detail=(
                "Administrator account is temporarily locked. "
                f"Try again at {retry_at}."
            ),
        )

    if admin and verify_password(data.password, admin.password_hash):
        if str(admin.status or "").strip().lower() != "active":
            _record_auth_login(
                db,
                request,
                success=False,
                actor_name=identifier,
                actor_id=admin.id,
                actor_role="admin",
                identifier=identifier,
                reason="Administrator account is inactive",
                admin_id=admin.id,
                entity_id=admin.id,
            )
            db.commit()
            raise HTTPException(status_code=403, detail="This administrator account is inactive.")
        admin.failed_login_attempts = 0
        admin.locked_until = None
        _reset_login_attempts(db, attempt_identifier)

        avatar_url = _get_avatar_url(admin, f"{admin.username}.jpg")
        require_admin_2fa = get_security_settings(db).admin_2fa

        admin_2fa_configured = bool(
            admin.two_factor_enabled
            and _decrypt_totp_secret(admin.two_factor_secret)
        )

        if not _admin_2fa_disabled() and (require_admin_2fa or admin_2fa_configured):
            challenge_token = _create_admin_login_challenge(db, admin)
            db.commit()

            return {
                "role": "admin",
                "requires_2fa": admin_2fa_configured,
                "requires_2fa_setup": not admin_2fa_configured,
                "challenge_token": challenge_token,
                "email_code_available": (
                    admin_2fa_configured
                    and _admin_login_email_is_configured()
                ),
                "remaining_backup_codes": (
                    _admin_backup_codes_remaining(db, admin)
                ),
            }

        # Admin login without 2FA
        token = _create_session_token(
            admin.username,
            "admin",
            SESSION_TOKEN_TIMEOUT_MINUTES,
            _get_session_secret(),
        )

        admin_session, token = _create_or_reuse_admin_session(db, admin, token, request)

        _record_admin_login_event(
            db,
            admin.id,
            "login_success",
            request,
            admin_session_id=admin_session.id,
        )
        _record_auth_login(
            db,
            request,
            success=True,
            actor_name=admin.full_name or admin.username,
            actor_id=admin.id,
            actor_role="admin",
            admin_id=admin.id,
            entity_id=admin.id,
        )

        db.commit()

        return {
            "role": "admin",
            "access_token": token,
            "user": {
                "name": admin.full_name or admin.username,
                "username": admin.username,
                "email": admin.email,
                "avatar_url": avatar_url,
                "avatarUrl": avatar_url,
            },
        }

    # Maintenance mode check
    if _setting_bool(
        _get_setting_value(db, "maintenance", "maintenanceMode", False)
    ):
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail=_get_setting_value(
                db,
                "maintenance",
                "maintenanceMessage",
                "Marketplace maintenance in progress.",
            ),
        )

    # 2.2 Check the student table
    if student and verify_password(data.password, student.password):
        if security.require_student_verification and not student.is_verified:
            _record_auth_login(
                db,
                request,
                success=False,
                actor_name=identifier,
                actor_id=student.student_id,
                actor_role="student",
                identifier=identifier,
                reason="Invalid password or unverified account",
                entity_id=student.id,
            )
            _record_failed_login(db, attempt_identifier, security)
            raise HTTPException(
                status_code=403,
                detail="Student verification is required before login.",
            )

        _reset_login_attempts(db, attempt_identifier)
        avatar_url = _get_avatar_url(student, f"{student.student_id}.jpg")

        if student.two_factor_enabled:
            otp = f"{secrets.randbelow(900000) + 100000:06d}"

            previous_otps = db.query(PasswordReset).filter(
                func.lower(PasswordReset.email) == student.email.lower(),
                PasswordReset.purpose == "student_login",
                PasswordReset.is_used == False,
            ).all()
            for previous_otp in previous_otps:
                previous_otp.is_used = True
                previous_otp.delivery_status = "invalidated"

            db.add(PasswordReset(
                email=student.email,
                otp_hash=_password_reset_otp_hash(
                    student.email,
                    otp,
                    "student_login",
                ),
                purpose="student_login",
                expires_at=(
                    datetime.now(timezone.utc) + timedelta(minutes=10)
                ),
                is_used=False,
                delivery_status="sending",
            ))
            db.commit()

            email_sent = send_otp_email(
                student.email,
                otp,
                purpose="student_login",
            )
            login_otp = _latest_password_reset(
                db,
                student.email,
                purpose="student_login",
                lock_for_update=True,
            )
            if login_otp and not login_otp.is_used:
                login_otp.delivery_status = "sent" if email_sent else "failed"
                db.commit()

            if not email_sent:
                logging.getLogger("app.auth").warning(
                    "Student login OTP email could not be sent."
                )

            return {
                "status": "otp_required",
                "email": student.email,
                "message": (
                    "A verification code was sent to your email."
                    if email_sent
                    else (
                        "A verification code was generated, "
                        "but email delivery failed."
                    )
                ),
                "email_sent": email_sent,
                "dev_mode": not email_sent,
            }

        user_session = _create_user_session(db, student, request)

        token = _create_session_token(
            student.student_id,
            "student",
            SESSION_TOKEN_TIMEOUT_MINUTES,
            _get_session_secret(),
            session_id=user_session.id,
        )

        _record_auth_login(
            db,
            request,
            success=True,
            actor_name=student.name,
            actor_id=student.student_id,
            actor_role="student",
            entity_id=student.id,
        )
        db.commit()

        return {
            "role": "student",
            "access_token": token,
            "user": {
                "name": student.name,
                "studentId": student.student_id,
                "email": student.email,
                "avatarUrl": avatar_url,
                "is_verified": bool(student.is_verified),
                "two_factor_enabled": bool(student.two_factor_enabled),
                "has_password": bool(student.has_password),
            },
        }

    # Failed login handling
    failed_attempt = db.query(LoginAttempt).filter(
        LoginAttempt.identifier == attempt_identifier
    ).first()
    if admin:
        admin.failed_login_attempts = int(
            admin.failed_login_attempts or 0
        ) + 1

        if admin.failed_login_attempts >= security.max_login_attempts:
            admin.locked_until = (
                datetime.now(timezone.utc) + timedelta(minutes=15)
            )

            _record_admin_login_event(
                db, admin.id, "login_failed_locked", request
            )

            lockout_email_sent = bool(
                _send_smtp_message(
                    admin.email,
                    "Admin account locked",
                    f"Admin account locked after {security.max_login_attempts} failed login attempts",
                )["success"]
            )

            if not lockout_email_sent:
                logging.getLogger("app.auth").warning(
                    "Admin lockout notification email could not be sent."
                )
        else:
            _record_admin_login_event(
                db, admin.id, "login_failed", request
            )

    failure_count = (
        int(admin.failed_login_attempts or 0)
        if admin
        else int(failed_attempt.failed_attempts if failed_attempt else 0) + 1
    )
    _record_auth_login(
        db,
        request,
        success=False,
        actor_name=identifier,
        actor_id=admin.id if admin else student.student_id if student else None,
        actor_role="admin" if admin else "student" if student else "unknown",
        identifier=identifier,
        reason="Invalid password or unverified account",
        severity="CRITICAL" if failure_count >= security.max_login_attempts else "WARNING",
        admin_id=admin.id if admin else None,
        entity_id=admin.id if admin else student.id if student else None,
    )

    _record_failed_login(db, attempt_identifier, security)

    raise HTTPException(
        status_code=400,
        detail="Invalid ID/Email or Password.",
    )


@app.post("/api/admin/login/2fa/email-code")
def send_admin_login_two_factor_email_code(
    payload: AdminLoginTwoFactorEmailCodeRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    try:
        challenge, admin = _get_admin_login_challenge(db, payload.challenge_token)
        if challenge.setup_verified or not admin.two_factor_enabled or not _decrypt_totp_secret(admin.two_factor_secret):
            raise HTTPException(status_code=400, detail="Email verification is only available after authenticator setup.")
        if not admin.email or not str(admin.email).strip():
            raise HTTPException(status_code=400, detail="This administrator does not have a registered email address.")
        if not _admin_login_email_is_configured():
            _audit_admin_login_email_event(
                db,
                admin,
                request,
                "Admin 2FA Email Code Failed",
                "Email verification was requested but SMTP sender credentials are not configured.",
                "FAILURE",
            )
            db.commit()
            raise HTTPException(
                status_code=503,
                detail="Email verification is not configured. Add SENDER_EMAIL and SENDER_PASSWORD in Backend/.env.",
            )

        now = datetime.now(timezone.utc)
        now_naive = now.replace(tzinfo=None)
        last_sent = db.query(AdminLoginEmailCode).filter(
            AdminLoginEmailCode.admin_id == admin.id,
        ).order_by(AdminLoginEmailCode.sent_at.desc()).first()
        if last_sent:
            seconds_since_send = (now - _as_utc_datetime(last_sent.sent_at)).total_seconds()
            if seconds_since_send < 60:
                retry_after = max(1, 60 - int(seconds_since_send))
                _audit_admin_login_email_event(
                    db,
                    admin,
                    request,
                    "Admin 2FA Email Code Failed",
                    "Email verification resend was rate-limited by the 60-second cooldown.",
                    "FAILURE",
                )
                db.commit()
                raise HTTPException(
                    status_code=429,
                    detail=f"Wait {retry_after} seconds before requesting another email code.",
                    headers={"Retry-After": str(retry_after)},
                )

        hourly_count = db.query(AdminLoginEmailCode).filter(
            AdminLoginEmailCode.admin_id == admin.id,
            AdminLoginEmailCode.sent_at >= (now - timedelta(hours=1)).replace(tzinfo=None),
        ).count()
        if hourly_count >= 5:
            oldest_allowed = db.query(AdminLoginEmailCode.sent_at).filter(
                AdminLoginEmailCode.admin_id == admin.id,
                AdminLoginEmailCode.sent_at >= (now - timedelta(hours=1)).replace(tzinfo=None),
            ).order_by(AdminLoginEmailCode.sent_at.asc()).first()
            retry_after = 3600
            if oldest_allowed:
                retry_after = max(
                    1,
                    3600 - int((now - _as_utc_datetime(oldest_allowed[0])).total_seconds()),
                )
            _audit_admin_login_email_event(
                db,
                admin,
                request,
                "Admin 2FA Email Code Failed",
                "Email verification resend was rate-limited by the five-per-hour limit.",
                "FAILURE",
            )
            db.commit()
            raise HTTPException(
                status_code=429,
                detail="Email code request limit reached. Try again later.",
                headers={"Retry-After": str(retry_after)},
            )

        email_code = _generate_otp_code()
        email_code_record = AdminLoginEmailCode(
            admin_id=admin.id,
            challenge_id=challenge.challenge_id,
            code_hash=_hash_admin_login_email_code(email_code),
            failed_attempts=0,
            used=False,
            expires_at=(now + timedelta(minutes=10)).replace(tzinfo=None),
            sent_at=now_naive,
        )
        db.query(AdminLoginEmailCode).filter(
            AdminLoginEmailCode.challenge_id == challenge.challenge_id,
            AdminLoginEmailCode.used.is_(False),
        ).update({"used": True}, synchronize_session=False)
        db.add(email_code_record)
        db.commit()

        if not send_otp_email(
            admin.email,
            email_code,
            purpose="admin_login_2fa",
        ):
            email_code_record.used = True
            _audit_admin_login_email_event(
                db,
                admin,
                request,
                "Admin 2FA Email Code Failed",
                "SMTP delivery failed while sending an administrator login code.",
                "FAILURE",
            )
            db.commit()
            raise HTTPException(
                status_code=400,
                detail="Could not send an email verification code. Check SMTP configuration and try again.",
            )

        _audit_admin_login_email_event(
            db,
            admin,
            request,
            "Admin 2FA Email Code Sent",
            "Sent an administrator login verification code to the registered email address.",
            "SUCCESS",
        )
        db.commit()
        return {
            "sent": True,
            "masked_email": _mask_admin_email(admin.email),
            "resend_after_seconds": 60,
        }
    except HTTPException:
        raise
    except Exception:
        logger.exception("Unhandled admin login email-code request error")
        return JSONResponse(
            status_code=500,
            content={"detail": "Could not send an email verification code. Please try again."},
        )


@app.post("/api/admin/login/2fa")
def verify_admin_login_two_factor(
    payload: AdminLoginTwoFactorRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    challenge, admin = _get_admin_login_challenge(db, payload.challenge_token)
    if challenge.setup_verified:
        raise HTTPException(
            status_code=400,
            detail="Finish the authenticator setup to complete this login.",
        )
    if payload.method == "email":
        email_code = db.query(AdminLoginEmailCode).filter(
            AdminLoginEmailCode.challenge_id == challenge.challenge_id,
            AdminLoginEmailCode.admin_id == admin.id,
            AdminLoginEmailCode.used.is_(False),
        ).order_by(AdminLoginEmailCode.sent_at.desc()).with_for_update().first()
        candidate = str(payload.code or "").strip()
        if email_code is None:
            _audit_admin_login_email_event(
                db,
                admin,
                request,
                "Admin 2FA Email Code Failed",
                "Administrator attempted to verify an email code without an active code for this challenge.",
                "FAILURE",
            )
            _record_admin_login_challenge_failure(
                db,
                challenge,
                admin,
                request,
                "Administrator submitted an email verification code before one was issued for this challenge.",
            )

        salt, separator, expected_hash = str(email_code.code_hash).partition("$")
        provided_hash = _hash_admin_login_email_code(candidate, salt).partition("$")[2] if separator else ""
        is_valid_email_code = bool(
            email_code
            and not email_code.used
            and email_code.failed_attempts < 5
            and _as_utc_datetime(email_code.expires_at) > datetime.now(timezone.utc)
            and re.fullmatch(r"\d{6}", candidate)
            and hmac.compare_digest(provided_hash, expected_hash)
        )
        if not is_valid_email_code:
            if email_code and not email_code.used:
                email_code.failed_attempts += 1
                if email_code.failed_attempts >= 5:
                    email_code.used = True
            _audit_admin_login_email_event(
                db,
                admin,
                request,
                "Admin 2FA Email Code Failed",
                "Administrator submitted an invalid, expired, or previously used email verification code.",
                "FAILURE",
            )
            _record_admin_login_challenge_failure(
                db,
                challenge,
                admin,
                request,
                "Administrator submitted an invalid or expired email verification code.",
            )
        email_code.used = True
        _audit_admin_login_email_event(
            db,
            admin,
            request,
            "Admin 2FA Email Code Succeeded",
            "Administrator completed login verification using an email code.",
            "SUCCESS",
        )
    elif payload.method == "backup":
        if payload.code is not None or payload.backup_code is None:
            _record_admin_login_challenge_failure(
                db, challenge, admin, request, "A backup-code challenge must supply exactly one backup code."
            )
    elif payload.code is None or payload.backup_code is not None:
        _record_admin_login_challenge_failure(
            db, challenge, admin, request, "A login challenge must use exactly one authenticator or backup code."
        )

    valid_code = payload.method == "email"
    if payload.method == "authenticator":
        secret = _decrypt_totp_secret(admin.two_factor_secret)
        valid_code = bool(
            admin.two_factor_enabled
            and secret
            and re.fullmatch(r"\d{6}", payload.code.strip())
            and pyotp.TOTP(secret).verify(payload.code.strip(), valid_window=1)
        )
    elif payload.method == "backup":
        valid_code = bool(
            admin.two_factor_enabled
            and _decrypt_totp_secret(admin.two_factor_secret)
            and payload.backup_code
            and _consume_admin_backup_code(db, admin, payload.backup_code)
        )

    if payload.method != "email" and not valid_code:
        _record_admin_login_challenge_failure(
            db, challenge, admin, request, "Administrator submitted an invalid authenticator or backup code."
        )

    challenge.used = True
    result = _complete_admin_login(db, admin, request)
    db.commit()
    return result


@app.post("/api/admin/login/2fa/setup")
def start_admin_login_two_factor_setup(
    payload: AdminLoginTwoFactorCompleteRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    challenge, admin = _get_admin_login_challenge(db, payload.challenge_token)
    if challenge.setup_verified:
        raise HTTPException(status_code=400, detail="Authenticator setup is already verified.")
    if admin.two_factor_enabled and _decrypt_totp_secret(admin.two_factor_secret):
        raise HTTPException(status_code=400, detail="This administrator already has an authenticator configured.")

    secret = pyotp.random_base32()
    admin.two_factor_pending_secret = _encrypt_totp_secret(secret)
    provisioning_uri = pyotp.TOTP(secret).provisioning_uri(
        name=admin.email,
        issuer_name="Campus Market",
    )
    qr_buffer = io.BytesIO()
    qrcode.make(provisioning_uri).save(qr_buffer, kind="PNG")
    qr_code = base64.b64encode(qr_buffer.getvalue()).decode("ascii")
    db.add(AuditLog(
        admin_id=admin.id,
        action="Admin 2FA Login Setup Started",
        entity_type="Admin",
        entity_id=admin.id,
        description="Administrator started the required authenticator setup from a password challenge.",
        status="SUCCESS",
        ip_address=request.client.host if request.client else None,
    ))
    db.commit()
    return {
        "secret": secret,
        "qr_code": f"data:image/png;base64,{qr_code}",
        "message": "Scan the QR code, then enter the six-digit code to finish setup.",
    }


@app.post("/api/admin/login/2fa/setup/verify")
def verify_admin_login_two_factor_setup(
    payload: AdminLoginTwoFactorSetupRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    challenge, admin = _get_admin_login_challenge(db, payload.challenge_token)
    if challenge.setup_verified:
        raise HTTPException(status_code=400, detail="Authenticator setup is already verified.")
    secret = _decrypt_totp_secret(admin.two_factor_pending_secret)
    if (
        not secret
        or not re.fullmatch(r"\d{6}", payload.code.strip())
        or not pyotp.TOTP(secret).verify(payload.code.strip(), valid_window=1)
    ):
        _record_admin_login_challenge_failure(
            db, challenge, admin, request, "Administrator submitted an invalid code during required 2FA setup."
        )

    admin.two_factor_secret = _encrypt_totp_secret(secret)
    admin.two_factor_pending_secret = None
    admin.two_factor_enabled = True
    db.query(AdminBackupCode).filter(
        AdminBackupCode.admin_id == admin.id,
    ).update({"used": True}, synchronize_session=False)
    backup_codes = [secrets.token_hex(5).upper() for _ in range(8)]
    admin.backup_codes = json.dumps([_hash_admin_backup_code(code) for code in backup_codes])
    db.add_all([
        AdminBackupCode(admin_id=admin.id, code_hash=_hash_admin_backup_code(code))
        for code in backup_codes
    ])
    challenge.setup_verified = True
    db.add(AuditLog(
        admin_id=admin.id,
        action="Admin 2FA Login Setup Verified",
        entity_type="Admin",
        entity_id=admin.id,
        description="Administrator verified the authenticator and received one-time backup codes.",
        status="SUCCESS",
        ip_address=request.client.host if request.client else None,
    ))
    db.commit()
    return {
        "setup_verified": True,
        "backup_codes": backup_codes,
        "remaining_backup_codes": len(backup_codes),
        "message": "Save these backup codes. They will not be shown again.",
    }


@app.post("/api/admin/login/2fa/setup/complete")
def complete_admin_login_two_factor_setup(
    payload: AdminLoginTwoFactorCompleteRequest,
    request: Request,
    db: Session = Depends(get_db),
):
    challenge, admin = _get_admin_login_challenge(db, payload.challenge_token)
    if not challenge.setup_verified or not admin.two_factor_enabled or not _decrypt_totp_secret(admin.two_factor_secret):
        raise HTTPException(status_code=400, detail="Verify your authenticator and save the backup codes first.")
    challenge.used = True
    result = _complete_admin_login(db, admin, request)
    db.commit()
    return result


def _redact_oauth_log_value(value: Optional[str], payload: dict) -> str:
    safe_value = str(value or "")
    sensitive_values = (
        payload.get("code"),
        payload.get("state"),
        payload.get("client_secret"),
        payload.get("code_verifier"),
        payload.get("access_token"),
        payload.get("refresh_token"),
        payload.get("id_token"),
    )
    for secret in sensitive_values:
        if secret:
            safe_value = safe_value.replace(str(secret), "[REDACTED]")
    safe_value = re.sub(
        r"([?&](?:code|state|access_token|refresh_token|id_token|client_secret|code_verifier)=)[^&\s]+",
        r"\1[REDACTED]",
        safe_value,
        flags=re.IGNORECASE,
    )
    return " ".join(safe_value.split())[:500]


async def _exchange_oauth_code(
    token_url: str,
    payload: dict,
    *,
    provider: str = "OAuth",
    redirect_uri: Optional[str] = None,
) -> dict:
    auth_logger = logging.getLogger("app.auth")
    safe_redirect_uri = _redact_oauth_log_value(redirect_uri, payload)
    auth_logger.info(
        "%s token exchange request: redirect_uri=%s",
        provider,
        safe_redirect_uri,
    )
    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            response = await client.post(token_url, data=payload)
    except httpx.RequestError as error:
        auth_logger.warning(
            "%s token exchange failed: status=unavailable error=provider_unavailable "
            "error_description=%s redirect_uri=%s exception_type=%s",
            provider,
            _redact_oauth_log_value(str(error), payload),
            safe_redirect_uri,
            type(error).__name__,
        )
        raise HTTPException(
            status_code=502,
            detail="The server could not reach the OAuth provider. Check backend internet access and try again.",
        ) from error

    try:
        token_data = (
            response.json()
            if response.headers.get("content-type", "").startswith("application/json")
            else {}
        )
    except ValueError as error:
        auth_logger.warning(
            "%s token exchange returned invalid JSON: status=%s error=invalid_json "
            "error_description=%s redirect_uri=%s",
            provider,
            response.status_code,
            "Provider response was not valid JSON.",
            safe_redirect_uri,
        )
        raise OAuthTokenExchangeError(
            status_code=502,
            provider_error=None,
            error_description="Provider response was not valid JSON.",
            detail="The OAuth provider returned an invalid token response.",
        ) from error
    if not isinstance(token_data, dict):
        token_data = {}
    if not response.is_success or not token_data.get("access_token"):
        provider_error_value = token_data.get("error")
        description_value = token_data.get("error_description")
        provider_error = str(provider_error_value) if provider_error_value else None
        error_description = str(description_value) if description_value else None
        safe_error = _redact_oauth_log_value(provider_error, payload)
        safe_description = _redact_oauth_log_value(error_description, payload)
        auth_logger.warning(
            "%s token exchange rejected: status=%s error=%s error_description=%s redirect_uri=%s",
            provider,
            response.status_code,
            safe_error or "unspecified",
            safe_description or "unspecified",
            safe_redirect_uri,
        )
        if provider_error == "invalid_client":
            raise OAuthTokenExchangeError(
                status_code=503,
                provider_error=provider_error,
                error_description=error_description,
                detail="Google OAuth client configuration is invalid. Check GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET.",
            )
        if provider_error == "redirect_uri_mismatch":
            raise OAuthTokenExchangeError(
                status_code=503,
                provider_error=provider_error,
                error_description=error_description,
                detail="Google OAuth redirect URI configuration does not match Google Cloud Console.",
            )
        raise OAuthTokenExchangeError(
            status_code=400,
            provider_error=provider_error,
            error_description=error_description,
            detail="The OAuth authorization code is invalid or expired.",
        )
    return token_data


def _google_oauth_settings() -> tuple[str, str, str]:
    client_id = os.getenv("GOOGLE_CLIENT_ID", "").strip()
    # Google client secrets cannot contain whitespace copied from a formatted value.
    client_secret = re.sub(r"\s+", "", os.getenv("GOOGLE_CLIENT_SECRET", ""))
    redirect_uri = (
        os.getenv("GOOGLE_REDIRECT_URI", "").strip()
        or GOOGLE_REDIRECT_URI_DEFAULT
    )
    missing = [
        name for name, value in (
            ("GOOGLE_CLIENT_ID", client_id),
            ("GOOGLE_CLIENT_SECRET", client_secret),
            ("GOOGLE_REDIRECT_URI", redirect_uri),
        ) if not value
    ]
    if missing:
        raise RuntimeError(
            "Google OAuth is not configured. Missing environment variables: "
            + ", ".join(missing)
        )
    return client_id, client_secret, redirect_uri


def _oauth_frontend_url() -> str:
    return (os.getenv("FRONTEND_URL") or "http://localhost:5173").strip().rstrip("#")


def _google_oauth_frontend_redirect(error: Optional[str] = None, domain: Optional[str] = None) -> RedirectResponse:
    frontend_url = urlsplit(_oauth_frontend_url())
    login_path = frontend_url.path.rstrip("/")
    if not login_path.endswith("/login"):
        login_path = f"{login_path}/login"
    query = {"oauth": "success"} if error is None else {"error": error}
    if domain:
        query["domain"] = domain
    return RedirectResponse(
        url=urlunsplit((
            frontend_url.scheme,
            frontend_url.netloc,
            login_path,
            urlencode(query),
            "",
        )),
        status_code=303,
    )


def _log_google_oauth_failure(reason: str) -> None:
    logging.getLogger("app.auth").warning("Google OAuth callback failed: reason=%s", reason)


class GoogleOAuthPolicyError(Exception):
    def __init__(self, code: str, domain: Optional[str] = None):
        self.code = code
        self.domain = domain


def _consume_google_oauth_state(db: Session, state: Optional[str]) -> Optional[str]:
    auth_logger = logging.getLogger("app.auth")
    state_record = (
        db.query(GoogleOAuthState).filter(GoogleOAuthState.state == state).first()
        if state else None
    )
    if not state_record:
        auth_logger.warning("Google OAuth state rejected: reason=unknown")
        return None

    now = datetime.now(timezone.utc)
    created_at = _as_utc_datetime(state_record.created_at)
    if created_at is None or created_at < now - GOOGLE_OAUTH_STATE_TTL:
        auth_logger.warning("Google OAuth state rejected: reason=expired")
        return None
    if state_record.used:
        auth_logger.warning("Google OAuth state rejected: reason=reused")
        return None

    verifier = state_record.verifier
    claimed_rows = db.query(GoogleOAuthState).filter(
        GoogleOAuthState.id == state_record.id,
        GoogleOAuthState.used.is_(False),
        GoogleOAuthState.created_at >= (now - GOOGLE_OAUTH_STATE_TTL).replace(tzinfo=None),
    ).update({"used": True}, synchronize_session=False)
    if claimed_rows != 1:
        db.rollback()
        auth_logger.warning("Google OAuth state rejected: reason=reused")
        return None
    db.commit()
    return verifier


def _oauth_cookie_secure() -> bool:
    frontend = urlsplit(_oauth_frontend_url())
    if frontend.scheme.lower() == "http" and frontend.hostname in {"localhost", "127.0.0.1", "::1"}:
        return False

    configured = os.getenv("COOKIE_SECURE")
    if configured is not None:
        return configured.strip().lower() in {"1", "true", "yes", "on"}
    return frontend.scheme.lower() == "https"


def _create_secure_session_for_student(
    student: Student,
    response: Response,
    db: Session,
    request: Optional[Request] = None,
    *,
    location: str,
) -> dict:
    user_session = _create_user_session(db, student, request, location=location)
    token = _create_session_token(
        student.student_id,
        "student",
        SESSION_TOKEN_TIMEOUT_MINUTES,
        _get_session_secret(),
        session_id=user_session.id,
    )
    _record_auth_login(
        db,
        request,
        success=True,
        actor_name=student.name,
        actor_id=student.student_id,
        actor_role="student",
        login_method="OAuth",
        entity_id=student.id,
    )
    db.commit()
    response.set_cookie(
        key="session_token",
        value=token,
        max_age=SESSION_TOKEN_TIMEOUT_MINUTES * 60,
        httponly=True,
        secure=_oauth_cookie_secure(),
        samesite="none" if _oauth_cookie_secure() else "lax",
        path="/",
    )

    avatar_url = _get_avatar_url(student, f"{student.student_id}.jpg")

    return {
        "role": "student",
        "access_token": token,
        "user": {
            "name": student.name,
            "studentId": student.student_id,
            "student_id": student.student_id,
            "email": student.email,
            "avatarUrl": avatar_url,
            "is_verified": bool(student.is_verified),
            "two_factor_enabled": bool(student.two_factor_enabled),
            "has_password": bool(student.has_password),
        },
    }


def _get_or_create_oauth_student(email: str, name: Optional[str], db: Session) -> Student:
    normalized_email = email.strip().lower()
    student = db.query(Student).filter(func.lower(Student.email) == normalized_email).first()
    if student:
        security = get_security_settings(db)
        if security.require_student_verification and not student.is_verified:
            raise GoogleOAuthPolicyError("account_pending")
        return student

    security = get_security_settings(db)
    student_verification_defaults = DEFAULT_SETTINGS_BLOCKS["studentVerification"]
    require_university_email = _setting_bool(
        _get_setting_value(
            db,
            "studentVerification",
            "requireUniversityEmail",
            student_verification_defaults["requireUniversityEmail"],
        ),
        student_verification_defaults["requireUniversityEmail"],
    )
    allowed_email_domain = str(
        _get_setting_value(
            db,
            "studentVerification",
            "allowedEmailDomain",
            student_verification_defaults["allowedEmailDomain"],
        )
        or ""
    ).strip().lstrip("@").lower()
    auto_approve_students = _setting_bool(
        _get_setting_value(
            db,
            "studentVerification",
            "autoApproveStudents",
            student_verification_defaults["autoApproveStudents"],
        ),
        student_verification_defaults["autoApproveStudents"],
    )
    email_domain = normalized_email.rsplit("@", 1)[-1]
    if require_university_email and email_domain != allowed_email_domain:
        raise GoogleOAuthPolicyError("domain_not_allowed", allowed_email_domain)

    for _ in range(5):
        generated_student_id = f"OAUTH-{secrets.token_hex(5).upper()}"
        if not db.query(Student).filter(Student.student_id == generated_student_id).first():
            break
    else:
        raise HTTPException(status_code=500, detail="Could not create an OAuth student identity.")

    student = Student(
        name=(name or normalized_email.split("@", 1)[0]).strip()[:100],
        student_id=generated_student_id,
        email=normalized_email,
        has_password=False,
        password=hash_password(secrets.token_urlsafe(32)),
        college="Pending profile",
        department="Pending profile",
        wallet_balance=Decimal("0.00"),
        status="Pending Verification" if security.require_student_verification else "Active",
        is_verified=auto_approve_students,
    )
    db.add(student)
    db.flush()
    db.add(Wallet(student_id=student.student_id, balance=Decimal("0.00")))
    db.commit()
    db.refresh(student)
    if security.require_student_verification and not student.is_verified:
        raise GoogleOAuthPolicyError("account_pending")
    return student


@app.get("/auth/google/login")
def google_login(db: Session = Depends(get_db)):
    try:
        client_id, _, redirect_uri = _google_oauth_settings()
    except RuntimeError as error:
        raise HTTPException(status_code=503, detail=str(error)) from error
    state = secrets.token_urlsafe(32)
    verifier = secrets.token_urlsafe(48)
    challenge = base64.urlsafe_b64encode(
        hashlib.sha256(verifier.encode("ascii")).digest()
    ).rstrip(b"=").decode("ascii")
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    db.query(GoogleOAuthState).filter(
        GoogleOAuthState.created_at < now - timedelta(hours=1)
    ).delete(synchronize_session=False)
    db.add(GoogleOAuthState(state=state, verifier=verifier, created_at=now))
    db.commit()
    authorization_url = "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode({
        "client_id": client_id,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": "openid email profile",
        "state": state,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
        "access_type": "online",
        "prompt": "select_account",
    })
    return RedirectResponse(url=authorization_url, status_code=307)


@app.get("/auth/google/callback")
async def google_callback(
    request: Request = None,
    code: Optional[str] = None,
    state: Optional[str] = None,
    error: Optional[str] = None,
    db: Session = Depends(get_db),
):
    verifier = _consume_google_oauth_state(db, state)
    if verifier is None:
        _log_google_oauth_failure("state_rejected")
        return _google_oauth_frontend_redirect("google_state_invalid")

    if error:
        _log_google_oauth_failure("google_denied")
        return _google_oauth_frontend_redirect("google_cancelled")
    if not code:
        _log_google_oauth_failure("missing_code")
        return _google_oauth_frontend_redirect("token_exchange_failed")
    try:
        client_id, client_secret, redirect_uri = _google_oauth_settings()
    except RuntimeError:
        _log_google_oauth_failure("oauth_not_configured")
        return _google_oauth_frontend_redirect("oauth_not_configured")

    try:
        token_data = await _exchange_oauth_code(
            "https://oauth2.googleapis.com/token",
            {
                "code": code,
                "code_verifier": verifier,
                "client_id": client_id,
                "client_secret": client_secret,
                "redirect_uri": redirect_uri,
                "grant_type": "authorization_code",
            },
            provider="Google",
            redirect_uri=redirect_uri,
        )
    except HTTPException as exchange_error:
        provider_error = getattr(exchange_error, "provider_error", None)
        error_code = {
            "invalid_grant": "google_invalid_grant",
            "redirect_uri_mismatch": "google_redirect_mismatch",
            "invalid_client": "google_invalid_client",
        }.get(
            provider_error,
            "google_provider_unavailable"
            if exchange_error.status_code == 502
            else "google_token_exchange_failed",
        )
        _log_google_oauth_failure(error_code)
        return _google_oauth_frontend_redirect(error_code)

    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            identity_response = await client.get(
                "https://openidconnect.googleapis.com/v1/userinfo",
                headers={"Authorization": f"Bearer {token_data['access_token']}"},
            )
    except httpx.RequestError:
        _log_google_oauth_failure("identity_provider_unavailable")
        return _google_oauth_frontend_redirect("identity_provider_unavailable")

    if not identity_response.is_success:
        _log_google_oauth_failure("identity_verification_failed")
        return _google_oauth_frontend_redirect("identity_verification_failed")
    profile = identity_response.json()
    if not profile.get("email") or profile.get("email_verified") is not True:
        _log_google_oauth_failure("email_not_verified")
        return _google_oauth_frontend_redirect("email_not_verified")

    try:
        student = _get_or_create_oauth_student(profile["email"], profile.get("name"), db)
    except GoogleOAuthPolicyError as policy_error:
        _log_google_oauth_failure(policy_error.code)
        return _google_oauth_frontend_redirect(policy_error.code, policy_error.domain)
    except HTTPException:
        _log_google_oauth_failure("account_unavailable")
        return _google_oauth_frontend_redirect("account_unavailable")

    response = _google_oauth_frontend_redirect()
    location = await resolve_ip_location(
        get_real_client_ip(request) if request else "127.0.0.1"
    )
    session_data = _create_secure_session_for_student(
        student, response, db, request, location=location
    )
    redirect_parts = urlsplit(response.headers["location"])
    response.headers["location"] = urlunsplit((
        redirect_parts.scheme,
        redirect_parts.netloc,
        redirect_parts.path,
        redirect_parts.query,
        urlencode({"access_token": session_data["access_token"]}),
    ))
    return response


@app.get("/api/auth/session")
def get_oauth_session(
    request: Request,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    session_token = request.cookies.get("session_token", "").strip()
    if authorization:
        student = _student_from_authorization(authorization, db)
        session_token = authorization.partition(" ")[-1].strip()
    elif session_token:
        student = _student_from_authorization(f"Bearer {session_token}", db)
    else:
        raise HTTPException(status_code=401, detail="No active student session.")
    return {
        "role": "student",
        "access_token": session_token,
        "user": {
            "name": student.name,
            "studentId": student.student_id,
            "student_id": student.student_id,
            "email": student.email,
            "is_verified": bool(student.is_verified),
            "two_factor_enabled": bool(student.two_factor_enabled),
        },
    }


@app.post("/api/auth/logout")
def logout_session(request: Request, response: Response, authorization: Optional[str] = Header(None), db: Session = Depends(get_db)):
    session_token = request.cookies.get("session_token", "").strip()
    if not session_token and authorization:
        scheme, separator, token = authorization.partition(" ")
        if separator and scheme.lower() == "bearer" and token.strip():
            session_token = token.strip()
    response.delete_cookie(key="session_token", path="/")
    if not session_token:
        return {"success": True}

    try:
        claims = _decode_student_jwt(session_token)
    except HTTPException:
        return {"success": True}

    try:
        _ensure_student_session_table(db)
        claimed_session_id = claims.get("session_id")
        if claimed_session_id:
            user_session = db.query(UserSession).filter(UserSession.id == str(claimed_session_id)).first()
            if user_session and user_session.revoked_at is None:
                user_session.revoked_at = datetime.now(timezone.utc)
        session = db.query(StudentSession).filter(StudentSession.session_token == session_token).first()
        if session:
            session.is_active = False
            session.last_active = datetime.now(timezone.utc)
        db.commit()
    except SQLAlchemyError:
        logger.exception("Failed to revoke session during logout.")
        try:
            db.rollback()
        except SQLAlchemyError:
            logger.exception("Failed to roll back the session during logout.")
    return {"success": True}


@app.post("/api/auth/google-callback")
async def google_oauth_callback(data: OAuthCallbackRequest, response: Response, request: Request, db: Session = Depends(get_db)):
    try:
        client_id, client_secret, configured_redirect_uri = _google_oauth_settings()
    except RuntimeError as error:
        raise HTTPException(status_code=503, detail=str(error)) from error
    if data.redirect_uri.strip() != configured_redirect_uri:
        raise HTTPException(status_code=400, detail="Invalid Google OAuth redirect URI.")

    token_data = await _exchange_oauth_code(
        "https://oauth2.googleapis.com/token",
        {
            "code": data.code,
            "code_verifier": data.code_verifier,
            "client_id": client_id,
            "client_secret": client_secret,
            "redirect_uri": configured_redirect_uri,
            "grant_type": "authorization_code",
        },
    )

    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            identity_response = await client.get(
                "https://openidconnect.googleapis.com/v1/userinfo",
                headers={"Authorization": f"Bearer {token_data['access_token']}"},
            )
    except httpx.RequestError as error:
        logging.getLogger("app.auth").error("Google userinfo request failed: %s", error)
        raise HTTPException(
            status_code=502,
            detail="The server could not reach Google identity services. Check backend internet access and try again.",
        ) from error

    if not identity_response.is_success:
        raise HTTPException(status_code=400, detail="Google identity verification failed.")
    profile = identity_response.json()
    if not profile.get("email") or profile.get("email_verified") is not True:
        raise HTTPException(status_code=400, detail="Google did not return a verified email address.")

    student = _get_or_create_oauth_student(profile["email"], profile.get("name"), db)
    location = await resolve_ip_location(get_real_client_ip(request))
    return _create_secure_session_for_student(
        student, response, db, request, location=location
    )


@app.post("/api/auth/microsoft-callback")
async def microsoft_oauth_callback(data: OAuthCallbackRequest, response: Response, request: Request, db: Session = Depends(get_db)):
    client_id = os.getenv("MICROSOFT_CLIENT_ID", "").strip()
    client_secret = os.getenv("MICROSOFT_CLIENT_SECRET", "").strip()
    configured_redirect_uri = os.getenv("MICROSOFT_REDIRECT_URI", "").strip()
    tenant = os.getenv("MICROSOFT_TENANT", "common").strip() or "common"
    if not client_id or not client_secret or not configured_redirect_uri:
        raise HTTPException(status_code=503, detail="Microsoft OAuth is not configured on the server.")
    if data.redirect_uri.strip() != configured_redirect_uri:
        raise HTTPException(status_code=400, detail="Invalid Microsoft OAuth redirect URI.")

    token_data = await _exchange_oauth_code(
        f"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token",
        {
            "code": data.code,
            "code_verifier": data.code_verifier,
            "client_id": client_id,
            "client_secret": client_secret,
            "redirect_uri": configured_redirect_uri,
            "grant_type": "authorization_code",
            "scope": "openid profile email User.Read",
        },
    )

    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            identity_response = await client.get(
                "https://graph.microsoft.com/v1.0/me?$select=displayName,mail,userPrincipalName",
                headers={"Authorization": f"Bearer {token_data['access_token']}"},
            )
    except httpx.RequestError as error:
        logging.getLogger("app.auth").error("Microsoft profile request failed: %s", error)
        raise HTTPException(status_code=502, detail="Microsoft identity service is unavailable.") from error

    if not identity_response.is_success:
        raise HTTPException(status_code=400, detail="Microsoft identity verification failed.")
    profile = identity_response.json()
    email = profile.get("mail") or profile.get("userPrincipalName")
    if not email:
        raise HTTPException(status_code=400, detail="Microsoft did not return an email address.")

    student = _get_or_create_oauth_student(email, profile.get("displayName"), db)
    location = await resolve_ip_location(get_real_client_ip(request))
    return _create_secure_session_for_student(
        student, response, db, request, location=location
    )


@app.post("/api/auth/verify-login-otp")
def verify_student_login_otp(request: StudentLoginOtpRequest, http_request: Request, db: Session = Depends(get_db)):
    email = _login_identifier(request.email)
    otp = request.otp_code.strip()
    if not otp.isdigit() or len(otp) != 6:
        logger.warning(
            "Student login OTP verification failed: email=%s, reason=%s, expires_at=%s, is_used=%s, purpose=%s, attempts=%s",
            email,
            "invalid code format",
            None,
            None,
            None,
            None,
        )
        _record_auth_login(
            db,
            http_request,
            success=False,
            actor_name=email,
            actor_id=None,
            actor_role="unknown",
            identifier=email,
            reason="Invalid student verification code format",
        )
        db.commit()
        raise HTTPException(status_code=400, detail="Invalid OTP format.")

    student = db.query(Student).filter(
        func.lower(func.trim(Student.email)) == email
    ).first()
    if not student:
        logger.warning(
            "Student login OTP verification failed: email=%s, reason=%s, expires_at=%s, is_used=%s, purpose=%s, attempts=%s",
            email,
            "student not found",
            None,
            None,
            None,
            None,
        )
        _record_auth_login(
            db,
            http_request,
            success=False,
            actor_name=email,
            actor_id=None,
            actor_role="unknown",
            identifier=email,
            reason="Invalid or expired student verification code",
        )
        db.commit()
        raise HTTPException(status_code=400, detail="Invalid or expired student verification code.")

    record = (
        db.query(PasswordReset)
        .filter(
            func.lower(func.trim(PasswordReset.email)) == email,
            PasswordReset.purpose.in_(("login", "student_login", "login_2fa")),
        )
        .order_by(PasswordReset.id.desc())
        .with_for_update()
        .first()
    )
    expires_at = _as_utc_datetime(record.expires_at) if record else None
    now = _utc_now()
    failure_reason = None

    if not record:
        failure_reason = "missing OTP record"
    elif record.verification_attempts >= 5:
        failure_reason = "max attempts exceeded"
    elif record.is_used:
        failure_reason = "code already used"
    elif record.delivery_status != "sent":
        failure_reason = f"delivery_status={record.delivery_status}"
    elif expires_at is None or expires_at <= now:
        failure_reason = "expired"
    elif not _password_reset_code_matches(db, record, otp):
        failure_reason = "invalid code"

    if failure_reason is not None:
        logger.warning(
            "Student login OTP verification failed: email=%s, reason=%s, expires_at=%s, is_used=%s, purpose=%s, attempts=%s",
            email,
            failure_reason,
            expires_at.isoformat() if expires_at else None,
            getattr(record, "is_used", None),
            getattr(record, "purpose", None),
            getattr(record, "verification_attempts", None),
        )
        _record_auth_login(
            db,
            http_request,
            success=False,
            actor_name=email,
            actor_id=student.student_id,
            actor_role="student",
            identifier=email,
            reason="Invalid or expired student verification code",
            entity_id=student.id,
        )
        db.commit()
        raise HTTPException(status_code=400, detail="Invalid or expired student verification code.")

    _reset_login_attempts(db, f"student:{student.student_id.lower()}")
    record.is_used = True
    user_session = _create_user_session(db, student, http_request)
    token = _create_session_token(
        student.student_id,
        "student",
        SESSION_TOKEN_TIMEOUT_MINUTES,
        _get_session_secret(),
        session_id=user_session.id,
    )
    _record_auth_login(
        db,
        http_request,
        success=True,
        actor_name=student.name,
        actor_id=student.student_id,
        actor_role="student",
        login_method="OTP",
        entity_id=student.id,
    )
    db.commit()
    return {
        "role": "student",
        "access_token": token,
        "user": {
            "name": student.name,
            "studentId": student.student_id,
            "email": student.email,
            "is_verified": bool(student.is_verified),
            "two_factor_enabled": bool(student.two_factor_enabled),
            "preferred_pickup_location": student.preferred_pickup_location,
        },
    }


@app.post("/api/login/verify-otp")
def verify_admin_login_otp(request: AdminLoginOtpRequest, http_request: Request, db: Session = Depends(get_db)):
    admin = db.query(Admin).filter(Admin.email.ilike(request.email.strip().lower())).first()
    if not admin:
        raise HTTPException(status_code=400, detail="Invalid or expired administrator verification code.")
    if (
        get_security_settings(db).admin_2fa
        or (admin.two_factor_enabled and _decrypt_totp_secret(admin.two_factor_secret))
    ):
        _record_auth_login(
            db,
            http_request,
            success=False,
            actor_name=admin.email,
            actor_id=admin.id,
            actor_role="admin",
            identifier=admin.email,
            reason="Rejected legacy OTP verification because this account requires the password-bound login challenge",
            admin_id=admin.id,
            entity_id=admin.id,
        )
        db.commit()
        raise HTTPException(status_code=400, detail="Use the active password login challenge to verify 2FA.")
    if admin.two_factor_enabled:
        admin = db.query(Admin).filter(Admin.id == admin.id).with_for_update().first()
        if not admin:
            raise HTTPException(status_code=400, detail="Invalid or expired administrator verification code.")
        second_factor_code = request.otp_code.strip()
        configured_secret = _decrypt_totp_secret(admin.two_factor_secret)
        valid_totp = bool(
            configured_secret
            and pyotp.TOTP(configured_secret).verify(second_factor_code, valid_window=1)
        )
        if valid_totp or _consume_admin_backup_code(db, admin, second_factor_code):
            token = _create_session_token(admin.username, "admin", SESSION_TOKEN_TIMEOUT_MINUTES, _get_session_secret())
            admin_session, token = _create_or_reuse_admin_session(db, admin, token, http_request)
            _record_admin_login_event(
                db, admin.id, "login_success_2fa", http_request, admin_session_id=admin_session.id
            )
            _record_auth_login(
                db,
                http_request,
                success=True,
                actor_name=admin.full_name or admin.username,
                actor_id=admin.id,
                actor_role="admin",
                login_method="two-factor verification",
                admin_id=admin.id,
                entity_id=admin.id,
            )
            db.commit()
            return {"role": "admin", "access_token": token, "user": {"name": admin.full_name or admin.username, "username": admin.username, "email": admin.email}, "remaining_backup_codes": _admin_backup_codes_remaining(db, admin)}
        if admin.two_factor_secret:
            db.rollback()
            raise HTTPException(status_code=400, detail="Invalid authenticator or backup code.")
    otp_record = _latest_password_reset(
        db,
        admin.email,
        purpose="admin_login",
        lock_for_update=True,
    )
    otp = request.otp_code.strip()
    if (
        not otp_record
        or otp_record.is_used
        or otp_record.expires_at < datetime.now(timezone.utc).replace(tzinfo=None)
        or otp_record.delivery_status != "sent"
        or not otp.isdigit()
        or len(otp) != 6
        or not _password_reset_code_matches(db, otp_record, otp)
    ):
        _record_auth_login(
            db,
            http_request,
            success=False,
            actor_name=admin.full_name or admin.username,
            actor_id=admin.id,
            actor_role="admin",
            identifier=admin.email,
            reason="Invalid or expired administrator verification code",
            admin_id=admin.id,
            entity_id=admin.id,
        )
        db.commit()
        raise HTTPException(status_code=400, detail="Invalid or expired administrator verification code.")
    otp_record.is_used = True
    token = _create_session_token(admin.username, "admin", SESSION_TOKEN_TIMEOUT_MINUTES, _get_session_secret())
    admin_session, token = _create_or_reuse_admin_session(db, admin, token, http_request)
    _record_admin_login_event(
        db, admin.id, "login_success_2fa", http_request, admin_session_id=admin_session.id
    )
    _record_auth_login(
        db,
        http_request,
        success=True,
        actor_name=admin.full_name or admin.username,
        actor_id=admin.id,
        actor_role="admin",
        login_method="two-factor verification",
        admin_id=admin.id,
        entity_id=admin.id,
    )
    db.commit()
    return {"role": "admin", "access_token": token, "user": {"name": admin.full_name or admin.username, "username": admin.username, "email": admin.email}}

# 2.3 የይለፍ ቃል መርሻ ኮድ መላኪያ (POST /api/auth/forgot-password)
PASSWORD_RESET_SEND_LIMIT = 5
PASSWORD_RESET_SEND_WINDOW = timedelta(hours=1)
PASSWORD_RESET_RESEND_COOLDOWN_SECONDS = 60


def _is_localhost_request(request: Optional[Request]) -> bool:
    client = request.client if request else None
    host = client.host.strip().lower().strip("[]") if client else ""
    return host in {"127.0.0.1", "localhost", "::1"}


def _password_reset_student(
    db: Session,
    identifier: str,
    lock_for_update: bool = False,
) -> Optional[Student]:
    normalized = _login_identifier(identifier)
    if _is_email_identifier(normalized):
        query = db.query(Student).filter(func.lower(Student.email) == normalized)
    else:
        query = db.query(Student).filter(func.lower(Student.student_id) == normalized)
    if lock_for_update:
        query = query.with_for_update()
    return query.first()


def _password_reset_otp_hash(
    email: str,
    otp: str,
    purpose: str = "password_reset",
) -> str:
    if purpose == "password_reset":
        message_value = f"{email.strip().lower()}:{otp}"
    else:
        message_value = f"{purpose}:{email.strip().lower()}:{otp}"
    message = message_value.encode("utf-8")
    return hmac.new(_get_session_secret().encode("utf-8"), message, hashlib.sha256).hexdigest()


def _latest_password_reset(
    db: Session,
    email: str,
    purpose: str = "password_reset",
    lock_for_update: bool = False,
) -> Optional[PasswordReset]:
    query = (
        db.query(PasswordReset)
        .filter(
            func.lower(PasswordReset.email) == email.strip().lower(),
            PasswordReset.purpose == purpose,
        )
        .order_by(PasswordReset.id.desc())
    )
    if lock_for_update:
        query = query.with_for_update()
    return query.first()


def _password_reset_code_matches(
    db: Session,
    reset_record: PasswordReset,
    otp: str,
) -> bool:
    if reset_record.verification_attempts >= 5:
        return False
    expected_hash = _password_reset_otp_hash(
        reset_record.email,
        otp,
        reset_record.purpose,
    )
    if hmac.compare_digest(reset_record.otp_hash, expected_hash):
        return True

    reset_record.verification_attempts += 1
    if reset_record.verification_attempts >= 5:
        reset_record.is_used = True
        reset_record.delivery_status = "invalidated"
    db.commit()
    return False


def _password_reset_rate_limit(
    db: Session,
    account_key: str,
    request_ip: str,
    now: datetime,
    include_ip_limit: bool = True,
) -> int:
    window_start = now - PASSWORD_RESET_SEND_WINDOW
    limit_scope = [PasswordResetRequest.account_key == account_key]
    if include_ip_limit:
        limit_scope.append(PasswordResetRequest.request_ip == request_ip)
    account_or_ip = or_(*limit_scope)
    latest = (
        db.query(PasswordResetRequest.requested_at)
        .filter(account_or_ip)
        .order_by(PasswordResetRequest.requested_at.desc())
        .first()
    )
    if latest:
        cooldown_remaining = PASSWORD_RESET_RESEND_COOLDOWN_SECONDS - int(
            (now - latest[0]).total_seconds()
        )
        if cooldown_remaining > 0:
            return cooldown_remaining

    account_count = db.query(PasswordResetRequest).filter(
        PasswordResetRequest.account_key == account_key,
        PasswordResetRequest.requested_at >= window_start,
    ).count()
    ip_count = (
        db.query(PasswordResetRequest)
        .filter(
            PasswordResetRequest.request_ip == request_ip,
            PasswordResetRequest.requested_at >= window_start,
        )
        .count()
        if include_ip_limit
        else 0
    )
    if max(account_count, ip_count) < PASSWORD_RESET_SEND_LIMIT:
        return 0

    oldest = (
        db.query(PasswordResetRequest.requested_at)
        .filter(account_or_ip, PasswordResetRequest.requested_at >= window_start)
        .order_by(PasswordResetRequest.requested_at.asc())
        .first()
    )
    if not oldest:
        return 0
    return max(1, int((oldest[0] + PASSWORD_RESET_SEND_WINDOW - now).total_seconds()))


def _clear_password_reset_rate_limit_history(db: Session) -> int:
    deleted_count = db.query(PasswordResetRequest).delete(synchronize_session=False)
    db.commit()
    return deleted_count


def _deliver_password_reset_email(
    reset_id: int,
    request_id: int,
    otp: str,
    purpose: str = "password_reset",
) -> None:
    db = SessionLocal()
    email_logger = logging.getLogger("app.auth.email")
    eligible_delivery_statuses = {"pending", "queued", "sending"}
    email_logger.info(
        "Starting OTP email background delivery purpose=%s reset_id=%s.",
        purpose,
        reset_id,
    )
    try:
        reset_record = (
            db.query(PasswordReset)
            .filter(PasswordReset.id == reset_id)
            .with_for_update()
            .first()
        )
        tracking = (
            db.query(PasswordResetRequest)
            .filter(PasswordResetRequest.id == request_id)
            .first()
        )
        if (
            not reset_record
            or not tracking
        ):
            email_logger.warning(
                "OTP email delivery skipped: reset or tracking row is missing reset_id=%s request_id=%s.",
                reset_id,
                request_id,
            )
            return
        if reset_record.is_used or reset_record.delivery_status == "invalidated":
            email_logger.info("OTP email delivery skipped because reset_id=%s is invalidated.", reset_id)
            tracking.delivery_status = "invalidated"
            db.commit()
            return
        if (
            reset_record.purpose != purpose
            or reset_record.delivery_status not in eligible_delivery_statuses
        ):
            email_logger.info(
                "OTP email delivery skipped because reset_id=%s is no longer queued.",
                reset_id,
            )
            return
        reset_record.delivery_status = "sending"
        tracking.delivery_status = "sending"
        db.commit()

        for attempt in range(1, 4):
            db.refresh(reset_record)
            db.refresh(tracking)
            expires_at = _as_utc_datetime(reset_record.expires_at)
            if (
                reset_record.is_used
                or reset_record.delivery_status not in eligible_delivery_statuses
                or (
                    attempt > 1
                    and (expires_at is None or expires_at <= _utc_now())
                )
            ):
                email_logger.info(
                    "OTP email retry stopped because reset_id=%s is no longer eligible "
                    "(is_used=%s reset_status=%s tracking_status=%s expires_at=%s).",
                    reset_id,
                    reset_record.is_used,
                    reset_record.delivery_status,
                    tracking.delivery_status,
                    reset_record.expires_at,
                )
                return

            if purpose == "password_reset":
                result = send_otp_email_diagnostic(reset_record.email, otp)
            else:
                result = send_otp_email_diagnostic(
                    reset_record.email,
                    otp,
                    purpose=purpose,
                )
            if result["success"]:
                db.refresh(reset_record)
                db.refresh(tracking)
                if reset_record.is_used:
                    reset_record.delivery_status = "invalidated"
                    tracking.delivery_status = "invalidated"
                else:
                    reset_record.delivery_status = "sent"
                    tracking.delivery_status = "sent"
                db.commit()
                email_logger.info(
                    "OTP email delivery status=%s purpose=%s receiver=%s.",
                    reset_record.delivery_status,
                    purpose,
                    reset_record.email,
                )
                return
            if attempt < 3:
                email_logger.warning(
                    "OTP email delivery attempt=%s failed purpose=%s receiver=%s stage=%s mode=%s; retrying.",
                    attempt,
                    purpose,
                    reset_record.email,
                    result.get("stage"),
                    result.get("mode"),
                )
                time_sleep(min(2 ** (attempt - 1), 4))

        db.refresh(reset_record)
        db.refresh(tracking)
        if reset_record.is_used:
            reset_record.delivery_status = "invalidated"
            tracking.delivery_status = "invalidated"
            db.commit()
            return
        reset_record.delivery_status = "failed"
        tracking.delivery_status = "failed"
        db.commit()
        print(
            f"OTP email delivery failed after 3 attempts purpose={purpose} "
            f"receiver={reset_record.email} stage={result.get('stage')} mode={result.get('mode')}.",
            flush=True,
        )
        email_logger.error(
            "OTP email delivery failed after 3 attempts purpose=%s receiver=%s stage=%s mode=%s.",
            purpose,
            reset_record.email,
            result.get("stage"),
            result.get("mode"),
        )
    except Exception:
        db.rollback()
        email_logger.exception("Failed to send OTP email")
        raise
    finally:
        db.close()


def _forgot_password_response(retry_after_seconds: int = 60) -> dict[str, Any]:
    return {
        "message": (
            "If the account exists, a verification code will be sent to its "
            "registered email address."
        ),
        "retry_after_seconds": max(1, retry_after_seconds),
    }


