@app.put("/api/admin/{admin_id}/permissions")
def update_admin_permissions(
    admin_id: int,
    payload: AdminPermissionsUpdate,
    request: Request,
    authorization: Optional[str] = Header(None),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    current_token = _extract_admin_token(authorization, session_token)
    requester, _ = _admin_for_session(db, current_token)
    target = db.query(Admin).filter(Admin.id == admin_id).first()
    if not target:
        raise HTTPException(status_code=404, detail="Admin profile not found.")

    requester_role = str(requester.role or "").strip().lower().replace("_", " ")
    is_super_admin = requester_role in {"super admin", "superadministrator"}
    if requester.id != target.id and not is_super_admin:
        raise HTTPException(status_code=403, detail="Only a Super Admin can edit another administrator's permissions.")

    invalid_keys = set(payload.permissions) - set(ADMIN_PERMISSION_KEYS)
    if invalid_keys:
        raise HTTPException(status_code=422, detail=f"Unsupported permission keys: {', '.join(sorted(invalid_keys))}")

    target.permissions = {
        key: bool(payload.permissions.get(key, False))
        for key in ADMIN_PERMISSION_KEYS
    }
    _add_admin_audit(
        db,
        requester,
        request,
        "Admin Permissions Updated",
        f"Updated permissions for administrator {target.username}.",
    )
    db.commit()
    db.refresh(target)
    return {"success": True, "admin_id": target.id, "permissions": _admin_permissions(target)}


@app.patch("/api/admin/me")
def update_current_admin_profile(
    payload: AdminProfileUpdate,
    request: Request,
    authorization: Optional[str] = Header(None),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    current_token = _extract_admin_token(authorization, session_token)
    admin, _ = _admin_for_session(db, current_token)

    username = (payload.username if payload.username is not None else admin.username).strip()
    email = (payload.email if payload.email is not None else admin.email).strip().lower()
    full_name = (payload.full_name if payload.full_name is not None else admin.full_name or "").strip()
    phone = (payload.phone if payload.phone is not None else admin.phone or "").strip()

    if payload.new_password:
        if not payload.current_password:
            raise HTTPException(status_code=400, detail="Current password is required to update the password.")
        if not verify_password(payload.current_password, admin.password_hash):
            raise HTTPException(status_code=400, detail="Current password is incorrect.")
        confirm_password = payload.confirm_password or ""
        if not secrets.compare_digest(payload.new_password, confirm_password):
            raise HTTPException(status_code=400, detail="New password and confirm password do not match.")
        _validate_admin_password(payload.new_password, _session_password_min_length(db))
        admin.password_hash = hash_password(payload.new_password)

    if username != admin.username:
        existing = db.query(Admin).filter(Admin.username == username).first()
        if existing and existing.id != admin.id:
            raise HTTPException(status_code=400, detail="Username is already in use.")
        admin.username = username
    if email != admin.email:
        existing = db.query(Admin).filter(Admin.email == email).first()
        if existing and existing.id != admin.id:
            raise HTTPException(status_code=400, detail="Email is already in use.")
        admin.email = email

    admin.full_name = full_name
    admin.phone = phone or None
    if payload.new_password or payload.logout_all_sessions:
        _revoke_admin_sessions(
            db,
            admin.id,
            "password_changed" if payload.new_password else "admin_forced",
            except_token=current_token,
        )

    db.commit()
    db.refresh(admin)
    _add_admin_audit(db, admin, request, "Admin Profile Updated", "Administrator updated personal information.")
    db.commit()

    return {
        "success": True,
        "message": "Profile updated successfully",
        "username": admin.username,
        "full_name": admin.full_name or "",
        "email": admin.email,
        "phone": admin.phone or "",
        "two_factor_enabled": bool(admin.two_factor_enabled),
    }


@app.put("/api/admin/profile")
def update_admin_profile(payload: AdminProfileUpdate, request: Request, db: Session = Depends(get_db)):
    admin = None
    if payload.current_session_token:
        admin, _ = _admin_for_session(db, payload.current_session_token)
    if not admin:
        admin = db.query(Admin).filter(Admin.username == payload.username).first()
    if not admin:
        admin = db.query(Admin).order_by(Admin.id.asc()).first()
    if not admin:
        raise HTTPException(status_code=404, detail="Admin profile not found.")

    username = (payload.username or admin.username).strip()
    email = (payload.email or admin.email).strip().lower()
    new_password = payload.new_password
    current_password = payload.current_password
    full_name = (payload.full_name if payload.full_name is not None else admin.full_name or admin.username).strip()
    phone = (payload.phone if payload.phone is not None else admin.phone or "").strip()

    if new_password:
        if not current_password:
            raise HTTPException(status_code=400, detail="Current password is required to update the password.")
        if not verify_password(current_password, admin.password_hash):
            raise HTTPException(status_code=400, detail="Current password is incorrect.")
        if not payload.confirm_password or not secrets.compare_digest(new_password, payload.confirm_password):
            raise HTTPException(status_code=400, detail="New password and confirm password do not match.")
        _validate_admin_password(new_password, _session_password_min_length(db))
        admin.password_hash = hash_password(new_password)

    admin.full_name = full_name
    admin.phone = phone or None

    if username and username != admin.username:
        existing = db.query(Admin).filter(Admin.username == username).first()
        if existing and existing.id != admin.id:
            raise HTTPException(status_code=400, detail="Username is already in use.")
        admin.username = username

    if email and email != admin.email:
        existing = db.query(Admin).filter(Admin.email == email).first()
        if existing and existing.id != admin.id:
            raise HTTPException(status_code=400, detail="Email is already in use.")
        admin.email = email

    current_token = payload.current_session_token
    if new_password or payload.logout_all_sessions:
        _revoke_admin_sessions(
            db,
            admin.id,
            "password_changed" if new_password else "admin_forced",
            except_token=current_token,
        )
    db.commit()
    db.refresh(admin)

    _add_admin_audit(db, admin, request, "Admin Profile Updated", "Administrator updated personal information.")
    if new_password:
        _record_admin_login_event(db, admin.id, "password_changed", request)
        _add_admin_audit(db, admin, request, "Admin Password Changed", "Administrator changed their password and terminated other sessions.")
    if payload.logout_all_sessions:
        _add_admin_audit(db, admin, request, "Admin Sessions Terminated", "Administrator requested logout from all other active sessions.")
    db.commit()

    return {
        "success": True,
        "message": "Profile updated successfully",
        "username": admin.username,
        "email": admin.email,
        "full_name": admin.full_name,
        "phone": admin.phone or "",
        "two_factor_enabled": bool(admin.two_factor_enabled),
    }


def _extract_admin_token(authorization: Optional[str], session_token: Optional[str]) -> str:
    if authorization:
        scheme, separator, credentials = authorization.partition(" ")
        if not separator or scheme.lower() != "bearer" or not credentials.strip():
            logging.getLogger("app.auth").warning("Admin auth rejected: authorization_header_invalid.")
            raise HTTPException(status_code=401, detail="Authorization header must use the Bearer scheme.")
        return credentials.strip()
    if session_token and session_token.strip():
        return session_token.strip()
    logging.getLogger("app.auth").warning("Admin auth rejected: token_missing.")
    raise HTTPException(status_code=401, detail="Provide an admin token using Authorization Bearer or session_token.")


def _decode_admin_jwt(session_token: str) -> dict:
    try:
        encoded_header, encoded_payload, encoded_signature = session_token.split(".")
        padding = lambda value: value + "=" * (-len(value) % 4)
        header = json.loads(base64.urlsafe_b64decode(padding(encoded_header)).decode())
        payload = json.loads(base64.urlsafe_b64decode(padding(encoded_payload)).decode())
        provided_signature = base64.urlsafe_b64decode(padding(encoded_signature))
    except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError, binascii.Error):
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_malformed.")
        raise HTTPException(status_code=401, detail="Invalid JWT token.")

    if not isinstance(header, dict) or not isinstance(payload, dict):
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_claims_invalid.")
        raise HTTPException(status_code=401, detail="Invalid JWT token.")
    if header.get("alg") != "HS256" or header.get("typ") != "JWT":
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_type_or_algorithm_mismatch.")
        raise HTTPException(status_code=401, detail="Unsupported JWT token.")
    session_secret = os.getenv("SESSION_SECRET", "").strip()
    if not session_secret:
        logging.getLogger("app.auth").error("Admin auth rejected: session_secret_missing.")
        raise HTTPException(status_code=401, detail="Invalid JWT token.")
    unsigned_token = f"{encoded_header}.{encoded_payload}"
    expected_signature = hmac.new(
        session_secret.encode(),
        unsigned_token.encode(),
        hashlib.sha256,
    ).digest()
    if not hmac.compare_digest(provided_signature, expected_signature):
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_signature_invalid.")
        raise HTTPException(status_code=401, detail="Invalid JWT signature.")
    if not payload.get("sub") or payload.get("role") != "admin":
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_subject_or_role_claim_invalid.")
        raise HTTPException(status_code=401, detail="JWT does not identify an administrator.")
    if not isinstance(payload.get("exp"), (int, float)) or payload["exp"] <= datetime.now(timezone.utc).timestamp():
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_expired_or_exp_missing.")
        raise HTTPException(
            status_code=401,
            detail={
                "code": "session_inactive",
                "message": "Admin session has expired. Please sign in again.",
            },
        )
    return payload


def _decode_student_jwt(token: str) -> dict:
    try:
        encoded_header, encoded_payload, encoded_signature = token.strip().split(".")
        padding = lambda value: value + "=" * (-len(value) % 4)
        header = json.loads(base64.urlsafe_b64decode(padding(encoded_header)).decode())
        payload = json.loads(base64.urlsafe_b64decode(padding(encoded_payload)).decode())
        provided_signature = base64.urlsafe_b64decode(padding(encoded_signature))
    except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError, binascii.Error):
        raise HTTPException(status_code=401, detail="Invalid JWT token.")

    session_secret = _get_session_secret()
    if header.get("alg") != "HS256" or header.get("typ") != "JWT":
        raise HTTPException(status_code=401, detail="Unsupported JWT token.")
    unsigned_token = f"{encoded_header}.{encoded_payload}"
    expected_signature = hmac.new(
        session_secret.encode(),
        unsigned_token.encode(),
        hashlib.sha256,
    ).digest()
    if not hmac.compare_digest(provided_signature, expected_signature):
        raise HTTPException(status_code=401, detail="Invalid JWT signature.")
    if payload.get("role") != "student" or not payload.get("sub"):
        raise HTTPException(status_code=401, detail="JWT does not identify a student.")
    if not isinstance(payload.get("exp"), (int, float)) or payload["exp"] <= datetime.now(timezone.utc).timestamp():
        raise HTTPException(status_code=401, detail="JWT token has expired.")
    return payload


def _ensure_student_session_table(db: Session) -> None:
    bind = db.bind or getattr(db, "get_bind", lambda: None)()
    if bind is None:
        return
    try:
        StudentSession.__table__.create(bind=bind, checkfirst=True)
    except Exception:
        pass


def _student_session_from_token(db: Session, token: str) -> StudentSession:
    _ensure_student_session_table(db)
    session = db.query(StudentSession).filter(StudentSession.session_token == token).first()
    if not session:
        jwt_payload = _decode_student_jwt(token)
        student_id = jwt_payload.get("sub")
        student = db.query(Student).filter(Student.student_id == student_id).first() if student_id else None
        if not student:
            raise HTTPException(status_code=401, detail="Student session is no longer valid.")
        session = StudentSession(
            student_id=student.student_id,
            session_token=token,
            is_active=True,
            last_active=datetime.now(timezone.utc),
        )
        db.add(session)
        db.flush()
    if not session.is_active:
        raise HTTPException(status_code=401, detail="Student session has been revoked.")
    now = datetime.now(timezone.utc)
    last_active = _as_utc_datetime(session.last_active)
    if last_active is None or now - last_active >= timedelta(minutes=get_security_settings(db).session_timeout):
        session.is_active = False
        db.commit()
        raise HTTPException(status_code=401, detail="Student session expired due to inactivity. Please sign in again.")
    session.last_active = now
    db.commit()
    return session


def _create_student_session(db: Session, student: Student, token: str, request: Optional[Request]) -> StudentSession:
    _ensure_student_session_table(db)
    user_agent = request.headers.get("user-agent") if request else None
    ip_address = request.client.host if request and request.client else None

    existing = db.query(StudentSession).filter(StudentSession.session_token == token).first()
    if existing:
        existing.student_id = student.student_id
        existing.ip_address = ip_address
        existing.device_browser = user_agent
        existing.is_active = True
        existing.last_active = datetime.now(timezone.utc)
        db.flush()
        return existing

    session = StudentSession(
        student_id=student.student_id,
        session_token=token,
        ip_address=ip_address,
        device_browser=user_agent,
        is_active=True,
        last_active=datetime.now(timezone.utc),
    )
    db.add(session)
    db.flush()
    return session


def _trusted_proxy_networks() -> List[Any]:
    configured = os.getenv("TRUSTED_PROXY_IPS", "").strip()
    networks = []
    for entry in configured.split(","):
        value = entry.strip()
        if value:
            try:
                networks.append(ipaddress.ip_network(value, strict=False))
            except ValueError as error:
                raise RuntimeError(f"Invalid TRUSTED_PROXY_IPS entry: {value}") from error
    return networks


def _request_client_ip(request: Optional[Request]) -> Optional[str]:
    if not request or not request.client:
        return None
    remote_host = request.client.host
    try:
        remote_ip = ipaddress.ip_address(remote_host)
    except ValueError:
        return remote_host or None

    if any(remote_ip in network for network in _trusted_proxy_networks()):
        forwarded_for = request.headers.get("x-forwarded-for", "")
        first_forwarded_ip = forwarded_for.split(",", 1)[0].strip()
        if first_forwarded_ip:
            try:
                return str(ipaddress.ip_address(first_forwarded_ip))
            except ValueError:
                logging.getLogger("app.auth").warning(
                    "Ignoring invalid first X-Forwarded-For value from a trusted proxy."
                )
    return str(remote_ip)


def get_real_client_ip(request: Request) -> str:
    x_forwarded_for = request.headers.get("x-forwarded-for")
    if x_forwarded_for:
        return x_forwarded_for.split(",")[0].strip()
    cf_ip = request.headers.get("cf-connecting-ip")
    if cf_ip:
        return cf_ip.strip()
    return request.client.host if request.client else "127.0.0.1"


async def resolve_ip_location(ip: str) -> str:
    try:
        ip_obj = ipaddress.ip_address(ip)
        if ip_obj.is_private or ip_obj.is_loopback:
            return "Local network"
    except ValueError:
        return "Local network"

    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            response = await client.get(
                f"http://ip-api.com/json/{ip_obj}?fields=status,city,country"
            )
        if response.status_code != 200:
            logging.getLogger("app.auth").warning(
                "IP geolocation service returned HTTP %s.", response.status_code
            )
            return "Unknown location"
        data = response.json()
    except (httpx.RequestError, ValueError) as error:
        logging.getLogger("app.auth").warning(
            "IP geolocation lookup failed (%s).", type(error).__name__
        )
        return "Unknown location"

    if not isinstance(data, dict) or data.get("status") != "success":
        logging.getLogger("app.auth").warning(
            "IP geolocation service did not return a successful location."
        )
        return "Unknown location"
    city = data.get("city")
    country = data.get("country")
    city = city.strip() if isinstance(city, str) else ""
    country = country.strip() if isinstance(country, str) else ""
    if city and country:
        return f"{city}, {country}"
    return city or country or "Unknown location"


def _resolve_ip_location_sync(ip: str) -> str:
    return asyncio.run(resolve_ip_location(ip))


def _session_device_name(user_agent: Optional[str]) -> str:
    parsed_agent = parse_user_agent(user_agent or "")
    operating_system = parsed_agent.os.family
    browser = parsed_agent.browser.family
    parts = [part for part in (operating_system, browser) if part and part != "Other"]
    return " / ".join(parts) if parts else "Unknown device"


def _create_user_session(
    db: Session,
    student: Student,
    request: Optional[Request],
    location: Optional[str] = None,
) -> UserSession:
    user_agent = request.headers.get("user-agent") if request else None
    ip_address = get_real_client_ip(request) if request else "127.0.0.1"
    device_name = _session_device_name(user_agent)
    known_combination = db.query(UserSession.id).filter(
        UserSession.user_id == student.student_id,
        UserSession.ip_address == ip_address,
        UserSession.device_name == device_name,
    ).first()
    now = datetime.now(timezone.utc)
    user_session = UserSession(
        user_id=student.student_id,
        ip_address=ip_address,
        user_agent=user_agent,
        device_name=device_name,
        location=location if location is not None else _resolve_ip_location_sync(ip_address),
        created_at=now,
        last_active_at=now,
    )
    db.add(user_session)
    db.flush()
    if not known_combination:
        location = user_session.location or "Unknown location"
        _add_student_notification(
            db,
            student,
            "New login",
            f"New login from {device_name} ({location})",
            "security",
        )
    return user_session


def _revoke_user_sessions(
    db: Session,
    user_id: str,
    except_session_id: Optional[str] = None,
) -> int:
    query = db.query(UserSession).filter(
        UserSession.user_id == user_id,
        UserSession.revoked_at.is_(None),
    )
    if except_session_id is not None:
        query = query.filter(UserSession.id != except_session_id)
    return query.update(
        {"revoked_at": datetime.now(timezone.utc)},
        synchronize_session=False,
    )


def _cleanup_inactive_user_sessions() -> int:
    cutoff = datetime.now(timezone.utc) - timedelta(days=30)
    db = SessionLocal()
    try:
        deleted = db.query(UserSession).filter(
            or_(
                and_(UserSession.revoked_at.isnot(None), UserSession.revoked_at < cutoff),
                and_(UserSession.revoked_at.is_(None), UserSession.last_active_at < cutoff),
            )
        ).delete(synchronize_session=False)
        db.commit()
        logging.getLogger("app.auth").info("Removed %s expired user sessions.", deleted)
        return deleted
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.auth").exception("User session cleanup failed.")
        raise
    finally:
        db.close()


def _cleanup_old_audit_logs() -> int:
    cutoff_date = datetime.utcnow() - timedelta(days=30)
    db = SessionLocal()
    try:
        deleted_count = db.query(AuditLog).filter(
            AuditLog.created_at < cutoff_date
        ).delete(synchronize_session=False)
        db.commit()
        logger.info(f"Audit log 30-day retention job purged {deleted_count} logs.")
        return deleted_count
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Audit log retention cleanup failed.")
        raise
    finally:
        db.close()


def _cleanup_inactive_admin_sessions() -> int:
    db = SessionLocal()
    try:
        now = _utc_now()
        timeout = timedelta(minutes=_admin_session_inactivity_minutes(db))
        cutoff = (now - timeout).replace(tzinfo=None)
        candidates = db.query(AdminSession).filter(
            AdminSession.is_active.is_(True),
            AdminSession.last_active < cutoff,
            AdminSession.created_at < cutoff,
        ).with_for_update().all()
        revoked = 0
        for session in candidates:
            if _admin_session_is_inactive(session, now, timeout):
                revoked += _revoke_admin_session(
                    session,
                    "inactivity_cleanup",
                    now,
                )
        db.commit()
        logging.getLogger("app.auth").info(
            "Admin session inactivity cleanup revoked %s sessions.",
            revoked,
        )
        return revoked
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.auth").exception("Admin session cleanup failed.")
        raise
    finally:
        db.close()


def _student_session_from_authorization(
    authorization: Optional[str],
    db: Session,
) -> Tuple[Student, UserSession, str]:
    if not authorization:
        raise HTTPException(status_code=401, detail="Authorization header is required.")
    scheme, separator, token = authorization.partition(" ")
    if not separator or scheme.lower() != "bearer" or not token.strip():
        raise HTTPException(status_code=401, detail="Authorization header must use the Bearer scheme.")

    token = token.strip()
    payload = _decode_student_jwt(token)
    session_id = payload.get("session_id")
    try:
        session_id = str(uuid.UUID(str(session_id)))
    except (ValueError, TypeError, AttributeError):
        raise HTTPException(status_code=401, detail="Student session is no longer valid.")

    user_id = str(payload["sub"]).strip()
    user_session = db.query(UserSession).filter(
        UserSession.id == session_id,
        UserSession.user_id == user_id,
    ).first()
    if not user_session or user_session.revoked_at is not None:
        raise HTTPException(status_code=401, detail="Student session has been revoked or is no longer valid.")

    student = db.query(Student).filter(func.lower(Student.student_id) == user_id.lower()).first()
    if not student:
        raise HTTPException(status_code=401, detail="Student session is no longer valid.")

    now = datetime.now(timezone.utc)
    last_active = _as_utc_datetime(user_session.last_active_at)
    if last_active is None or now - last_active >= timedelta(minutes=get_security_settings(db).session_timeout):
        user_session.revoked_at = now
        db.commit()
        raise HTTPException(status_code=401, detail="Student session expired due to inactivity. Please sign in again.")
    user_session.last_active_at = now
    db.commit()
    return student, user_session, token


def _serialize_user_session(user_session: UserSession, current_session_id: str) -> Dict[str, Any]:
    signed_in_at = _as_utc_datetime(user_session.created_at)
    last_active_at = _as_utc_datetime(user_session.last_active_at)
    return {
        "id": user_session.id,
        "is_current": user_session.id == current_session_id,
        "ip_address": user_session.ip_address,
        "device_name": user_session.device_name,
        "location": user_session.location,
        "created_at": signed_in_at.isoformat() if signed_in_at else None,
        "signed_in_at": signed_in_at.isoformat() if signed_in_at else None,
        "last_active_at": last_active_at.isoformat() if last_active_at else None,
    }


def _serialize_student_session(session: StudentSession, current_token: Optional[str] = None) -> Dict[str, Any]:
    current_value = bool(current_token and session.session_token == current_token)
    return {
        "id": session.id,
        "session_id": session.id,
        "session_token": session.session_token,
        "is_current": current_value,
        "ip_address": session.ip_address,
        "device_browser": session.device_browser,
        "last_active": session.last_active.isoformat() if session.last_active else None,
        "created_at": session.created_at.isoformat() if session.created_at else None,
    }


def _legacy_student_from_authorization(authorization: Optional[str], db: Session) -> Student:
    if not authorization:
        raise HTTPException(status_code=401, detail="Authorization Bearer token is required.")
    scheme, separator, token = authorization.partition(" ")
    if not separator or scheme.lower() != "bearer" or not token.strip():
        raise HTTPException(status_code=401, detail="Authorization header must use the Bearer scheme.")

    try:
        encoded_header, encoded_payload, encoded_signature = token.strip().split(".")
        padding = lambda value: value + "=" * (-len(value) % 4)
        header = json.loads(base64.urlsafe_b64decode(padding(encoded_header)).decode())
        payload = json.loads(base64.urlsafe_b64decode(padding(encoded_payload)).decode())
        provided_signature = base64.urlsafe_b64decode(padding(encoded_signature))
    except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError, binascii.Error):
        raise HTTPException(status_code=401, detail="Invalid JWT token.")

    session_secret = _get_session_secret()
    unsigned_token = f"{encoded_header}.{encoded_payload}"
    expected_signature = hmac.new(
        session_secret.encode(),
        unsigned_token.encode(),
        hashlib.sha256,
    ).digest()
    if header.get("alg") != "HS256" or header.get("typ") != "JWT" or not hmac.compare_digest(provided_signature, expected_signature):
        raise HTTPException(status_code=401, detail="Invalid JWT token.")
    if payload.get("role") != "student" or not payload.get("sub") or not isinstance(payload.get("exp"), (int, float)) or payload["exp"] <= datetime.now(timezone.utc).timestamp():
        raise HTTPException(status_code=401, detail="Invalid or expired student session.")

    session = _student_session_from_token(db, token.strip())
    student_id = str(payload["sub"]).strip().lower()
    if str(session.student_id).strip().lower() != student_id:
        raise HTTPException(status_code=401, detail="Student session does not match the bearer token.")

    student = db.query(Student).filter(func.lower(Student.student_id) == student_id).first()
    if not student:
        raise HTTPException(status_code=401, detail="Student session is no longer valid.")
    return student


def _student_from_authorization(authorization: Optional[str], db: Session) -> Student:
    student, _, _ = _student_session_from_authorization(authorization, db)
    return student


def get_current_user(
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
) -> Student:
    return _student_from_authorization(authorization, db)


def _admin_for_session(db: Session, session_token: Optional[str]) -> tuple[Admin, AdminSession]:
    if not session_token:
        logging.getLogger("app.auth").warning("Admin auth rejected: session_token_missing.")
        raise HTTPException(status_code=401, detail="An admin session token is required.")
    claims = _decode_admin_jwt(session_token)
    session = db.query(AdminSession).filter(AdminSession.session_token == session_token).first()
    if not session:
        logging.getLogger("app.auth").warning("Admin auth rejected: admin_session_not_found.")
        raise HTTPException(
            status_code=401,
            detail={
                "code": "session_revoked",
                "message": "Admin session is no longer available. Please sign in again.",
            },
        )
    if not session.is_active:
        if session.revoke_reason == "new_login_single_session":
            code = "session_replaced"
            message = "This admin session was replaced by a newer login."
        elif session.revoke_reason == "inactivity_cleanup":
            code = "session_inactive"
            message = "Admin session expired due to inactivity. Please sign in again."
        else:
            code = "session_revoked"
            message = "Admin session was revoked. Please sign in again."
        logging.getLogger("app.auth").warning(
            "Admin auth rejected: code=%s session_id=%s reason=%s.",
            code,
            session.id,
            session.revoke_reason or "other",
        )
        raise HTTPException(status_code=401, detail={"code": code, "message": message})
    admin = db.query(Admin).filter(Admin.id == session.admin_id).first()
    if not admin:
        logging.getLogger("app.auth").warning("Admin auth rejected: session_admin_record_missing.")
        raise HTTPException(status_code=404, detail="Admin profile not found.")
    if str(admin.status or "").strip().lower() != "active":
        _revoke_admin_sessions(db, admin.id, "admin_deactivated")
        db.commit()
        raise HTTPException(
            status_code=401,
            detail={
                "code": "session_revoked",
                "message": "This administrator account is inactive. Please contact an administrator.",
            },
        )
    if admin.username != claims["sub"]:
        logging.getLogger("app.auth").warning("Admin auth rejected: jwt_subject_session_mismatch.")
        raise HTTPException(status_code=401, detail="JWT subject does not match the admin session.")
    now = _utc_now()
    timeout = timedelta(minutes=_admin_session_inactivity_minutes(db))
    if _admin_session_is_inactive(session, now, timeout):
        _revoke_admin_session(session, "inactivity_cleanup", now)
        db.commit()
        raise HTTPException(
            status_code=401,
            detail={
                "code": "session_inactive",
                "message": "Admin session expired due to inactivity. Please sign in again.",
            },
        )
    session.last_active = now.replace(tzinfo=None)
    db.commit()
    return admin, session


@app.post("/api/admin/logout")
def logout_admin_session(
    payload: Optional[AdminSessionRequest] = None,
    authorization: Optional[str] = Header(None),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    current_token = _extract_admin_token(
        authorization,
        payload.session_token if payload else session_token,
    )
    _, current_session = _admin_for_session(db, current_token)
    _revoke_admin_session(current_session, "logout")
    db.commit()
    return {"success": True}


@app.get("/api/admin/sessions")
def get_admin_sessions(
    session_token: Optional[str] = None,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    session_token = _extract_admin_token(authorization, session_token)
    admin, current_session = _admin_for_session(db, session_token)
    sessions = db.query(AdminSession).filter(AdminSession.admin_id == admin.id, AdminSession.is_active.is_(True)).order_by(AdminSession.last_active.desc()).all()
    db.commit()
    return [{
        "id": item.id,
        "is_current": item.id == current_session.id,
        "ip_address": item.ip_address,
        "location": item.location,
        "device_browser": item.device_browser,
        "last_active": item.last_active.isoformat() if item.last_active else None,
        "created_at": item.created_at.isoformat() if item.created_at else None,
    } for item in sessions]


