@app.post("/api/admin/2fa/setup")
def setup_admin_two_factor(payload: AdminTwoFactorRequest, request: Request, db: Session = Depends(get_db)):
    admin, _ = _admin_for_session(db, payload.session_token)
    secret = pyotp.random_base32()
    admin.two_factor_pending_secret = _encrypt_totp_secret(secret)
    db.commit()
    provisioning_uri = pyotp.TOTP(secret).provisioning_uri(
        name=admin.email,
        issuer_name="Campus Market",
    )
    qr_buffer = io.BytesIO()
    qrcode.make(provisioning_uri).save(qr_buffer, kind="PNG")
    qr_code = base64.b64encode(qr_buffer.getvalue()).decode("ascii")
    return {
        "enabled": _admin_two_factor_configured(admin),
        "secret": secret,
        "qr_code": f"data:image/png;base64,{qr_code}",
        "message": "Scan the QR code, then enter the six-digit code to finish setup.",
    }


@app.post("/api/admin/2fa/setup/verify")
def verify_admin_two_factor_setup(payload: AdminTwoFactorVerifyRequest, request: Request, db: Session = Depends(get_db)):
    admin, _ = _admin_for_session(db, payload.session_token)
    admin = db.query(Admin).filter(Admin.id == admin.id).with_for_update().first()
    if not admin:
        raise HTTPException(status_code=404, detail="Administrator account not found.")
    secret = _decrypt_totp_secret(admin.two_factor_pending_secret)
    if not secret or not pyotp.TOTP(secret).verify(payload.code.strip(), valid_window=1):
        raise HTTPException(status_code=400, detail="Invalid authenticator code.")
    admin.two_factor_secret = _encrypt_totp_secret(secret)
    admin.two_factor_pending_secret = None
    admin.two_factor_enabled = True
    _record_admin_login_event(db, admin.id, "2fa_enabled", request)
    db.add(AuditLog(admin_id=admin.id, action="Admin 2FA Enabled", entity_type="Admin", entity_id=admin.id, description="Authenticator setup was verified and enabled.", status="SUCCESS", ip_address=request.client.host if request.client else None))
    db.commit()
    return {"enabled": True, "message": "Authenticator-based two-factor authentication is enabled."}


def _hash_admin_backup_code(code: str, salt: Optional[str] = None) -> str:
    code_salt = salt or secrets.token_hex(16)
    digest = hashlib.sha256(f"{code_salt}:{code.strip().upper()}".encode("utf-8")).hexdigest()
    return f"{code_salt}${digest}"


def _consume_admin_backup_code(db: Session, admin: Admin, code: str) -> bool:
    candidate = code.strip().upper()
    if not candidate:
        return False

    code_records = db.query(AdminBackupCode).filter(
        AdminBackupCode.admin_id == admin.id,
    ).with_for_update().all()
    for record in code_records:
        if record.used:
            continue
        salt, _, expected_hash = str(record.code_hash).partition("$")
        candidate_hash = _hash_admin_backup_code(candidate, salt).partition("$")[2]
        if hmac.compare_digest(candidate_hash, expected_hash):
            record.used = True
            return True

    if code_records:
        return False

    raw_codes = str(admin.backup_codes or "").strip()
    if not raw_codes:
        return False
    try:
        stored_codes = json.loads(raw_codes)
    except (TypeError, json.JSONDecodeError):
        return False
    if not isinstance(stored_codes, list):
        return False
    for index, stored_code in enumerate(stored_codes):
        if "$" in str(stored_code):
            salt, _, expected_hash = str(stored_code).partition("$")
            candidate_hash = _hash_admin_backup_code(candidate, salt).partition("$")[2]
            matches = hmac.compare_digest(candidate_hash, expected_hash)
        else:
            matches = hmac.compare_digest(candidate, str(stored_code).upper())
        if matches:
            stored_codes.pop(index)
            admin.backup_codes = json.dumps(stored_codes)
            return True
    return False


def _admin_backup_codes_remaining(db: Session, admin: Admin) -> int:
    table_query = db.query(AdminBackupCode).filter(
        AdminBackupCode.admin_id == admin.id,
    )
    if table_query.count():
        return table_query.filter(AdminBackupCode.used.is_(False)).count()

    try:
        stored_codes = json.loads(str(admin.backup_codes or "[]"))
    except (TypeError, json.JSONDecodeError):
        return 0
    return len(stored_codes) if isinstance(stored_codes, list) else 0


def _verify_admin_reauthentication(db: Session, admin: Admin, current_password: Optional[str], otp_code: Optional[str]) -> bool:
    if current_password and verify_password(current_password, admin.password_hash):
        return True
    candidate = str(otp_code or "").strip()
    configured_secret = _decrypt_totp_secret(admin.two_factor_secret)
    if candidate and configured_secret and pyotp.TOTP(configured_secret).verify(candidate, valid_window=1):
        return True
    return _consume_admin_backup_code(db, admin, candidate)


@app.post("/api/admin/2fa/backup-codes")
def generate_admin_backup_codes(payload: AdminTwoFactorRequest, request: Request, db: Session = Depends(get_db)):
    admin, _ = _admin_for_session(db, payload.session_token)
    admin = db.query(Admin).filter(Admin.id == admin.id).with_for_update().first()
    if not admin:
        raise HTTPException(status_code=404, detail="Administrator account not found.")
    if not admin.two_factor_enabled or not _decrypt_totp_secret(admin.two_factor_secret):
        raise HTTPException(status_code=400, detail="Enable authenticator-based 2FA before generating backup codes.")
    if not payload.current_password or not verify_password(payload.current_password, admin.password_hash):
        raise HTTPException(status_code=403, detail="Your current password is required to generate backup codes.")
    codes = [secrets.token_hex(5).upper() for _ in range(8)]
    db.query(AdminBackupCode).filter(AdminBackupCode.admin_id == admin.id).update({"used": True}, synchronize_session=False)
    admin.backup_codes = json.dumps([_hash_admin_backup_code(code) for code in codes])
    db.add_all([AdminBackupCode(admin_id=admin.id, code_hash=_hash_admin_backup_code(code)) for code in codes])
    _record_admin_login_event(db, admin.id, "backup_codes_generated", request)
    db.add(AuditLog(admin_id=admin.id, action="Admin 2FA Backup Codes Generated", entity_type="Admin", entity_id=admin.id, description="Generated a new set of authenticator backup codes.", status="SUCCESS", ip_address=request.client.host if request.client else None))
    db.commit()
    return {"backup_codes": codes}


@app.post("/api/admin/2fa/disable")
def disable_admin_two_factor(payload: AdminTwoFactorRequest, request: Request, db: Session = Depends(get_db)):
    admin, _ = _admin_for_session(db, payload.session_token)
    admin = db.query(Admin).filter(Admin.id == admin.id).with_for_update().first()
    if not admin:
        raise HTTPException(status_code=404, detail="Administrator account not found.")
    if not _verify_admin_reauthentication(db, admin, payload.current_password, payload.otp_code):
        raise HTTPException(status_code=403, detail="Re-authentication is required to disable two-factor authentication.")
    admin.two_factor_enabled = False
    admin.two_factor_secret = None
    admin.two_factor_pending_secret = None
    _record_admin_login_event(db, admin.id, "2fa_disabled", request)
    db.add(AuditLog(admin_id=admin.id, action="Admin 2FA Disabled", entity_type="Admin", entity_id=admin.id, description="Authenticator-based two-factor authentication disabled.", status="SUCCESS", ip_address=request.client.host if request.client else None))
    db.commit()
    return {"enabled": False}


@app.post("/api/admin/profile/avatar")
async def upload_admin_avatar(
    request: Request,
    authorization: Optional[str] = Header(None),
    session_token: Optional[str] = None,
    avatar: UploadFile = File(...),
    db: Session = Depends(get_db)
):
    current_token = _extract_admin_token(authorization, session_token)
    admin, _ = _admin_for_session(db, current_token)
    max_size = 5 * 1024 * 1024
    previous_url = str(admin.avatar_url or "")
    new_path = None
    try:
        content = await avatar.read(max_size + 1)
        if len(content) > max_size:
            raise HTTPException(status_code=413, detail="Profile photo must be 5 MB or smaller.")

        try:
            with warnings.catch_warnings():
                warnings.simplefilter("error", Image.DecompressionBombWarning)
                with Image.open(io.BytesIO(content)) as image:
                    detected_format = image.format
                    image.verify()
                if detected_format not in {"JPEG", "PNG", "WEBP"}:
                    raise HTTPException(status_code=415, detail="Unsupported image type. Upload a JPEG, PNG, or WEBP image.")

                with Image.open(io.BytesIO(content)) as image:
                    normalized = ImageOps.exif_transpose(image).convert("RGB")
                    normalized = ImageOps.fit(
                        normalized,
                        (512, 512),
                        method=Image.Resampling.LANCZOS,
                        centering=(0.5, 0.5),
                    )
                    output = io.BytesIO()
                    normalized.save(output, format="WEBP", quality=85)
        except HTTPException:
            raise
        except (Image.DecompressionBombError, Image.DecompressionBombWarning, OSError, UnidentifiedImageError, ValueError) as error:
            raise HTTPException(status_code=415, detail="Unsupported or invalid image. Upload a valid JPEG, PNG, or WEBP image.") from error

        os.makedirs(AVATAR_DIR, exist_ok=True)
        filename = f"admin_{admin.id}_{uuid.uuid4().hex}.webp"
        new_path = os.path.join(AVATAR_DIR, filename)
        with open(new_path, "wb") as saved_file:
            saved_file.write(output.getvalue())

        avatar_url = f"/uploads/avatars/{filename}"
        admin.avatar_url = avatar_url
        _add_admin_audit(db, admin, request, "Profile photo updated", "Profile photo updated")
        db.commit()
    except HTTPException:
        raise
    except Exception:
        db.rollback()
        if new_path and os.path.exists(new_path):
            os.remove(new_path)
        logging.getLogger("app.avatar").exception("Failed to save admin avatar file.")
        raise HTTPException(status_code=500, detail="Failed to save profile photo.")
    finally:
        await avatar.close()

    previous_path = None
    previous_url_path = urlsplit(previous_url).path
    if previous_url_path.startswith(("/uploads/avatars/", "/static/uploads/avatars/")):
        previous_path = os.path.join(AVATAR_DIR, os.path.basename(previous_url_path))
    elif previous_url_path.startswith("/static/uploads/"):
        relative_path = previous_url_path.removeprefix("/static/uploads/")
        candidate_path = os.path.realpath(os.path.join(STATIC_DIR, relative_path))
        static_upload_root = os.path.realpath(STATIC_DIR)
        if os.path.commonpath([static_upload_root, candidate_path]) == static_upload_root:
            previous_path = candidate_path
    if previous_path and previous_path != new_path and os.path.isfile(previous_path):
        try:
            os.remove(previous_path)
        except OSError:
            logging.getLogger("app.avatar").warning("Could not remove previous admin avatar %s", previous_path)

    return {"avatar_url": avatar_url, "message": "Profile photo updated"}


@app.get("/api/admin/settings", response_model=AdminSettingsResponse)
def get_admin_settings(db: Session = Depends(get_db)):
    response = json.loads(json.dumps(DEFAULT_SETTINGS_BLOCKS))
    grouped_keys = set(DEFAULT_SETTINGS_BLOCKS)
    for item in db.query(SystemSetting).filter(SystemSetting.key.in_(grouped_keys)).all():
        parsed = _parse_setting_value(item.value)
        if isinstance(parsed, dict):
            if item.key == "studentVerification":
                response[item.key] = _normalize_student_verification_settings(parsed)
            else:
                response[item.key].update(parsed)
    response["studentVerification"] = _normalize_student_verification_settings(
        response.get("studentVerification", {})
    )
    security = get_security_settings(db)
    response["security"] = {
        "requireStudentVerification": security.require_student_verification,
        "admin2FA": security.admin_2fa,
        "maxLoginAttempts": security.max_login_attempts,
        "sessionTimeout": security.session_timeout,
        "minPasswordLength": security.min_password_length,
        "auditLogging": security.audit_logging,
    }
    response["support_email"] = str(
        response.get("general", {}).get("supportEmail") or "support@campus.edu.et"
    ).strip() or "support@campus.edu.et"
    response["payment"] = get_payment_settings(db)
    public_key = os.getenv("CHAPA_PUBLIC_KEY", "")
    secret_key = os.getenv("CHAPA_SECRET_KEY", "")
    response["payment"]["publicKey"] = f"{public_key[:8]}••••••" if public_key else "Not configured"
    response["payment"]["secretKey"] = "••••••••••••" if secret_key else "Not configured"
    return response


@app.put("/api/admin/settings", response_model=AdminSettingsSaveResponse)
def update_admin_settings(
    payload: AdminSettingsUpdateRequest,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    try:
        submitted_payload = payload.model_dump(exclude_unset=True)

        current = get_admin_settings(db)
        normalized = json.loads(json.dumps(DEFAULT_SETTINGS_BLOCKS))
        for block, values in submitted_payload.items():
            if block not in normalized:
                raise HTTPException(status_code=400, detail=f"Unknown settings block: {block}")
            if not isinstance(values, dict):
                raise HTTPException(status_code=400, detail=f"Settings block '{block}' must be an object.")
            normalized[block].update(values)

        submitted_verification = submitted_payload.get("studentVerification", {})
        verification_values = {}
        verification_fields = (
            ("allowed_email_domain", "allowedEmailDomain"),
            ("require_university_email", "requireUniversityEmail"),
            ("auto_approve_students", "autoApproveStudents"),
        )
        for snake_key, camel_key in verification_fields:
            if camel_key in submitted_verification:
                verification_values[camel_key] = submitted_verification[camel_key]
            elif snake_key in submitted_verification:
                verification_values[snake_key] = submitted_verification[snake_key]
            else:
                verification_values[camel_key] = normalized["studentVerification"].get(
                    camel_key,
                    DEFAULT_SETTINGS_BLOCKS["studentVerification"][camel_key],
                )
        try:
            normalized_verification = _normalize_student_verification_settings(verification_values)
        except ValidationError as error:
            raise HTTPException(status_code=400, detail="Student verification settings are invalid.") from error
        domain = normalized_verification["allowedEmailDomain"]
        if normalized_verification["requireUniversityEmail"] and not re.fullmatch(
            r"(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}",
            domain,
        ):
            raise HTTPException(status_code=400, detail="Allowed Email Domain must be a valid domain when university email is required.")
        normalized["studentVerification"] = normalized_verification

        payment_values = normalized["payment"]
        submitted_payment = submitted_payload.get("payment", {})
        if isinstance(submitted_payment, dict) and isinstance(submitted_payment.get("security"), dict):
            payment_values["security"].update(submitted_payment["security"])
        if isinstance(submitted_payment, dict) and isinstance(submitted_payment.get("commission"), dict):
            payment_values["commission"].update(submitted_payment["commission"])
        payment_values["paymentProvider"] = "Chapa"
        payment_values["currency"] = "ETB"
        payment_values["paymentVerification"] = "Automatic"
        if payment_values.get("refundPolicy") not in {"Admin approval required", "Automatic"}:
            raise HTTPException(status_code=400, detail="Invalid refund policy.")
        if payment_values.get("maximumRefund") not in {"100%", "75%", "50%"}:
            raise HTTPException(status_code=400, detail="Invalid maximum refund value.")
        if not isinstance(payment_values.get("enableOnlinePayment"), bool) or not isinstance(payment_values.get("refundsEnabled"), bool):
            raise HTTPException(status_code=400, detail="Payment toggles must be boolean values.")
        security_values = payment_values.get("security")
        if (
            not isinstance(security_values, dict)
            or set(security_values) != set(PAYMENT_SETTINGS_SCHEMA["security"])
            or any(not isinstance(value, bool) for value in security_values.values())
        ):
            raise HTTPException(status_code=400, detail="Payment security rules must be boolean values.")

        if (
            normalized["security"]["admin2FA"]
            and not current.get("security", {}).get("admin2FA", False)
        ):
            session_token = _extract_admin_token(authorization, None)
            admin, _ = _admin_for_session(db, session_token)
            if not admin.two_factor_enabled or not _decrypt_totp_secret(admin.two_factor_secret):
                raise HTTPException(
                    status_code=400,
                    detail="Set up your own authenticator before enabling this",
                )
        payment_values["commission"] = _normalize_payment_commission_settings(payment_values.get("commission"))
        payment_values.pop("publicKey", None)
        payment_values.pop("secretKey", None)
        normalized["payment"] = payment_values

        normalized["general"]["currency"] = "ETB"
        normalized["general"]["timezone"] = "Africa/Addis_Ababa"

        for key, value in normalized.items():
            existing = db.query(SystemSetting).filter(SystemSetting.key == key).first()
            serialized = json.dumps(value, ensure_ascii=False)
            if existing:
                existing.value = serialized
            else:
                db.add(SystemSetting(key=key, value=serialized))

        db.query(SystemSetting).filter(~SystemSetting.key.in_(normalized.keys())).delete(synchronize_session=False)

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        audit_current = json.loads(json.dumps(current))
        audit_current.get("payment", {}).pop("publicKey", None)
        audit_current.get("payment", {}).pop("secretKey", None)
        changes = _settings_change_details(audit_current, normalized)
        audit_logging_enabled = _setting_bool(
            audit_current.get("security", {}).get("auditLogging"),
            DEFAULT_SETTINGS_BLOCKS["security"]["auditLogging"],
        ) or _setting_bool(
            normalized.get("security", {}).get("auditLogging"),
            DEFAULT_SETTINGS_BLOCKS["security"]["auditLogging"],
        )
        if admin and changes and audit_logging_enabled:
            db.add(AuditLog(
                admin_id=admin.id,
                action="System Settings Updated",
                entity_type="Settings",
                entity_id=1,
                description=json.dumps({
                    "username": admin.username,
                    "old_values": audit_current,
                    "new_values": normalized,
                    "changes": changes,
                }, ensure_ascii=False),
                status="SUCCESS",
                ip_address="127.0.0.1",
            ))
        db.commit()

        return {"success": True, "message": "Settings saved successfully", "settings": normalized, "changes": changes}
    except HTTPException:
        db.rollback()
        raise
    except Exception as error:
        db.rollback()
        logger.exception("Failed to update admin settings: %s", error)
        raise HTTPException(status_code=500, detail="Could not save system settings.") from error


@app.patch("/api/admin/settings", response_model=AdminSettingsSaveResponse)
def patch_admin_security_settings(
    payload: AdminSecuritySettingsPatchRequest,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    try:
        submitted = payload.security.model_dump(exclude_unset=True)
        if not submitted or any(value is None for value in submitted.values()):
            raise HTTPException(status_code=400, detail="Provide at least one security setting with a valid value.")

        session_token = _extract_admin_token(authorization, None)
        admin, _ = _admin_for_session(db, session_token)
        current = get_admin_settings(db)
        current_security = current["security"]
        normalized_security = {**current_security, **submitted}
        validated_security = AdminSecuritySettingsRequest(**normalized_security).model_dump()

        if validated_security["admin2FA"] and not current_security["admin2FA"]:
            if not admin.two_factor_enabled or not _decrypt_totp_secret(admin.two_factor_secret):
                raise HTTPException(
                    status_code=400,
                    detail="Set up your own authenticator before enabling this",
                )

        changes = [
            f"security.{key}"
            for key, value in validated_security.items()
            if current_security[key] != value
        ]
        stored = db.query(SystemSetting).filter(SystemSetting.key == "security").first()
        serialized = json.dumps(validated_security, ensure_ascii=False)
        if stored:
            stored.value = serialized
        else:
            db.add(SystemSetting(key="security", value=serialized))

        if changes and (current_security["auditLogging"] or validated_security["auditLogging"]):
            db.add(AuditLog(
                admin_id=admin.id,
                action="Admin Security Settings Updated",
                entity_type="Settings",
                entity_id=1,
                description=json.dumps({
                    "username": admin.username,
                    "old_values": current_security,
                    "new_values": validated_security,
                    "changes": changes,
                }, ensure_ascii=False),
                status="SUCCESS",
                ip_address="127.0.0.1",
            ))
        db.commit()

        return {
            "success": True,
            "message": "Security settings saved successfully",
            "settings": get_admin_settings(db),
            "changes": changes,
        }
    except HTTPException:
        db.rollback()
        raise
    except Exception as error:
        db.rollback()
        logger.exception("Failed to update admin security settings: %s", error)
        raise HTTPException(status_code=500, detail="Could not save security settings.") from error


