@app.put("/api/student/profile/password")
def update_student_password(
    payload: StudentPasswordUpdate,
    request: Request,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    student, current_session, _ = _student_session_from_authorization(authorization, db)

    if student.has_password and not verify_password(payload.current_password or "", student.password):
        raise HTTPException(status_code=400, detail="Current password is incorrect.")
    minimum_password_length = _session_password_min_length(db)
    if len(payload.new_password) < minimum_password_length:
        raise HTTPException(status_code=400, detail=f"New password must be at least {minimum_password_length} characters.")
    if not secrets.compare_digest(payload.new_password, payload.confirm_password):
        raise HTTPException(status_code=400, detail="New password and confirmation do not match.")

    student.password = hash_password(payload.new_password)
    student.has_password = True
    _revoke_user_sessions(db, student.student_id, except_session_id=current_session.id)
    db.add(AuditLog(
        admin_id=None,
        action="Student Password Changed",
        entity_type="Student",
        entity_id=student.id,
        description="Student changed their account password.",
        status="SUCCESS",
        ip_address=request.client.host if request.client else None,
    ))
    db.commit()
    return {"success": True, "message": "Password updated successfully."}


