    if not student:
        return {
            "student_id": student_id,
            "unreadCount": 0,
            "unread_count": 0,
        }

    unread_count = (
        db.query(Notification.id)
        .filter(
            Notification.student_id == student_id,
            Notification.is_read.is_(False),
        )
        .count()
    )

    return {
        "student_id": student_id,
        "unreadCount": unread_count,
        "unread_count": unread_count,
    }


