def _seller_payout_status(db: Session, seller_identifier: Optional[str]) -> str:
    if not seller_identifier:
        return "Pending"

    seller = db.query(Student).filter(
        or_(Student.student_id == seller_identifier, Student.name == seller_identifier)
    ).first()
    if not seller:
        return "Pending"

    account = db.query(SellerPaymentAccount).filter(
        SellerPaymentAccount.student_id == seller.student_id,
    ).first()
    if not account or account.account_status != "Active" or not account.chapa_sub_account_id:
        return "Pending"
    return "Active"


def _public_marketplace_product_query(db: Session):
    """Build the public product query without sold or out-of-stock listings."""
    return db.query(Product).filter(
        func.lower(func.trim(func.coalesce(Product.status, ""))).in_(
            ("approved", "active", "available"),
        ),
    ).filter(Product.stock > 0)


def _optional_student_from_authorization(
    authorization: Optional[str],
    db: Session,
) -> Optional[Student]:
    if not isinstance(authorization, str) or not authorization.strip():
        return None
    try:
        return _student_from_authorization(authorization, db)
    except HTTPException as error:
        if error.status_code == status.HTTP_401_UNAUTHORIZED:
            return None
        raise


def apply_public_listing_filters(query, current_user: Optional[Student]):
    if not current_user:
        return query

    student_id = str(current_user.student_id or "").strip().lower()
    seller_identifiers = {
        student_id,
        str(current_user.name or "").strip().lower(),
    }
    seller_identifiers.discard("")
    return query.filter(
        or_(
            Product.seller_id.is_(None),
            func.lower(func.trim(Product.seller_id)) != student_id,
        ),
        or_(
            Product.seller.is_(None),
            func.lower(func.trim(Product.seller)).notin_(seller_identifiers),
        ),
    )


def _get_similar_products(
    db: Session,
    product: Product,
    current_user: Optional[Student] = None,
) -> List[Product]:
    current_price = _parse_price_to_etb(product.price)
    candidates = apply_public_listing_filters(_public_marketplace_product_query(db), current_user).filter(
        Product.id != product.id,
        Product.category == product.category,
        func.lower(func.trim(Product.status)) == "approved",
        Product.stock > 0,
    ).order_by(Product.created_at.desc(), Product.id.desc()).all()

    def sort_by_price_then_newest(products):
        return sorted(
            products,
            key=lambda candidate: abs(_parse_price_to_etb(candidate.price) - current_price),
        )

    same_subcategory = [
        candidate for candidate in candidates
        if product.subcategory and candidate.subcategory == product.subcategory
    ]
    other_subcategories = [
        candidate for candidate in candidates
        if not product.subcategory or candidate.subcategory != product.subcategory
    ]
    return (
        sort_by_price_then_newest(same_subcategory)
        + sort_by_price_then_newest(other_subcategories)
    )[:8]


def _similar_product_response(product: Product) -> Dict[str, Any]:
    return {
        "id": product.id,
        "title": product.title,
        "category": product.category,
        "price": _parse_price_to_etb(product.price),
        "image": _normalize_product_image(product.image),
        "status": product.status,
    }


def _seller_typical_response_bucket(
    db: Session,
    seller_id: Optional[str],
    now: Optional[datetime] = None,
) -> Optional[str]:
    if not seller_id:
        return None

    current_time = now or datetime.now(timezone.utc)
    if current_time.tzinfo is None:
        current_time = current_time.replace(tzinfo=timezone.utc)
    else:
        current_time = current_time.astimezone(timezone.utc)
    cutoff = current_time - timedelta(days=30)
    recent_messages = db.query(Message.sender_id, Message.receiver_id).filter(
        or_(
            Message.sender_id == seller_id,
            Message.receiver_id == seller_id,
        ),
        Message.created_at >= cutoff.replace(tzinfo=None),
    ).all()
    buyer_ids = {
        message.receiver_id if message.sender_id == seller_id else message.sender_id
        for message in recent_messages
        if (message.receiver_id if message.sender_id == seller_id else message.sender_id) != seller_id
    }
    if not buyer_ids:
        return None

    conversation_messages = db.query(Message).filter(
        or_(
            (Message.sender_id == seller_id) & Message.receiver_id.in_(buyer_ids),
            (Message.receiver_id == seller_id) & Message.sender_id.in_(buyer_ids),
        )
    ).order_by(Message.created_at.asc(), Message.id.asc()).all()
    messages_by_buyer: Dict[str, List[Message]] = {}
    for message in conversation_messages:
        buyer_id = message.receiver_id if message.sender_id == seller_id else message.sender_id
        messages_by_buyer.setdefault(buyer_id, []).append(message)

    reply_times = []
    for buyer_messages in messages_by_buyer.values():
        first_message = buyer_messages[0]
        if first_message.sender_id == seller_id:
            continue

        seller_reply = next(
            (
                message for message in buyer_messages[1:]
                if message.sender_id == seller_id and message.receiver_id == first_message.sender_id
            ),
            None,
        )
        if not seller_reply or not first_message.created_at or not seller_reply.created_at:
            continue

        reply_time = seller_reply.created_at
        if reply_time.tzinfo is None:
            reply_time = reply_time.replace(tzinfo=timezone.utc)
        if reply_time < cutoff:
            continue

        elapsed_hours = (seller_reply.created_at - first_message.created_at).total_seconds() / 3600
        if elapsed_hours >= 0:
            reply_times.append(elapsed_hours)

    if len(reply_times) < 3:
        return None

    reply_times.sort()
    middle = len(reply_times) // 2
    median_hours = (
        reply_times[middle]
        if len(reply_times) % 2
        else (reply_times[middle - 1] + reply_times[middle]) / 2
    )
    if median_hours < 1:
        return "responseUnderHour"
    if median_hours <= 6:
        return "responseWithinFewHours"
    if median_hours <= 24:
        return "responseWithinDay"
    return "responseWithinFewDays"


PRODUCT_OWNERSHIP_ERROR = "You cannot buy or save your own product."


def _reject_own_product_action(db: Session, product: Product, student: Student) -> None:
    if _is_product_owner(db, product, student):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=PRODUCT_OWNERSHIP_ERROR)


def _is_product_owner(db: Session, product: Product, student: Optional[Student]) -> bool:
    if not student or not product.seller:
        return False

    seller_identifier = str(product.seller).strip().lower()
    student_identifiers = {
        str(student.student_id or "").strip().lower(),
        str(student.name or "").strip().lower(),
    }
    if seller_identifier in student_identifiers:
        return True

    seller = db.query(Student).filter(
        or_(
            func.lower(Student.student_id) == seller_identifier,
            func.lower(Student.name) == seller_identifier,
        )
    ).first()
    return bool(seller and seller.student_id.strip().lower() == student.student_id.strip().lower())

# 4. የዕቃዎች ማውጫ እና ማጣሪያ ኤፒአይ (GET /api/products)
@app.get("/api/products")
def get_products(
    category: Optional[str] = None,
    subcategory: Optional[str] = None,
    search: Optional[str] = None,
    limit: int = 24,
    department: Optional[str] = None,
    seller: Optional[str] = None,
    product_ids: Optional[List[int]] = Query(None),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    from sqlalchemy import case, or_

    if _setting_bool(_get_setting_value(db, "maintenance", "maintenanceMode", False)):
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail=_get_setting_value(
                db,
                "maintenance",
                "maintenanceMessage",
                "Marketplace maintenance in progress.",
            ),
        )

    query = _public_marketplace_product_query(db)
    authenticated_student = _optional_student_from_authorization(authorization, db)
    query = apply_public_listing_filters(query, authenticated_student)
    try:
        auto_hide_reported = _setting_bool(
            _get_setting_value(
                db,
                "moderation",
                "autoHideReported",
                DEFAULT_SETTINGS_BLOCKS["moderation"]["autoHideReported"],
            ),
            DEFAULT_SETTINGS_BLOCKS["moderation"]["autoHideReported"],
        )
    except Exception as error:
        db.rollback()
        logger.exception("Failed to fetch moderation settings for products: %s", error)
        raise HTTPException(status_code=500, detail="Could not load product moderation settings.") from error
    if auto_hide_reported:
        query = query.filter(Product.status.notin_(["Flagged", "Pending"]))
    manual_filters_active = bool(category or subcategory or search or seller or product_ids is not None)

    if product_ids is not None:
        query = query.filter(Product.id.in_(product_ids))

    if category:
        query = query.filter(Product.category == category)
    if subcategory:
        query = query.filter(Product.subcategory == subcategory)
    if search:
        search_term = search.strip()
        if search_term:
            query = query.filter(
                or_(
                    Product.title.ilike(f"%{search_term}%"),
                    Product.description.ilike(f"%{search_term}%"),
                    Product.subcategory.ilike(f"%{search_term}%"),
                    Product.category.ilike(f"%{search_term}%"),
                )
            )
    if seller:
        seller_student = db.query(Student).filter(Student.student_id == seller.strip()).first()
        seller_values = [seller.strip()]
        if seller_student:
            seller_values.append(seller_student.name)
        query = query.filter(Product.seller.in_(seller_values))

    if department and not manual_filters_active:
        cleaned_department = re.sub(r"(?i)\bdepartment of\b|\bdept\.?\b|\bdepartment\b", "", department)
        cleaned_department = cleaned_department.replace("(IT)", "").replace("/", " ")
        tokens = [
            token.strip(" ,;:-()[]")
            for token in re.split(r"\s+", cleaned_department)
            if token.strip(" ,;:-()[]") and len(token.strip(" ,;:-()[]")) > 2
        ]
        excluded = {"the", "and", "for", "with", "engineering", "science", "technology", "school", "college"}
        keyword = next((token for token in tokens if token.lower() not in excluded), None)

        if keyword:
            keyword = keyword.strip()
            query = query.order_by(
                case(
                    (Product.title.ilike(f"%{keyword}%"), 0),
                    (Product.description.ilike(f"%{keyword}%"), 0),
                    (Product.category.ilike(f"%{keyword}%"), 0),
                    else_=1,
                ),
                Product.created_at.desc(),
            )
        else:
            query = query.order_by(Product.created_at.desc())
    else:
        query = query.order_by(Product.created_at.desc())

    query = query.limit(limit)

    try:
        products = query.all()
        return [
            {
                **{
                    column.name: (
                        _normalize_product_image(getattr(product, column.name))
                        if column.name == "image"
                        else getattr(product, column.name)
                    )
                    for column in Product.__table__.columns
                },
                "seller_payout_status": _seller_payout_status(db, product.seller),
            }
            for product in products
        ]
    except Exception as error:
        db.rollback()
        logger.exception("Failed to fetch products: %s", error)
        raise HTTPException(status_code=500, detail="Could not fetch products.") from error


@app.get("/api/products/{product_id}/similar")
def get_similar_products(
    product_id: int,
    db: Session = Depends(get_db),
    authorization: Optional[str] = Header(None, alias="Authorization"),
):
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")

    try:
        current_user = _optional_student_from_authorization(authorization, db)
        return [
            _similar_product_response(candidate)
            for candidate in _get_similar_products(db, product, current_user)
        ]
    except SQLAlchemyError as error:
        db.rollback()
        logger.exception("Failed to fetch similar products: %s", error)
        raise HTTPException(status_code=500, detail="Could not fetch similar products.") from error


@app.get("/api/products/{product_id}")
def get_product_detail(
    product_id: int,
    request: Request,
    response: Response,
    viewer_id: Optional[str] = None,
    track_view: bool = True,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Fetch details for a single product by ID."""
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")

    authenticated_student = None
    authenticated_admin = False
    if authorization:
        try:
            authenticated_student = _student_from_authorization(authorization, db)
        except HTTPException as error:
            if error.status_code != status.HTTP_401_UNAUTHORIZED:
                raise
            try:
                _require_admin_dashboard_access(authorization, None, db, "products")
                authenticated_admin = True
            except HTTPException as admin_error:
                if admin_error.status_code not in {
                    status.HTTP_401_UNAUTHORIZED,
                    status.HTTP_403_FORBIDDEN,
                }:
                    raise

    seller = None
    if product.seller:
        seller = db.query(Student).filter(
            or_(Student.student_id == product.seller, Student.name == product.seller)
        ).first()

    seller_id = seller.student_id if seller else product.seller
    is_owner = _is_product_owner(db, product, authenticated_student)
    if not is_owner and not authenticated_admin and not _public_marketplace_product_query(db).filter(Product.id == product_id).first():
        raise HTTPException(status_code=404, detail="Product not found.")

    viewer = authenticated_student or (
        db.query(Student).filter(Student.student_id == viewer_id.strip()).first() if viewer_id else None
    )
    visitor_cookie = request.cookies.get("campace_viewer") if request else None
    is_new_visitor_cookie = not visitor_cookie
    if is_new_visitor_cookie:
        visitor_cookie = secrets.token_urlsafe(24)
    tracking_viewer = authenticated_student
    visitor_identity = (
        f"student:{tracking_viewer.student_id}"
        if tracking_viewer
        else f"session:{visitor_cookie}"
    )
    now = datetime.now()
    cooldown_start = now - timedelta(hours=24)
    legacy_visitor_keys = (
        visitor_identity,
        f"{visitor_identity}:{now.date().isoformat()}",
        f"{visitor_identity}:{(now - timedelta(days=1)).date().isoformat()}",
    )
    should_count_view = False
    if track_view and not _is_product_owner(db, product, tracking_viewer):
        view_identity_filters = [
            ProductView.visitor_key.in_(legacy_visitor_keys),
        ]
        if tracking_viewer:
            view_identity_filters.append(
                ProductView.viewer_id == tracking_viewer.student_id,
            )
        existing_view_query = db.query(ProductView).filter(
            ProductView.product_id == product.id,
            or_(*view_identity_filters),
        )
        recent_view = existing_view_query.filter(
            ProductView.viewed_at > cooldown_start,
        ).order_by(ProductView.viewed_at.desc()).first()
        existing_view = None if recent_view else (
            existing_view_query.filter(
                ProductView.visitor_key == visitor_identity,
            ).first()
            or existing_view_query.order_by(ProductView.viewed_at.desc()).first()
        )
        if recent_view:
            should_count_view = False
        elif existing_view:
            if existing_view.viewed_at <= cooldown_start:
                should_count_view = (
                    db.query(ProductView)
                    .filter(
                        ProductView.id == existing_view.id,
                        ProductView.viewed_at <= cooldown_start,
                    )
                    .update(
                        {
                            ProductView.viewer_id: tracking_viewer.student_id if tracking_viewer else None,
                            ProductView.visitor_key: visitor_identity,
                            ProductView.viewed_at: now,
                        },
                        synchronize_session=False,
                    )
                    == 1
                )
        else:
            try:
                with db.begin_nested():
                    db.add(ProductView(
                        product_id=product.id,
                        viewer_id=tracking_viewer.student_id if tracking_viewer else None,
                        visitor_key=visitor_identity,
                        viewed_at=now,
                    ))
                    db.flush()
                should_count_view = True
            except IntegrityError:
                # Another request from this visitor recorded the unique view first.
                should_count_view = False

        if should_count_view:
            db.query(Product).filter(Product.id == product.id).update(
                {Product.views: func.coalesce(Product.views, 0) + 1},
                synchronize_session=False,
            )
            db.refresh(product, attribute_names=["views"])
    if is_new_visitor_cookie and response:
        response.set_cookie("campace_viewer", visitor_cookie, max_age=60 * 60 * 24 * 365, httponly=True, samesite="lax")

    review_rows = db.query(Review, Student).join(
        Student, Student.student_id == Review.student_id
    ).join(
        Order, Order.id == Review.order_id
    ).filter(
        Order.product_id == product.id,
        Review.is_hidden.is_(False),
    ).order_by(Review.created_at.desc()).all()
    review_items = [
        {
            "id": review.id,
            "reviewer_name": reviewer.name,
            "rating": int(review.rating),
            "comment": review.comment,
            "created_at": review.created_at,
        }
        for review, reviewer in review_rows
    ]
    average_rating = round(sum(item["rating"] for item in review_items) / len(review_items), 1) if review_items else 0

    seller_rating_summary = (0, 0)
    seller_items_sold = 0
    seller_member_since = seller.created_at if seller else None
    if seller_id:
        seller_rating_summary = db.query(
            func.avg(Review.rating),
            func.count(Review.id),
        ).join(
            Order, Order.id == Review.order_id
        ).filter(
            Order.seller_id == seller_id,
            Review.is_hidden.is_(False),
        ).first() or (0, 0)
        seller_items_sold = db.query(
            func.coalesce(func.sum(Order.quantity), 0),
        ).filter(
            Order.seller_id == seller_id,
            func.lower(Order.status) == "completed",
        ).scalar() or 0

    try:
        image_notes = json.loads(product.image_notes or "[]")
    except (TypeError, json.JSONDecodeError):
        image_notes = []
    image_values = _product_image_values(product.image)
    gallery = [
        {"url": image_url, "note": image_notes[index] if index < len(image_notes) else None}
        for index, image_url in enumerate(image_values) if image_url
    ]

    if is_owner:
        similar_query = apply_public_listing_filters(
            _public_marketplace_product_query(db),
            authenticated_student,
        ).filter(Product.id != product.id)
        if product.category:
            similar_query = similar_query.filter(Product.category == product.category)
        if product.subcategory:
            similar_query = similar_query.filter(Product.subcategory == product.subcategory)
        similar_products = similar_query.order_by(Product.created_at.desc()).limit(8).all()
    else:
        similar_products = _get_similar_products(db, product, authenticated_student)

    seller_values = {value for value in (seller_id, seller.name if seller else None) if value}
    more_from_seller = []
    if seller_values:
        more_from_seller = db.query(Product).filter(
            Product.id != product.id,
            Product.seller.in_(seller_values),
            func.lower(Product.status) == "approved",
            Product.stock > 0,
        ).order_by(Product.created_at.desc()).limit(4).all()

    response_hours = []
    if seller_id:
        messages = db.query(Message).filter(
            or_(Message.sender_id == seller_id, Message.receiver_id == seller_id),
        ).order_by(Message.created_at.asc(), Message.id.asc()).all()
        listing_messages = [message for message in messages if message.product_id == product.id]
        for index, message in enumerate(listing_messages):
            if message.sender_id == seller_id:
                continue
            seller_reply = next((
                candidate for candidate in listing_messages[index + 1:]
                if candidate.sender_id == seller_id and candidate.receiver_id == message.sender_id
            ), None)
            if seller_reply and message.created_at and seller_reply.created_at:
                response_hours.append((seller_reply.created_at - message.created_at).total_seconds() / 3600)

    typical_response_bucket = _seller_typical_response_bucket(db, seller_id)

    db.commit()

    result = {
        "id": product.id,
        "title": product.title,
        "category": product.category,
        "subcategory": product.subcategory,
        "price": product.price,
        "stock": max(0, int(product.stock or 0)),
        "image": _normalize_product_image(product.image),
        "images": gallery,
        "description": product.description,
        "seller": product.seller,
        "seller_id": seller_id,
        "seller_name": seller.name if seller else product.seller,
        "seller_dept": seller.department if seller else None,
        "seller_payout_status": _seller_payout_status(db, product.seller),
        "negotiable": bool(product.negotiable),
        "pickup_location": product.pickup_location,
        "pickup_hours": product.pickup_hours,
        "status": product.status,
        "created_at": product.created_at,
        "reviews": review_items,
        "average_rating": average_rating,
        "review_count": len(review_items),
        "seller_average_rating": round(float(seller_rating_summary[0] or 0), 1),
        "seller_review_count": int(seller_rating_summary[1] or 0),
        "seller_items_sold": int(seller_items_sold),
        "seller_member_since": seller_member_since,
        "views": int(product.views or 0),
        "similar_products": [
            ({
                "id": similar.id,
                "title": similar.title,
                "category": similar.category,
                "subcategory": similar.subcategory,
                "price": similar.price,
                "image": _normalize_product_image(similar.image),
                "description": similar.description,
                "pickup_location": similar.pickup_location,
            } if is_owner else _similar_product_response(similar))
            for similar in similar_products
        ],
        "more_from_seller": [
            {
                "id": other.id,
                "title": other.title,
                "price": other.price,
                "image": _normalize_product_image(other.image),
                "pickup_location": other.pickup_location,
            }
            for other in more_from_seller
        ],
        "seller_response_time_hours": round(sum(response_hours) / len(response_hours), 1) if response_hours else None,
        "seller_typical_response_bucket": typical_response_bucket,
    }
    if authenticated_student or authenticated_admin:
        result["seller_phone"] = seller.phone if seller else None
    result["is_owner"] = is_owner
    if is_owner:
        result["stats"] = {
            "views": int(product.views or 0),
            "wishlist_count": db.query(WishlistItem.id).filter(
                WishlistItem.product_id == product.id,
            ).count(),
            "inquiries_count": db.query(func.count(func.distinct(Message.sender_id))).filter(
                Message.product_id == product.id,
                Message.receiver_id == seller_id,
                Message.sender_id != seller_id,
            ).scalar() or 0,
            "cart_count": db.query(func.coalesce(func.sum(CartItem.quantity), 0)).filter(
                CartItem.product_id == product.id,
            ).scalar() or 0,
        }
    return result


