# 4.1. አዲስ ተለጠፈ እቃ በተማሪ ወይም ሻጭ የሚፈጠር ኤፒአይ (POST /api/products)
# 4.1. አዲስ ተለጠፈ እቃ በተማሪ ወይም ሻጭ የሚፈጠር ኤፒአይ (POST /api/products)
@app.post("/api/products", status_code=status.HTTP_201_CREATED)
def create_product(
    title: str = Form(...),
    category: str = Form(...),
    subcategory: Optional[str] = Form(None),
    price: str = Form(...),
    quantity: int = Form(1),
    condition: Optional[str] = Form(None),
    pickup_location: Optional[str] = Form(None),
    pickup_hours: Optional[str] = Form(None),
    negotiable: bool = Form(False),
    image_notes: Optional[str] = Form(None),
    description: Optional[str] = Form(None),
    seller: Optional[str] = Form(None),
    student_id: Optional[str] = Form(None),  # <-- ADDED: Capture student_id from frontend Form
    images: List[UploadFile] = File(default=[]),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db)
):
    """
    ተለጠፈ እቃ ፈጠር - ተማሪ ወይም ሻጭ አዲስ ምርት ሊለጥፉ ይችላሉ።
    """
    try:
        title_value = str(title or "").strip()
        price_value = str(price or "").strip()
        if not title_value:
            raise HTTPException(status_code=422, detail="Product title is required.")
        if not price_value:
            raise HTTPException(status_code=422, detail="Product price is required.")
        if quantity <= 0:
            raise HTTPException(status_code=422, detail="Product quantity must be at least 1.")

        image_url = None
        max_images_per_product = _get_setting_value(
            db,
            "marketplace",
            "maxImagesPerProduct",
            DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImagesPerProduct"],
        )
        try:
            max_images_per_product = max(0, int(max_images_per_product))
        except (TypeError, ValueError):
            max_images_per_product = DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImagesPerProduct"]
        max_image_size = _get_setting_value(
            db,
            "marketplace",
            "maxImageSize",
            DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImageSize"],
        )

        if len(images) > max_images_per_product:
            raise HTTPException(
                status_code=400,
                detail=f"You can upload a maximum of {max_images_per_product} images per product.",
            )
        require_approval = _setting_bool(
            _get_setting_value(
                db,
                "marketplace",
                "requireApproval",
                DEFAULT_SETTINGS_BLOCKS["marketplace"]["requireApproval"],
            ),
            DEFAULT_SETTINGS_BLOCKS["marketplace"]["requireApproval"],
        )

        authenticated_student = _student_from_authorization(authorization, db)
        normalized_student_id = authenticated_student.student_id
        _require_verified_student(authenticated_student, db, "posting listings")
        payout_account = db.query(SellerPaymentAccount).filter(
            SellerPaymentAccount.student_id == normalized_student_id,
        ).first()
        if not payout_account or str(payout_account.account_status or "").strip().lower() != "active":
            raise HTTPException(
                status_code=403,
                detail="Complete payout setup before listing products, so you can receive payment for sales.",
            )
        
        # ስዕል ወደ ፋይል ያስቀምጡ (Save image if provided)
        image_urls = []
        for image in images:
            if not image.filename:
                continue

            allowed_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.webp', '.jfif'}
            file_ext = os.path.splitext(image.filename)[1].lower()
            
            if file_ext not in allowed_extensions:
                raise HTTPException(status_code=400, detail="Invalid image format. Allowed: jpg, jpeg, png, gif, webp, jfif")

            max_image_size_bytes = _parse_size_bytes(max_image_size)
            image_urls.append(save_upload(image, "campace/products", max_size_bytes=max_image_size_bytes))

        image_url = json.dumps(image_urls, ensure_ascii=False) if image_urls else None
        try:
            parsed_image_notes = json.loads(image_notes or "[]")
            if not isinstance(parsed_image_notes, list):
                parsed_image_notes = []
        except json.JSONDecodeError:
            parsed_image_notes = []
        
        # Resolve the seller's identity properly (የሻጩን ማንነት መፍታት)
        seller_value = normalized_student_id

        initial_status = "Pending" if require_approval else "Approved"
        _validate_product_stock_status(quantity, initial_status)

        # ምርት ወደ ዳታቤዝ ያስቀምጡ (Save product to database)
        db_product = Product(
            title=title_value,
            category=category,
            subcategory=subcategory,
            price=price_value,
            stock=quantity,
            condition=condition,
            image=image_url,
            image_notes=json.dumps(parsed_image_notes, ensure_ascii=False),
            description=description,
            seller=seller_value,
            seller_id=normalized_student_id,
            negotiable=negotiable,
            pickup_location=str(pickup_location or "").strip(),
            pickup_hours=(pickup_hours or "08:00-17:00").strip(),
            status=initial_status
        )
        db_product.location = "Addis Ababa"
        db.add(db_product)
        db.commit()
        db.refresh(db_product)
        
        return {
            "success": True,
            "message": "Product posted successfully! Awaiting admin approval." if require_approval else "Product posted successfully!",
            "product": {
                "id": db_product.id,
                "title": db_product.title,
                "image": _normalize_product_image(db_product.image),
                "pickup_location": db_product.pickup_location,
                "status": db_product.status,
                "created_at": db_product.created_at
            }
        }
    except HTTPException:
        raise
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=500, detail=f"Failed to create product: {str(e)}")


@app.put("/api/student/products/{product_id}")
def update_student_product(
    product_id: int,
    payload: StudentProductUpdate,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Update a seller's own product details or marketplace status."""
    allow_editing = _setting_bool(
        _get_setting_value(
            db,
            "marketplace",
            "allowEditing",
            DEFAULT_SETTINGS_BLOCKS["marketplace"]["allowEditing"],
        ),
        DEFAULT_SETTINGS_BLOCKS["marketplace"]["allowEditing"],
    )
    if not allow_editing:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Product editing is currently disabled.")

    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")
    authenticated_student = _student_from_authorization(authorization, db)
    if str(product.seller or "").strip().lower() not in {
        authenticated_student.student_id.strip().lower(),
        authenticated_student.name.strip().lower(),
    }:
        raise HTTPException(status_code=403, detail="You can only update your own products.")
    if payload.quantity is not None and payload.quantity < 0:
        raise HTTPException(status_code=400, detail="Product quantity cannot be negative.")

    next_stock = int(payload.quantity) if payload.quantity is not None else int(getattr(product, "stock", 0) or 0)
    next_status = payload.status if payload.status is not None else product.status
    if payload.quantity == 0 and str(next_status or "").strip().lower() != "sold":
        raise HTTPException(status_code=400, detail="Product quantity must be at least 1 unless the product is Sold.")
    if payload.quantity is not None and payload.quantity > 0 and str(product.status or "").strip().lower() == "sold" and payload.status is None:
        next_status = "Approved"
    if str(next_status or "").strip().lower() == "sold":
        if payload.quantity is not None and payload.quantity > 0:
            raise HTTPException(status_code=400, detail="Set stock to 0 before marking a product Sold.")
        next_stock = 0
    _validate_product_stock_status(next_stock, next_status)

    update_fields = {
        "title": payload.title,
        "category": payload.category,
        "subcategory": payload.subcategory,
        "price": payload.price,
        "stock": next_stock if payload.quantity is not None or str(next_status or "").strip().lower() == "sold" else None,
        "description": payload.description,
        "condition": payload.condition,
        "pickup_location": payload.pickup_location,
        "pickup_hours": payload.pickup_hours,
        "negotiable": payload.negotiable,
        "image_notes": json.dumps(payload.image_notes, ensure_ascii=False) if payload.image_notes is not None else None,
        "image": json.dumps(payload.image, ensure_ascii=False) if payload.image is not None else None,
        "status": next_status if payload.status is not None or next_status != product.status else None,
    }
    for field_name, value in update_fields.items():
        if value is not None:
            setattr(product, field_name, value)

    db.commit()
    db.refresh(product)
    return {
        "success": True,
        "product": {
            "id": product.id,
            "title": product.title,
            "category": product.category,
            "subcategory": product.subcategory,
            "price": product.price,
            "stock": int(getattr(product, "stock", 1) or 0),
            "description": product.description,
            "status": product.status,
            "image": _normalize_product_image(product.image),
            "condition": product.condition,
            "pickup_location": product.pickup_location,
            "pickup_hours": product.pickup_hours,
            "negotiable": bool(product.negotiable),
            "created_at": product.created_at,
        },
    }


@app.post("/api/student/products/{product_id}/images")
async def upload_student_product_images(
    product_id: int,
    existing_images: str = Form("[]"),
    images: List[UploadFile] = File(default=[]),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Replace the selected product images while preserving seller ownership checks."""
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")
    authenticated_student = _student_from_authorization(authorization, db)
    if str(product.seller or "").strip().lower() not in {
        authenticated_student.student_id.strip().lower(),
        authenticated_student.name.strip().lower(),
    }:
        raise HTTPException(status_code=403, detail="You can only update your own products.")

    try:
        requested_existing = json.loads(existing_images or "[]")
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise HTTPException(status_code=400, detail="Existing product images are invalid.") from error
    if not isinstance(requested_existing, list):
        raise HTTPException(status_code=400, detail="Existing product images must be a list.")

    raw_images = product.image
    try:
        current_images = json.loads(raw_images) if isinstance(raw_images, str) and raw_images.strip().startswith("[") else [raw_images]
    except json.JSONDecodeError:
        current_images = [raw_images]
    current_images = [str(item).strip() for item in current_images if str(item or "").strip()]
    current_image_keys = {
        image
        for item in current_images
        for image in (item, _normalize_product_image(item))
        if image
    }
    retained_images = [
        str(item).strip()
        for item in requested_existing
        if str(item or "").strip() in current_image_keys
        or _normalize_product_image(str(item).strip()) in current_image_keys
    ]
    max_image_size = _parse_size_bytes(_get_setting_value(
        db, "marketplace", "maxImageSize", DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImageSize"]
    ))
    new_image_urls = []
    for image in images:
        filename = image.filename or ""
        extension = os.path.splitext(filename)[1].lower()
        if extension not in {".jpg", ".jpeg", ".png", ".gif", ".webp", ".jfif"}:
            raise HTTPException(status_code=400, detail="Invalid image format.")
        try:
            image_url = save_upload(image, "campace/products", max_size_bytes=max_image_size)
        finally:
            await image.close()
        new_image_urls.append(image_url)

    product.image = json.dumps(retained_images + new_image_urls, ensure_ascii=False) if retained_images or new_image_urls else None
    db.commit()
    db.refresh(product)
    return {
        "success": True,
        "product": {
            "id": product.id,
            "title": product.title,
            "category": product.category,
            "price": product.price,
            "stock": int(getattr(product, "stock", 0) or 0),
            "status": product.status,
            "image": _normalize_product_image(product.image),
            "created_at": product.created_at,
        },
    }


@app.delete("/api/student/products/{product_id}")
def delete_student_product(
    product_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    authenticated_student = _student_from_authorization(authorization, db)
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")
    if str(product.seller or "").strip().lower() not in {
        authenticated_student.student_id.strip().lower(),
        authenticated_student.name.strip().lower(),
    }:
        raise HTTPException(status_code=403, detail="You can only delete your own products.")
    if _product_has_open_orders(db, product.id):
        raise HTTPException(status_code=409, detail="Products with open orders cannot be deleted.")
    if _product_has_open_disputes(db, product.id):
        raise HTTPException(status_code=409, detail="Products with open disputes cannot be deleted.")
    if _product_has_orders(db, product.id):
        product.status = "Hidden"
        product.stock = 0
        db.commit()
        return {"success": True, "product_id": product_id, "soft_deleted": True}
    db.delete(product)
    db.commit()
    return {"success": True, "product_id": product_id, "soft_deleted": False}
    
@app.post("/api/student/chat/initiate")
def initiate_chat(
    request: ChatInitiateRequest,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    authenticated_student = _student_from_authorization(authorization, db)
    buyer_id = _validate_student_id(db, request.buyer_id, field_name="buyer_id")
    if buyer_id.strip().lower() != authenticated_student.student_id.strip().lower():
        raise HTTPException(status_code=403, detail="You can only start a chat as yourself.")
    buyer = db.query(Student).filter(Student.student_id == buyer_id).first()
    if not buyer:
        raise HTTPException(status_code=404, detail="Buyer not found")

    product = db.query(Product).filter(Product.id == request.product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found")
    _reject_own_product_action(db, product, authenticated_student)

    seller = None
    if product.seller:
        seller = db.query(Student).filter(
            (Student.student_id == product.seller) | (Student.name == product.seller)
        ).first()

    if not seller:
        raise HTTPException(status_code=404, detail="Seller not found")

    notification = None
    if seller.notif_msg_inapp:
        notification = Notification(
            student_id=seller.student_id,
            message=f"Student {buyer.name} wants to start a chat regarding your item {product.title}."
        )
        db.add(notification)
    if seller.notif_msg_email:
        _send_student_notification_email(
            seller,
            "New chat request",
            f"Student {buyer.name} wants to start a chat regarding your item {product.title}.",
            "message",
        )
    db.commit()
    if notification:
        db.refresh(notification)

    return {
        "success": True,
        "message": "Chat notification sent to the seller.",
        "notification_id": notification.id if notification else None,
    }


