# 21. የሻጭ ስታቲስቲክስ እና የደረሱ ትዕዛዞች መጥሪያ ኤፒአይ (GET /api/student/seller/dashboard-data) - Database-driven
SELLER_COMPLETED_ORDER_STATUSES = {"completed", "successful", "delivered", "sold"}
SELLER_PAID_ORDER_STATUSES = {"successful", "success", "paid", "completed"}


def _seller_completed_product_ids(db: Session, seller_filter) -> set[int]:
    completed_product_rows = db.query(Order.product_id).join(
        Product, Order.product_id == Product.id,
    ).filter(
        seller_filter,
        func.lower(func.trim(func.coalesce(Order.status, ""))).in_(SELLER_COMPLETED_ORDER_STATUSES),
        func.lower(func.trim(func.coalesce(Order.payment_status, ""))).in_(SELLER_PAID_ORDER_STATUSES),
    ).distinct().all()
    return {product_id for (product_id,) in completed_product_rows if product_id is not None}


def _seller_product_is_sold(product: Product, completed_product_ids: set[int]) -> bool:
    return bool(
        str(product.status or "").strip().lower() == "sold"
        or int(getattr(product, "stock", 0) or 0) <= 0
        or product.id in completed_product_ids
    )


def _seller_inventory_summary(products: List[Product], completed_product_ids: set[int]) -> dict:
    summary = {"total": len(products), "active": 0, "sold": 0, "pending": 0}
    for product in products:
        normalized_status = str(product.status or "Pending").strip().lower()
        if _seller_product_is_sold(product, completed_product_ids):
            summary["sold"] += 1
        elif normalized_status in {"approved", "active", "available"}:
            summary["active"] += 1
        elif normalized_status in {"pending", "under review", "under_review"}:
            summary["pending"] += 1
    return summary


@app.get("/api/student/seller/products")
def get_seller_products(
    student_id: str,
    page: int = Query(1),
    page_size: int = Query(10),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    if student.student_id.strip().lower() != str(student_id).strip().lower():
        raise HTTPException(status_code=403, detail="You can only view your own products.")

    seller_filter = (Product.seller_id == student.student_id) | (
        Product.seller_id.is_(None)
        & ((Product.seller == student.student_id) | (Product.seller == student.name))
    )
    page_size = min(max(page_size, 1), 50)
    inventory_products = db.query(Product).filter(seller_filter).all()
    completed_product_ids = _seller_completed_product_ids(db, seller_filter)
    summary = _seller_inventory_summary(inventory_products, completed_product_ids)
    total = summary["total"]
    total_pages = math.ceil(total / page_size) if total else 0
    page = min(max(page, 1), total_pages) if total_pages else 1

    products = (
        db.query(Product)
        .filter(seller_filter)
        .order_by(Product.created_at.desc(), Product.id.desc())
        .offset((page - 1) * page_size)
        .limit(page_size)
        .all()
    )
    product_ids = [product.id for product in products]
    products_with_orders = set()
    if product_ids:
        products_with_orders = {
            product_id
            for (product_id,) in db.query(Order.product_id)
            .filter(Order.product_id.in_(product_ids))
            .distinct()
            .all()
        }

    items = [
        {
            "id": product.id,
            "title": product.title,
            "category": product.category,
            "subcategory": product.subcategory,
            "price": product.price,
            "stock": int(getattr(product, "stock", 1) or 0),
            "image": _normalize_product_image(product.image),
            "status": "Sold" if _seller_product_is_sold(product, completed_product_ids) else product.status,
            "has_orders": product.id in products_with_orders,
            "has_completed_orders": product.id in completed_product_ids,
            "sold_via": (
                "Marketplace Order" if product.id in completed_product_ids
                else "Marked by Seller" if _seller_product_is_sold(product, completed_product_ids)
                else None
            ),
            "created_at": product.created_at,
        }
        for product in products
    ]
    return {
        "items": items,
        "total": total,
        "page": page,
        "page_size": page_size,
        "total_pages": total_pages,
        "summary": summary,
    }


@app.get("/api/student/seller/dashboard-data")
def get_seller_dashboard_data(
    student_id: str,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Return database-backed seller KPIs, alerts, listings, and received orders."""
    student = _student_from_authorization(authorization, db)
    if student.student_id.strip().lower() != str(student_id).strip().lower():
        raise HTTPException(status_code=403, detail="You can only view your own seller dashboard.")

    seller_filter = (Product.seller_id == student.student_id) | (
        Product.seller_id.is_(None)
        & ((Product.seller == student.student_id) | (Product.seller == student.name))
    )

    all_listings = db.query(Product).filter(seller_filter).order_by(Product.created_at.desc()).all()
    completed_product_ids = _seller_completed_product_ids(db, seller_filter)
    listings = [
        listing for listing in all_listings
        if not _seller_product_is_sold(listing, completed_product_ids)
    ]
    received_orders = db.query(Order).join(Product, Order.product_id == Product.id).filter(
        seller_filter,
    ).order_by(Order.created_at.desc()).all()

    inventory_summary = _seller_inventory_summary(all_listings, completed_product_ids)
    active_listings = inventory_summary["active"]
    pending_listings = inventory_summary["pending"]
    sold_listings = inventory_summary["sold"]
    pending_orders = sum(str(order.status or "").strip().lower() in {"pending", "processing"} for order in received_orders)
    completed_orders = [
        order for order in received_orders
        if str(order.status or "").strip().lower() in {"completed", "successful", "delivered", "sold"}
    ]
    completed_revenue = sum(
        float(re.sub(r"[^0-9.]", "", str(order.price or "0")) or 0)
        for order in completed_orders
    )
    listing_analytics = _build_seller_listing_analytics(listings, completed_orders)
    for item in listing_analytics:
        item["has_orders"] = _product_has_orders(db, item["listing"].id)
    advisor_candidate = next(
        (
            item for item in sorted(listing_analytics, key=lambda value: value["views"], reverse=True)
            if item["views"] > 0 and item["conversion_rate"] < 2
        ),
        max(listing_analytics, key=lambda value: value["views"], default=None),
    )
    review_average = db.query(func.avg(Review.rating)).join(
        Order, Review.order_id == Order.id
    ).join(
        Product, Order.product_id == Product.id
    ).filter(
        seller_filter,
        Review.is_hidden.is_(False),
    ).scalar()
    cancelled_orders = [
        order for order in received_orders
        if str(order.status or "").strip().lower() in {"cancelled", "canceled", "rejected"}
    ]
    resolved_orders = len(completed_orders) + len(cancelled_orders)
    order_completion = (len(completed_orders) / resolved_orders * 100) if resolved_orders else 0
    response_rate = (
        (len(received_orders) - len(cancelled_orders)) / len(received_orders) * 100
        if received_orders else 0
    )
    payout_account = db.query(SellerPaymentAccount).filter(
        SellerPaymentAccount.student_id == student.student_id,
    ).first()

    return {
        "account_status": payout_account.account_status if payout_account else "Pending",
        "stats": {
            "total_listings": len(all_listings),
            "active_listings": active_listings,
            "pending_listings": pending_listings,
            "sold_listings": sold_listings,
            "received_orders": len(received_orders),
            "completed_revenue": completed_revenue,
            "pending_orders": pending_orders,
            "unapproved_products": pending_listings,
        },
        "alerts": {
            "pending_orders": pending_orders,
            "unapproved_products": pending_listings,
            "open_disputes": db.query(Dispute).filter(
                Dispute.seller_id == student.student_id,
                Dispute.status.in_(ACTIVE_DISPUTE_STATUSES),
            ).count(),
        },
        "performance": {
            "rating": round(float(review_average or 0), 1),
            "response_rate": round(response_rate, 1),
            "order_completion": round(order_completion, 1),
        },
        "my_listings": [
            {
                "id": item["listing"].id,
                "title": item["listing"].title,
                "category": item["listing"].category,
                "subcategory": item["listing"].subcategory,
                "price": item["listing"].price,
                "stock": int(getattr(item["listing"], "stock", 1) or 0),
                "image": _normalize_product_image(item["listing"].image),
                "status": item["listing"].status,
                "has_orders": item["has_orders"],
                "sold_via": (
                    "Marketplace Order" if item["has_orders"]
                    else "Marked by Seller" if str(item["listing"].status or "").strip().lower() == "sold"
                    else None
                ),
                "created_at": item["listing"].created_at,
                "views": item["views"],
                "completed_orders": item["completed_orders"],
                "completed_revenue": item["completed_revenue"],
                "conversion_rate": item["conversion_rate"],
            }
            for item in listing_analytics
        ],
        "advisor": {
            "product_id": advisor_candidate["listing"].id,
            "product_title": advisor_candidate["listing"].title,
            "views": advisor_candidate["views"],
            "completed_orders": advisor_candidate["completed_orders"],
            "conversion_rate": advisor_candidate["conversion_rate"],
        } if advisor_candidate else None,
        "received_orders": [
            _serialize_order(db, o)
            for o in received_orders
        ]
    }


@app.get("/api/student/seller/sales-analytics")
@app.get("/api/seller/analytics")
@app.get("/seller/analytics")
def get_seller_sales_analytics(
    request: Request = None,
    range_value: str = Query("3m", alias="range"),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Return range-scoped seller KPIs, comparisons, and revenue series."""
    if isinstance(request, str):
        # Compatibility for direct helper-style calls in tests and older callers.
        legacy_range = request
        legacy_authorization = range_value
        legacy_db = authorization
        request = None
        range_value = legacy_range
        authorization = legacy_authorization
        db = legacy_db

    if request is not None:
        session_token = request.cookies.get("session_token", "").strip()
    else:
        session_token = ""

    student = _student_from_authorization(
        authorization or (f"Bearer {session_token}" if session_token else None),
        db,
    )
    normalized_range = str(range_value or "3m").strip().lower()
    if normalized_range not in {"7d", "30d", "3m"}:
        raise HTTPException(status_code=400, detail="Range must be 7d, 30d, or 3m.")

    now = analytics_local_now()
    current_buckets = get_sales_trend_buckets(normalized_range, now)
    current_start = current_buckets.start
    previous_buckets = get_sales_trend_buckets(
        normalized_range,
        current_start - timedelta(microseconds=1),
    )
    previous_start = previous_buckets.start
    current_end = current_buckets.end

    seller_filter = or_(
        Product.seller_id == student.student_id,
        and_(
            Product.seller_id.is_(None),
            or_(
                Product.seller == student.student_id,
                Product.seller == student.name,
            ),
        ),
    )
    completed_statuses = {"completed", "successful", "delivered", "sold"}
    completed_at = func.coalesce(Order.completed_at, Order.created_at)

    def aggregate(start, end, starts):
        orders = db.query(Order).join(Product, Order.product_id == Product.id).filter(
            seller_filter,
            func.lower(func.trim(Order.status)).in_(completed_statuses),
            completed_at >= start,
            completed_at < end,
        ).all()
        revenue_buckets = {item: 0.0 for item in starts}
        order_buckets = {item: 0 for item in starts}
        revenue = 0.0
        products_sold = 0
        for order in orders:
            quantity = int(order.quantity or 1)
            amount = float(re.sub(r"[^0-9.]", "", str(order.price or "0")) or 0) * quantity
            revenue += amount
            products_sold += quantity
            order_time = (
                getattr(order, "completed_at", None)
                or getattr(order, "created_at", None)
                or now
            )
            bucket = (
                datetime(order_time.year, order_time.month, 1)
                if normalized_range == "3m"
                else order_time.date()
            )
            if bucket in revenue_buckets:
                revenue_buckets[bucket] += amount
                order_buckets[bucket] += 1
        views = db.query(ProductView).join(Product, ProductView.product_id == Product.id).filter(
            seller_filter,
            ProductView.viewed_at >= start,
            ProductView.viewed_at < end,
        ).count()
        return {
            "revenue": revenue,
            "orders": len(orders),
            "products_sold": products_sold,
            "views": views,
            "conversion_rate": len(orders) / views * 100 if views else 0,
            "average_order_value": revenue / len(orders) if orders else 0,
            "revenue_buckets": revenue_buckets,
            "order_buckets": order_buckets,
        }

    current = aggregate(current_start, current_end, current_buckets.buckets)
    previous = aggregate(previous_start, current_start, previous_buckets.buckets)

    def percent_change(current_value, previous_value):
        return 100.0 if current_value and not previous_value else ((current_value - previous_value) / previous_value * 100 if previous_value else 0.0)

    points = [{
        "date": bucket.isoformat(),
        "label": label,
        "total": round(current["revenue_buckets"][bucket], 2),
        "orders": current["order_buckets"][bucket],
    } for bucket, label in zip(current_buckets.buckets, current_buckets.labels)]
    total_revenue = round(current["revenue"], 2)
    return {
        "range": normalized_range,
        "points": points,
        "labels": list(current_buckets.labels),
        "values": [point["total"] for point in points],
        "totals": {
            "revenue": total_revenue,
            "orders": current["orders"],
        },
        "stats": {
            "total_revenue": total_revenue,
            "total_orders": current["orders"],
            "products_sold": current["products_sold"],
            "conversion_rate": round(current["conversion_rate"], 2),
            "average_order_value": round(current["average_order_value"], 2),
            "total_views": current["views"],
        },
        "comparisons": {
            "total_revenue": round(percent_change(current["revenue"], previous["revenue"]), 2),
            "total_orders": round(percent_change(current["orders"], previous["orders"]), 2),
            "products_sold": round(percent_change(current["products_sold"], previous["products_sold"]), 2),
            "conversion_rate": round(percent_change(current["conversion_rate"], previous["conversion_rate"]), 2),
            "average_order_value": round(percent_change(current["average_order_value"], previous["average_order_value"]), 2),
            "total_views": round(percent_change(current["views"], previous["views"]), 2),
        },
        "total": total_revenue,
        "order_count": current["orders"],
    }


