# ==========================================
# --- Student Support, Activity, Feeds ---
# ==========================================

# 5. ተማሪዎች አዲስ ቅሬታ ወይም የድጋፍ ፎርም የሚልኩበት ኤፒአይ (POST /api/student/report)
@app.post("/api/student/report", status_code=status.HTTP_201_CREATED)
def create_report(
    background_tasks: BackgroundTasks = None,
    student_name: str = Form(...),
    email: str = Form(...),
    category: str = Form(...),
    issue: str = Form(...),
    product_id: Optional[int] = Form(None),
    order_id: Optional[int] = Form(None),
    student_id: Optional[str] = Form(None),
    seller_id: Optional[str] = Form(None),
    evidence_image: Optional[UploadFile] = File(None),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    try:
        authenticated_student = _student_from_authorization(authorization, db)
        if not isinstance(product_id, int):
            product_id = None
        if not isinstance(order_id, int):
            order_id = None
        if not isinstance(seller_id, str):
            seller_id = None

        allow_student_reports = _setting_bool(
            _get_setting_value(
                db,
                "moderation",
                "allowStudentReports",
                DEFAULT_SETTINGS_BLOCKS["moderation"]["allowStudentReports"],
            ),
            DEFAULT_SETTINGS_BLOCKS["moderation"]["allowStudentReports"],
        )
        if product_id is not None and not allow_student_reports:
            raise HTTPException(status_code=403, detail="Product reporting is currently disabled.")

        provided_student_id = student_id.strip() if student_id else None
        if provided_student_id and provided_student_id.strip().lower() != authenticated_student.student_id.strip().lower():
            raise HTTPException(status_code=403, detail="You can only submit a report as yourself.")
        student = authenticated_student
        if len(issue.strip()) < 10 or len(issue) > 5000:
            raise HTTPException(status_code=422, detail="Report text must be between 10 and 5000 characters.")
        since = datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(hours=1)
        recent_count = db.query(Report.id).filter(
            Report.student_id == student.student_id,
            Report.created_at >= since,
        ).count()
        if recent_count >= SUPPORT_RATE_LIMIT_PER_HOUR:
            raise HTTPException(status_code=429, detail="Report limit reached. Please try again later.")

        product = None
        order = None
        if order_id is not None:
            order = db.query(Order).filter(Order.id == order_id).first()
            if not order:
                raise HTTPException(status_code=404, detail="Order not found.")
            if not authenticated_student or order.student_id != authenticated_student.student_id:
                raise HTTPException(status_code=403, detail="You can only report your own order.")
            if product_id is not None and product_id != order.product_id:
                raise HTTPException(status_code=422, detail="The product does not match the selected order.")
            product_id = order.product_id

        if product_id is not None:
            product = db.query(Product).filter(Product.id == product_id).first()
            if not product:
                raise HTTPException(status_code=404, detail="Product not found.")
            if order is None:
                _reject_own_product_action(db, product, authenticated_student)

        owner_student_id = get_product_owner_student_id(db, product)
        seller_match = _student_by_exact_id(db, owner_student_id)
        if not seller_match and not product and not order:
            seller_match = _student_by_exact_id(db, seller_id)
        reported_seller_id = seller_match.student_id if seller_match else None

        evidence_url = None
        if evidence_image and evidence_image.filename:
            allowed_extensions = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".jfif"}
            file_ext = os.path.splitext(evidence_image.filename)[1].lower()
            if file_ext not in allowed_extensions:
                raise HTTPException(status_code=400, detail="Invalid evidence image format.")
            max_evidence_size = _parse_size_bytes(_get_setting_value(
                db, "marketplace", "maxImageSize", DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImageSize"]
            ))
            evidence_url = _store_private_report_evidence(evidence_image, max_evidence_size)

        normalized_issue = issue.strip()
        db_report = Report(
            product_id=product.id if product else None,
            order_id=order.id if order else None,
            student_id=student.student_id if student else None,
            seller_id=reported_seller_id,
            student_name=student.name,
            email=student.email,
            category=category.strip() if category else None,
            issue=normalized_issue,
            evidence_image=evidence_url,
            priority=determine_report_priority(normalized_issue),
            status="Open"
        )
        db.add(db_report)
        db.flush()
        report_reference = f"RPT-{db_report.id:04d}"
        report_url = f"/dashboard?tab=buyer&section=reports-support&item=report-{db_report.id}"
        outbox_id = _queue_student_item_notification(
            db,
            student,
            title="Report received",
            message=f"We received your report {report_reference}.",
            item_type="report",
            item_id=db_report.id,
            action_url=report_url,
            email_subject=f"We received your report {report_reference}",
            email_summary=f"We usually reply within {SUPPORT_SLA_HOURS} hours.",
            email_status="Received",
            critical=True,
        )
        _notify_admins(
            db,
            title=f"New report {report_reference}",
            message="A student submitted a report for admin review.",
            reference_type="report",
            reference_id=db_report.id,
            action_url=f"/admin/reports?report={db_report.id}",
        )

        if product:
            active_report_count = db.query(Report).filter(
                Report.product_id == product.id,
                Report.status.in_(["Open", "Pending"]),
            ).count()
            max_reports_before_review = _get_setting_value(
                db,
                "moderation",
                "maxReportsBeforeReview",
                DEFAULT_SETTINGS_BLOCKS["moderation"]["maxReportsBeforeReview"],
            )
            try:
                max_reports_before_review = max(1, int(max_reports_before_review))
            except (TypeError, ValueError):
                max_reports_before_review = DEFAULT_SETTINGS_BLOCKS["moderation"]["maxReportsBeforeReview"]

            if active_report_count >= max_reports_before_review:
                product.status = "Flagged"
                db.add(AuditLog(
                    action="AUTO_FLAG_PRODUCT",
                    entity_type="Product",
                    entity_id=product.id,
                    description=f"Product automatically flagged after {active_report_count} active reports.",
                    status="SUCCESS",
                    severity="warning",
                ))

        db.commit()
        db.refresh(db_report)
        _schedule_outbox_delivery(background_tasks, db, outbox_id)

        return {
            "message": "Report submitted successfully.",
            "ticket_reference": report_reference,
            "report": {
                "id": db_report.id,
                "product_id": db_report.product_id,
                "order_id": db_report.order_id,
                "student_id": db_report.student_id,
                "seller_id": db_report.seller_id,
                "student_name": db_report.student_name,
                "email": db_report.email,
                "category": db_report.category,
                "issue": db_report.issue,
                "evidence_image": db_report.evidence_image,
                "priority": db_report.priority,
                "status": db_report.status,
                "created_at": db_report.created_at.isoformat() if db_report.created_at else None,
            },
        }
    except HTTPException:
        db.rollback()
        raise
    except Exception as error:
        db.rollback()
        logger.exception("Failed to create support report: %s", error)
        raise HTTPException(status_code=500, detail="Could not create support ticket.") from error


@app.get("/api/student/highlights")
def get_student_highlights(student_id: str, db: Session = Depends(get_db)):
    student = db.query(Student).filter(Student.student_id == student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found.")

    cart_rows = (
        db.query(CartItem, Product)
        .join(Product, CartItem.product_id == Product.id)
        .filter(CartItem.student_id == student_id)
        .all()
    )
    cart_total_etb = 0.0
    for cart_item, product in cart_rows:
        try:
            unit_price_etb = _parse_price_to_etb(product.price)
            cart_total_etb += unit_price_etb * int(cart_item.quantity or 1)
        except Exception:
            continue

    wishlist_count = db.query(WishlistItem).filter(WishlistItem.student_id == student_id).count()
    unread_notifications = db.query(Notification).filter(
        Notification.student_id == student_id,
        Notification.is_read.is_(False)
    ).count()
    pending_chat_messages = db.query(Notification).filter(
        Notification.student_id == student_id,
        Notification.is_read.is_(False),
        Notification.message.ilike('%chat%')
    ).count()
    approved_products = db.query(Product).filter(Product.status.ilike('%approved%')).count()

    pending_messages = unread_notifications + pending_chat_messages

    return {
        "student_id": student_id,
        "cartValue": round(cart_total_etb, 2),
        "cart_total_etb": round(cart_total_etb, 2),
        "wishlistCount": wishlist_count,
        "wishlist_count": wishlist_count,
        "unreadNotifications": unread_notifications,
        "unread_notifications": unread_notifications,
        "pendingChatMessages": pending_chat_messages,
        "pending_chat_messages": pending_chat_messages,
        "pendingMessages": pending_messages,
        "pending_messages": pending_messages,
        "aiPicks": min(3, max(approved_products, 0)),
        "latestListings": approved_products,
    }


def _collaborative_product_scores(student: Student, db: Session) -> Dict[int, float]:
    purchased_product_ids = {
        order.product_id
        for order in db.query(Order).filter(Order.student_id == student.student_id).all()
        if order.product_id
    }
    wishlist_product_ids = {
        item.product_id
        for item in db.query(WishlistItem).filter(WishlistItem.student_id == student.student_id).all()
        if item.product_id
    }
    interacted_product_ids = purchased_product_ids | wishlist_product_ids | {
        item.product_id
        for item in db.query(CartItem).filter(CartItem.student_id == student.student_id).all()
        if item.product_id
    }

    direct_peer_ids = {
        order.student_id
        for order in db.query(Order).filter(Order.product_id.in_(purchased_product_ids)).all()
        if order.student_id and order.student_id != student.student_id
    } if purchased_product_ids else set()
    direct_peer_ids.update(
        item.student_id
        for item in db.query(WishlistItem).filter(WishlistItem.product_id.in_(wishlist_product_ids)).all()
        if item.student_id and item.student_id != student.student_id
    ) if wishlist_product_ids else None

    cohort_query = db.query(Student.student_id).filter(Student.student_id != student.student_id)
    cohort_filters = []
    if getattr(student, "department", None):
        cohort_filters.append(Student.department == student.department)
    if getattr(student, "college", None):
        cohort_filters.append(Student.college == student.college)
    cohort_peer_ids = {
        peer_id for peer_id in cohort_query.filter(or_(*cohort_filters)).all()
        for peer_id in [peer_id[0]] if peer_id
    } if cohort_filters else set()

    if not direct_peer_ids and not cohort_peer_ids:
        return {}

    scores: Dict[int, float] = {}
    for order in db.query(Order).filter(Order.student_id.in_(direct_peer_ids | cohort_peer_ids)).all():
        if not order.product_id or order.product_id in interacted_product_ids:
            continue
        peer_weight = 1.0 if order.student_id in direct_peer_ids else 0.35
        purchase_weight = 2.0 if str(getattr(order, "status", "")).lower() == "completed" else 1.0
        scores[order.product_id] = scores.get(order.product_id, 0.0) + peer_weight * purchase_weight

    for item in db.query(WishlistItem).filter(WishlistItem.student_id.in_(direct_peer_ids | cohort_peer_ids)).all():
        if not item.product_id or item.product_id in interacted_product_ids:
            continue
        peer_weight = 1.0 if item.student_id in direct_peer_ids else 0.35
        scores[item.product_id] = scores.get(item.product_id, 0.0) + peer_weight * 0.75

    maximum_score = max(scores.values(), default=0.0)
    return {
        product_id: score / maximum_score
        for product_id, score in scores.items()
    } if maximum_score else {}


def _fallback_student_recommendations(
    department: str,
    college: str,
    products: List[dict],
    limit: int,
) -> List[dict]:
    profile_terms = {
        token for token in re.findall(r"[a-z0-9]+", f"{department} {college}".lower())
        if len(token) > 2
    }
    category_counts: Dict[str, int] = {}
    for product in products:
        category = str(product.get("category") or "").strip().lower()
        if category:
            category_counts[category] = category_counts.get(category, 0) + 1

    def recommendation_key(product: dict) -> tuple:
        category = str(product.get("category") or "").strip().lower()
        category_text = " ".join((
            category,
            str(product.get("subcategory") or ""),
            str(product.get("title") or ""),
        )).lower()
        department_match = sum(
            1 for term in profile_terms if term in category_text
        )
        created_at = product.get("created_at")
        return (
            department_match,
            category_counts.get(category, 0),
            created_at.isoformat() if created_at else "",
            product.get("id") or 0,
        )

    recommendations = []
    for product in sorted(products, key=recommendation_key, reverse=True)[:limit]:
        category = product.get("category") or "General"
        recommendations.append({
            "id": product.get("id"),
            "seller_id": product.get("seller_id"),
            "title": product.get("title") or "Marketplace item",
            "description": product.get("description") or "Recommended from campus marketplace categories.",
            "category": category,
            "price": product.get("price"),
            "image": product.get("image"),
            "match_score": 0,
            "match": "Recommended",
            "reason": (
                "Matches your department or college"
                if profile_terms and recommendation_key(product)[0] > 0
                else f"Recommended from {category} listings"
            ),
        })
    return recommendations


def _recommendation_traceback() -> str:
    rendered = traceback.format_exc()
    rendered = re.sub(
        r"(?i)(api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|secret)([\"']?\s*[:=]\s*[\"']?)[^\"'\s,;]+",
        r"\1\2[REDACTED]",
        rendered,
    )
    rendered = re.sub(r"(?i)(Bearer\s+)[^\s\"']+", r"\1[REDACTED]", rendered)
    rendered = re.sub(r"\bsk-[A-Za-z0-9_-]{20,}\b", "[REDACTED]", rendered)
    rendered = re.sub(r"\bAIza[A-Za-z0-9_-]{30,}\b", "[REDACTED]", rendered)
    return re.sub(
        r"(://[^:/\s]+:)[^@/\s]+@",
        r"\1[REDACTED]@",
        rendered,
    )


def _build_student_recommendations(
    student_id: str,
    db: Session,
    current_user: Optional[Student] = None,
):
    student = db.query(Student).filter(Student.student_id == student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found.")

    ai_enabled = _setting_bool(
        _get_setting_value(db, "ai", "enableAI", DEFAULT_SETTINGS_BLOCKS["ai"]["enableAI"]),
        DEFAULT_SETTINGS_BLOCKS["ai"]["enableAI"],
    )
    if not ai_enabled:
        return []

    try:
        num_recommendations = max(0, int(_get_setting_value(
            db,
            "ai",
            "numRecommendations",
            DEFAULT_SETTINGS_BLOCKS["ai"]["numRecommendations"],
        )))
    except (TypeError, ValueError):
        num_recommendations = DEFAULT_SETTINGS_BLOCKS["ai"]["numRecommendations"]

    try:
        min_similarity_score = float(_get_setting_value(
            db,
            "ai",
            "minSimilarityScore",
            DEFAULT_SETTINGS_BLOCKS["ai"]["minSimilarityScore"],
        ))
    except (TypeError, ValueError):
        min_similarity_score = DEFAULT_SETTINGS_BLOCKS["ai"]["minSimilarityScore"]

    if num_recommendations == 0:
        return []

    recommendation_engine = str(_get_setting_value(
        db,
        "ai",
        "recommendationEngine",
        DEFAULT_SETTINGS_BLOCKS["ai"]["recommendationEngine"],
    )).strip()
    supported_engines = {
        "Content-Based Filtering (TF-IDF)",
        "Collaborative Filtering",
        "Hybrid Recommendation",
    }
    if recommendation_engine not in supported_engines:
        recommendation_engine = DEFAULT_SETTINGS_BLOCKS["ai"]["recommendationEngine"]

    approved_products = apply_public_listing_filters(
        _public_marketplace_product_query(db),
        current_user,
    ).filter(Product.status.ilike("%approved%")).all()
    if not approved_products:
        return []

    department = str(getattr(student, "department", None) or "").strip()
    college = str(getattr(student, "college", None) or "").strip()
    fallback_products = [
        {
            "id": product.id,
            "seller_id": product.seller_id,
            "title": product.title,
            "description": product.description,
            "category": product.category,
            "subcategory": product.subcategory,
            "price": product.price,
            "image": _normalize_product_image(product.image),
            "created_at": product.created_at,
        }
        for product in approved_products
    ]
    try:
        owned_product_ids = {
            order.product_id
            for order in db.query(Order).filter(Order.student_id == student.student_id).all()
            if order.product_id
        }
        cart_product_ids = {
            item.product_id
            for item in db.query(CartItem).filter(CartItem.student_id == student.student_id).all()
            if item.product_id
        }
        wishlist_product_ids = {
            item.product_id
            for item in db.query(WishlistItem).filter(WishlistItem.student_id == student.student_id).all()
            if item.product_id
        }
        excluded_product_ids = owned_product_ids | cart_product_ids | wishlist_product_ids

        content_scores: Dict[int, float] = {}
        if recommendation_engine in {"Content-Based Filtering (TF-IDF)", "Hybrid Recommendation"}:
            profile_text = _student_interest_text(student, db)
            product_texts = [
                " ".join([
                    str(product.title or ''),
                    str(product.category or ''),
                    str(product.subcategory or ''),
                    str(product.description or ''),
                    str(product.seller or ''),
                ])
                for product in approved_products
            ]
            vectors, _ = _build_tfidf_vectors([profile_text] + product_texts)
            if vectors is not None:
                profile_vector = vectors[0:1]
                for idx, product in enumerate(approved_products, start=1):
                    content_scores[product.id] = _cosine_similarity(profile_vector, vectors[idx:idx + 1]) if idx < vectors.shape[0] else 0.0

        collaborative_scores = (
            _collaborative_product_scores(student, db)
            if recommendation_engine in {"Collaborative Filtering", "Hybrid Recommendation"}
            else {}
        )
        scored_products = []
        for product in approved_products:
            if product.id in excluded_product_ids:
                continue
            content_score = content_scores.get(product.id, 0.0)
            collaborative_score = collaborative_scores.get(product.id, 0.0)
            if recommendation_engine == "Collaborative Filtering":
                score = collaborative_score
            elif recommendation_engine == "Hybrid Recommendation":
                score = (content_score * 0.6) + (collaborative_score * 0.4)
            else:
                score = content_score
            scored_products.append({
                "product": product,
                "score": score,
                "content_score": content_score,
                "collaborative_score": collaborative_score,
            })
    except Exception:
        db.rollback()
        logger.error(
            "Recommendation scoring failed; using department/category fallback.\n%s",
            _recommendation_traceback(),
        )
        return _fallback_student_recommendations(
            department,
            college,
            fallback_products,
            num_recommendations,
        )

    scored_products.sort(key=lambda item: item["score"], reverse=True)
    threshold_matches = sum(item["score"] >= min_similarity_score for item in scored_products)
    logging.info(
        "[AI recommendations] student=%s engine=%s candidates=%d threshold=%.3f matches=%d limit=%d",
        student.student_id,
        recommendation_engine,
        len(scored_products),
        min_similarity_score,
        threshold_matches,
        num_recommendations,
    )
    threshold_fallback = threshold_matches == 0 and bool(scored_products)
    if threshold_fallback:
        logging.warning(
            "[AI recommendations] threshold %.3f filtered all scored candidates for student=%s; using closest matches",
            min_similarity_score,
            student.student_id,
        )
    best_matches = []
    seen_ids = set()
    for item in scored_products:
        product = item["product"]
        if item["score"] < min_similarity_score and not threshold_fallback:
            continue
        if product.id in seen_ids:
            continue
        seen_ids.add(product.id)
        if threshold_fallback:
            reason = "Closest match to your marketplace activity"
        elif item["collaborative_score"] > item["content_score"] and item["collaborative_score"] > 0:
            reason = "Popular among similar students"
        elif item["content_score"] > 0 and product.category:
            reason = f"Because you liked similar {product.category} items"
        elif department:
            reason = f"Because you're in {department}"
        else:
            reason = "Recommended from your marketplace activity"
        best_matches.append({
            "id": product.id,
            "seller_id": product.seller_id,
            "title": product.title,
            "description": product.description or 'Popular product recommended for your academic needs.',
            "category": product.category or 'General',
            "price": product.price,
            "image": _normalize_product_image(product.image),
            "match_score": round(item["score"], 4),
            "match": "High match" if item["score"] >= 0.15 else "Recommended",
            "reason": reason,
        })
        if len(best_matches) >= num_recommendations:
            break

    if len(best_matches) < num_recommendations:
        latest_products = apply_public_listing_filters(
            _public_marketplace_product_query(db),
            current_user,
        ).filter(
            Product.status.ilike("%approved%"),
        ).order_by(Product.created_at.desc()).limit(max(5, num_recommendations * 3)).all()
        for product in latest_products:
            if product.id in seen_ids or product.id in excluded_product_ids:
                continue
            seen_ids.add(product.id)
            best_matches.append({
                "id": product.id,
                "seller_id": product.seller_id,
                "title": product.title,
                "description": product.description or 'Latest active product available in the marketplace.',
                "category": product.category or 'General',
                "price": product.price,
                "image": _normalize_product_image(product.image),
                "match_score": 0,
                "match": "Latest listing",
                "reason": "Latest listing in the marketplace",
            })
            if len(best_matches) >= num_recommendations:
                break

    for recommendation in best_matches:
        db.add(AIRecommendationLog(
            student_id=student.student_id,
            product_id=recommendation["id"],
            action_type="impression",
        ))
    db.commit()
    return best_matches


def _filter_public_recommendations(
    recommendations: List[dict],
    current_user: Optional[Student],
    db: Session,
) -> List[dict]:
    if not recommendations:
        return recommendations

    def recommendation_product_id(recommendation: dict) -> Optional[int]:
        value = recommendation.get("id", recommendation.get("product_id"))
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    recommendation_ids = {
        product_id
        for recommendation in recommendations
        for product_id in [recommendation_product_id(recommendation)]
        if product_id is not None
    }
    if not recommendation_ids:
        return []

    visible_ids = {
        product_id
        for (product_id,) in apply_public_listing_filters(
            _public_marketplace_product_query(db),
            current_user,
        ).with_entities(Product.id).filter(Product.id.in_(recommendation_ids)).all()
    }
    return [
        recommendation
        for recommendation in recommendations
        if recommendation_product_id(recommendation) in visible_ids
    ]


@app.get("/api/student/recommendations")
def get_student_recommendations(
    student_id: str,
    db: Session = Depends(get_db),
    authorization: Optional[str] = Header(None, alias="Authorization"),
):
    try:
        current_user = _optional_student_from_authorization(authorization, db)
        recommendations = _build_student_recommendations(student_id, db, current_user)
        return _filter_public_recommendations(recommendations, current_user, db)
    except HTTPException:
        raise
    except Exception:
        db.rollback()
        logger.error(
            "Unexpected student recommendations failure.\n%s",
            _recommendation_traceback(),
        )
        return JSONResponse(
            status_code=500,
            content={"detail": "Unable to load recommendations right now. Please try again."},
        )


