@app.post("/api/student/notifications/mark-all-read")
def mark_all_student_notifications_read(
    student_id: str,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    if student.student_id != student_id:
        raise HTTPException(status_code=404, detail="Student not found.")

    unread_notifications = db.query(Notification).filter(
        Notification.student_id == student_id,
        Notification.is_read.is_(False),
    ).all()

    for notification in unread_notifications:
        notification.is_read = True

    db.commit()

    return {
        "success": True,
        "student_id": student_id,
        "updatedCount": len(unread_notifications),
        "updated_count": len(unread_notifications),
    }


@app.delete("/api/student/notifications/{notification_id}")
def delete_student_notification(
    notification_id: int,
    student_id: Optional[str] = None,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    if student_id and student.student_id != student_id:
        raise HTTPException(status_code=404, detail="Notification not found.")
    query = db.query(Notification).filter(
        Notification.id == notification_id,
        Notification.student_id == student.student_id,
    )
    notification = query.first()
    if not notification:
        raise HTTPException(status_code=404, detail="Notification not found.")

    try:
        db.delete(notification)
        db.commit()
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to delete notification.")

    return {"success": True, "notification_id": notification_id}


@app.post("/api/student/notifications")
def create_student_notification(request: NotificationCreate, db: Session = Depends(get_db)):
    validated_student_id = _validate_student_id(db, request.student_id)
    student = db.query(Student).filter(Student.student_id == validated_student_id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found.")

    notification_text = request.message.strip() if request.message and request.message.strip() else "Marketplace update"
    if request.title and request.title.strip():
        notification_text = f"{request.title.strip()}: {notification_text}"

    notification_type = request.type or "system"
    notification = Notification(
        student_id=request.student_id,
        title=request.title.strip() if request.title and request.title.strip() else None,
        message=notification_text,
        type=notification_type,
        is_read=False,
    )
    if notification_type not in NOTIFICATION_PREFERENCE_FIELDS or _student_notification_in_app_enabled(student, notification_type):
        db.add(notification)
    else:
        notification = None
    db.commit()
    if notification:
        db.refresh(notification)
    return {
        "success": True,
        "message": "Notification created successfully" if notification else "Notification preference is disabled",
        "notification": None if not notification else {
            "id": notification.id,
            "student_id": notification.student_id,
            "title": notification.title,
            "message": notification.message,
            "type": notification.type,
            "is_read": notification.is_read,
            "created_at": notification.created_at,
        },
    }


