@app.post("/api/wallet/set-pin")
def set_wallet_pin(
    payload: WalletPinSetRequest,
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    _require_verified_student(student, db, "setting up a wallet PIN")
    locked_student = db.query(Student).filter(
        Student.student_id == student.student_id,
    ).with_for_update().first()
    if not locked_student:
        raise HTTPException(status_code=401, detail="Authentication required.")

    if locked_student.has_wallet_pin:
        current_pin = payload.current_pin.get_secret_value() if payload.current_pin else ""
        _verify_wallet_pin(
            db,
            locked_student,
            current_pin,
            request,
            incorrect_message="Current wallet PIN is incorrect.",
        )

    locked_student.wallet_pin_hash = hash_password(payload.pin.get_secret_value())
    locked_student.pay_failed_attempts = 0
    locked_student.pay_locked_until = None
    db.commit()
    return {"has_wallet_pin": True, "message": "Wallet PIN saved successfully."}


@app.post("/api/wallet/pin-reset/request")
def request_wallet_pin_reset(
    http_request: Request,
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    _require_verified_student(student, db, "resetting a wallet PIN")
    email = str(student.email or "").strip().lower()
    if not email:
        raise HTTPException(status_code=409, detail="A registered email address is required to reset your Wallet PIN.")

    now = datetime.now(timezone.utc).replace(tzinfo=None)
    purpose = "wallet_pin_reset"
    latest_reset = _latest_password_reset(
        db,
        email,
        purpose=purpose,
        lock_for_update=True,
    )
    if (
        latest_reset
        and not latest_reset.is_used
        and latest_reset.expires_at >= now
        and latest_reset.created_at
        and (now - latest_reset.created_at).total_seconds()
        < PASSWORD_RESET_RESEND_COOLDOWN_SECONDS
    ):
        cooldown_remaining = PASSWORD_RESET_RESEND_COOLDOWN_SECONDS - int(
            (now - latest_reset.created_at).total_seconds()
        )
        return _forgot_password_response(cooldown_remaining)

    request_ip = _request_client_ip(http_request) or "unknown"
    retry_after = _password_reset_rate_limit(db, email, request_ip, now)
    if retry_after:
        return _forgot_password_response(retry_after)

    previous_resets = db.query(PasswordReset).filter(
        func.lower(PasswordReset.email) == email,
        PasswordReset.purpose == purpose,
        PasswordReset.is_used == False,
    ).all()
    for previous_reset in previous_resets:
        previous_reset.is_used = True
        previous_reset.delivery_status = "invalidated"

    otp = _generate_otp_code()
    now = datetime.utcnow().replace(microsecond=0)
    expires_at = now + timedelta(minutes=10)
    reset_entry = PasswordReset(
        email=email,
        otp_hash=_password_reset_otp_hash(email, otp, purpose),
        expires_at=expires_at,
        is_used=False,
        delivery_status="queued",
        verification_attempts=0,
        purpose=purpose,
        created_at=now,
    )
    tracking = PasswordResetRequest(
        account_key=email,
        request_ip=request_ip,
        requested_at=now,
        delivery_status="queued",
    )
    db.add_all([reset_entry, tracking])
    try:
        db.flush()
        reset_id = reset_entry.id
        request_id = tracking.id
        logger.info("[OTP CREATED] now=%s, expires_at=%s", now, reset_entry.expires_at)
        db.commit()
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Unable to create a Wallet PIN reset request.")
        raise HTTPException(status_code=500, detail="Unable to request a Wallet PIN reset.")

    background_tasks.add_task(
        _deliver_password_reset_email,
        reset_id,
        request_id,
        otp,
        purpose,
    )
    return _forgot_password_response()


@app.post("/api/wallet/pin-reset/confirm")
def confirm_wallet_pin_reset(
    payload: WalletPinResetRequest,
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    _require_verified_student(student, db, "resetting a wallet PIN")
    locked_student = db.query(Student).filter(
        Student.student_id == student.student_id,
    ).with_for_update().first()
    if not locked_student:
        raise HTTPException(status_code=401, detail="Authentication required.")

    email = str(locked_student.email or "").strip().lower()
    reset_record = _latest_password_reset(
        db,
        email,
        purpose="wallet_pin_reset",
        lock_for_update=True,
    )
    now = _utc_now()
    expires_at = _as_utc_datetime(reset_record.expires_at) if reset_record else None
    failure_reason = None
    expected_hash_match = None
    identifier_matches = bool(
        reset_record
        and _login_identifier(reset_record.email) == email
    )

    if not reset_record:
        failure_reason = "missing reset record"
    elif reset_record.is_used:
        failure_reason = "code already used"
    elif reset_record.verification_attempts >= 5:
        failure_reason = "max attempts exceeded"
    elif reset_record.delivery_status != "sent":
        failure_reason = f"delivery_status={reset_record.delivery_status}"
    elif expires_at is None or expires_at <= now:
        failure_reason = "expired"
    else:
        expected_hash_match = _password_reset_code_matches(
            db,
            reset_record,
            payload.otp_code,
        )
        if not expected_hash_match:
            failure_reason = "invalid code"

    if failure_reason is not None:
        logger.warning(
            "Wallet PIN reset failed: reason=%s entered_code_present=%s expected_hash_match=%s "
            "expires_at=%s is_used=%s purpose=%s identifier_matches=%s delivery_status=%s "
            "reset_id=%s attempts=%s",
            failure_reason,
            bool(payload.otp_code),
            expected_hash_match,
            expires_at.isoformat() if expires_at else None,
            getattr(reset_record, "is_used", None),
            getattr(reset_record, "purpose", None),
            identifier_matches,
            getattr(reset_record, "delivery_status", None),
            getattr(reset_record, "id", None),
            getattr(reset_record, "verification_attempts", None),
        )
        raise HTTPException(status_code=400, detail="Invalid or expired Wallet PIN reset code.")

    locked_student.wallet_pin_hash = hash_password(payload.pin.get_secret_value())
    locked_student.pay_failed_attempts = 0
    locked_student.pay_locked_until = None
    reset_record.is_used = True
    db.add(AuditLog(
        admin_id=None,
        action="wallet_pin_reset",
        entity_type="Student",
        entity_id=locked_student.id,
        description="Student reset their Wallet PIN using email verification.",
        status="SUCCESS",
        severity="informational",
        ip_address=request.client.host if request.client else None,
    ))
    try:
        db.commit()
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Unable to confirm a Wallet PIN reset.")
        raise HTTPException(status_code=500, detail="Unable to reset your Wallet PIN.")
    return {"has_wallet_pin": True, "message": "Wallet PIN reset successfully."}


@app.get("/api/products/{product_id}/pay-summary")
def get_product_pay_summary(
    product_id: int,
    quantity: int = Query(1, ge=1),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    _require_verified_student(buyer, db, "checking out")
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
    if _is_product_owner(db, product, buyer):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="You cannot buy your own listing.",
        )
    stock = int(product.stock or 0)
    if stock < 1:
        raise HTTPException(status_code=409, detail={"code": "OUT_OF_STOCK", "message": "This item is out of stock."})
    if str(product.status or "").strip().lower() not in {"approved", "active", "visible", "published"}:
        raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
    if quantity > stock:
        raise HTTPException(status_code=409, detail={"code": "OUT_OF_STOCK", "message": "Requested quantity exceeds available stock.", "stock": stock})
    seller = _payment_product_seller(db, product)
    if not seller:
        raise HTTPException(status_code=409, detail="The listing seller could not be verified.")
    unit_price = _validated_payment_unit_price(product.price)
    item_total = (unit_price * quantity).quantize(Decimal("0.01"))
    wallet = db.query(Wallet).filter(Wallet.student_id == buyer.student_id).first()
    balance = Decimal(str(wallet.balance if wallet else buyer.wallet_balance or 0)).quantize(Decimal("0.01"))
    return {
        "product_id": product.id,
        "title": product.title,
        "item_title": product.title,
        "unit_price": str(unit_price),
        "quantity_limit": stock,
        "stock": stock,
        "quantity": quantity,
        "total": str(item_total),
        "checkout_total": str(item_total),
        "seller_commission": str(_calculate_platform_commission(db, item_total)),
        "seller_name": seller.name,
        "wallet_balance": str(balance),
        "has_wallet_pin": buyer.has_wallet_pin,
    }


@app.post("/api/products/{product_id}/pay")
def pay_for_product(
    product_id: int,
    payload: ProductPaymentRequest,
    request: Request,
    idempotency_key: str = Header(..., alias="Idempotency-Key"),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    _require_verified_student(buyer, db, "checking out")
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
    if _is_product_owner(db, product, buyer):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="You cannot buy your own listing.",
        )
    key = idempotency_key.strip()
    if not 8 <= len(key) <= 64:
        raise HTTPException(status_code=422, detail="Idempotency-Key must contain 8 to 64 characters.")
    cart_item = db.query(CartItem).filter(
        CartItem.student_id == buyer.student_id,
        CartItem.product_id == product_id,
    ).first()
    if not cart_item:
        raise HTTPException(status_code=409, detail="Add this product to your cart before paying.")
    scoped_key = f"{buyer.student_id}:{key}"

    # PIN attempts are committed independently so failed-attempt counters
    # cannot be erased by a later rollback in the wallet transaction.
    try:
        locked_buyer = db.query(Student).filter(
            Student.student_id == buyer.student_id,
        ).with_for_update().first()
        if not locked_buyer:
            raise HTTPException(status_code=401, detail="Authentication required.")
        _verify_wallet_pin(
            db,
            locked_buyer,
            payload.pin.get_secret_value(),
            request,
        )
    except HTTPException:
        raise
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Unable to validate password for product payment.")
        raise HTTPException(status_code=500, detail="Unable to verify payment credentials.")

    existing = db.query(PaymentIdempotency).filter(
        PaymentIdempotency.idempotency_key == scoped_key,
    ).first()
    if existing:
        prior_product_id = existing.product_id
        if prior_product_id is None and existing.order_id:
            prior_order = db.query(Order).filter(Order.id == existing.order_id).first()
            prior_product_id = prior_order.product_id if prior_order else None
        if prior_product_id != product_id or existing.buyer_id != buyer.student_id:
            raise HTTPException(status_code=409, detail="This Idempotency-Key was already used for another product.")
        order = db.query(Order).filter(Order.id == existing.order_id).first()
        if order:
            return _payment_result(order, already_paid=True)

    try:
        product = db.query(Product).filter(Product.id == product_id).with_for_update().first()
        if not product:
            raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
        cart_item = db.query(CartItem).filter(
            CartItem.student_id == buyer.student_id,
            CartItem.product_id == product_id,
        ).with_for_update().first()
        if not cart_item:
            raise HTTPException(status_code=409, detail="Add this product to your cart before paying.")
        stock = int(product.stock or 0)
        if stock < 1:
            raise HTTPException(status_code=409, detail={"code": "OUT_OF_STOCK", "message": "Not enough stock is available.", "stock": stock})
        if str(product.status or "").strip().lower() not in {"approved", "active", "visible", "published"}:
            raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
        existing = db.query(PaymentIdempotency).filter(
            PaymentIdempotency.idempotency_key == scoped_key,
        ).first()
        if existing:
            prior_product_id = existing.product_id
            if prior_product_id is None and existing.order_id:
                prior_order = db.query(Order).filter(Order.id == existing.order_id).first()
                prior_product_id = prior_order.product_id if prior_order else None
            if prior_product_id != product_id or existing.buyer_id != buyer.student_id:
                raise HTTPException(status_code=409, detail="This Idempotency-Key was already used for another product.")
            winning_order = db.query(Order).filter(Order.id == existing.order_id).first()
            if winning_order:
                db.rollback()
                return _payment_result(winning_order, already_paid=True)
        seller = _payment_product_seller(db, product)
        if not seller:
            raise HTTPException(status_code=409, detail="The listing seller could not be verified.")
        if seller.student_id == buyer.student_id:
            raise HTTPException(status_code=400, detail={"code": "OWN_LISTING", "message": "You cannot buy your own listing."})
        quantity = payload.quantity
        if quantity > stock:
            raise HTTPException(status_code=409, detail={"code": "OUT_OF_STOCK", "message": "Not enough stock is available.", "stock": stock})
        unit_price = _validated_payment_unit_price(product.price)
        amount = (unit_price * Decimal(quantity)).quantize(Decimal("0.01"))
        commission_settings = _get_commission_settings(db)
        commission = commission_fee_from_settings(amount, commission_settings).quantize(Decimal("0.01"))
        commission_rate = (
            as_decimal(commission_settings["commission_rate"], field_name="commission_rate")
            if commission_settings["commission_enabled"]
            else Decimal("0")
        )
        seller_credit = (amount - commission).quantize(Decimal("0.01"))
        if amount <= 0 or seller_credit < 0:
            raise HTTPException(status_code=409, detail="This listing has an invalid payment amount.")

        student_by_id = {buyer.student_id: buyer, seller.student_id: seller}
        wallets: Dict[str, Wallet] = {}
        for student_id in sorted(student_by_id):
            account = student_by_id[student_id]
            wallet = db.query(Wallet).filter(
                Wallet.student_id == student_id,
            ).with_for_update().first()
            if wallet is None:
                wallet = Wallet(student_id=student_id, balance=Decimal(str(account.wallet_balance or 0)).quantize(Decimal("0.01")))
                db.add(wallet)
                db.flush()
            wallets[student_id] = wallet
        buyer_wallet = wallets[buyer.student_id]
        seller_wallet = wallets[seller.student_id]
        balance = Decimal(str(buyer_wallet.balance or 0)).quantize(Decimal("0.01"))
        if balance < amount:
            missing = (amount - balance).quantize(Decimal("0.01"))
            db.rollback()
            raise HTTPException(status_code=402, detail={
                "code": "INSUFFICIENT_BALANCE",
                "message": "Your wallet balance is too low to complete this payment.",
                "balance": str(balance),
                "required": str(amount),
                "missing": str(missing),
                "action": "topup",
            })

        buyer_wallet.balance = (balance - amount).quantize(Decimal("0.01"))
        seller_wallet.balance = (
            Decimal(str(seller_wallet.balance or 0)) + seller_credit
        ).quantize(Decimal("0.01"))
        if buyer_wallet.balance < 0:
            raise HTTPException(status_code=402, detail={"code": "INSUFFICIENT_BALANCE", "message": "Your wallet balance is too low.", "action": "topup"})
        buyer.wallet_balance = buyer_wallet.balance
        seller.wallet_balance = seller_wallet.balance
        product.stock = stock - quantity
        _sync_product_status_with_stock(product)
        completed_at = datetime.now(timezone.utc).replace(tzinfo=None)
        order = Order(
            student_id=buyer.student_id,
            product_id=product.id,
            title=product.title,
            price=str(unit_price),
            platform_fee=Decimal("0.00"),
            commission_amount=commission,
            commission_rate=commission_rate,
            commission_type=commission_settings["commission_type"],
            product_category=product.category,
            product_subcategory=product.subcategory,
            product_description=product.description,
            product_condition=product.condition,
            product_image=product.image,
            seller_id=seller.student_id,
            seller_name=seller.name,
            buyer_name=buyer.name,
            buyer_email=buyer.email,
            buyer_phone=buyer.phone,
            quantity=quantity,
            status="Completed",
            payment_status="Successful",
            created_at=completed_at,
            paid_at=completed_at,
            completed_at=completed_at,
            is_funds_released=True,
        )
        db.add(order)
        db.flush()
        buyer_tx = f"ORDER-PAY-{order.id}"
        db.add_all([
            Transaction(
                student_id=buyer.student_id,
                wallet_id=buyer_wallet.id,
                tx_id=buyer_tx,
                type="Product Purchase",
                amount=amount,
                description=f"Wallet payment for order #{order.id}",
                status="Successful",
            ),
            Transaction(
                student_id=seller.student_id,
                wallet_id=seller_wallet.id,
                tx_id=f"ORDER-SALE-{order.id}",
                type="Product Sale",
                amount=seller_credit,
                description=f"Sale proceeds for order #{order.id}",
                status="Successful",
            ),
        ])
        system_wallet = db.query(SystemSetting).filter(
            SystemSetting.key == "system_wallet_balance",
        ).with_for_update().first()
        if system_wallet:
            system_wallet.value = str((Decimal(str(system_wallet.value or 0)) + commission).quantize(Decimal("0.01")))
        elif commission:
            db.add(SystemSetting(key="system_wallet_balance", value=str(commission)))
        db.add(PaymentIdempotency(
            idempotency_key=scoped_key,
            order_id=order.id,
            buyer_id=buyer.student_id,
            product_id=product.id,
            transaction_id=buyer_tx,
        ))
        db.add(AuditLog(
            admin_id=None,
            action="payment_completed",
            entity_type="Order",
            entity_id=order.id,
            description=f"Buyer {buyer.student_id} paid seller {seller.student_id} for product {product.id}.",
            status="SUCCESS",
            ip_address=request.client.host if request.client else None,
        ))
        buyer_message = f"Payment for '{product.title}' is complete. Report a problem within {get_dispute_window_hours()} hours if needed."
        seller_message = f"Payment received for '{product.title}'. You can now hand over the item."
        order_target = json.dumps({"kind": "order", "order_id": order.id})
        _add_student_notification(
            db,
            buyer,
            "Payment completed",
            buyer_message,
            "payment",
            order_target,
            reference_id=str(order.id),
            action_label="View Order",
            action_url=f"/dashboard?tab=buyer&section=orders&order={order.id}",
        )
        _add_student_notification(
            db,
            seller,
            "Payment received",
            seller_message,
            "payment",
            order_target,
            reference_id=str(order.id),
            action_label="View Order",
            action_url=f"/dashboard?tab=seller&section=orders&order={order.id}",
        )
        db.commit()
        order_date = completed_at.strftime("%b %d, %Y").replace(" 0", " ")
        _send_student_notification_email(
            buyer,
            "Payment completed",
            buyer_message,
            "payment",
            badge="Completed",
            details_table={
                "Order ID": f"#{order.id}",
                "Item": product.title,
                "Unit price": f"{unit_price} ETB",
                "Quantity": quantity,
                "Total": f"{amount} ETB",
                "Reference": buyer_tx,
                "Date": order_date,
            },
            action_button={
                "label": "Track Order",
                "url": f"{FRONTEND_BASE_URL.rstrip('/')}/dashboard?tab=my_orders&order_id={order.id}",
            },
        )
        _send_student_notification_email(
            seller,
            "Payment received",
            seller_message,
            "payment",
            badge="Payment received",
            details_table={
                "Order ID": f"#{order.id}",
                "Item": product.title,
                "Quantity": quantity,
                "Payout amount": f"{seller_credit} ETB",
                "Reference": f"ORDER-SALE-{order.id}",
                "Date": order_date,
            },
            action_button={
                "label": "View Order",
                "url": urljoin(
                    FRONTEND_BASE_URL.rstrip("/") + "/",
                    f"dashboard?tab=seller&section=orders&order={order.id}",
                ),
            },
        )
        db.refresh(order)
        return _payment_result(order, already_paid=False)
    except HTTPException:
        if db.is_active:
            db.rollback()
        raise
    except IntegrityError:
        db.rollback()
        duplicate = db.query(PaymentIdempotency).filter(
            PaymentIdempotency.idempotency_key == scoped_key,
        ).first()
        if duplicate and duplicate.product_id == product_id and duplicate.buyer_id == buyer.student_id:
            winning_order = db.query(Order).filter(Order.id == duplicate.order_id).first()
            if winning_order:
                return _payment_result(winning_order, already_paid=True)
        raise HTTPException(status_code=409, detail="The payment request could not be uniquely recorded.")
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Database error during wallet payment for product %s.", product_id)
        raise HTTPException(status_code=500, detail="Unable to complete wallet payment.")


@app.post("/api/products/{product_id}/checkout")
async def initialize_product_chapa_checkout(
    product_id: int,
    payload: ProductCheckoutRequest,
    idempotency_key: str = Header(..., alias="Idempotency-Key"),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    _require_verified_student(buyer, db, "checking out")
    payment_settings = get_payment_settings(db)
    if not payment_settings["enableOnlinePayment"]:
        raise HTTPException(status_code=503, detail="Online payment is currently disabled.")

    key = idempotency_key.strip()
    if not 8 <= len(key) <= 64:
        raise HTTPException(status_code=422, detail="Idempotency-Key must contain 8 to 64 characters.")

    try:
        secret = get_chapa_secret_key()
    except PayoutProviderError as error:
        raise HTTPException(status_code=503, detail="Chapa checkout is not configured.") from error
    if not secret:
        raise HTTPException(status_code=503, detail="Chapa checkout is not configured.")

    try:
        callback_url = _get_public_payment_url("CHAPA_CALLBACK_URL")
        return_url = _get_chapa_return_url()
        if not _is_production_environment():
            return_url = f"{return_url.rstrip('/')}/dashboard"
    except HTTPException as error:
        raise HTTPException(
            status_code=503,
            detail="Payment setup is incomplete. Configure the public payment callback and frontend URLs.",
        ) from error

    scoped_key = f"{buyer.student_id}:chapa-product:{key}"
    order = None
    transaction = None
    seller_account = None

    try:
        existing_payment = (
            db.query(PaymentIdempotency)
            .filter(PaymentIdempotency.idempotency_key == scoped_key)
            .with_for_update()
            .first()
        )
        if existing_payment:
            order = db.query(Order).filter(Order.id == existing_payment.order_id).with_for_update().first()
            transaction = (
                db.query(Transaction)
                .filter(Transaction.tx_id == existing_payment.transaction_id)
                .with_for_update()
                .first()
            )
            if (
                not order
                or not transaction
                or order.student_id != buyer.student_id
                or order.product_id != product_id
            ):
                raise HTTPException(status_code=409, detail="This Idempotency-Key was already used for another checkout.")
            if _normalize_payment_status(transaction.status) == "Successful":
                return {
                    "status": "success",
                    "message": "This product payment is already complete.",
                    "order_id": order.id,
                    "tx_ref": transaction.tx_id,
                    "already_paid": True,
                }
            transaction_status = _normalize_payment_status(transaction.status)
            order_payment_status = _normalize_payment_status(order.payment_status)
            if transaction_status != "Pending" or order_payment_status != "Pending":
                terminal_statuses = {"Failed", "Expired", "Cancelled"}
                if transaction_status in terminal_statuses and order_payment_status in terminal_statuses:
                    # The prior attempt cannot settle; release its key so a retry can reserve stock again.
                    db.delete(existing_payment)
                    db.flush()
                    existing_payment = None
                else:
                    raise HTTPException(status_code=409, detail="This checkout is no longer available. Start a new checkout.")
            if existing_payment:
                product = db.query(Product).filter(Product.id == product_id).first()
                seller = _payment_product_seller(db, product) if product else None
                if not seller or seller.student_id != order.seller_id:
                    raise HTTPException(status_code=409, detail="The listing seller could not be verified.")
                seller_account = (
                    db.query(SellerPaymentAccount)
                    .filter(SellerPaymentAccount.student_id == seller.student_id)
                    .with_for_update()
                    .first()
                )
                if (
                    not seller_account
                    or str(seller_account.account_status or "").strip().casefold() != "active"
                    or not str(seller_account.chapa_sub_account_id or "").strip()
                ):
                    raise HTTPException(
                        status_code=409,
                        detail="The seller must complete Chapa payout setup before this product can be purchased.",
                    )
        if not existing_payment:
            product = (
                db.query(Product)
                .filter(Product.id == product_id)
                .with_for_update()
                .first()
            )
            if not product:
                raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
            if _is_product_owner(db, product, buyer):
                raise HTTPException(status_code=403, detail="You cannot buy your own listing.")

            seller = _payment_product_seller(db, product)
            if not seller or seller.student_id == buyer.student_id:
                raise HTTPException(status_code=409, detail="The listing seller could not be verified.")

            seller_account = (
                db.query(SellerPaymentAccount)
                .filter(SellerPaymentAccount.student_id == seller.student_id)
                .with_for_update()
                .first()
            )
            if (
                not seller_account
                or str(seller_account.account_status or "").strip().casefold() != "active"
                or not str(seller_account.chapa_sub_account_id or "").strip()
            ):
                raise HTTPException(
                    status_code=409,
                    detail="The seller must complete Chapa payout setup before this product can be purchased.",
                )
            if seller_account.provider_id:
                payout_provider = (
                    db.query(PayoutProvider)
                    .filter(PayoutProvider.id == seller_account.provider_id)
                    .first()
                )
                if not payout_provider or not payout_provider.is_active:
                    raise HTTPException(
                        status_code=409,
                        detail="The seller's payout account is inactive. Ask the seller to update their payout setup.",
                    )

            cart_item = (
                db.query(CartItem)
                .filter(
                    CartItem.student_id == buyer.student_id,
                    CartItem.product_id == product_id,
                )
                .with_for_update()
                .first()
            )
            if not cart_item:
                raise HTTPException(status_code=409, detail="Add this product to your cart before paying.")
            quantity = payload.quantity
            stock = int(product.stock or 0)
            if str(product.status or "").strip().lower() not in {"approved", "active", "visible", "published"}:
                raise HTTPException(status_code=404, detail="This listing is not available for purchase.")
            if quantity > stock or quantity > int(cart_item.quantity or 1):
                raise HTTPException(
                    status_code=409,
                    detail={"code": "OUT_OF_STOCK", "message": "Requested quantity exceeds available cart or listing stock.", "stock": stock},
                )

            amount = (
                _validated_payment_unit_price(product.price) * Decimal(quantity)
            ).quantize(Decimal("0.01"))
            commission_settings = _get_commission_settings(db)
            commission = commission_fee_from_settings(amount, commission_settings).quantize(Decimal("0.01"))
            commission_rate = (
                as_decimal(commission_settings["commission_rate"], field_name="commission_rate")
                if commission_settings["commission_enabled"]
                else Decimal("0")
            )
            if amount <= 0 or commission > amount:
                raise HTTPException(status_code=409, detail="This listing has an invalid payment amount.")

            tx_ref = f"TX-{uuid.uuid4().hex.upper()}"
            order = Order(
                student_id=buyer.student_id,
                product_id=product.id,
                title=product.title,
                price=str(_validated_payment_unit_price(product.price)),
                platform_fee=Decimal("0.00"),
                seller_commission=commission,
                commission_rate=commission_rate,
                commission_type=commission_settings["commission_type"],
                product_category=product.category,
                product_subcategory=product.subcategory,
                product_description=product.description,
                product_condition=product.condition,
                product_image=product.image,
                seller_id=seller.student_id,
                seller_name=seller.name,
                seller_business_name=seller_account.business_name,
                buyer_name=buyer.name,
                buyer_email=buyer.email,
                buyer_phone=buyer.phone,
                quantity=quantity,
                status="Pending",
                payment_status="Pending",
                is_funds_released=False,
            )
            product.stock = stock - quantity
            _sync_product_status_with_stock(product)
            db.add(order)
            db.flush()
            transaction = Transaction(
                student_id=buyer.student_id,
                wallet_id=None,
                tx_id=tx_ref,
                type="Product Purchase",
                amount=amount,
                description=f"Pending Chapa split payment for order #{order.id}",
                status="Pending",
            )
            db.add(transaction)
            db.add(PaymentIdempotency(
                idempotency_key=scoped_key,
                order_id=order.id,
                buyer_id=buyer.student_id,
                product_id=product.id,
                transaction_id=tx_ref,
            ))
            db.commit()
            db.refresh(order)
            db.refresh(transaction)
            seller_account = (
                db.query(SellerPaymentAccount)
                .filter(SellerPaymentAccount.student_id == seller.student_id)
                .first()
            )
    except HTTPException:
        db.rollback()
        raise
    except IntegrityError as error:
        db.rollback()
        raise HTTPException(status_code=409, detail="This product checkout is already being processed.") from error
    except SQLAlchemyError as error:
        db.rollback()
        logging.getLogger("app.payments").exception(
            "Unable to save pending Chapa product checkout for product %s.",
            product_id,
        )
        raise HTTPException(status_code=500, detail="Unable to save the pending product order safely.") from error

    if not order or not transaction or not seller_account:
        raise HTTPException(status_code=500, detail="Unable to prepare product checkout safely.")

    amount = Decimal(str(transaction.amount)).quantize(Decimal("0.01"))
    commission = Decimal(str(order.seller_commission or 0)).quantize(Decimal("0.01"))
    commission_rate = Decimal(str(order.commission_rate or 0))
    raw_percentage_commission = (amount * commission_rate / Decimal("100")).quantize(Decimal("0.01"))
    if (
        str(order.commission_type or "").strip().lower() == "percentage"
        and commission == raw_percentage_commission
        and commission_rate > 0
    ):
        split_type = "percentage"
        split_value = commission_rate.quantize(Decimal("0.0001"))
    elif commission > 0:
        split_type = "flat"
        split_value = commission
    else:
        split_type = None
        split_value = None

    name_parts = (buyer.name or "Student").strip().split(maxsplit=1)
    marketplace_name = str(
        _get_setting_value(
            db,
            "general",
            "marketplaceName",
            DEFAULT_SETTINGS_BLOCKS["general"]["marketplaceName"],
        )
        or DEFAULT_SETTINGS_BLOCKS["general"]["marketplaceName"]
    ).strip()[:16]
    chapa_payload = {
        "amount": f"{amount:.2f}",
        "currency": "ETB",
        "email": buyer.email,
        "first_name": name_parts[0],
        "last_name": name_parts[1] if len(name_parts) > 1 else name_parts[0],
        "tx_ref": transaction.tx_id,
        "callback_url": callback_url,
        "return_url": return_url,
        "customization": {"title": marketplace_name},
        "subaccounts": {
            "id": seller_account.chapa_sub_account_id,
            **(
                {"split_type": split_type, "split_value": str(split_value)}
                if split_value is not None and split_value > 0
                else {}
            ),
        },
    }

    def fail_product_checkout(*, release_inventory: bool) -> None:
        if release_inventory:
            _release_pending_chapa_product_order(db, transaction.tx_id, expired=False)

    payment_logger = logging.getLogger("app.payments")
    payment_logger.info(
        "Chapa product checkout request tx_ref=%s payload=%s",
        transaction.tx_id,
        json.dumps(chapa_payload, ensure_ascii=False, separators=(",", ":")),
    )
    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            response = await client.post(
                "https://api.chapa.co/v1/transaction/initialize",
                headers={"Authorization": f"Bearer {secret}", "Content-Type": "application/json"},
                json=chapa_payload,
            )
            try:
                response_payload = response.json()
            except ValueError as error:
                if response.is_error:
                    response_payload = None
                else:
                    payment_logger.error(
                        "Chapa product checkout failed tx_ref=%s http_status=%s response_body=%s",
                        transaction.tx_id,
                        response.status_code,
                        response.text,
                    )
                    raise HTTPException(
                        status_code=502,
                        detail="Chapa returned an invalid checkout response.",
                    ) from error
    except httpx.TimeoutException as error:
        logging.getLogger("app.payments").warning(
            "Chapa product checkout timed out tx_ref=%s; pending checkout retained for retry.",
            transaction.tx_id,
        )
        raise HTTPException(
            status_code=503,
            detail="Chapa did not respond in time. Retry checkout to resume the same payment safely.",
        ) from error
    except httpx.HTTPError as error:
        logging.getLogger("app.payments").warning(
            "Chapa product checkout request failed tx_ref=%s error_type=%s.",
            transaction.tx_id,
            type(error).__name__,
        )
        raise HTTPException(
            status_code=503,
            detail="Chapa is temporarily unavailable. Retry checkout to resume the same payment safely.",
        ) from error
    response_data = response_payload.get("data") if isinstance(response_payload, dict) else None
    checkout_url = response_data.get("checkout_url") if isinstance(response_data, dict) else None
    if response.is_error or not checkout_url:
        response_body = response.text
        payment_logger.error(
            "Chapa product checkout failed tx_ref=%s http_status=%s response_body=%s",
            transaction.tx_id,
            response.status_code,
            response_body,
        )
        release_inventory = response.status_code < 500
        fail_product_checkout(release_inventory=release_inventory)
        if response.status_code == 400:
            provider_message = None
            if isinstance(response_payload, dict):
                provider_message = response_payload.get("message") or response_payload.get("error")
                provider_data = response_payload.get("data")
                if isinstance(provider_data, dict):
                    provider_message = provider_message or provider_data.get("message")
                provider_errors = response_payload.get("errors")
                if provider_errors is None and isinstance(provider_data, dict):
                    provider_errors = provider_data.get("errors")
                if provider_errors:
                    error_detail = json.dumps(
                        provider_errors,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    provider_message = (
                        f"{provider_message}: {error_detail}"
                        if provider_message
                        else error_detail
                    )
                elif isinstance(provider_message, (dict, list)):
                    provider_message = json.dumps(
                        provider_message,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
            raise HTTPException(
                status_code=400,
                detail=str(provider_message or response_body or "Chapa rejected the checkout request."),
            )
        if response.status_code in {401, 403}:
            raise HTTPException(status_code=502, detail="Chapa rejected the payment credentials. Please contact support.")
        if response.status_code == 429 or response.status_code >= 500:
            raise HTTPException(status_code=503, detail="Chapa is temporarily unavailable. Retry checkout shortly.")
        raise HTTPException(status_code=502, detail="Chapa could not initialize this product payment.")

    return {
        "status": "success",
        "message": "Product payment initialized successfully.",
        "checkout_url": checkout_url,
        "tx_ref": transaction.tx_id,
        "order_id": order.id,
    }


def _build_seller_listing_analytics(listings: list, completed_orders: list) -> list:
    completed_orders_by_product = Counter(order.product_id for order in completed_orders)
    completed_revenue_by_product = Counter()
    for order in completed_orders:
        completed_revenue_by_product[order.product_id] += (
            _parse_price_to_etb(order.price) * int(getattr(order, "quantity", 1) or 1)
        )
    analytics = []
    for listing in listings:
        views = int(getattr(listing, "views", 0) or 0)
        completed_product_orders = int(completed_orders_by_product.get(listing.id, 0))
        analytics.append({
            "listing": listing,
            "views": views,
            "completed_orders": completed_product_orders,
            "completed_revenue": round(completed_revenue_by_product.get(listing.id, 0), 2),
            "conversion_rate": round((completed_product_orders / views) * 100, 2) if views else 0,
        })
    return analytics


def _product_has_orders(db: Session, product_id: int) -> bool:
    return bool(db.query(Order.id).filter(Order.product_id == product_id).first())


def _product_has_open_orders(db: Session, product_id: int) -> bool:
    terminal_statuses = {
        "completed",
        "successful",
        "sold",
        "delivered",
        "cancelled",
        "canceled",
        "rejected",
        "expired",
        "refunded",
        "returned",
    }
    return bool(
        db.query(Order.id)
        .filter(
            Order.product_id == product_id,
            func.lower(func.trim(Order.status)).notin_(terminal_statuses),
        )
        .first()
    )


def _product_has_open_disputes(db: Session, product_id: int) -> bool:
    return bool(
        db.query(Dispute.id)
        .join(Order, Dispute.order_id == Order.id)
        .filter(
            Order.product_id == product_id,
            func.upper(func.trim(Dispute.status)).in_(ACTIVE_DISPUTE_STATUSES),
        )
        .first()
    )








def _notify_admins_of_order_event(db: Session, order: Order, action: str, description: str) -> None:
    for admin in db.query(Admin).all():
        db.add(AuditLog(
            admin_id=admin.id,
            action=action,
            entity_type="Order",
            entity_id=order.id,
            description=description,
            status="SUCCESS",
            ip_address=None,
        ))


@app.get("/api/student/orders")
def get_student_orders(
    student_id: str,
    hidden: bool = Query(False),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    if buyer.student_id.strip().lower() != str(student_id).strip().lower():
        raise HTTPException(status_code=403, detail="You can only view your own orders.")
    student_id = buyer.student_id

    hidden_filter = Order.hidden_by_buyer.is_(True) if hidden else or_(
        Order.hidden_by_buyer.is_(False), Order.hidden_by_buyer.is_(None)
    )
    orders = db.query(Order).filter(
        Order.student_id == student_id,
        hidden_filter,
    ).order_by(Order.created_at.desc()).all()
    return [_serialize_order(db, order) for order in orders]


@app.patch("/api/student/orders/{order_id}/hide")
def hide_student_order(
    order_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    order = db.query(Order).filter(Order.id == order_id).with_for_update().first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found.")
