@app.get("/api/student/orders/{order_id}/receipt")
def get_student_order_receipt(
    order_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    viewer = _student_from_authorization(authorization, db)
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found.")
    product = db.query(Product).filter(Product.id == order.product_id).first()
    seller_identifier = getattr(order, "seller_id", None) or (product.seller if product else None)
    seller = db.query(Student).filter(
        or_(Student.student_id == seller_identifier, Student.name == seller_identifier)
    ).first() if seller_identifier else None
    is_buyer = viewer.student_id.strip().lower() == order.student_id.strip().lower()
    is_seller = bool(
        seller and seller.student_id.strip().lower() == viewer.student_id.strip().lower()
    )
    if not is_buyer and not is_seller:
        raise HTTPException(status_code=403, detail="You are not authorized to view this receipt.")
    normalized_order_status = _normalize_order_status(order.status).lower()
    if normalized_order_status in {"rejected", "expired", "refunded"}:
        if _normalize_payment_status(order.payment_status) == "Refunded":
            detail = "Receipts are unavailable for refunded orders. Your refund confirmation is available in order details."
        else:
            detail = "Receipts are unavailable for cancelled or expired deals because no payment was taken."
        raise HTTPException(status_code=409, detail=detail)
    if _normalize_payment_status(order.payment_status) == "Refunded":
        raise HTTPException(status_code=409, detail="Receipts are unavailable for rejected, expired, or refunded orders. Your refund confirmation is available in order details.")
    if _normalize_payment_status(order.payment_status) != "Successful":
        raise HTTPException(status_code=409, detail="A receipt is available only for paid orders.")

    quantity = int(getattr(order, "quantity", 1) or 1)
    unit_price = Decimal(str(_parse_price_to_etb(order.price))).quantize(Decimal("0.01"))
    item_total = (unit_price * quantity).quantize(Decimal("0.01"))
    platform_commission, commission_percent, commission_type = _order_commission_details(order, item_total)

    chapa_transaction_ids = (
        db.query(PaymentIdempotency.transaction_id)
        .filter(
            PaymentIdempotency.order_id == order.id,
            PaymentIdempotency.buyer_id == order.student_id,
        )
    )
    payment_transaction = (
        db.query(Transaction)
        .filter(
            Transaction.student_id == order.student_id,
            or_(
                Transaction.tx_id == f"ORDER-PAY-{order.id}",
                Transaction.tx_id.in_(chapa_transaction_ids),
                func.lower(func.coalesce(Transaction.description, ""))
                == f"chapa split payment for order #{order.id}",
                and_(
                    func.lower(Transaction.type) == "escrow hold",
                    func.lower(func.coalesce(Transaction.description, ""))
                    == f"escrow hold for order #{order.id}",
                ),
            ),
            func.lower(func.trim(Transaction.status)).in_(
                ["successful", "success", "paid", "completed", "held", "released", "refunded"]
            ),
        )
        .order_by(
            case(
                (Transaction.tx_id == f"ORDER-PAY-{order.id}", 0),
                (Transaction.tx_id.in_(chapa_transaction_ids), 1),
                (
                    func.lower(func.coalesce(Transaction.description, ""))
                    == f"chapa split payment for order #{order.id}",
                    1,
                ),
                else_=2,
            ),
            Transaction.created_at.desc(),
        )
        .first()
    )
    if not payment_transaction:
        raise HTTPException(status_code=409, detail="The successful payment transaction could not be matched to this order.")

    escrow_hold = db.query(Transaction).filter(
        Transaction.student_id == order.student_id,
        Transaction.type == "Escrow Hold",
        Transaction.description == f"Escrow hold for order #{order.id}",
    ).order_by(Transaction.created_at.desc()).first()
    refund = db.query(Transaction).filter(
        Transaction.student_id == order.student_id,
        Transaction.type == "Refund",
        Transaction.description.like(f"%order #{order.id}%"),
    ).order_by(Transaction.created_at.desc()).first()
    dispute = db.query(Dispute).filter(Dispute.order_id == order.id).order_by(Dispute.created_at.desc()).first()
    buyer = db.query(Student).filter(Student.student_id == order.student_id).first()
    buyer_name = getattr(order, "buyer_name", None) or (buyer.name if buyer else None) or order.student_id
    seller_name = getattr(order, "seller_name", None) or (seller.name if seller else None) or seller_identifier or "Campus Seller"
    is_direct_payment = payment_transaction.tx_id == f"ORDER-PAY-{order.id}"
    is_chapa_payment = (
        _normalize_payment_type(payment_transaction.type) == "Product Purchase"
        and payment_transaction.wallet_id is None
    )
    payment_message = (
        "The buyer paid through Chapa Split Payment."
        if is_chapa_payment else
        "Payment was transferred to the seller at handover."
        if is_direct_payment else
        "This is a legacy order with escrow payment history."
    )
    paid_on = payment_transaction.created_at or order.created_at
    receipt_number = f"RCPT-{paid_on.strftime('%Y%m%d')}-{order.id:04d}"

    return {
        "receipt_number": receipt_number,
        "order_number": order.id,
        "order_date": order.created_at,
        "payment_date": paid_on,
        "payment_status": _normalize_payment_status(order.payment_status),
        "product_name": getattr(order, "title", None) or (product.title if product else "Campus Purchase"),
        "product_image": _normalize_product_image(getattr(order, "product_image", None) or (product.image if product else None)),
        "quantity": quantity,
        "unit_price": float(unit_price),
        "item_total": float(item_total),
        "fees": float(platform_commission),
        "platform_commission_percent": float(commission_percent),
        "platform_commission_label": _order_commission_label(commission_percent, commission_type),
        "total_paid": float(payment_transaction.amount),
        "payment_method": "Chapa Split Payment" if is_chapa_payment else _normalize_payment_type(payment_transaction.type),
        "transaction_reference": payment_transaction.tx_id,
        "buyer_name": buyer_name,
        "buyer_email": (buyer.email or "") if is_buyer else "",
        "seller_name": seller_name,
        "order_status": _normalize_order_status(order.status),
        "payment_message": payment_message,
        "dispute_status": dispute.status if dispute and dispute.status in ACTIVE_DISPUTE_STATUSES else None,
        "refund_amount": float(refund.amount) if refund else None,
        "refund_reference": refund.tx_id if refund else None,
    }




DISPUTE_REASONS = {
    "refund_not_received",
    "Item not received",
    "Wrong item",
    "Item damaged",
    "Item differs from description",
    "Item not as described",
    "Seller did not show up",
    "Other",
    "Item is different from description",
    "Item is damaged",
    "Wrong item received",
    "Seller refused to hand over the item",
    "Payment/order problem",
}
ACTIVE_DISPUTE_STATUSES = {"OPEN", "UNDER_REVIEW"}
DISPUTE_ARCHIVE_THRESHOLD_DAYS = 1


def _is_archived_dispute(dispute: Dispute) -> bool:
    if str(dispute.status or "").upper() != "RESOLVED":
        return False
    if not dispute.resolved_at:
        return False
    age_days = (datetime.now(timezone.utc) - dispute.resolved_at).total_seconds() / (60 * 60 * 24)
    return age_days >= DISPUTE_ARCHIVE_THRESHOLD_DAYS


def _dispute_resolution_label(dispute: Dispute) -> str:
    order_status = str(getattr(dispute.order, "status", "") if dispute.order else getattr(dispute, "previous_order_status", "") or "").strip().lower()
    resolution = str(dispute.resolution or "").strip().upper()

    if order_status in {"refunded", "returned", "refund", "return"}:
        return "Resolved - Refunded"
    if order_status in {"cancelled", "canceled", "cancel"}:
        return "Resolved - Order Cancelled"
    if order_status in {"completed", "successful", "sold", "delivered"}:
        return "Resolved - Completed"
    if resolution == "BUYER":
        return "Resolved - Refunded"
    if resolution == "SELLER":
        return "Resolved - Completed"
    if resolution == "CANCELLED":
        return "Resolved - Order Cancelled"
    if str(dispute.status or "").upper() == "RESOLVED":
        return "Resolved"
    return str(dispute.status or "OPEN").title()


def _normalize_dispute_evidence_value(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(item) for item in value if item]
    if isinstance(value, str):
        trimmed = value.strip()
        if not trimmed:
            return []
        try:
            parsed = json.loads(trimmed)
        except (TypeError, ValueError):
            return [trimmed]
        if isinstance(parsed, list):
            return [str(item) for item in parsed if item]
        if isinstance(parsed, str):
            return [parsed] if parsed.strip() else []
        return []
    return [str(value)]


def _prepare_dispute_evidence_value(
    evidence_value: Optional[Any],
    uploaded_files: Optional[List[Any]] = None,
    *,
    db: Optional[Session] = None,
    static_dir: str = STATIC_DIR,
    now: Optional[Callable[[], datetime]] = None,
    save_file: Optional[Callable[[str, Any], None]] = None,
) -> Optional[str]:
    files = uploaded_files or []
    if files:
        urls = []
        for uploaded_file in files:
            filename = getattr(uploaded_file, "filename", None) or ""
            if not filename:
                continue
            file_obj = getattr(uploaded_file, "file", None)
            if file_obj is None:
                continue
            file_ext = os.path.splitext(filename)[1].lower()
            allowed_extensions = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".jfif"}
            if file_ext not in allowed_extensions:
                raise HTTPException(status_code=400, detail="Invalid evidence image format.")
            file_obj.seek(0, os.SEEK_END)
            file_size = file_obj.tell()
            file_obj.seek(0)
            max_evidence_size = 5 * 1024 * 1024
            if db is not None:
                max_evidence_size = _parse_size_bytes(_get_setting_value(
                    db,
                    "marketplace",
                    "maxImageSize",
                    DEFAULT_SETTINGS_BLOCKS["marketplace"]["maxImageSize"],
                ))
            if file_size > max_evidence_size:
                raise HTTPException(status_code=400, detail="Evidence image exceeds the maximum allowed size.")
            if save_file is not None:
                current_time = (now or (lambda: datetime.now(timezone.utc)))()
                unique_filename = f"{current_time.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex}{file_ext}"
                save_path = os.path.join(static_dir, unique_filename)
                save_file(save_path, file_obj)
                urls.append(f"http://127.0.0.1:8000/static/uploads/{unique_filename}")
            else:
                urls.append(save_upload(uploaded_file, "campace/evidence", max_size_bytes=max_evidence_size))
        return json.dumps(urls, ensure_ascii=False) if urls else None

    if evidence_value is None:
        return None
    candidate = str(evidence_value).strip()
    return candidate if candidate else None


def _format_dispute_timestamp(value: Any) -> Optional[str]:
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    if isinstance(value, str):
        return value
    return str(value)


def _derived_dispute_thread(dispute: Dispute) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    buyer_message = str(dispute.description or "").strip()
    if buyer_message:
        entries.append({
            "id": f"buyer-{dispute.id}-initial",
            "sender": "Buyer",
            "role": "buyer",
            "message": buyer_message,
            "created_at": _format_dispute_timestamp(getattr(dispute, "created_at", None)),
            "attachments": [],
        })

    raw_response = getattr(dispute, "seller_response", None)
    if raw_response is None:
        return entries

    response_text = str(raw_response).strip()
    if not response_text:
        return entries

    try:
        parsed_response = json.loads(response_text)
    except (TypeError, ValueError):
        parsed_response = None

    if isinstance(parsed_response, list):
        normalized = []
        for item in parsed_response:
            if not isinstance(item, dict):
                continue
            normalized.append({
                "id": item.get("id") or f"seller-{dispute.id}-{len(normalized)}",
                "sender": item.get("sender") or ("Seller" if str(item.get("role") or "").lower() == "seller" else "Buyer"),
                "role": str(item.get("role") or "seller").lower(),
                "message": str(item.get("message") or item.get("text") or "").strip(),
                "created_at": item.get("created_at") or _format_dispute_timestamp(getattr(dispute, "updated_at", None)),
                "attachments": _normalize_dispute_evidence_value(item.get("attachments") or item.get("evidence") or []),
            })
        if normalized:
            return entries + [item for item in normalized if str(item.get("message") or "").strip()]

    seller_message = {
        "id": f"seller-{dispute.id}-response",
        "sender": "Seller",
        "role": "seller",
        "message": response_text,
        "created_at": _format_dispute_timestamp(getattr(dispute, "updated_at", None)) or _format_dispute_timestamp(getattr(dispute, "created_at", None)),
        "attachments": _normalize_dispute_evidence_value(getattr(dispute, "seller_evidence", None)),
    }
    return entries + [seller_message]


def _serialize_dispute(dispute: Dispute, *, include_parties: bool = False) -> dict:
    dispute_thread = _derived_dispute_thread(dispute)
    latest_seller_response = ""
    if dispute_thread:
        for item in reversed(dispute_thread):
            if str(item.get("role") or "").lower() == "seller":
                latest_seller_response = str(item.get("message") or "").strip()
                break
    if not latest_seller_response:
        latest_seller_response = str(dispute.seller_response or "").strip()
    payload = {
        "id": dispute.id,
        "order_id": dispute.order_id,
        "buyer_id": dispute.buyer_id,
        "seller_id": dispute.seller_id,
        "reason": dispute.reason,
        "description": dispute.description,
        "evidence_image": dispute.evidence_image,
        "seller_response": latest_seller_response,
        "seller_evidence": dispute.seller_evidence,
        "dispute_thread": dispute_thread,
        "status": dispute.status,
        "resolution": dispute.resolution,
        "frozen_amount": float(dispute.frozen_amount or 0),
        "post_payment": bool(dispute.post_payment),
        "resolution_label": _dispute_resolution_label(dispute),
        "created_at": _format_dispute_timestamp(getattr(dispute, "created_at", None)),
        "updated_at": _format_dispute_timestamp(getattr(dispute, "updated_at", None)),
        "resolved_at": _format_dispute_timestamp(getattr(dispute, "resolved_at", None)),
    }
    if include_parties:
        payload["buyer"] = {"student_id": dispute.buyer.student_id, "name": dispute.buyer.name, "email": dispute.buyer.email} if dispute.buyer else None
        payload["seller"] = {"student_id": dispute.seller.student_id, "name": dispute.seller.name, "email": dispute.seller.email} if dispute.seller else None
        if dispute.order:
            unit_price = _parse_price_to_etb(dispute.order.price)
            quantity = int(getattr(dispute.order, "quantity", 1) or 1)
            payload["order"] = {
                "id": dispute.order.id,
                "title": dispute.order.title,
                "price": dispute.order.price,
                "quantity": quantity,
                "escrow_amount": float(unit_price * quantity),
                "status": dispute.order.status,
                "expired_at": _format_dispute_timestamp(dispute.order.expired_at),
                "refund_status": dispute.order.refund_status,
                "refund_attempts": int(dispute.order.refund_attempts or 0),
                "refund_reference": dispute.order.refund_reference,
            }
        else:
            payload["order"] = None
        payload["product"] = {"id": dispute.order.product_id, "title": dispute.order.product.title} if dispute.order and dispute.order.product else None
    return payload


@app.post("/api/student/orders/{order_id}/disputes")
@app.post("/api/student/orders/{order_id}/dispute")
async def raise_order_dispute(
    request: Request,
    order_id: int,
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    order = db.query(Order).filter(Order.id == order_id).with_for_update().first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found.")
    if order.student_id.strip().lower() != buyer.student_id.strip().lower():
        raise HTTPException(status_code=403, detail="You can only dispute your own orders.")

    reason = ""
    description = ""
    evidence_value = None
    uploaded_files = []
    content_type = request.headers.get("content-type", "").lower()

    if content_type.startswith("multipart/form-data"):
        form = await request.form()
        reason = str(form.get("reason") or "").strip()
        description = str(form.get("description") or "").strip()
        evidence_value = form.get("evidence_image")
        uploaded_files = [value for value in form.getlist("evidence_images") if getattr(value, "filename", None)]
        if not uploaded_files and getattr(form.get("evidence_image"), "filename", None):
            uploaded_files = [form.get("evidence_image")]
    else:
        try:
            payload = await request.json()
        except Exception:
            payload = None
        if payload is None:
            raise HTTPException(status_code=400, detail="Dispute payload is required.")
        if not isinstance(payload, dict):
            raise HTTPException(status_code=400, detail="Request body must be an object.")
        reason = str(payload.get("reason") or "").strip()
        description = str(payload.get("description") or "").strip()
        evidence_value = payload.get("evidence_image")

    if reason not in DISPUTE_REASONS:
        raise HTTPException(status_code=400, detail="Select a valid dispute reason.")
    if not description:
        raise HTTPException(status_code=400, detail="Dispute description is required.")
    if len(description) > 5000:
        raise HTTPException(status_code=400, detail="Dispute description must be 5000 characters or fewer.")
    active_dispute = db.query(Dispute).filter(
        Dispute.order_id == order.id,
        Dispute.status.in_(ACTIVE_DISPUTE_STATUSES),
    ).first()
    if active_dispute:
        raise HTTPException(status_code=409, detail="This order already has an active dispute.")
    if db.query(Dispute.id).filter(Dispute.order_id == order.id).first():
        raise HTTPException(status_code=409, detail="A problem has already been reported for this order.")

    normalized_order_status = _normalize_order_status(order.status).lower()
    completed_at = order.completed_at or order.paid_at
    if normalized_order_status != "completed" or _normalize_payment_status(order.payment_status) != "Successful" or not completed_at:
        raise HTTPException(status_code=409, detail="Only completed, successfully paid orders can be reported.")
    completed_at_utc = _as_utc_datetime(completed_at)
    if datetime.now(timezone.utc) > completed_at_utc + timedelta(hours=get_dispute_window_hours()):
        raise HTTPException(
            status_code=409,
            detail=f"Problems must be reported within {get_dispute_window_hours()} hours of payment.",
        )

    product = db.query(Product).filter(Product.id == order.product_id).first()
    seller_id = order.seller_id or (product.seller_id if product else None)
    if not seller_id and product and product.seller:
        seller_id = db.query(Student.student_id).filter(Student.student_id == product.seller).scalar()
    seller = db.query(Student).filter(Student.student_id == seller_id).first() if seller_id else None
    if not seller:
        raise HTTPException(status_code=409, detail="Seller not found for order.")
    dispute_evidence = _prepare_dispute_evidence_value(evidence_value, uploaded_files, db=db)
    dispute = Dispute(
        order_id=order.id,
        buyer_id=buyer.student_id,
        seller_id=seller.student_id,
        reason=reason,
        description=description,
        evidence_image=dispute_evidence,
        previous_order_status=order.status,
        status="OPEN",
        post_payment=True,
    )
    db.add(dispute)
    db.flush()
    report = Report(
        product_id=order.product_id,
        order_id=order.id,
        student_id=buyer.student_id,
        seller_id=seller.student_id,
        student_name=buyer.name,
        email=buyer.email,
        category="Order Problem",
        issue=f"{reason}: {description}",
        evidence_image=dispute_evidence,
        priority=determine_report_priority(description),
        status="Open",
    )
    db.add(report)
    db.flush()
    outbox_id = _queue_student_item_notification(
        db,
        buyer,
        title="Report received",
        message=f"We received your report RPT-{report.id:04d}.",
        item_type="report",
        item_id=report.id,
        action_url=f"/dashboard?tab=buyer&section=reports-support&item=report-{report.id}",
        email_subject=f"We received your report RPT-{report.id:04d}",
        email_summary=f"We usually reply within {SUPPORT_SLA_HOURS} hours.",
        email_status="Received",
        critical=True,
    )
    _notify_admins(
        db,
        title=f"New report RPT-{report.id:04d}",
        message="A student submitted an order report for admin review.",
        reference_type="report",
        reference_id=report.id,
        action_url=f"/admin/reports?report={report.id}",
    )
    direct_sale = db.query(Transaction).filter(
        Transaction.tx_id == f"ORDER-SALE-{order.id}",
        Transaction.type == "Product Sale",
        Transaction.status == "Successful",
    ).first()
    if direct_sale:
        seller_wallet = db.query(Wallet).filter(
            Wallet.student_id == seller.student_id,
        ).with_for_update().first()
        if not seller_wallet:
            seller_wallet = Wallet(student_id=seller.student_id, balance=Decimal(str(seller.wallet_balance or 0)))
            db.add(seller_wallet)
            db.flush()
        seller_net = Decimal(str(direct_sale.amount or 0)).quantize(Decimal("0.01"))
        available_balance = Decimal(str(seller_wallet.balance or 0)).quantize(Decimal("0.01"))
        frozen_amount = min(seller_net, available_balance)
        shortfall = (seller_net - frozen_amount).quantize(Decimal("0.01"))
        seller_wallet.balance = (available_balance - frozen_amount).quantize(Decimal("0.01"))
        seller_wallet.frozen_balance = (
            Decimal(str(seller_wallet.frozen_balance or 0)) + frozen_amount
        ).quantize(Decimal("0.01"))
        seller.wallet_balance = seller_wallet.balance
        if frozen_amount:
            db.add(Transaction(
                student_id=seller.student_id,
                wallet_id=seller_wallet.id,
                tx_id=f"DISPUTE-HOLD-{dispute.id}",
                type="Dispute Hold",
                amount=frozen_amount,
                description=f"Funds frozen for dispute #{dispute.id} on order #{order.id}",
                status="Successful",
            ))
        dispute.frozen_amount = frozen_amount
        db.add(AuditLog(
            admin_id=None,
            action="Dispute Funds Frozen",
            entity_type="Dispute",
            entity_id=dispute.id,
            description=f"Seller proceeds of {frozen_amount:.2f} ETB frozen for dispute #{dispute.id}; shortfall {shortfall:.2f} ETB.",
            status="SUCCESS",
            severity="warning",
            ip_address=request.client.host if request.client else None,
        ))
    order.status = "Disputed"
    order.dispute_reason = reason
    dispute_message = f"Order #{order.id} has been disputed. Reason: {order.dispute_reason}"
    dispute_target = json.dumps({"kind": "dispute", "dispute_id": dispute.id, "order_id": order.id})
    _dispatch_student_notification(db, buyer, "Order Disputed", dispute_message, "order", dispute_target)

    if seller and seller.student_id != buyer.student_id:
        _dispatch_student_notification(
            db,
            seller,
            "Order Disputed",
            f"Order #{order.id} for '{order.title}' was disputed by the buyer and is awaiting admin resolution.",
            "order",
            dispute_target,
        )
    _notify_admins_of_order_event(db, order, "Order Dispute Raised", dispute_message)
    try:
        db.commit()
        db.refresh(dispute)
    except IntegrityError:
        db.rollback()
        raise HTTPException(status_code=409, detail="This order already has an active dispute.")
    _schedule_outbox_delivery(background_tasks, db, outbox_id)

    return {
        "success": True,
        "message": "Dispute raised successfully.",
        "order_id": order.id,
        "status": order.status,
        "dispute_reason": order.dispute_reason,
        "dispute": _serialize_dispute(dispute),
    }


@app.get("/api/orders/{order_id}/dispute")
def get_buyer_order_dispute(
    order_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    buyer = _student_from_authorization(authorization, db)
    dispute = db.query(Dispute).join(Order).filter(
        Dispute.order_id == order_id,
        Order.student_id == buyer.student_id,
    ).order_by(Dispute.created_at.desc()).first()
    if not dispute:
        raise HTTPException(status_code=404, detail="Dispute not found.")
    return _serialize_dispute(dispute)


@app.post("/api/disputes/{dispute_id}/response")
async def respond_to_dispute(
    request: Request,
    dispute_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    seller = _student_from_authorization(authorization, db)

    response_text = ""
    evidence_value = None
    uploaded_files = []

    content_type = request.headers.get("content-type", "").lower()
    if content_type.startswith("multipart/form-data"):
        form = await request.form()
        response_text = str(form.get("response") or "").strip()
        evidence_value = form.get("evidence")
        uploaded_files = [value for value in form.getlist("evidence_images") if getattr(value, "filename", None)]
    else:
        payload = await request.json()
        if not isinstance(payload, dict):
            raise HTTPException(status_code=400, detail="Request body must be an object.")
        response_text = str(payload.get("response") or "").strip()
        evidence_value = payload.get("evidence")

    if not response_text:
        raise HTTPException(status_code=400, detail="A response is required.")
    if len(response_text) < 20:
        raise HTTPException(status_code=400, detail="Response must be at least 20 characters long.")
    if len(response_text) > 5000:
        raise HTTPException(status_code=400, detail="Response must be 5000 characters or fewer.")

    evidence_value = _prepare_dispute_evidence_value(evidence_value, uploaded_files, db=db)

    dispute = db.query(Dispute).filter(Dispute.id == dispute_id).with_for_update().first()
    if not dispute:
        raise HTTPException(status_code=404, detail="Dispute not found.")
    if dispute.seller_id != seller.student_id:
        raise HTTPException(status_code=403, detail="Only the seller for this dispute can respond.")
    if dispute.status not in ACTIVE_DISPUTE_STATUSES:
        raise HTTPException(status_code=409, detail="This dispute is no longer accepting responses.")

    dispute_thread = _derived_dispute_thread(dispute)
    seller_message = {
        "id": f"seller-{dispute.id}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}",
        "sender": "Seller",
        "role": "seller",
        "message": response_text,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "attachments": _normalize_dispute_evidence_value(evidence_value),
    }
    if dispute_thread and dispute_thread[-1].get("role") == "seller":
        dispute_thread[-1] = seller_message
    else:
        dispute_thread.append(seller_message)
    dispute.seller_response = json.dumps(dispute_thread, ensure_ascii=False)
    dispute.seller_evidence = evidence_value
    dispute.status = "UNDER_REVIEW"
    buyer = db.query(Student).filter(Student.student_id == dispute.buyer_id).first()
    if buyer:
        _dispatch_student_notification(db, buyer, "Dispute Updated", f"The seller responded to dispute #{dispute.id}.", "order", order_id=dispute.order_id)
    db.commit()
    db.refresh(dispute)
    return {"success": True, "message": "Dispute response submitted.", "dispute": _serialize_dispute(dispute)}


def _require_admin(authorization: Optional[str], session_token: Optional[str], db: Session) -> Admin:
    token = _extract_admin_token(authorization, session_token)
    admin, _ = _admin_for_session(db, token)
    return admin


def _require_admin_dashboard_access(
    authorization: Optional[str],
    session_token: Optional[str],
    db: Session,
    permission: Optional[str] = None,
) -> Admin:
    try:
        _student_from_authorization(authorization, db)
    except HTTPException:
        admin = _require_admin(authorization, session_token, db)
    else:
        raise HTTPException(status_code=403, detail="Admin access is required.")

    if permission and admin.role != "Admin" and not _admin_permissions(admin).get(permission, False):
        raise HTTPException(status_code=403, detail=f"{permission.replace('_', ' ').title()} permission is required.")
    return admin


def _require_audit_log_reader(authorization: Optional[str], session_token: Optional[str], db: Session) -> Admin:
    admin = _require_admin(authorization, session_token, db)
    if admin.role == "Admin":
        return admin
    if admin.role == "sub_admin" and _admin_permissions(admin).get("audit_logs", False):
        return admin
    logging.getLogger("app.auth").warning("Admin auth rejected: audit_log_role_or_permission_denied.")
    raise HTTPException(status_code=403, detail="Audit-log read permission is required.")


SUPPORT_TICKET_CATEGORIES = {
    "Payment Issue",
    "Dispute",
    "Account Problem",
    "Bug Report",
    "Other",
    "General Inquiry",
    "Login Issue",
    "Payment Problem",
    "Fraud Report",
}
SUPPORT_TICKET_STATUSES = {"Open", "In Progress", "Waiting for User", "Resolved", "Closed"}
SUPPORT_SLA_HOURS = max(1, int(os.getenv("SUPPORT_SLA_HOURS", "48")))
SUPPORT_REOPEN_DAYS = max(1, int(os.getenv("SUPPORT_REOPEN_DAYS", "7")))
SUPPORT_AUTO_CLOSE_DAYS = max(1, int(os.getenv("SUPPORT_AUTO_CLOSE_DAYS", "7")))
SUPPORT_RATE_LIMIT_PER_HOUR = max(1, int(os.getenv("SUPPORT_RATE_LIMIT_PER_HOUR", "5")))
EMAIL_MAX_RETRIES = max(1, int(os.getenv("EMAIL_MAX_RETRIES", "3")))
FRONTEND_BASE_URL = (
    os.getenv("FRONTEND_BASE_URL", "").strip()
    or os.getenv("FRONTEND_URL", "").strip()
    or "http://localhost:5173"
).rstrip("/")


@app.get("/api/payment/return")
async def chapa_payment_return(request: Request, db: Session = Depends(get_db)):
    """Send Chapa's browser return back to the configured frontend."""
    reference = (
        request.query_params.get("trx_ref")
        or request.query_params.get("tx_ref")
        or request.query_params.get("ref_id")
    )
    transaction = (
        db.query(Transaction)
        .filter(Transaction.tx_id == reference)
        .first()
        if reference
        else None
    )
    target_url = (
        f"{FRONTEND_BASE_URL}/dashboard"
        if transaction and _normalize_payment_type(transaction.type) == "Product Purchase"
        else f"{FRONTEND_BASE_URL}/"
    )
    if request.url.query:
        target_url = f"{target_url}?{request.url.query}"
    return RedirectResponse(url=target_url, status_code=303)


def _support_ticket_payload(
    ticket: SupportTicket,
    *,
    include_private: bool = False,
    last_student_activity_at: Optional[datetime] = None,
) -> dict:
    return {
        "id": ticket.id,
        "ticket_number": f"SUP-{ticket.id:04d}",
        "subject": ticket.subject or ticket.category,
        "category": ticket.category,
        "status": ticket.status,
        "created_at": ticket.created_at.isoformat() if ticket.created_at else None,
        "updated_at": ticket.updated_at.isoformat() if ticket.updated_at else None,
        "last_admin_reply_at": ticket.last_admin_reply_at.isoformat() if ticket.last_admin_reply_at else None,
        "assigned_admin_id": ticket.assigned_admin_id,
        "revision": ticket.revision,
        "overdue": _ticket_is_overdue(ticket, last_student_activity_at=last_student_activity_at),
        **({
            "user_id": ticket.user_id,
            "name": ticket.requester_name,
            "email": ticket.requester_email,
            "attachment_url": ticket.attachment_url,
        } if include_private else {}),
    }


def _ticket_is_overdue(
    ticket: SupportTicket,
    now: Optional[datetime] = None,
    last_student_activity_at: Optional[datetime] = None,
) -> bool:
    if ticket.status in {"Resolved", "Closed"}:
        return False
    now = now or datetime.now(timezone.utc).replace(tzinfo=None)
    last_student_activity = last_student_activity_at or ticket.created_at
    if ticket.last_admin_reply_at and last_student_activity and ticket.last_admin_reply_at >= last_student_activity:
        return False
    return bool(last_student_activity and now - last_student_activity > timedelta(hours=SUPPORT_SLA_HOURS))


@app.get("/api/admin/sidebar-counts")
def get_admin_sidebar_counts(
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    admin = _require_admin_dashboard_access(authorization, session_token, db)
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    reports = db.query(Report).all()
    tickets = db.query(SupportTicket).all()
    report_activity = _admin_report_activity_map(db, reports)
    support_activity = _admin_support_activity_map(db, tickets)
    report_seen = _admin_item_seen_map(db, admin.id, "report")
    support_seen = _admin_item_seen_map(db, admin.id, "support_ticket")
    active_ticket_statuses = ("Open", "In Progress", "Waiting for User")
    overdue_tickets = [
        ticket for ticket in tickets
        if ticket.status in active_ticket_statuses
        and _ticket_is_overdue(ticket, now, support_activity[ticket.id])
    ]
    return {
        "pendingVerifications": db.query(Student.id).filter(
            Student.is_verified.is_(False),
            or_(Student.verification_reason.is_(None), Student.verification_reason == ""),
        ).count(),
        "unseenReports": sum(
            report.id not in report_seen or report_activity[report.id] > report_seen[report.id]
            for report in reports
        ),
        "unseenSupport": sum(
            ticket.id not in support_seen or support_activity[ticket.id] > support_seen[ticket.id]
            for ticket in tickets
        ),
        "supportOverdue": len(overdue_tickets),
        "unreadNotifications": db.query(AdminNotification.id).filter(
            AdminNotification.admin_id == admin.id,
            AdminNotification.is_read.is_(False),
        ).count(),
    }


def _admin_item_seen_map(db: Session, admin_id: int, item_type: str) -> dict[int, datetime]:
    return {
        item.item_id: item.seen_at
        for item in db.query(AdminItemSeen).filter(
            AdminItemSeen.admin_id == admin_id,
            AdminItemSeen.item_type == item_type,
        ).all()
    }


def _admin_report_activity_map(db: Session, reports: list[Report]) -> dict[int, datetime]:
    if not reports:
        return {}
    report_ids = [report.id for report in reports]
    reporter_notes = dict(db.query(
        ReportMessage.report_id,
        func.max(ReportMessage.created_at),
    ).filter(
        ReportMessage.report_id.in_(report_ids),
        ReportMessage.admin_id.is_(None),
        ReportMessage.is_internal.is_(False),
    ).group_by(ReportMessage.report_id).all())
    return {
        report.id: max(
            (timestamp for timestamp in (
                report.created_at,
                report.appealed_at,
                report.seller_response_at,
                reporter_notes.get(report.id),
            ) if timestamp is not None),
            default=datetime.min,
        )
        for report in reports
    }


def _admin_support_activity_map(db: Session, tickets: list[SupportTicket]) -> dict[int, datetime]:
    if not tickets:
        return {}
    ticket_ids = [ticket.id for ticket in tickets]
    student_messages = dict(db.query(
        SupportTicketMessage.ticket_id,
        func.max(SupportTicketMessage.created_at),
    ).filter(
        SupportTicketMessage.ticket_id.in_(ticket_ids),
        SupportTicketMessage.sender_type == "student",
        SupportTicketMessage.is_internal.is_(False),
        SupportTicketMessage.is_deleted.is_(False),
    ).group_by(SupportTicketMessage.ticket_id).all())
    return {
        ticket.id: max(
            ticket.created_at or datetime.min,
            student_messages.get(ticket.id) or datetime.min,
        )
        for ticket in tickets
    }


def _record_admin_items_seen(
    db: Session,
    admin: Admin,
    item_type: str,
    activities: dict[int, datetime],
) -> int:
    changed = 0
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    for item_id, activity in activities.items():
        seen = db.query(AdminItemSeen).filter_by(
            admin_id=admin.id,
            item_type=item_type,
            item_id=item_id,
        ).first()
        if seen is not None and activity <= seen.seen_at:
            continue
        seen_at = max(now, activity)
        if seen is None:
            db.add(AdminItemSeen(
                admin_id=admin.id,
                item_type=item_type,
                item_id=item_id,
                seen_at=seen_at,
            ))
        else:
            seen.seen_at = seen_at
        changed += 1
    return changed


def _mark_admin_queue_notifications_read(
    db: Session,
    admin_id: int,
    reference_type: str,
    reference_ids: Optional[list[int]] = None,
) -> None:
    query = db.query(AdminNotification).filter(
        AdminNotification.admin_id == admin_id,
        AdminNotification.reference_type == reference_type,
        AdminNotification.is_read.is_(False),
    )
    if reference_ids is not None:
        query = query.filter(AdminNotification.reference_id.in_([str(item_id) for item_id in reference_ids]))
    query.update({"is_read": True}, synchronize_session="fetch")


@app.post("/api/admin/reports/seen-all")
def mark_all_admin_reports_seen(
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    admin = _require_report_admin(authorization, db)
    reports = db.query(Report).all()
    activities = _admin_report_activity_map(db, reports)
    changed = _record_admin_items_seen(db, admin, "report", activities)
    _mark_admin_queue_notifications_read(db, admin.id, "report")
    if changed:
        _add_admin_audit(db, admin, request, "Admin Reports Marked Seen", f"Marked {changed} report(s) as seen.")
    db.commit()
    return {"success": True, "marked_seen": len(reports)}


@app.post("/api/admin/reports/{report_id}/seen")
def mark_admin_report_seen(
    report_id: int,
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    admin = _require_report_admin(authorization, db)
    report = db.query(Report).filter(Report.id == report_id).first()
    if report is None:
        raise HTTPException(status_code=404, detail="Report not found.")
    activity = _admin_report_activity_map(db, [report])[report.id]
    changed = _record_admin_items_seen(db, admin, "report", {report.id: activity})
    _mark_admin_queue_notifications_read(db, admin.id, "report", [report.id])
    if changed:
        _add_admin_audit(db, admin, request, "Admin Report Marked Seen", f"Marked RPT-{report.id:04d} as seen.")
    db.commit()
    return {"success": True}


