@app.get("/support/tickets/{ticket_id}")
def get_admin_support_ticket(
    ticket_id: int,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    admin = _require_admin(authorization, session_token, db)
    ticket = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()
    if not ticket:
        raise HTTPException(status_code=404, detail="Support ticket not found.")
    db.add(AuditLog(
        admin_id=admin.id,
        action="Support Conversation Viewed",
        entity_type="SupportTicket",
        entity_id=ticket.id,
        description=f"Admin viewed private conversation for SUP-{ticket.id:04d}.",
        status="SUCCESS",
    ))
    db.commit()
    payload = _support_ticket_detail(
        db,
        ticket,
        include_internal=True,
        viewer_type="admin",
        viewer_id=str(admin.id),
    )
    activity = _admin_support_activity_map(db, [ticket])[ticket.id]
    payload["overdue"] = _ticket_is_overdue(ticket, last_student_activity_at=activity)
    seen = db.query(AdminItemSeen).filter_by(
        admin_id=admin.id,
        item_type="support_ticket",
        item_id=ticket.id,
    ).first()
    payload["is_unseen"] = seen is None or activity > seen.seen_at
    return payload


