def _process_support_ticket_automation() -> dict:
    db = SessionLocal()
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    closed_count = 0
    overdue_count = 0
    queued_email_ids = []
    try:
        tickets = db.query(SupportTicket).filter(
            SupportTicket.status.in_(["Waiting for User", "Resolved"]),
            SupportTicket.updated_at <= now - timedelta(days=SUPPORT_AUTO_CLOSE_DAYS),
        ).all()
        for ticket in tickets:
            ticket.status = "Closed"
            ticket.updated_at = now
            student = db.query(Student).filter(Student.student_id == ticket.user_id).first()
            if student:
                ticket_url = f"/dashboard?tab=buyer&section=reports-support&item=support-{ticket.id}"
                outbox_id = _queue_student_item_notification(
                    db,
                    student,
                    title=f"SUP-{ticket.id:04d} was closed",
                    message="Your support request was automatically closed after inactivity.",
                    item_type="support_status",
                    item_id=ticket.id,
                    action_url=ticket_url,
                    email_subject=f"SUP-{ticket.id:04d} was closed",
                    email_summary="Your support request was closed after inactivity.",
                    email_status="Closed",
                )
                if outbox_id:
                    queued_email_ids.append(outbox_id)
            closed_count += 1
        overdue_tickets = db.query(SupportTicket).filter(
            SupportTicket.status.notin_(["Resolved", "Closed"]),
        ).all()
        student_activity = _admin_support_activity_map(db, overdue_tickets)
        for ticket in overdue_tickets:
            if _ticket_is_overdue(ticket, now, student_activity[ticket.id]) and (
                not ticket.last_reminder_at
                or now - ticket.last_reminder_at > timedelta(hours=SUPPORT_SLA_HOURS)
            ):
                _notify_admins(
                    db,
                    title=f"Overdue ticket SUP-{ticket.id:04d}",
                    message=f"This support request has not received an admin reply within {SUPPORT_SLA_HOURS} hours.",
                    reference_type="support",
                    reference_id=ticket.id,
                    action_url=f"/admin/support?ticket={ticket.id}",
                )
                ticket.last_reminder_at = now
                overdue_count += 1
        db.commit()
        for outbox_id in queued_email_ids:
            _deliver_outbox_email(outbox_id)
        return {"closed": closed_count, "overdue": overdue_count}
    except Exception:
        db.rollback()
        logging.getLogger("app.support").exception("Support ticket automation failed.")
        raise
    finally:
        db.close()


@app.get("/api/seller/disputes")
def get_seller_disputes(
    status: Optional[str] = Query(None),
    search: Optional[str] = Query(None),
    date_range: Optional[str] = Query(None, alias="dateRange"),
    archived: Optional[bool] = Query(False),
    limit: Optional[int] = Query(20),
    offset: Optional[int] = Query(0),
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    seller = _student_from_authorization(authorization, db)
    query = db.query(Dispute).filter(Dispute.seller_id == seller.student_id)

    normalized_status = str(status or "").strip().lower()
    if normalized_status in {"active", "open", "pending"}:
        query = query.filter(Dispute.status.in_(ACTIVE_DISPUTE_STATUSES))
    elif normalized_status in {"resolved", "closed"}:
        query = query.filter(Dispute.status == "RESOLVED")

    normalized_search = str(search or "").strip()
    if normalized_search:
        term = f"%{normalized_search}%"
        query = query.join(Order, Order.id == Dispute.order_id).join(Product, Product.id == Order.product_id).filter(
            or_(
                Order.id.cast(String).like(term),
                Product.title.ilike(term),
                Dispute.reason.ilike(term),
            )
        )

    normalized_range = str(date_range or "").strip().lower()
    if normalized_range in {"30d", "30", "30_days", "30days"}:
        cutoff = datetime.now(timezone.utc) - timedelta(days=30)
        query = query.filter(Dispute.created_at >= cutoff)
    elif normalized_range in {"90d", "90", "90_days", "90days"}:
        cutoff = datetime.now(timezone.utc) - timedelta(days=90)
        query = query.filter(Dispute.created_at >= cutoff)
    elif normalized_range in {"180d", "180", "6m", "6months", "6_months"}:
        cutoff = datetime.now(timezone.utc) - timedelta(days=180)
        query = query.filter(Dispute.created_at >= cutoff)
    elif normalized_range in {"all", ""}:
        pass

    cutoff = datetime.now(timezone.utc) - timedelta(days=DISPUTE_ARCHIVE_THRESHOLD_DAYS)
    if archived:
        query = query.filter(Dispute.status == "RESOLVED")
        query = query.filter(Dispute.resolved_at.isnot(None))
        query = query.filter(Dispute.resolved_at < cutoff)
    else:
        query = query.filter(
            or_(
                Dispute.status.in_(ACTIVE_DISPUTE_STATUSES),
                Dispute.status != "RESOLVED",
                Dispute.resolved_at.is_(None),
                Dispute.resolved_at >= cutoff,
            )
        )

    total = query.count()
    disputes = query.order_by(Dispute.created_at.desc()).offset(offset or 0).limit(limit or 20).all()
    return {
        "items": [_serialize_dispute(item, include_parties=True) for item in disputes],
        "total": total,
        "limit": limit or 20,
        "offset": offset or 0,
        "archived": bool(archived),
    }


