@app.get("/api/admin/ai-analytics")
def get_admin_ai_analytics(db: Session = Depends(get_db)):
    """Return live recommendation-model metrics and ranking insights."""
    major_tables = (
        Student, Category, SubCategory, Product, Admin, AuditLog, Report,
        Notification, Message, WishlistItem, CartItem, Order, Transaction,
        PasswordReset, SystemSetting, Review, AIRecommendationLog,
    )
    table_record_counts = {
        model.__tablename__: db.query(model).count() for model in major_tables
    }
    db_records = sum(table_record_counts.values())
    user_profiles = table_record_counts[Student.__tablename__]
    products_indexed = table_record_counts[Product.__tablename__]

    product_columns = {
        column["name"] for column in inspect(db.get_bind()).get_columns(Product.__tablename__)
    }
    has_product_views = "views" in product_columns
    request_count = db.query(AIRecommendationLog).filter(AIRecommendationLog.action_type == "impression").count()
    clicks = db.query(AIRecommendationLog).filter(AIRecommendationLog.action_type == "click").count()
    purchases = db.query(AIRecommendationLog).filter(AIRecommendationLog.action_type == "purchase").count()
    ctr_percentage = round((clicks / request_count) * 100, 2) if request_count else 0
    weekly_start = datetime.now() - timedelta(days=6)
    weekly_rows = db.query(
        func.date(AIRecommendationLog.created_at).label("event_date"),
        AIRecommendationLog.action_type,
        func.count(AIRecommendationLog.id),
    ).filter(
        AIRecommendationLog.created_at >= weekly_start,
        AIRecommendationLog.action_type.in_(["impression", "click"]),
    ).group_by(
        func.date(AIRecommendationLog.created_at), AIRecommendationLog.action_type
    ).all()
    weekly_counts = {}
    for event_date, action_type, count in weekly_rows:
        weekly_counts.setdefault(str(event_date), {})[action_type] = int(count)
    weekly_dates = [(datetime.now() - timedelta(days=6 - index)).date().isoformat() for index in range(7)]
    weekly_requests = [weekly_counts.get(day, {}).get("impression", 0) for day in weekly_dates]
    weekly_clicks = [weekly_counts.get(day, {}).get("click", 0) for day in weekly_dates]
    completed_orders = db.query(Order).filter(Order.status.ilike("Completed")).count()
    precision_percentage = round((purchases / clicks) * 100, 2) if clicks else 0
    recall_percentage = round((purchases / request_count) * 100, 2) if request_count else 0

    top_product_rows = db.query(
        Product.id,
        Product.title,
        func.sum(case((AIRecommendationLog.action_type == "impression", 1), else_=0)).label("views"),
        func.sum(case((AIRecommendationLog.action_type == "click", 1), else_=0)).label("clicks"),
        func.sum(case((AIRecommendationLog.action_type == "purchase", 1), else_=0)).label("purchases"),
    ).join(
        AIRecommendationLog, AIRecommendationLog.product_id == Product.id
    ).group_by(Product.id, Product.title).order_by(
        func.sum(case((AIRecommendationLog.action_type == "impression", 1), else_=0)).desc(),
        Product.title.asc(),
    ).limit(5).all()
    top_products = [
        {
            "id": product_id,
            "product": title,
            "title": title,
            "views": int(views or 0),
            "clicks": int(product_clicks or 0),
            "purchases": int(product_purchases or 0),
        }
        for product_id, title, views, product_clicks, product_purchases in top_product_rows
    ]

    category_rows = (
        db.query(Product.category, func.count(Product.id).label("product_count"))
        .filter(Product.status.ilike("Approved"))
        .group_by(Product.category)
        .order_by(func.count(Product.id).desc())
        .limit(5)
        .all()
    )
    total_approved = sum(int(product_count) for _, product_count in category_rows)
    category_performance = [
        {
            "label": category_name or "General",
            "value": round((int(product_count) / total_approved) * 100, 2) if total_approved else 0,
        }
        for category_name, product_count in category_rows
    ]

    newest_product = db.query(Product.created_at).order_by(Product.created_at.desc()).first()
    newest_product_at = newest_product[0] if newest_product else None
    freshness_is_stable = bool(
        newest_product_at and newest_product_at >= datetime.now() - timedelta(days=3)
    )

    lowest_category = (
        db.query(Product.category, func.count(Product.id).label("product_count"))
        .filter(Product.status.ilike("Approved"))
        .group_by(Product.category)
        .order_by(func.count(Product.id).asc(), Product.category.asc())
        .first()
    )
    lowest_category_name = (lowest_category[0] if lowest_category else None) or "General"
    lowest_category_count = int(lowest_category[1]) if lowest_category else 0
    low_confidence = lowest_category_count < 2

    ai_enabled = bool(_get_setting_value(db, "ai", "enableAI", DEFAULT_SETTINGS_BLOCKS["ai"]["enableAI"]))
    alerts = [
        {
            "title": "Recommendation freshness",
            "status": "STABLE" if freshness_is_stable else "CHECK",
            "type": "success" if freshness_is_stable else "warning",
            "description": (
                "Model updated successfully with the latest product catalog and clickstream data."
                if freshness_is_stable
                else "The product catalog has not received a fresh listing in the last 3 days."
            ),
        },
        {
            "title": "Low confidence cluster",
            "status": "CHECK" if low_confidence else "STABLE",
            "type": "warning" if low_confidence else "success",
            "description": (
                f"{lowest_category_name} subcategory still needs more behavioral signals for better ranking."
                if low_confidence
                else f"{lowest_category_name} has sufficient approved products for reliable ranking signals."
            ),
        },
        {
            "title": "Search relevance boosted",
            "status": "IMPROVED" if ai_enabled else "CHECK",
            "type": "info" if ai_enabled else "warning",
            "description": (
                "Cross-sell recommendations improved with AI-enabled relevance ranking."
                if ai_enabled
                else "AI relevance ranking is disabled in system settings."
            ),
        },
    ]

    return {
        "db_records": db_records,
        "user_profiles": user_profiles,
        "products_indexed": products_indexed,
        "clicks": clicks,
        "requests": request_count,
        "request_count": request_count,
        "ctr": ctr_percentage,
        "weeklyRequests": weekly_requests,
        "weeklyClicks": weekly_clicks,
        "topRecommendedProducts": top_products,
        "ctr_percentage": ctr_percentage,
        "purchase_conversions": purchases,
        "purchase_conversion": purchases,
        "completed_orders": completed_orders,
        "purchases": purchases,
        "precision": precision_percentage,
        "recall": recall_percentage,
        "top_products": top_products,
        "category_performance": category_performance,
        "alerts": alerts,
        "table_record_counts": table_record_counts,
    }


@app.get("/api/admin/payments/gateway-status")
def get_payment_gateway_status():
    checked_at = datetime.now(timezone.utc).isoformat()
    secret_key = os.getenv("CHAPA_SECRET_KEY", "").strip()
    gateway = "Disconnected"
    if secret_key:
        try:
            with httpx.Client(timeout=3.0) as chapa_client:
                response = chapa_client.get(
                    "https://api.chapa.co/v1/banks",
                    headers={"Authorization": f"Bearer {secret_key}"},
                )
            if response.status_code == 200:
                gateway = "Connected"
        except (httpx.RequestError, httpx.TimeoutException):
            gateway = "Disconnected"

    return {
        "gateway": gateway,
        "webhook": "Active" if os.getenv("CHAPA_WEBHOOK_SECRET", "").strip() else "Not configured",
        "currency": "ETB",
        "last_checked": checked_at,
    }


def _completed_order_revenue_expression():
    normalized_price = func.lower(Order.price)
    clean_price = func.replace(
        func.replace(
            func.replace(
                func.replace(normalized_price, "etb", ""),
                "birr",
                "",
            ),
            "usd",
            "",
        ),
        "$",
        "",
    )
    clean_price = func.replace(clean_price, ",", "")
    currency_multiplier = case(
        (
            or_(
                Order.price.ilike("%$%"),
                Order.price.ilike("%usd%"),
            ),
            56,
        ),
        else_=1,
    )
    return sql_cast(clean_price, SQLNumeric(12, 2)) * Order.quantity * currency_multiplier


def _completed_paid_order_filters():
    return (
        func.lower(Order.status) == "completed",
        func.lower(Order.payment_status).in_(("successful", "success", "paid", "completed")),
    )


def _analytics_local_now():
    return analytics_local_now()


@app.get("/api/admin/analytics/sales-trend")
def get_admin_sales_trend(
    months: int = Query(6, ge=1, le=12),
    period: Optional[str] = Query(None, alias="range", pattern="^(7d|30d|year)$"),
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    _require_admin(authorization, None, db)

    local_now = _analytics_local_now()
    if period:
        buckets = get_sales_trend_buckets(period, local_now)
        sales_date = func.coalesce(Order.paid_at, Order.created_at)
        sales_rows = db.query(
            sales_date,
            _completed_order_revenue_expression(),
        ).filter(
            *_completed_paid_order_filters(),
            sales_date >= buckets.start,
            sales_date < buckets.end,
        ).all()
        return build_sales_trend_response(buckets, sales_rows)

    current_month = local_now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    month_rows = []
    for month_offset in range(months - 1, -1, -1):
        absolute_month = current_month.year * 12 + current_month.month - 1 - month_offset
        year, zero_based_month = divmod(absolute_month, 12)
        month_rows.append(datetime(year, zero_based_month + 1, 1))

    range_start = month_rows[0]
    range_end = datetime(
        current_month.year + (current_month.month == 12),
        current_month.month % 12 + 1,
        1,
    )
    sales_date = func.coalesce(Order.paid_at, Order.created_at)
    sales_year = extract("year", sales_date)
    sales_month = extract("month", sales_date)
    grouped_sales = db.query(
        sales_year,
        sales_month,
        func.coalesce(func.sum(_completed_order_revenue_expression()), 0),
        func.count(Order.id),
    ).filter(
        *_completed_paid_order_filters(),
        sales_date >= range_start,
        sales_date < range_end,
    ).group_by(sales_year, sales_month).all()

    sales_by_month = {
        (int(year), int(month)): (round(float(revenue or 0), 2), int(order_count))
        for year, month, revenue, order_count in grouped_sales
    }
    return [
        {
            "month": month_start.strftime("%Y-%m"),
            "label": month_start.strftime("%b %y"),
            "revenue": sales_by_month.get((month_start.year, month_start.month), (0, 0))[0],
            "orders": sales_by_month.get((month_start.year, month_start.month), (0, 0))[1],
        }
        for month_start in month_rows
    ]


@app.get("/api/admin/analytics")
def get_admin_analytics(period: str = "7d", db: Session = Depends(get_db)):
    period = str(period or "7d").strip().lower()
    if period not in {"7d", "30d", "year"}:
        raise HTTPException(status_code=400, detail="Period must be 7d, 30d, or year.")

    total_students = db.query(Student).count()
    active_students = db.query(Student).filter(Student.status.ilike("Active")).count()
    total_products = db.query(Product).count()
    pending_products = db.query(Product).filter(Product.status.ilike("Pending")).count()
    total_orders = db.query(Order).count()
    completed_orders = db.query(Order).filter(Order.status.ilike("Completed")).count()
    revenue_total = db.query(func.coalesce(func.sum(_completed_order_revenue_expression()), 0)).filter(
        *_completed_paid_order_filters(),
    ).scalar() or 0
    revenue_total = float(revenue_total)

    current_period = get_sales_trend_buckets(period, _analytics_local_now())
    previous_period = get_sales_trend_buckets(
        period,
        current_period.start - timedelta(microseconds=1),
    )
    period_order_date = func.coalesce(Order.completed_at, Order.created_at)
    period_revenue_date = func.coalesce(Order.paid_at, Order.created_at)

    def period_growth(current_value, previous_value):
        current_value = float(current_value or 0)
        previous_value = float(previous_value or 0)
        if previous_value == 0:
            change_pct = None
            trend = "new" if current_value > 0 else "unavailable"
        else:
            change_pct = round(((current_value - previous_value) / previous_value) * 100, 1)
            trend = "up" if change_pct > 0 else "down" if change_pct < 0 else "neutral"
        return {
            "value": current_value,
            "previous_value": previous_value,
            "change_pct": change_pct,
            "trend": trend,
        }

    current_users = db.query(Student).filter(
        Student.created_at >= current_period.start,
        Student.created_at < current_period.end,
    ).count()
    previous_users = db.query(Student).filter(
        Student.created_at >= previous_period.start,
        Student.created_at < previous_period.end,
    ).count()
    current_products = db.query(Product).filter(
        Product.created_at >= current_period.start,
        Product.created_at < current_period.end,
    ).count()
    previous_products = db.query(Product).filter(
        Product.created_at >= previous_period.start,
        Product.created_at < previous_period.end,
    ).count()
    current_orders = db.query(Order).filter(
        func.lower(Order.status) == "completed",
        period_order_date >= current_period.start,
        period_order_date < current_period.end,
    ).count()
    previous_orders = db.query(Order).filter(
        func.lower(Order.status) == "completed",
        period_order_date >= previous_period.start,
        period_order_date < previous_period.end,
    ).count()
    current_revenue = db.query(
        func.coalesce(func.sum(_completed_order_revenue_expression()), 0)
    ).filter(
        *_completed_paid_order_filters(),
        period_revenue_date >= current_period.start,
        period_revenue_date < current_period.end,
    ).scalar() or 0
    previous_revenue = db.query(
        func.coalesce(func.sum(_completed_order_revenue_expression()), 0)
    ).filter(
        *_completed_paid_order_filters(),
        period_revenue_date >= previous_period.start,
        period_revenue_date < previous_period.end,
    ).scalar() or 0
    growth = {
        "users": period_growth(current_users, previous_users),
        "products": period_growth(current_products, previous_products),
        "orders": period_growth(current_orders, previous_orders),
        "revenue": period_growth(current_revenue, previous_revenue),
    }

    pending_reports = db.query(Report).filter(Report.status.ilike("Open")).count()
    recommendation_requests = db.query(AIRecommendationLog).filter(
        AIRecommendationLog.action_type == "impression"
    ).count()
    recommendation_clicks = db.query(AIRecommendationLog).filter(
        AIRecommendationLog.action_type == "click"
    ).count()
    recommendation_purchases = db.query(AIRecommendationLog).filter(
        AIRecommendationLog.action_type == "purchase"
    ).count()
    recommendation_ctr = round(
        (recommendation_clicks / recommendation_requests) * 100, 2
    ) if recommendation_requests else 0

    product_status_rows = db.query(Product.status, func.count(Product.id)).group_by(Product.status).all()
    product_status_breakdown = {"Approved": 0, "Pending": 0, "Rejected": 0}
    for status_value, count in product_status_rows:
        normalized = (status_value or "").strip().title()
        if normalized in product_status_breakdown:
            product_status_breakdown[normalized] = int(count)

    def format_revenue(value: float) -> str:
        if value >= 1_000_000:
            return f"{value / 1_000_000:.1f}M ETB"
        if value >= 1_000:
            return f"{value / 1_000:.1f}K ETB"
        return f"{value:,.0f} ETB"

    college_rows = db.query(
        Student.college,
        func.count(Student.id).label("count")
    ).group_by(Student.college).order_by(func.count(Student.id).desc()).all()

    total_college_students = sum(int(count) for _, count in college_rows)
    college_activity = []
    for index, (college_name, count) in enumerate(college_rows):
        color_palette = ["bg-indigo-500", "bg-sky-500", "bg-teal-500", "bg-rose-500", "bg-amber-500", "bg-purple-500"]
        college_activity.append({
            "name": college_name or "Unknown",
            "value": int(count),
            "percentage": round((int(count) / total_college_students) * 100, 1) if total_college_students else 0,
            "color": color_palette[index % len(color_palette)]
        })

    category_rows = db.query(
        Product.category,
        func.count(Product.id).label("product_count")
    ).group_by(Product.category).order_by(func.count(Product.id).desc()).all()

    total_category_products = sum(int(product_count) for _, product_count in category_rows)
    categories = []
    category_colors = ["bg-blue-500", "bg-emerald-500", "bg-amber-500", "bg-rose-500"]
    for index, (category_name, product_count) in enumerate(category_rows):
        percentage = round((int(product_count) / total_category_products) * 100, 1) if total_category_products else 0
        categories.append({
            "name": category_name or "General",
            "product_count": int(product_count),
            "percentage": percentage,
            "color": category_colors[index % len(category_colors)]
        })

    monthly_revenue = []
    monthly_order_counts = []
    months_labels = []
    current_month = datetime.now().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    for month_offset in range(5, -1, -1):
        month_index = current_month.month - month_offset
        year = current_month.year + (month_index - 1) // 12
        month = (month_index - 1) % 12 + 1
        month_start = datetime(year, month, 1)
        month_end = datetime(year + (month == 12), 1 if month == 12 else month + 1, 1)
        months_labels.append(month_start.strftime("%b %y"))
        monthly_revenue.append(float(db.query(func.coalesce(func.sum(Transaction.amount), 0)).filter(
            func.lower(Transaction.status) == "successful",
            func.lower(Transaction.type).in_(("purchase", "product purchase")),
            Transaction.created_at >= month_start,
            Transaction.created_at < month_end,
        ).scalar() or 0))
        monthly_order_counts.append(db.query(Order).filter(
            Order.status.ilike("Completed"),
            Order.created_at >= month_start,
            Order.created_at < month_end,
        ).count())

    recent_audit_rows = db.query(AuditLog, Admin.username).outerjoin(
        Admin, AuditLog.admin_id == Admin.id
    ).order_by(AuditLog.created_at.desc(), AuditLog.id.desc()).limit(3).all()
    recent_activity = [
        {
            "id": audit_log.id,
            "time": audit_log.created_at.strftime("%d %b %Y, %I:%M %p") if audit_log.created_at else "Unknown date",
            "created_at": audit_log.created_at.isoformat() if audit_log.created_at else None,
            "action": audit_log.action,
            "description": audit_log.description,
            "user": admin_username or "System",
            "username": admin_username,
            "status": audit_log.status,
        }
        for audit_log, admin_username in recent_audit_rows
    ]

    chapa_public_key = os.getenv("CHAPA_PUBLIC_KEY", "").strip()
    chapa_secret_key = os.getenv("CHAPA_SECRET_KEY", "").strip()
    successful_transaction_cutoff = datetime.now() - timedelta(hours=24)
    latest_successful_transaction = db.query(Transaction).filter(
        Transaction.status.ilike("Successful"),
        Transaction.created_at >= successful_transaction_cutoff,
    ).order_by(Transaction.created_at.desc()).first()
    gateway_status = "Disconnected"
    if chapa_secret_key:
        try:
            with httpx.Client(timeout=3.0) as chapa_client:
                chapa_response = chapa_client.get(
                    "https://api.chapa.co/v1/banks",
                    headers={"Authorization": f"Bearer {chapa_secret_key}"},
                )
            if chapa_response.status_code == 200:
                gateway_status = "Connected"
        except (httpx.RequestError, httpx.TimeoutException):
            gateway_status = "Disconnected"

    gateway_configured = gateway_status == "Connected"
    gateway_status = {
        "provider": "Chapa",
        "configured": gateway_configured,
        "status": "Connected" if gateway_configured else "Disconnected",
        "webhookStatus": "Active" if latest_successful_transaction else "Awaiting successful transaction",
        "lastSuccessfulTransaction": (
            latest_successful_transaction.created_at.isoformat()
            if latest_successful_transaction and latest_successful_transaction.created_at
            else None
        ),
    }

    order_status_rows = db.query(
        Order.status,
        func.count(Order.id),
    ).group_by(Order.status).order_by(Order.status).all()
    status_counts = {}
    for status_value, count in order_status_rows:
        label = (status_value or "").strip().title() or "Unknown"
        status_counts[label] = status_counts.get(label, 0) + int(count)
    status_total = sum(status_counts.values())
    status_colors = {
        "Completed": "#10b981",
        "Processing": "#3b82f6",
        "Pending": "#f59e0b",
        "Ready For Pickup": "#8b5cf6",
        "Cancelled": "#ef4444",
        "Expired": "#64748b",
        "Disputed": "#f97316",
    }
    fallback_status_colors = ["#06b6d4", "#a855f7", "#ec4899", "#84cc16"]
    status_distribution = [
        {
            "label": label,
            "count": count,
            "value": round((count / status_total) * 100, 1) if status_total else 0,
            "color": status_colors.get(label, fallback_status_colors[index % len(fallback_status_colors)]),
        }
        for index, (label, count) in enumerate(status_counts.items())
    ]

    seven_day_start = datetime.now().date() - timedelta(days=6)
    seven_day_end = seven_day_start + timedelta(days=7)
    registration_date = func.date(Student.created_at).label("registration_date")
    registration_rows = db.query(
        registration_date,
        func.count(Student.id),
    ).filter(
        Student.created_at >= seven_day_start,
        Student.created_at < seven_day_end,
    ).group_by(registration_date).all()
    product_upload_date = func.date(Product.created_at).label("upload_date")
    product_upload_rows = db.query(
        product_upload_date,
        func.count(Product.id),
    ).filter(
        Product.created_at >= seven_day_start,
        Product.created_at < seven_day_end,
    ).group_by(product_upload_date).all()

    registration_counts = {
        str(row_date): int(count)
        for row_date, count in registration_rows
    }
    product_upload_counts = {
        str(row_date): int(count)
        for row_date, count in product_upload_rows
    }
    registrations = []
    product_uploads_trend = []
    cumulative_registrations = 0
    for day_offset in range(7):
        trend_date = seven_day_start + timedelta(days=day_offset)
        date_key = trend_date.isoformat()
        cumulative_registrations += registration_counts.get(date_key, 0)
        registrations.append(cumulative_registrations)
        product_uploads_trend.append(product_upload_counts.get(date_key, 0))

    trend_months = []
    user_growth = []
    product_uploads = []
    revenue_trend = []
    current_month = _analytics_local_now().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    history_months_limit = 6
    month_windows = []
    for month_offset in range(history_months_limit - 1, -1, -1):
        month_index = current_month.month - month_offset
        year = current_month.year + (month_index - 1) // 12
        month = (month_index - 1) % 12 + 1
        target_date = datetime(year, month, 1)
        next_month = datetime(year + (month == 12), 1 if month == 12 else month + 1, 1)
        month_windows.append((target_date, next_month))

    student_year = extract("year", Student.created_at)
    student_month = extract("month", Student.created_at)
    student_rows = db.query(
        student_year,
        student_month,
        func.count(Student.id),
    ).filter(
        Student.created_at >= month_windows[0][0],
        Student.created_at < month_windows[-1][1],
    ).group_by(student_year, student_month).all()
    student_counts_by_month = {
        (int(year), int(month)): int(count)
        for year, month, count in student_rows
    }

    product_year = extract("year", Product.created_at)
    product_month = extract("month", Product.created_at)
    product_rows = db.query(
        product_year,
        product_month,
        func.count(Product.id),
    ).filter(
        Product.created_at >= month_windows[0][0],
        Product.created_at < month_windows[-1][1],
    ).group_by(product_year, product_month).all()
    product_counts_by_month = {
        (int(year), int(month)): int(count)
        for year, month, count in product_rows
    }

    revenue_rows = db.query(Transaction.created_at, Transaction.amount).filter(
        Transaction.created_at >= month_windows[0][0],
        Transaction.created_at < month_windows[-1][1],
        func.lower(Transaction.status) == "successful",
        func.lower(Transaction.type).in_(("purchase", "product purchase")),
    ).all()
    revenue_by_month = {}
    for created_at, amount in revenue_rows:
        month_key = (created_at.year, created_at.month)
        revenue_by_month[month_key] = revenue_by_month.get(month_key, 0) + float(amount or 0)

    for target_date, next_month in month_windows:
        month_key = (target_date.year, target_date.month)
        trend_months.append(target_date.strftime("%b %y"))
        user_growth.append(student_counts_by_month.get(month_key, 0))
        product_uploads.append(product_counts_by_month.get(month_key, 0))
        revenue_trend.append(revenue_by_month.get(month_key, 0.0))

    return {
        "total_students": total_students,
        "active_students": active_students,
        "total_products": total_products,
        "pending_products": pending_products,
        "total_orders": total_orders,
        "completed_orders": completed_orders,
        "total_revenue": revenue_total,
        "analytics_period": period,
        "growth": growth,
        "pending_reports": pending_reports,
        "requests": recommendation_requests,
        "clicks": recommendation_clicks,
        "ctr": recommendation_ctr,
        "purchases": recommendation_purchases,
        "users": total_students,
        "activeStudents": active_students,
        "products": total_products,
        "orders": total_orders,
        "completedOrders": completed_orders,
        "pendingProducts": pending_products,
        "pendingReports": pending_reports,
        "gatewayStatus": gateway_status,
        "revenue": format_revenue(revenue_total),
        "trends": {
            "months": trend_months,
            "user_growth": user_growth,
            "product_uploads": product_uploads,
            "revenue": revenue_trend,
        },
        "userGrowth": [
            {"month": month, "users": users, "products": products}
            for month, users, products in zip(trend_months, user_growth, product_uploads)
        ],
        "salesTrend": product_uploads,
        "revenueTrend": revenue_trend,
        "registrations": registrations,
        "registrationLabels": [
            (seven_day_start + timedelta(days=day_offset)).strftime("%d %b")
            for day_offset in range(7)
        ],
        "productUploadsTrend": product_uploads_trend,
        "monthlyRevenue": revenue_trend,
        "monthlyOrderCounts": monthly_order_counts,
        "monthsLabels": months_labels,
        "orderStatus": status_distribution,
        "categories": categories,
        "college_activity": college_activity,
        "collegeActivity": college_activity,
        "collegesActivity": college_activity,
        "categoryPerformance": categories,
        "productStatusBreakdown": product_status_breakdown,
        "recentActivity": recent_activity,
    }


@app.get("/api/admin/users")
def get_admin_users(
    search: Optional[str] = None,
    college: Optional[str] = None,
    department: Optional[str] = None,
    db: Session = Depends(get_db),
):
    query = db.query(Student)

    if search and search.strip():
        term = f"%{search.strip()}%"
        query = query.filter(
            or_(
                Student.name.ilike(term),
                Student.email.ilike(term),
                Student.student_id.ilike(term),
            )
        )

    if college and college.strip().lower() != "all":
        query = query.filter(Student.college.ilike(college.strip()))

    if department and department.strip().lower() != "all":
        query = query.filter(Student.department.ilike(department.strip()))

    students = query.order_by(Student.id.desc()).all()
    results = []

    for s in students:
        active_listing_count = db.query(Product).filter(
            or_(Product.seller == s.student_id, Product.seller == s.name),
            Product.status.ilike("Approved"),
        ).count()

        wallet_balance = float(s.wallet_balance) if s.wallet_balance is not None else 0.0

        results.append({
            "id": s.id,
            "name": s.name,
            "email": s.email,
            "student_id": s.student_id,
            "phone": s.phone,
            "college": s.college,
            "department": s.department,
            "year": s.student_id[:4] if s.student_id and s.student_id[:4].isdigit() else "Year 1",
            "is_verified": bool(s.is_verified),
            "status": s.status or "Active",
            "restriction_reason": s.restriction_reason,
            "wallet_balance": wallet_balance,
            "active_listings": active_listing_count,
            "rating": "No ratings",
            "activity": [{"action": "Account synced", "time": "Recently"}],
            "role": "Student",
        })

    return results


@app.post("/api/admin/users", status_code=status.HTTP_201_CREATED)
def create_admin_user(payload: AdminStudentCreate, db: Session = Depends(get_db)):
    try:
        student_id = payload.student_id.strip()
        email = payload.email.strip().lower()
        if not all((payload.name.strip(), student_id, email, payload.college.strip(), payload.department.strip(), payload.password)):
            raise HTTPException(status_code=400, detail="Name, student ID, email, college, department, and password are required.")

        if db.query(Student).filter(Student.student_id == student_id).first():
            raise HTTPException(status_code=400, detail="Student ID is already registered.")
        if db.query(Student).filter(func.lower(Student.email) == email).first():
            raise HTTPException(status_code=400, detail="Email is already registered.")

        defaults = DEFAULT_SETTINGS_BLOCKS["studentVerification"]
        allowed_domain = str(_get_setting_value(db, "studentVerification", "allowedEmailDomain", defaults["allowedEmailDomain"]) or "").strip().lstrip("@").lower()
        require_university_email = _setting_bool(
            _get_setting_value(db, "studentVerification", "requireUniversityEmail", defaults["requireUniversityEmail"]),
            defaults["requireUniversityEmail"],
        )
        auto_approve_students = _setting_bool(
            _get_setting_value(db, "studentVerification", "autoApproveStudents", defaults["autoApproveStudents"]),
            defaults["autoApproveStudents"],
        )
        if require_university_email and email.rsplit("@", 1)[-1].lower() != allowed_domain:
            raise HTTPException(status_code=400, detail=f"Registration failed. Please use your official university email ending with @{allowed_domain}")

        student = Student(
            name=payload.name.strip(),
            student_id=student_id,
            email=email,
            phone=payload.phone.strip() if payload.phone else None,
            college=payload.college.strip(),
            department=payload.department.strip(),
            password=hash_password(payload.password),
            is_verified=auto_approve_students,
            status="Active",
        )
        db.add(student)
        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Admin Student Created",
            entity_type="Student",
            entity_id=None,
            description=f"Admin {admin.username if admin else 'system'} created a new student account: {student.name} ({student.student_id}).",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        db.commit()
        db.refresh(student)
        return {
            "message": "Student account created successfully.",
            "student": {
                "id": student.id,
                "name": student.name,
                "student_id": student.student_id,
                "email": student.email,
                "phone": student.phone,
                "college": student.college,
                "department": student.department,
                "is_verified": bool(student.is_verified),
                "status": student.status,
            },
        }
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to create student account.")


@app.post("/api/admin/users/bulk-approve")
def bulk_approve_users(student_ids: List[int], db: Session = Depends(get_db)):
    if not student_ids:
        raise HTTPException(status_code=400, detail="Select at least one user to approve.")

    try:
        unique_ids = list(dict.fromkeys(student_ids))
        students = db.query(Student).filter(Student.id.in_(unique_ids)).all()
        students_by_id = {student.id: student for student in students}
        missing_ids = [student_id for student_id in unique_ids if student_id not in students_by_id]
        if missing_ids:
            raise HTTPException(status_code=404, detail=f"Student not found: {missing_ids[0]}")

        for student in students:
            student.is_verified = True
            student.verification_reason = None

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Bulk User Verification Approved",
            entity_type="Student",
            entity_id=None,
            description=f"Admin approved verification for {len(students)} selected user(s): {', '.join(student.student_id for student in students)}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        db.commit()
        return {"message": f"Approved {len(students)} selected user(s).", "approved_ids": unique_ids}
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to approve selected users.")


@app.post("/api/admin/users/bulk-reject")
def bulk_reject_users(payload: BulkRejectVerificationRequest, db: Session = Depends(get_db)):
    if not payload.student_ids:
        raise HTTPException(status_code=400, detail="Select at least one user to reject.")
    reason = payload.reason.strip()
    if not reason:
        raise HTTPException(status_code=400, detail="A rejection reason is required.")

    try:
        unique_ids = list(dict.fromkeys(payload.student_ids))
        students = db.query(Student).filter(Student.id.in_(unique_ids)).all()
        students_by_id = {student.id: student for student in students}
        missing_ids = [student_id for student_id in unique_ids if student_id not in students_by_id]
        if missing_ids:
            raise HTTPException(status_code=404, detail=f"Student not found: {missing_ids[0]}")

        for student in students:
            student.is_verified = False
            student.verification_reason = reason

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Bulk User Verification Rejected",
            entity_type="Student",
            entity_id=None,
            description=f"Admin rejected verification for {len(students)} selected user(s). Reason: {reason}. Students: {', '.join(student.student_id for student in students)}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        db.commit()
        return {"message": f"Rejected {len(students)} selected user(s).", "rejected_ids": unique_ids}
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to reject selected users.")


@app.get("/api/admin/colleges")
def get_colleges():
    """Returns all colleges from the university structure."""
    return sorted(list(UNIVERSITY_STRUCTURE.keys()))


@app.get("/api/admin/departments")
def get_departments(college: Optional[str] = None):
    """
    Returns departments from the university structure.
    If college is provided, returns only that college's departments.
    Otherwise, returns all departments flattened.
    """
    if college and college in UNIVERSITY_STRUCTURE:
        return UNIVERSITY_STRUCTURE[college]
    
    all_departments = []
    for depts in UNIVERSITY_STRUCTURE.values():
        all_departments.extend(depts)
    return sorted(all_departments)


@app.put("/api/admin/users/{id}/status")
def update_user_status(id: int, payload: UserStatusUpdate, db: Session = Depends(get_db)):
    student = db.query(Student).filter(Student.id == id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")

    normalized_status = (payload.status or "").strip()
    valid_statuses = {"Active", "Suspended", "Deactivated"}
    if normalized_status not in valid_statuses:
        raise HTTPException(status_code=400, detail="Status must be one of: Active, Suspended, Deactivated")

    reason_text = (payload.reason or "").strip() if payload.reason else ""
    if normalized_status in {"Suspended", "Deactivated"} and not reason_text:
        reason_text = "Policy review"

    try:
        previous_status = student.status
        student.status = normalized_status
        student.restriction_reason = reason_text if normalized_status in {"Suspended", "Deactivated"} else None

        if normalized_status in {"Suspended", "Deactivated"} and previous_status != normalized_status:
            admin = db.query(Admin).order_by(Admin.id.asc()).first()
            message = (
                f"Your account has been restricted to {normalized_status}. Reason: {reason_text}. Please contact support for review."
            )

            db.add(Notification(
                student_id=student.student_id,
                message=message,
                is_read=False,
            ))

        if previous_status != normalized_status:
            admin = db.query(Admin).order_by(Admin.id.asc()).first()
            db.add(AuditLog(
                admin_id=admin.id if admin else None,
                action=f"User {normalized_status}",
                entity_type="User",
                entity_id=student.id,
                description=(
                    f"Admin updated user {student.name} ({student.student_id}) from {previous_status} "
                    f"to {normalized_status}. Reason: {reason_text or 'None'}"
                ),
                status="SUCCESS",
                ip_address="127.0.0.1",
            ))

        db.commit()
        db.refresh(student)

        return {
            "message": "User status updated successfully",
            "id": student.id,
            "student_id": student.student_id,
            "status": student.status,
            "reason": student.restriction_reason,
        }
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to update user status.")


@app.put("/api/admin/users/{id}")
def update_admin_user(id: int, payload: AdminUserUpdate, db: Session = Depends(get_db)):
    student = db.query(Student).filter(Student.id == id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")

    normalized_email = payload.email.strip().lower()
    if not normalized_email:
        raise HTTPException(status_code=400, detail="Email is required.")

    duplicate_email = db.query(Student).filter(
        func.lower(Student.email) == normalized_email,
        Student.id != id,
    ).first()
    if duplicate_email:
        raise HTTPException(status_code=400, detail="Email is already registered to another student.")

    normalized_status = payload.status.strip()
    if normalized_status not in {"Active", "Suspended", "Deactivated"}:
        raise HTTPException(status_code=400, detail="Status must be Active, Suspended, or Deactivated.")

    try:
        previous_values = {
            "name": student.name,
            "email": student.email,
            "phone": student.phone,
            "college": student.college,
            "department": student.department,
            "is_verified": bool(student.is_verified),
            "status": student.status,
        }
        updated_values = {
            "name": payload.name.strip(),
            "email": normalized_email,
            "phone": payload.phone.strip() if payload.phone else None,
            "college": payload.college.strip(),
            "department": payload.department.strip(),
            "is_verified": payload.is_verified,
            "status": normalized_status,
        }
        if not updated_values["name"] or not updated_values["college"] or not updated_values["department"]:
            raise HTTPException(status_code=400, detail="Name, college, and department are required.")

        for field, value in updated_values.items():
            setattr(student, field, value)

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        changes = [
            f"{field} changed from {previous_values[field]!r} to {value!r}"
            for field, value in updated_values.items()
            if previous_values[field] != value
        ]
        if changes:
            db.add(AuditLog(
                admin_id=admin.id if admin else None,
                action="Student Profile Updated",
                entity_type="Student",
                entity_id=student.id,
                description="; ".join(changes),
                status="SUCCESS",
                ip_address="127.0.0.1",
            ))

        db.commit()
        db.refresh(student)
        return {
            "message": "Student profile updated successfully.",
            "student": {
                "id": student.id,
                "name": student.name,
                "email": student.email,
                "phone": student.phone,
                "college": student.college,
                "department": student.department,
                "is_verified": bool(student.is_verified),
                "status": student.status,
            },
            "changes": changes,
        }
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to update student profile.")


@app.delete("/api/admin/users/{id}")
def delete_user(id: int, db: Session = Depends(get_db)):
    student = db.query(Student).filter(Student.id == id).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")

    try:
        db.query(Product).filter(
            or_(
                Product.seller == student.student_id,
                Product.seller == student.name,
            )
        ).delete(synchronize_session=False)
        db.delete(student)
        db.commit()
        return {"message": "User deleted successfully"}
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to delete user and associated products.")


@app.get("/api/admin/verifications")
def get_admin_verifications(
    search: Optional[str] = None,
    college: Optional[str] = None,
    department: Optional[str] = None,
    db: Session = Depends(get_db),
):
    verification_counts = {
        "pending": db.query(Student).filter(
            Student.is_verified == False,
            or_(Student.verification_reason.is_(None), Student.verification_reason == ""),
        ).count(),
        "verified": db.query(Student).filter(Student.is_verified == True).count(),
        "rejected": db.query(Student).filter(
            Student.is_verified == False,
            Student.verification_reason.isnot(None),
            Student.verification_reason != "",
        ).count(),
    }
    query = db.query(Student).filter(Student.is_verified == False)
    if search and search.strip():
        term = f"%{search.strip()}%"
        query = query.filter(or_(Student.name.ilike(term), Student.student_id.ilike(term), Student.email.ilike(term)))

    if college and college.strip().lower() != "all":
        query = query.filter(Student.college.ilike(college.strip()))

    if department and department.strip().lower() != "all":
        query = query.filter(Student.department.ilike(department.strip()))

    students = query.order_by(Student.id.desc()).all()
    results = []
    for student in students:
        status_value = "Rejected" if student.verification_reason else "Pending"
        id_card_path = os.path.join(ID_CARD_DIR, f"{student.student_id}.jpg")
        avatar_path = os.path.join(AVATAR_DIR, f"{student.student_id}.jpg")
        uploaded_id_card = student.id_card_url or (
            f"http://127.0.0.1:8000/static/uploads/id_cards/{student.student_id}.jpg"
            if os.path.exists(id_card_path)
            else f"http://127.0.0.1:8000/static/uploads/avatars/{student.student_id}.jpg"
            if os.path.exists(avatar_path)
            else None
        )
        results.append({
            "id": student.id,
            "name": student.name,
            "student_id": student.student_id,
            "email": student.email,
            "phone": student.phone,
            "college": student.college,
            "department": student.department or "General Studies",
            "status": status_value,
            "uploaded_id_card": uploaded_id_card,
            "reason": student.verification_reason,
            "is_verified": student.is_verified,
        })

    return {
        "verifications": results,
        "counts": verification_counts,
        "total_pending": verification_counts["pending"],
        "total_verified": verification_counts["verified"],
        "total_rejected": verification_counts["rejected"],
    }




@app.post("/api/admin/verifications/bulk-approve")
def bulk_approve_verifications(student_ids: List[int], db: Session = Depends(get_db)):
    if not student_ids:
        raise HTTPException(status_code=400, detail="Select at least one student to approve.")

    try:
        unique_ids = list(dict.fromkeys(student_ids))
        students = db.query(Student).filter(
            Student.id.in_(unique_ids)
        ).with_for_update().all()
        students_by_id = {student.id: student for student in students}
        missing_ids = [student_id for student_id in unique_ids if student_id not in students_by_id]
        if missing_ids:
            raise HTTPException(status_code=404, detail=f"Student not found: {missing_ids[0]}")

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        approved_ids = []
        approved_students = []
        for student in students:
            if not student.is_verified:
                student.is_verified = True
                notify_id_verified(db, student.student_id)
            student.verification_reason = None
            approved_ids.append(student.id)
            approved_students.append(f"{student.name} ({student.student_id})")

        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Bulk Student Verification Approved",
            entity_type="Student Verification",
            entity_id=None,
            description=f"Admin approved {len(approved_ids)} student verification request(s) via bulk action: {', '.join(approved_students)}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))

        db.commit()
        return {"message": f"Approved {len(approved_ids)} student verification request(s).", "approved_ids": approved_ids}
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to approve selected verifications.")


@app.post("/api/admin/verifications/bulk-reject")
def bulk_reject_verifications(payload: BulkRejectVerificationRequest, db: Session = Depends(get_db)):
    if not payload.student_ids:
        raise HTTPException(status_code=400, detail="Select at least one student to reject.")
    reason = payload.reason.strip()
    if not reason:
        raise HTTPException(status_code=400, detail="A rejection reason is required.")

    try:
        unique_ids = list(dict.fromkeys(payload.student_ids))
        students = db.query(Student).filter(Student.id.in_(unique_ids)).all()
        students_by_id = {student.id: student for student in students}
        missing_ids = [student_id for student_id in unique_ids if student_id not in students_by_id]
        if missing_ids:
            raise HTTPException(status_code=404, detail=f"Student not found: {missing_ids[0]}")

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        rejected_names = []
        for student in students:
            student.is_verified = False
            student.verification_reason = reason
            rejected_names.append(f"{student.name} ({student.student_id})")
            db.add(Notification(
                student_id=student.student_id,
                title="Identity verification update",
                message=f"Your student identity verification was rejected. Reason: {reason}. Please resubmit a clear and readable student ID.",
                type="system",
                is_read=False,
            ))

        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Bulk Student Verification Rejected",
            entity_type="Student Verification",
            entity_id=None,
            description=f"Admin rejected {len(students)} student verification request(s) via bulk action. Reason: {reason}. Students: {', '.join(rejected_names)}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        db.commit()
        return {"message": f"Rejected {len(students)} student verification request(s).", "rejected_ids": unique_ids}
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to reject selected verifications.")


@app.post("/api/student/upload-id")
async def upload_student_id(
    student_id: str = Form(...),
    id_photo: UploadFile = File(...),
    db: Session = Depends(get_db),
):
    student = db.query(Student).filter(Student.student_id == student_id.strip()).first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found.")

    content_type = (id_photo.content_type or "").lower()
    allowed_types = {"image/jpeg", "image/png", "image/webp"}
    if content_type not in allowed_types:
        raise HTTPException(status_code=400, detail="ID photo must be a JPEG, PNG, or WebP image.")

    try:
        id_card_url = save_upload(id_photo, "campace/ids")
    finally:
        await id_photo.close()

    student.id_card_url = id_card_url
    student.verification_reason = None
    db.commit()
    db.refresh(student)

    return {
        "message": "Student ID uploaded successfully.",
        "student_id": student.student_id,
        "id_card_url": student.id_card_url,
    }


@app.put("/api/admin/verifications/{id}")
def update_student_verification(
    id: int,
    payload: VerificationDecisionRequest,
    db: Session = Depends(get_db),
):
    student = db.query(Student).filter(Student.id == id).with_for_update().first()
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")

    normalized_status = (payload.status or "").strip().lower()
    if normalized_status not in {"approved", "verified", "rejected", "rejected_flagged", "flagged"}:
        raise HTTPException(status_code=400, detail="Status must be one of: Approved, Verified, Rejected")

    approved = normalized_status in {"approved", "verified"}
    rejection_reason = (payload.reason or "").strip() if not approved else None
    if approved and student.is_verified:
        return {
            "message": "Student is already verified.",
            "student_id": student.student_id,
            "status": "Approved",
            "reason": None,
            "is_verified": True,
            "email_sent": False,
            "email_detail": "No status change was made.",
        }

    admin = db.query(Admin).order_by(Admin.id.asc()).first()

    try:
        if approved:
            student.is_verified = True
            student.verification_reason = None
            notify_id_verified(db, student.student_id)
            log_action = "Student Verification Approved"
            description = f"Admin approved student verification for {student.name} ({student.student_id})."
        else:
            student.is_verified = False
            student.verification_reason = rejection_reason
            notification_message = (
                f"Your student identity verification was rejected. "
                f"Reason: {rejection_reason}. Please resubmit a clear and readable student ID."
            )
            notification_title = "Identity verification update"
            log_action = "Student Verification Rejected"
            description = (
                f"Admin rejected student verification for {student.name} ({student.student_id}) "
                f"with reason: {rejection_reason}."
            )

            db.add(Notification(
                student_id=student.student_id,
                title=notification_title,
                message=notification_message,
                type="system",
                is_read=False,
            ))

        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action=log_action,
            entity_type="Student",
            entity_id=student.id,
            description=description,
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))

        email_sent = send_verification_status_email(
            student.email,
            "Approved" if approved else "Rejected",
            rejection_reason,
        )
        if not email_sent:
            logging.getLogger("app.auth").warning(
                "Verification status was saved, but the notification email could not be sent to %s.",
                student.email,
            )

        db.commit()
        db.refresh(student)

        return {
            "message": "Student verification updated successfully",
            "student_id": student.student_id,
            "status": "Approved" if approved else "Rejected",
            "reason": rejection_reason,
            "is_verified": student.is_verified,
            "email_sent": email_sent,
            "email_detail": (
                "Verification status email delivered successfully."
                if email_sent
                else "Verification status was updated, but the notification email could not be delivered."
            ),
        }
    except Exception:
        db.rollback()
        raise HTTPException(status_code=500, detail="Failed to process student verification request.")


@app.put("/api/admin/products/{product_id}")
def update_admin_product_moderation(
    product_id: int,
    payload: ProductModerationUpdate,
    db: Session = Depends(get_db),
):
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found.")

    status_by_key = {value.lower(): value for value in ("Approved", "Flagged", "Pending", "Rejected")}
    normalized_status = status_by_key.get(payload.status.strip().lower())
    if normalized_status is None:
        detail = "Invalid product moderation status."
        logger.warning(
            "Admin product moderation rejected: product_id=%s status=%r detail=%s",
            product_id,
            payload.status,
            detail,
        )
        raise HTTPException(status_code=400, detail=detail)

    reason = payload.reason.strip() if payload.reason else None
    if normalized_status == "Approved":
        product.stock = max(1, int(getattr(product, "stock", None) or 1))

    try:
        _validate_product_stock_status(int(getattr(product, "stock", 0) or 0), normalized_status)
    except HTTPException as error:
        if error.status_code == 400:
            logger.warning(
                "Admin product moderation rejected: product_id=%s status=%r detail=%s",
                product_id,
                payload.status,
                error.detail,
            )
        raise

    try:
        product.status = normalized_status
        product.moderation_reason = reason if normalized_status in {"Flagged", "Rejected"} else None

        seller = db.query(Student).filter(
            or_(Student.student_id == product.seller, Student.name == product.seller)
        ).first() if product.seller else None
        if seller and normalized_status in {"Flagged", "Rejected"}:
            db.add(Notification(
                student_id=seller.student_id,
                title="Product Requires Review",
                message=f"Your product '{product.title}' was {normalized_status.lower()}. Reason: {reason or 'Policy review'}. Please review and update your listing.",
                type="moderation",
                is_read=False,
            ))

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action=f"Product {normalized_status}",
            entity_type="Product",
            entity_id=product.id,
            description=f"Admin moderated product {product.title} ({product.id}) as {normalized_status}. Reason: {reason or 'None'}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))
        db.commit()
        db.refresh(product)
        return {
            "message": "Product moderation updated successfully.",
            "id": product.id,
            "status": product.status,
            "moderation_reason": product.moderation_reason,
            "seller_notified": bool(seller and normalized_status in {"Flagged", "Rejected"}),
        }
    except SQLAlchemyError:
        db.rollback()
        logger.exception("Database error updating admin product moderation: product_id=%s", product_id)
        raise HTTPException(status_code=500, detail="Failed to update product moderation.")


