@app.get("/api/admin/products")
def get_admin_products(
    status: Optional[str] = None,
    search: Optional[str] = None,
    category: Optional[str] = None,
    subcategory: Optional[str] = None,
    db: Session = Depends(get_db),
):
    query = db.query(Product)

    if status and status.strip().lower() != "all":
        query = query.filter(Product.status.ilike(status.strip()))

    if category and category.strip().lower() != "all":
        query = query.filter(Product.category.ilike(category.strip()))

    if subcategory and subcategory.strip().lower() != "all":
        query = query.filter(Product.subcategory.ilike(subcategory.strip()))

    if search and search.strip():
        term = f"%{search.strip()}%"
        query = query.filter(
            or_(
                Product.title.ilike(term),
                Product.description.ilike(term),
                Product.category.ilike(term),
                Product.seller.ilike(term),
            )
        )

    products = query.order_by(Product.created_at.desc()).all()
    results = []
    for p in products:
        seller_id = p.seller or "Unknown"
        student_record = db.query(Student).filter(
            (Student.student_id == seller_id) | (Student.name == seller_id)
        ).first()

        normalized_price = p.price or "0 ETB"
        price_value = str(normalized_price).replace(",", "").replace(" ETB", "").replace("etb", "").strip()
        if p.condition:
            condition = p.condition
        else:
            try:
                condition = "New" if float(price_value) >= 1000 else "Gently Used"
            except (TypeError, ValueError):
                condition = "New"

        results.append({
            "id": p.id,
            "title": p.title,
            "seller": p.seller or "Student",
            "seller_id": seller_id,
            "category": p.category,
            "status": p.status or "Pending",
            "price": p.price,
            "image": _normalize_product_image(p.image),
            "description": p.description or "No description provided yet.",
            "subcategory": p.subcategory,
            "condition": condition,
            "seller_verified": bool(student_record),
            "moderation_reason": p.moderation_reason,
        })

    return results


def _get_admin_product_status_counts(
    db: Session,
    category: Optional[str] = None,
    subcategory: Optional[str] = None,
) -> Dict[str, int]:
    normalized_status = func.lower(func.trim(func.coalesce(Product.status, "")))
    query = db.query(
        normalized_status.label("normalized_status"),
        func.count(Product.id).label("status_count"),
    )

    if category and category.strip().lower() != "all":
        query = query.filter(Product.category.ilike(category.strip()))
    if subcategory and subcategory.strip().lower() != "all":
        query = query.filter(Product.subcategory.ilike(subcategory.strip()))

    query = query.group_by(normalized_status)
    logger.debug(
        "Admin product moderation status SQL: %s",
        query.statement.compile(
            bind=db.get_bind(),
            compile_kwargs={"literal_binds": True},
        ),
    )

    counts = {"total": 0, "available": 0, "sold": 0, "pending": 0, "flagged": 0}
    for status_value, row_count in query.all():
        count = int(row_count)
        status_value = str(status_value or "")
        counts["total"] += count
        if status_value in {"approved", "active", "available"}:
            counts["available"] += count
        elif status_value == "sold":
            counts["sold"] += count
        elif status_value == "pending":
            counts["pending"] += count
        elif status_value == "flagged":
            counts["flagged"] += count

    logger.debug("Admin product moderation status counts: %s", counts)
    return counts


@app.get("/api/admin/products/stats")
def get_admin_product_stats(
    category: Optional[str] = None,
    subcategory: Optional[str] = None,
    db: Session = Depends(get_db),
):
    return _get_admin_product_status_counts(db, category, subcategory)


def update_product_status_impl(id: int, data: ProductStatusUpdate, db: Session):
    product = db.query(Product).filter(Product.id == id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found")

    normalized_status = (data.status or "").strip()
    if not normalized_status:
        raise HTTPException(status_code=400, detail="Status is required.")

    action_label = normalized_status.lower()
    current_status = str(product.status or "").strip().lower()
    if current_status == "sold" and action_label != "sold":
        raise HTTPException(
            status_code=400,
            detail="Sold products cannot be moved back to another status.",
        )

    reason_text = None
    if data.reason and data.reason.strip():
        reason_text = data.reason.strip()
        product.moderation_reason = reason_text

    if action_label in {"flagged", "rejected", "rejected_flagged", "flag"}:
        if reason_text is None:
            raise HTTPException(status_code=400, detail="A rejection reason is required when flagging or rejecting a product.")

    _validate_product_stock_status(int(getattr(product, "stock", 0) or 0), normalized_status)
    product.status = normalized_status

    seller_id = product.seller or None
    seller_student = None
    if seller_id:
        seller_student = db.query(Student).filter(
            (Student.student_id == seller_id) | (Student.name == seller_id)
        ).first()

    try:
        if action_label in {"flagged", "rejected", "flag", "rejected_flagged"}:
            moderation_label = "flagged for review" if action_label in {"flagged", "flag"} else "rejected"
            notification_message = (
                f"Your previously approved listing '{product.title}' has been {moderation_label} by the admin moderation team. "
                f"Reason: {reason_text}. Please review and update the listing before requesting approval again."
                if current_status == "approved"
                else f"Your listing '{product.title}' was {moderation_label} by the admin moderation team. "
                f"Reason: {reason_text}. Please review and update the listing before requesting approval again."
            )
            if _notifications_enabled(db, "approvalNotifs"):
                if seller_student:
                    db.add(Notification(
                        student_id=seller_student.student_id,
                        message=notification_message,
                        is_read=False,
                    ))
                elif seller_id:
                    db.add(Notification(
                        student_id=seller_id,
                        message=notification_message,
                        is_read=False,
                    ))

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        log_action = "Product Approved" if normalized_status.lower() == "approved" else "Product Flagged" if normalized_status.lower() in {"flagged", "flag"} else "Product Rejected" if normalized_status.lower() in {"rejected", "rejected_flagged"} else f"Product {normalized_status}"
        log_desc = (
            f"Admin updated product '{product.title}' to status '{normalized_status}'."
            if reason_text is None
            else f"Admin updated product '{product.title}' to status '{normalized_status}' with reason: {reason_text}."
        )

        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action=log_action,
            entity_type="Product",
            entity_id=product.id,
            description=log_desc,
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))

        db.commit()
        db.refresh(product)

        return {
            "message": "Product status updated successfully",
            "product": {
                "id": product.id,
                "title": product.title,
                "status": product.status,
                "reason": product.moderation_reason,
            },
            "notification_created": bool(
                (seller_student or seller_id) and _notifications_enabled(db, "approvalNotifs")
            ),
        }
    except Exception:
        db.rollback()
        raise


@app.patch("/api/admin/products/{id}")
def update_product_status_patch(id: int, data: ProductStatusUpdate, db: Session = Depends(get_db)):
    return update_product_status_impl(id=id, data=data, db=db)


