@app.get("/api/admin/payments")
def get_admin_payments_endpoint(
    search: Optional[str] = None,
    payment_type: Optional[str] = None,
    status: Optional[str] = None,
    limit: int = 100,
    db: Session = Depends(get_db),
):
    try:
        query = db.query(
            Transaction,
            Wallet.student_id.label("wallet_owner_id"),
        ).outerjoin(Wallet, Transaction.wallet_id == Wallet.id)

        if search and search.strip():
            term = f"%{search.strip()}%"
            query = query.filter(
                or_(
                    Transaction.tx_id.ilike(term),
                    Transaction.student_id.ilike(term),
                    Transaction.description.ilike(term),
                    Transaction.type.ilike(term),
                )
            )

        if payment_type and payment_type.strip().lower() != "all":
            normalized = _normalize_payment_type(payment_type)
            query = query.filter(
                (Transaction.type.ilike(f"%{normalized}%"))
                | (Transaction.description.ilike(f"%{normalized}%"))
            )

        if status and str(status).strip().lower() != "all":
            normalized_status = str(status).strip().title()
            query = query.filter(Transaction.status.ilike(f"%{normalized_status}%"))

        transactions = query.order_by(Transaction.created_at.desc()).limit(limit).all()

        def get_order_id(transaction):
            description_match = re.search(
                r"\border(?:\s+id)?\s*#?\s*(\d+)\b",
                transaction.description or "",
                re.IGNORECASE,
            )
            reference_match = re.fullmatch(
                r"(?:REFUND|RELEASE|ORDER)[-_](\d+)",
                transaction.tx_id or "",
                re.IGNORECASE,
            )
            match = description_match or reference_match
            return int(match.group(1)) if match else None

        order_ids = {
            order_id
            for transaction, _ in transactions
            if (order_id := get_order_id(transaction)) is not None
        }
        orders_by_id = {}
        if order_ids:
            order_rows = (
                db.query(Order, Product.seller)
                .outerjoin(Product, Product.id == Order.product_id)
                .filter(Order.id.in_(order_ids))
                .all()
            )
            orders_by_id = {
                order.id: {
                    "id": order.id,
                    "seller_id": order.seller_id or product_seller or "-",
                }
                for order, product_seller in order_rows
            }

        results = []
        for tx, wallet_owner_id in transactions:
            payment_type_value = _normalize_payment_type(tx.type or tx.description or "Product Purchase")
            payment_status = _normalize_payment_status(tx.status or "Pending")
            payment_source = f"{tx.type or ''} {tx.description or ''}".lower()
            is_chapa_deposit = payment_type_value == "Wallet Deposit" and "chapa" in payment_source
            is_chapa_product_payment = payment_type_value == "Product Purchase" and tx.wallet_id is None
            is_wallet_withdrawal = (
                payment_type_value in {"Seller Payout", "Wallet Withdrawal"}
                or str(tx.tx_id or "").upper().startswith("PAYOUT-")
            )
            parsed_order_id = None if is_chapa_deposit or is_wallet_withdrawal else get_order_id(tx)
            related_order = orders_by_id.get(parsed_order_id)
            payment_method = (
                "Chapa" if payment_type_value == "Wallet Deposit" or is_chapa_product_payment
                else "Wallet" if payment_type_value == "Product Purchase"
                else "SantimPay" if payment_type_value == "Seller Payout"
                else "Wallet"
            )
            seller_display = (
                "System (Chapa)"
                if is_chapa_deposit
                else (wallet_owner_id or tx.student_id or "-")
                if is_wallet_withdrawal
                else related_order["seller_id"]
                if related_order
                else "-"
            )

            results.append({
                "id": tx.id,
                "transaction_id": tx.tx_id,
                "buyer_id": tx.student_id,
                "seller_id": seller_display,
                "order_id": related_order["id"] if related_order else "-",
                "amount": float(tx.amount or 0),
                "payment_type": payment_type_value,
                "payment_method": payment_method,
                "status": payment_status,
                "date": tx.created_at.isoformat() if tx.created_at else None,
                "created_date": tx.created_at.isoformat() if tx.created_at else None,
                "completed_date": tx.created_at.isoformat() if payment_status == "Successful" and tx.created_at else None,
                "chapa_reference": tx.tx_id if payment_method == "Chapa" else None,
                "student_id": tx.student_id,
                "type": tx.type,
                "description": tx.description,
            })

        return results
    except (OperationalError, SQLAlchemyError):
        logging.getLogger("app.payments").exception("Failed to load payment transactions.")
        return JSONResponse(
            status_code=500,
            content={
                "error": "Failed to load payment transactions",
                "detail": "An internal error occurred while loading payment transactions.",
            },
        )
    except Exception:
        logging.getLogger("app.payments").exception("Unexpected error while loading payment transactions.")
        return JSONResponse(
            status_code=500,
            content={
                "error": "Unexpected error while loading payment transactions",
                "detail": "An unexpected internal error occurred.",
            },
        )


@app.put("/api/admin/payments/{payment_id}/status")
def update_admin_payment_status(payment_id: int, payload: dict, db: Session = Depends(get_db)):
    raise HTTPException(
        status_code=403,
        detail="Payment status can only be changed by a verified gateway webhook or verification.",
    )


def _request_chapa_verification(tx_ref: str) -> dict:
    try:
        secret = get_chapa_secret_key()
    except PayoutProviderError as error:
        raise HTTPException(status_code=503, detail="Chapa verification is not configured.") from error
    if not secret:
        raise HTTPException(status_code=503, detail="Chapa verification is not configured.")

    try:
        response = httpx.get(
            f"https://api.chapa.co/v1/transaction/verify/{tx_ref}",
            headers={"Authorization": f"Bearer {secret}"},
            timeout=15.0,
        )
        response.raise_for_status()
        payload = response.json()
    except httpx.HTTPError:
        logging.getLogger("app.payments").warning("Chapa verification request failed for tx_ref=%s.", tx_ref)
        raise HTTPException(status_code=502, detail="Unable to verify payment with Chapa.") from None
    except ValueError:
        logging.getLogger("app.payments").warning("Chapa returned invalid verification JSON for tx_ref=%s.", tx_ref)
        raise HTTPException(status_code=502, detail="Chapa returned an invalid payment verification response.") from None

    data = payload.get("data") if isinstance(payload, dict) else None
    if not isinstance(data, dict):
        raise HTTPException(status_code=502, detail="Chapa returned an invalid payment verification response.")
    reference = str(data.get("tx_ref") or "").strip()
    if reference != tx_ref:
        raise HTTPException(status_code=400, detail="Chapa transaction reference does not match the pending payment.")
    try:
        amount = Decimal(str(data.get("amount"))).quantize(Decimal("0.01"))
    except (InvalidOperation, TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Chapa transaction amount is invalid.")
    currency = str(data.get("currency") or "").strip().upper()
    if not amount.is_finite() or amount <= 0:
        raise HTTPException(status_code=400, detail="Chapa transaction amount is invalid.")
    if currency != "ETB":
        raise HTTPException(status_code=400, detail="Chapa transaction currency must be ETB.")
    return {
        "tx_ref": reference,
        "amount": amount,
        "currency": currency,
        "status": _normalize_payment_status(data.get("status")),
    }


@app.get("/api/payment/verify/{tx_ref}")
def verify_payment_with_chapa(
    tx_ref: str,
    authorization: Optional[str] = Header(None),
    db: Session = Depends(get_db),
):
    student = _student_from_authorization(authorization, db)
    transaction = db.query(Transaction).filter(Transaction.tx_id == tx_ref).first()
    if not transaction:
        raise HTTPException(status_code=404, detail="Payment transaction not found.")
    if transaction.student_id != student.student_id:
        raise HTTPException(status_code=403, detail="You can only verify your own payments.")
    transaction_type = _normalize_payment_type(transaction.type)
    if transaction_type not in {"Wallet Deposit", "Product Purchase"}:
        raise HTTPException(status_code=400, detail="This payment type cannot be verified through Chapa.")
    payment_record = None
    order = None
    if transaction_type == "Product Purchase":
        payment_record = db.query(PaymentIdempotency).filter(
            PaymentIdempotency.transaction_id == tx_ref,
            PaymentIdempotency.buyer_id == student.student_id,
        ).first()
        if not payment_record or not payment_record.order_id:
            raise HTTPException(status_code=404, detail="Product order not found for payment.")
        order = db.query(Order).filter(Order.id == payment_record.order_id).first()
        if not order or order.student_id != student.student_id:
            raise HTTPException(status_code=404, detail="Product order not found for payment.")

    expected_amount = Decimal(str(transaction.amount)).quantize(Decimal("0.01"))
    if os.getenv("CHAPA_MODE", "").strip().lower() == "test":
        current_status = _normalize_payment_status(transaction.status)
        verification = {
            "tx_ref": tx_ref,
            "amount": expected_amount,
            "currency": "ETB",
            "status": "Successful" if current_status == "Pending" else current_status,
        }
    else:
        verification = _request_chapa_verification(tx_ref)
        if verification["amount"] != expected_amount:
            raise HTTPException(status_code=400, detail="Chapa transaction amount does not match the pending payment.")
    gateway_status = verification["status"]

    settlement = None
    try:
        if gateway_status == "Successful":
            if transaction_type == "Wallet Deposit":
                settlement = _settle_verified_chapa_transaction(
                    db,
                    tx_ref,
                    expected_amount=verification["amount"],
                )
            else:
                settlement = _settle_verified_chapa_product_order(
                    db,
                    tx_ref,
                    expected_amount=verification["amount"],
                )
            transaction = db.query(Transaction).filter(Transaction.tx_id == tx_ref).first()
        else:
            if transaction_type == "Product Purchase" and gateway_status in {"Failed", "Cancelled", "Expired"}:
                _release_pending_chapa_product_order(
                    db,
                    tx_ref,
                    expired=gateway_status == "Expired",
                )
            else:
                db.rollback()
                with db.begin():
                    transaction = (
                        db.query(Transaction)
                        .filter(Transaction.tx_id == tx_ref)
                        .with_for_update()
                        .first()
                    )
                    if not transaction:
                        raise HTTPException(status_code=404, detail="Payment transaction not found.")
                    if _normalize_payment_status(transaction.status) != "Successful":
                        transaction.status = gateway_status
                        if transaction_type == "Product Purchase":
                            order = (
                                db.query(Order)
                                .filter(Order.id == payment_record.order_id)
                                .with_for_update()
                                .first()
                            )
                            if order and _normalize_payment_status(order.payment_status) != "Successful":
                                order.payment_status = gateway_status

        if not transaction:
            raise HTTPException(status_code=404, detail="Payment transaction not found after verification.")
        db.refresh(transaction)
        final_status = _normalize_payment_status(transaction.status)
        result = {
            "success": True,
            "transaction_id": transaction.tx_id,
            "status": final_status,
            "amount": float(expected_amount),
            "chapa_reference": verification["tx_ref"],
            "transaction_type": transaction_type,
        }
        if transaction_type == "Wallet Deposit":
            wallet_balance = settlement["wallet_balance"] if settlement else (
                db.query(Student.wallet_balance)
                .filter(Student.student_id == transaction.student_id)
                .scalar()
            )
            result["wallet_balance"] = float(wallet_balance or 0)
        else:
            order = db.query(Order).filter(Order.id == payment_record.order_id).first()
            result["order_id"] = order.id if order else None
            result["order_status"] = order.status if order else None
            result["order"] = _serialize_order(db, order) if order else None
        return result
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception("Unable to verify and settle Chapa payment %s safely.", tx_ref)
        raise HTTPException(status_code=500, detail="Unable to verify and settle payment safely.")


@app.post("/api/admin/payments/{payment_ref}/verify")
async def verify_admin_payment_with_chapa(
    payment_ref: str,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    admin = _require_admin(authorization, session_token, db)
    tx_ref = str(payment_ref).strip()
    transaction = db.query(Transaction).filter(Transaction.tx_id == tx_ref).first()
    if not transaction:
        try:
            payment_id = int(tx_ref)
        except ValueError:
            raise HTTPException(status_code=404, detail="Payment transaction not found.")
        transaction = db.query(Transaction).filter(Transaction.id == payment_id).first()
    if not transaction:
        raise HTTPException(status_code=404, detail="Payment transaction not found.")
    confirmed_id = transaction.id
    if _normalize_payment_type(transaction.type) != "Wallet Deposit":
        raise HTTPException(status_code=400, detail="Only wallet deposits can be verified through Chapa.")

    if _normalize_payment_status(transaction.status) == "Successful":
        return {
            "success": True,
            "verified": True,
            "warning": "Payment already processed; replay blocked.",
            "transaction_id": transaction.tx_id,
            "status": transaction.status,
            "wallet_balance": float((db.query(Student).filter(Student.student_id == transaction.student_id).first() or Student()).wallet_balance or 0),
            "chapa_reference": transaction.tx_id,
        }

    try:
        verification = _request_chapa_verification(transaction.tx_id)
    except HTTPException as error:
        logging.getLogger("app.payments").warning(
            "Chapa verification could not be completed for tx_ref=%s: %s",
            transaction.tx_id,
            error.detail,
        )
        return JSONResponse(
            status_code=400 if error.status_code == 400 else 200,
            content={
                "success": False,
                "verified": False,
                "transaction_id": transaction.tx_id,
                "status": "Pending",
                "chapa_reference": transaction.tx_id,
                "detail": f"Chapa verification could not be completed: {error.detail}",
            },
        )

    expected_amount = Decimal(str(transaction.amount)).quantize(Decimal("0.01"))
    if verification["amount"] != expected_amount:
        return JSONResponse(
            status_code=400,
            content={
                "success": False,
                "verified": False,
                "transaction_id": transaction.tx_id,
                "status": "Pending",
                "chapa_reference": transaction.tx_id,
                "detail": "Chapa transaction amount does not match the pending payment.",
            },
        )
    gateway_status = verification["status"]
    if gateway_status != "Successful":
        return {
            "success": False,
            "verified": False,
            "transaction_id": transaction.tx_id,
            "status": "Pending" if gateway_status == "Pending" else gateway_status,
            "chapa_reference": transaction.tx_id,
            "detail": (
                "Transaction is still pending on Chapa"
                if gateway_status == "Pending"
                else f"Chapa verification returned {gateway_status}."
            ),
        }

    try:
        settlement = _settle_verified_chapa_transaction(
            db,
            transaction.tx_id,
            expected_amount=verification["amount"],
        )
        if settlement["already_settled"]:
            return {
                "success": True,
                "verified": True,
                "warning": "Payment already processed; replay blocked.",
                "transaction_id": settlement["transaction_id"],
                "status": "Successful",
                "wallet_balance": float(settlement["wallet_balance"]),
                "chapa_reference": settlement["transaction_id"],
            }

        transaction = db.query(Transaction).filter(Transaction.tx_id == settlement["transaction_id"]).first()
        student = db.query(Student).filter(Student.student_id == settlement["student_id"]).first()
        if not transaction or not student:
            raise HTTPException(status_code=404, detail="Settled payment records could not be loaded.")
        _dispatch_student_notification(
            db,
            student,
            "Payment Successful",
            f"Your wallet deposit of {settlement['amount']} ETB was completed successfully.",
            "payment",
            badge="Completed",
            details_table={
                "Amount": f"{settlement['amount']} ETB",
                "Reference": settlement["transaction_id"],
                "Date": datetime.now(timezone.utc).strftime("%b %d, %Y").replace(" 0", " "),
            },
        )

        db.add(AuditLog(
            admin_id=admin.id,
            action="Payment Verified",
            entity_type="Payment",
            entity_id=transaction.id,
            description=f"Admin {admin.username} verified Chapa payment {transaction.tx_id}; credited {settlement['amount']} ETB to student {student.student_id}.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))

        db.commit()
        db.refresh(transaction)
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception("Unable to settle payment safely.")
        raise HTTPException(status_code=500, detail="Unable to settle payment safely.")

    return {
        "success": True,
        "verified": True,
        "transaction_id": transaction.tx_id,
        "status": transaction.status,
        "wallet_balance": float(student.wallet_balance or 0),
        "chapa_reference": transaction.tx_id,
    }


@app.get("/api/admin/orders")
def get_admin_orders(
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    _require_admin(authorization, session_token, db)
    try:
        rows = db.query(Order).order_by(Order.created_at.desc()).all()
        results = []
        for order in rows:
            amount_value = 0.0
            try:
                if isinstance(order.price, str):
                    cleaned = order.price.replace("ETB", "").replace("$", "").replace(",", "").strip()
                    amount_value = float(cleaned) if cleaned else 0.0
                elif order.price is not None:
                    amount_value = float(order.price)
            except (TypeError, ValueError):
                amount_value = 0.0

            product = db.query(Product).filter(Product.id == order.product_id).first()
            dispute = db.query(Dispute).filter(Dispute.order_id == order.id).order_by(Dispute.created_at.desc()).first()
            buyer = db.query(Student).filter(Student.student_id == order.student_id).first()
            seller = db.query(Student).filter(
                (Student.student_id == (product.seller if product else None))
                | (Student.name == (product.seller if product else None))
            ).first() if product and product.seller else None
            product_title = product.title if product else (order.title or "Unnamed Product")
            seller_id = product.seller if product and product.seller else "Unknown"
            buyer_id = order.student_id
            order_status = _normalize_order_status(order.status)
            payment_status = _normalize_payment_status(order.payment_status or "Pending")
            payment_rows = db.query(Transaction).filter(Transaction.student_id == buyer_id).order_by(Transaction.created_at.desc()).all()
            if payment_status == "Pending" and payment_rows:
                payment_status = _normalize_payment_status(payment_rows[0].status)

            record = {
                "id": order.id,
                "buyer_id": buyer_id,
                "seller_id": seller_id,
                "product_title": product_title,
                "total_amount": amount_value,
                "order_status": order_status,
                "payment_status": payment_status,
                "pay_status": payment_status,
                "dispute_reason": order.dispute_reason,
                "dispute_status": dispute.status if dispute else None,
                "dispute_id": dispute.id if dispute else None,
                "dispute_description": dispute.description if dispute else None,
                "dispute_created_at": dispute.created_at.isoformat() if dispute and dispute.created_at else None,
                "seller_response": dispute.seller_response if dispute else None,
                "seller_payout_status": "Paid to seller wallet" if payment_status == "Successful" else "Unavailable",
                "refund_status": order.refund_status,
                "refund_reference": order.refund_reference,
                "buyer_name": buyer.name if buyer else buyer_id,
                "seller_name": seller.name if seller else seller_id,
                "date": order.created_at.isoformat() if order.created_at else None,
                "price": f"{amount_value:,.0f} ETB",
                "item": product_title,
                "buyer": buyer_id,
                "seller": seller_id,
                "amount": amount_value,
            }
            results.append(record)
        return results
    except (OperationalError, SQLAlchemyError):
        logging.getLogger("app.orders").exception("Failed to load order records.")
        return JSONResponse(status_code=500, content={"error": "Failed to load order records", "detail": "An internal error occurred while loading order records."})
    except Exception:
        logging.getLogger("app.orders").exception("Unexpected error while loading order records.")
        return JSONResponse(status_code=500, content={"error": "Unexpected error while loading order records", "detail": "An unexpected internal error occurred."})




@app.post("/api/admin/orders/{order_id}/resolve-dispute")
def resolve_order_dispute(
    order_id: int,
    payload: DisputeResolutionRequest,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session_token: Optional[str] = None,
    db: Session = Depends(get_db),
):
    _require_admin(authorization, session_token, db)
    active_dispute = db.query(Dispute).filter(
        Dispute.order_id == order_id,
        Dispute.status.in_(ACTIVE_DISPUTE_STATUSES),
    ).order_by(Dispute.created_at.desc()).first()
    if not active_dispute:
        raise HTTPException(status_code=404, detail="No open dispute was found for this order.")
    return resolve_dispute(
        active_dispute.id,
        payload,
        authorization=authorization,
        session_token=session_token,
        db=db,
    )


@app.get("/api/payment/webhook")
@app.get("/payment/webhook")
async def acknowledge_chapa_get_callback(
    trx_ref: Optional[str] = None,
    tx_ref: Optional[str] = None,
    status: Optional[str] = None,
    ref_id: Optional[str] = None,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    db: Session = Depends(get_db),
):
    """Verify Chapa browser callbacks so successful deposits settle automatically."""
    reference = (trx_ref or tx_ref or ref_id or "").strip() or None
    if reference:
        return verify_payment_with_chapa(
            reference,
            authorization=authorization,
            db=db,
        )

    return {
        "success": True,
        "message": "Payment callback received. Payment verification is performed server-side.",
        "transaction_id": reference,
        "status": status or "pending",
        "verified": False,
    }


@app.post("/api/payment/webhook")
@app.post("/payment/webhook")
@app.post("/api/admin/payments/webhook")
async def simulate_chapa_webhook(
    payload: ChapaWebhookPayload,
    request: Request,
    db: Session = Depends(get_db),
    authorization: Optional[str] = Header(None, alias="Authorization"),
):
    webhook_logger = logging.getLogger("app.payments.webhook")
    raw_body = await request.body()
    try:
        incoming_payload = await request.json()
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
        incoming_payload = {}
    webhook_logger.info(
        "Chapa payment webhook received path=%s signature_present=%s payload_reference=%s",
        request.url.path,
        bool(request.headers.get("x-chapa-signature") or authorization or incoming_payload.get("signature") if isinstance(incoming_payload, dict) else False),
        incoming_payload.get("tx_ref") or incoming_payload.get("transaction_id") if isinstance(incoming_payload, dict) else None,
    )
    raw_payload = incoming_payload
    if not raw_payload and raw_body:
        try:
            raw_payload = json.loads(raw_body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raw_payload = {}
    if not isinstance(raw_payload, dict):
        raw_payload = {}
    payload_dict = raw_payload if isinstance(raw_payload, dict) else (
        payload.dict() if hasattr(payload, "dict") else dict(payload)
    )
    callback_data = payload_dict.get("data") if isinstance(payload_dict.get("data"), dict) else {}

    try:
        secret = get_chapa_webhook_secret()
    except PayoutProviderError as error:
        raise HTTPException(status_code=503, detail="Webhook verification is not configured.") from error
    callback_signature = request.headers.get("x-chapa-signature")

    # A success callback is allowed to settle automatically only after its
    # signature is verified. Admin review remains the fallback for rejected
    # or invalid callbacks; it is never required for a valid success callback.
    if not secret:
        webhook_logger.error("Rejected Chapa payment webhook: CHAPA_WEBHOOK_SECRET is not configured.")
        raise HTTPException(status_code=503, detail="Webhook verification is not configured.")
    if not callback_signature:
        webhook_logger.warning("Rejected Chapa payment webhook: signature is missing.")
        raise HTTPException(status_code=401, detail="Missing transaction signature.")
    raw_body_signature = _compute_chapa_body_signature(secret, raw_body)
    if not hmac.compare_digest(callback_signature.lower(), raw_body_signature.lower()):
        webhook_logger.warning(
            "Rejected Chapa callback with an invalid signature for transaction %s.",
            payload_dict.get("tx_ref") or payload_dict.get("transaction_id") or payload_dict.get("tx_id"),
        )
        raise HTTPException(status_code=401, detail="Invalid transaction signature. Admin verification is required.")

    status_value = str(
        payload_dict.get("status")
        or payload_dict.get("state")
        or callback_data.get("status")
        or payload_dict.get("event")
        or "pending"
    ).strip().lower()
    if status_value not in {"success", "successful", "paid", "completed", "charge.success"}:
        webhook_logger.info(
            "Acknowledged signed Chapa callback without settlement status=%s transaction=%s.",
            payload_dict.get("tx_ref") or payload_dict.get("transaction_id") or callback_data.get("tx_ref"),
            status_value,
        )
        return {
            "message": "Payment callback received; no settlement was performed.",
            "status": status_value,
            "verified": True,
            "settled": False,
        }

    tx_ref = str(
        payload_dict.get("tx_ref")
        or payload_dict.get("transaction_id")
        or payload_dict.get("tx_id")
        or payload_dict.get("reference")
        or callback_data.get("tx_ref")
        or callback_data.get("transaction_id")
        or callback_data.get("tx_id")
        or callback_data.get("reference")
        or "TX-UNKNOWN"
    )
    amount_value = (
        payload_dict.get("amount")
        or payload_dict.get("total_amount")
        or callback_data.get("amount")
        or callback_data.get("total_amount")
        or 0
    )
    currency_value = (
        payload_dict.get("currency")
        or callback_data.get("currency")
        or ""
    )
    try:
        amount = Decimal(str(amount_value)).quantize(Decimal("0.01"))
    except (InvalidOperation, TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Payment callback amount is invalid.")

    transaction = db.query(Transaction).filter(Transaction.tx_id == tx_ref).first()
    if not transaction:
        raise HTTPException(status_code=404, detail="Pending payment transaction not found for callback.")
    transaction_type = _normalize_payment_type(transaction.type)
    if transaction_type == "Product Purchase":
        product_payment = db.query(PaymentIdempotency).filter(
            PaymentIdempotency.transaction_id == tx_ref,
            PaymentIdempotency.order_id.isnot(None),
        ).first()
        if not product_payment:
            transaction_type = "Other"
    if transaction_type not in {"Wallet Deposit", "Product Purchase"}:
        webhook_logger.warning(
            "Ignored signed Chapa callback for unrelated transaction tx_ref=%s type=%s status=%s.",
            tx_ref,
            transaction.type,
            status_value,
        )
        return {
            "message": "Payment callback received; no settlement was performed because this transaction is not a wallet deposit or linked product order.",
            "status": status_value,
            "verified": True,
            "settled": False,
            "transaction_id": tx_ref,
            "transaction_type": transaction.type,
        }

    if amount <= 0:
        raise HTTPException(status_code=400, detail="Payment callback amount must be greater than 0.")
    if currency_value and str(currency_value).strip().upper() != "ETB":
        raise HTTPException(status_code=400, detail="Payment callback currency must be ETB.")
    if Decimal(str(transaction.amount)).quantize(Decimal("0.01")) != amount:
        raise HTTPException(status_code=400, detail="Payment callback amount does not match the initialized transaction.")

    student_identifier = (
        payload_dict.get("student_id")
        or payload_dict.get("buyer_id")
        or payload_dict.get("studentId")
        or payload_dict.get("customer")
        or callback_data.get("student_id")
        or callback_data.get("buyer_id")
        or callback_data.get("studentId")
        or callback_data.get("customer")
    )
    if isinstance(student_identifier, dict):
        student_identifier = (
            student_identifier.get("student_id")
            or student_identifier.get("buyer_id")
            or student_identifier.get("studentId")
        )

    if student_identifier and str(student_identifier) != str(transaction.student_id):
        raise HTTPException(status_code=400, detail="Payment callback student does not match the transaction.")

    try:
        verification = _request_chapa_verification(tx_ref)
        if verification["status"] != "Successful":
            return {
                "message": "Chapa has not verified this payment as successful.",
                "status": verification["status"],
                "verified": True,
                "settled": False,
                "transaction_id": tx_ref,
            }
        if verification["amount"] != amount:
            raise HTTPException(status_code=400, detail="Chapa verification amount does not match the callback.")
        if verification["currency"] != "ETB":
            raise HTTPException(status_code=400, detail="Chapa verification currency must be ETB.")
        if transaction_type == "Product Purchase":
            settlement = _settle_verified_chapa_product_order(
                db,
                tx_ref,
                expected_amount=verification["amount"],
            )
            if settlement["already_settled"]:
                return {
                    "message": "Product payment webhook was already processed; replay blocked.",
                    "status": "Successful",
                    "transaction_id": settlement["transaction_id"],
                    "student_id": settlement["student_id"],
                    "order_id": settlement["order_id"],
                    "amount": float(settlement["amount"]),
                    "settled": False,
                }
            return {
                "message": "Product payment webhook processed successfully.",
                "status": "Successful",
                "verified": True,
                "settled": True,
                "transaction_id": settlement["transaction_id"],
                "student_id": settlement["student_id"],
                "order_id": settlement["order_id"],
                "amount": float(settlement["amount"]),
                "commission": float(settlement["commission"]),
            }

        settlement = _settle_verified_chapa_transaction(db, tx_ref, expected_amount=verification["amount"])
        if settlement["already_settled"]:
            return {
                "message": "Payment webhook was already processed; replay blocked.",
                "status": "Successful",
                "transaction_id": settlement["transaction_id"],
                "student_id": settlement["student_id"],
                "wallet_balance": float(settlement["wallet_balance"]),
                "amount": float(settlement["amount"]),
            }

        transaction = db.query(Transaction).filter(Transaction.tx_id == settlement["transaction_id"]).first()
        student = db.query(Student).filter(Student.student_id == settlement["student_id"]).first()
        if not transaction or not student:
            raise HTTPException(status_code=404, detail="Settled payment records could not be loaded.")
        transaction.description = transaction.description or "Chapa webhook settlement captured via payment callback."

        _dispatch_student_notification(
            db,
            student,
            "Payment Successful",
            f"Your Chapa wallet deposit of {settlement['amount']} ETB was completed successfully.",
            "payment",
            badge="Completed",
            details_table={
                "Amount": f"{settlement['amount']} ETB",
                "Reference": settlement["transaction_id"],
                "Date": datetime.now(timezone.utc).strftime("%b %d, %Y").replace(" 0", " "),
            },
        )

        admin = db.query(Admin).order_by(Admin.id.asc()).first()
        db.add(AuditLog(
            admin_id=admin.id if admin else None,
            action="Payment Webhook Success",
            entity_type="Payment",
            entity_id=transaction.id,
            description=f"Chapa webhook processed successfully for student {student.student_id}, tx_ref {tx_ref}, amount {settlement['amount']} ETB.",
            status="SUCCESS",
            ip_address="127.0.0.1",
        ))

        db.commit()
        db.refresh(transaction)
        db.refresh(student)
        webhook_logger.info(
            "Chapa payment webhook settled tx_ref=%s student_id=%s amount=%s wallet_balance=%s.",
            transaction.tx_id,
            student.student_id,
            settlement["amount"],
            student.wallet_balance,
        )
    except HTTPException:
        db.rollback()
        raise
    except SQLAlchemyError:
        db.rollback()
        logging.getLogger("app.payments").exception("Unable to settle signed Chapa webhook %s safely.", tx_ref)
        raise HTTPException(status_code=500, detail="Unable to settle payment webhook safely.")

    return {
        "message": "Payment webhook processed successfully.",
        "status": "Successful",
        "transaction_id": transaction.tx_id,
        "student_id": student.student_id,
        "wallet_balance": float(student.wallet_balance),
        "amount": float(settlement["amount"]),
    }


# 17. Admin-only report review and resolution workflow.
REPORT_DECISION_OPTIONS = (
    {"key": "dismiss", "label": "Dismiss, no violation found"},
    {"key": "warn", "label": "Warn seller"},
    {"key": "hide_product", "label": "Hide product"},
    {"key": "suspend", "label": "Suspend seller"},
    {"key": "deactivate", "label": "Deactivate seller"},
    {"key": "escalate", "label": "Escalate / request more info"},
)
LEGACY_REPORT_DECISIONS = {
    "warning": "warn",
    "remove product": "hide_product",
    "suspend user": "suspend",
    "reject": "dismiss",
}
try:
    REPORT_ABUSE_THRESHOLD = max(1, int(os.getenv("REPORT_ABUSE_THRESHOLD", "5")))
except ValueError:
    REPORT_ABUSE_THRESHOLD = 5
try:
    WARNINGS_BEFORE_SUSPEND = max(1, int(os.getenv("WARNINGS_BEFORE_SUSPEND", "3")))
except ValueError:
    WARNINGS_BEFORE_SUSPEND = 3


def _normalize_report_decision(decision: Optional[str]) -> Optional[str]:
    if decision is None:
        return None
    normalized = decision.strip().lower()
    return LEGACY_REPORT_DECISIONS.get(normalized, normalized)


def _require_report_admin(authorization: Optional[str], db: Session) -> Admin:
    token = _extract_admin_token(authorization, None)
    try:
        admin, _ = _admin_for_session(db, token)
        return admin
    except HTTPException as admin_error:
        if admin_error.status_code != 401:
            raise
        try:
            _decode_student_jwt(token)
        except HTTPException:
            raise admin_error
        raise HTTPException(status_code=403, detail="Administrator access is required for reports.")


def _report_product_and_order(db: Session, report: Report) -> tuple[Optional[Product], Optional[Order]]:
    product = db.query(Product).filter(Product.id == report.product_id).first() if report.product_id else None
    order = db.query(Order).filter(Order.id == report.order_id).first() if report.order_id else None
    return product, order


def _report_seller_name(db: Session, seller_id: Optional[str]) -> str:
    if not seller_id:
        return "Not linked"
    seller = db.query(Student).filter(Student.student_id == seller_id).first()
    return seller.name if seller else "Not linked"


def _report_payment_transaction(db: Session, order: Order) -> Optional[Transaction]:
    return (
        db.query(Transaction)
        .filter(
            Transaction.student_id == order.student_id,
            or_(
                Transaction.tx_id == f"ORDER-PAY-{order.id}",
                and_(
                    Transaction.type == "Escrow Hold",
                    Transaction.description == f"Escrow hold for order #{order.id}",
                ),
            ),
            Transaction.status.in_(["Successful", "Released", "Refunded"]),
        )
        .order_by(Transaction.created_at.asc())
        .first()
    )


def _student_by_exact_id(db: Session, student_id: Optional[str]) -> Optional[Student]:
    value = (student_id or "").strip()
    if not value:
        return None
    candidates = db.query(Student).filter(Student.student_id == value).all()
    matches = [student for student in candidates if student.student_id == value]
    return matches[0] if len(matches) == 1 else None


def get_product_owner_student_id(db: Session, product: Optional[Product]) -> Optional[str]:
    if not product:
        return None
    if product.seller_id:
        owner = _student_by_exact_id(db, product.seller_id)
        return owner.student_id if owner else None
    legacy_owner = _student_by_exact_id(db, product.seller)
    return legacy_owner.student_id if legacy_owner else None


def _auto_link_report_targets(
    db: Session,
    report: Report,
    admin_id: Optional[int] = None,
    request: Optional[Request] = None,
) -> Optional[str]:
    """Fill only absent report targets using authoritative order/product ownership."""
    source = None
    order = db.query(Order).filter(Order.id == report.order_id).first() if report.order_id else None
    if order:
        order_product = db.query(Product).filter(Product.id == order.product_id).first()
        if order_product and report.product_id != order_product.id:
            report.product_id = order_product.id
            source = "order"
        product = order_product
        owner_student_id = get_product_owner_student_id(db, product)
        if not report.seller_id and owner_student_id:
            report.seller_id = owner_student_id
            source = source or "product"
    else:
        product = db.query(Product).filter(Product.id == report.product_id).first() if report.product_id else None
        owner_student_id = get_product_owner_student_id(db, product)
        if not report.seller_id and owner_student_id:
            report.seller_id = owner_student_id
            source = "product"

    if source:
        db.add(AuditLog(
            admin_id=admin_id,
            action="Report Targets Auto-Linked",
            entity_type="Report",
            entity_id=report.id,
            description=(
                f"Automatically linked report targets from {source}: "
                f"seller={report.seller_id or 'none'}, product={report.product_id or 'none'}, "
                f"order={report.order_id or 'none'}."
            ),
            status="SUCCESS",
            ip_address=request.client.host if request and request.client else None,
        ))
    return source


def backfill_report_targets(db: Session) -> int:
    reports = db.query(Report).filter(
        or_(Report.seller_id.is_(None), Report.product_id.is_(None)),
    ).order_by(Report.id.asc()).all()
    linked_count = 0
    for report in reports:
        if _auto_link_report_targets(db, report):
            linked_count += 1
    if linked_count:
        db.commit()
    return linked_count


def _report_payload(db: Session, report: Report) -> dict:
    product, order = _report_product_and_order(db, report)
    reviewer = db.query(Admin).filter(Admin.id == report.reviewed_by).first() if report.reviewed_by else None
    resolver = db.query(Admin).filter(Admin.id == report.resolved_by).first() if report.resolved_by else None
    return {
        "id": report.id,
        "report_id": f"RPT-{report.id:04d}",
        "issue": report.issue,
        "category": report.category,
        "email": report.email,
        "student": report.student_name,
        "student_id": report.student_id,
        "seller_id": report.seller_id or "Not linked",
        "seller_name": _report_seller_name(db, report.seller_id),
        "product_id": report.product_id,
        "product_name": product.title if product else "Not linked",
        "product_url": f"/?productId={product.id}" if product else None,
        "order_id": report.order_id,
        "order_name": order.title if order else "Not linked",
        "evidence_image": (
            f"/api/admin/reports/{report.id}/evidence"
            if (report.evidence_image or "").startswith("private-report:")
            else report.evidence_image
        ),
        "status": report.status,
        "date": report.created_at.isoformat() if report.created_at else None,
        "priority": report.priority,
        "review_by": report.review_by.isoformat() if report.review_by else None,
        "decision": _normalize_report_decision(report.decision),
        "decision_reason": report.decision_reason,
        "reviewed_by": report.reviewed_by,
        "reviewed_by_name": reviewer.full_name or reviewer.username if reviewer else None,
        "reviewed_at": report.reviewed_at.isoformat() if report.reviewed_at else None,
        "resolved_at": report.resolved_at.isoformat() if report.resolved_at else None,
        "resolved_by": report.resolved_by,
        "resolved_by_name": resolver.full_name or resolver.username if resolver else None,
        "seller_response": report.seller_response,
        "seller_response_image": report.seller_response_image,
        "seller_response_at": report.seller_response_at.isoformat() if report.seller_response_at else None,
        "appeal_text": report.appeal_text,
        "evidence_url": (
            f"/api/student/reports/{report.id}/evidence"
            if (report.evidence_image or "").startswith("private-report:")
            else None
        ),
        "appealed_at": report.appealed_at.isoformat() if report.appealed_at else None,
        "appealed_by": report.appealed_by,
        "refunded_amount": str(report.refunded_amount or Decimal("0.00")),
    }


def _add_report_notification(db: Session, student_id: Optional[str], report: Report, title: str, message: str) -> None:
    if not student_id:
        return
    student = db.query(Student).filter(Student.student_id == student_id).first()
    if not student or not student.notif_msg_inapp:
        return
    db.add(Notification(
        student_id=student_id,
        title=title,
        message=message[:500],
        type="report_update",
        reference_id=str(report.id),
        action_label="View report",
        action_url=f"/dashboard?tab=buyer&section=reports-support&item=report-{report.id}",
    ))


def _record_report_review_side_effects(
    db: Session,
    report: Report,
    admin: Admin,
    request: Request,
    background_tasks: BackgroundTasks,
) -> None:
    db.add(AuditLog(
        admin_id=admin.id,
        action="Report Status Changed",
        entity_type="Report",
        entity_id=report.id,
        description=f"RPT-{report.id:04d} moved to Under Review.",
        status="SUCCESS",
        ip_address=request.client.host if request.client else None,
    ))
    student = (
        db.query(Student).filter(Student.student_id == report.student_id).first()
        if report.student_id else None
    )
    outbox_id = None
    if student:
        outbox_id = _queue_student_item_notification(
            db,
            student,
            title=f"Update on RPT-{report.id:04d}",
            message="An admin is reviewing your report.",
            item_type="report_status",
            item_id=report.id,
            action_url=f"/dashboard?tab=buyer&section=reports-support&item=report-{report.id}",
            email_subject=f"Update on RPT-{report.id:04d}",
            email_summary="An administrator is reviewing your report.",
            email_status=report.status,
        )
    db.commit()
    if outbox_id and db.get_bind() is engine:
        background_tasks.add_task(
            _deliver_report_review_outbox,
            outbox_id,
            report.id,
        )


def _deliver_report_review_outbox(outbox_id: int, report_id: int) -> None:
    try:
        _deliver_outbox_email(outbox_id)
    except Exception:
        logging.getLogger("app.reports").exception(
            "Best-effort report review notification delivery failed (report_id=%s).",
            report_id,
        )


def _student_report_payload(db: Session, report: Report) -> dict:
    public_messages = db.query(ReportMessage).filter(
        ReportMessage.report_id == report.id,
        ReportMessage.is_internal.is_(False),
    ).order_by(ReportMessage.created_at.asc(), ReportMessage.id.asc()).all()
    return {
        "id": report.id,
        "report_id": f"RPT-{report.id:04d}",
        "issue": report.issue,
        "category": report.category,
        "status": report.status,
        "decision": _normalize_report_decision(report.decision),
        "decision_reason": report.decision_reason,
        "date": report.created_at.isoformat() if report.created_at else None,
        "updated_at": (
            (report.resolved_at or report.reviewed_at or report.created_at).isoformat()
            if (report.resolved_at or report.reviewed_at or report.created_at) else None
        ),
        "order_id": report.order_id,
        "appeal_submitted": bool(report.appeal_text),
        "appealed_at": report.appealed_at.isoformat() if report.appealed_at else None,
        "can_appeal": report.status in {"Resolved", "Dismissed"} and not report.appeal_text,
        "appeal_text": report.appeal_text,
        "messages": [{
            "id": message.id,
            "body": message.body,
            "sender_type": "admin",
            "created_at": message.created_at.isoformat() if message.created_at else None,
        } for message in public_messages],
    }


@app.get("/api/admin/reports")
def get_admin_reports(
    authorization: Optional[str] = Header(None, alias="Authorization"),
    status_filter: Optional[str] = Query(None, alias="status"),
    category: Optional[str] = Query(None),
    assigned_admin_id: Optional[int] = Query(None),
    overdue: Optional[bool] = Query(None),
    db: Session = Depends(get_db),
):
    admin = _require_report_admin(authorization, db)
    query = db.query(Report)
    if status_filter:
        query = query.filter(Report.status == status_filter)
    if category:
        query = query.filter(Report.category == category)
    if assigned_admin_id is not None:
        query = query.filter(Report.reviewed_by == assigned_admin_id)
    reports = query.order_by(Report.created_at.desc()).all()
    if overdue is not None:
        reports = [
            report for report in reports
            if (
                report.status in {"Open", "Under Review"}
                and report.created_at
                and datetime.now(timezone.utc).replace(tzinfo=None) - report.created_at
                > timedelta(hours=SUPPORT_SLA_HOURS)
            ) == overdue
        ]
    activities = _admin_report_activity_map(db, reports)
    seen = _admin_item_seen_map(db, admin.id, "report")
    items = []
    for report in reports:
        payload = _report_payload(db, report)
        payload["is_unseen"] = report.id not in seen or activities[report.id] > seen[report.id]
        items.append(payload)
    return items


